local L = rawget(_G, "Lapsus")
if not L and type(Lapsus) == "table" then
    L = Lapsus
end

function vehicleLaunchScale()
    -- Les effets de projection restent utilisables, avec une impulsion reduite.
    for _, name in ipairs(_G.AC_BypassesApplied or {}) do
        if name == "Seed" or name == "Putin" then return 0.08 end
    end
    if type(GetResourceState) == "function" then
        for _, name in ipairs({"seed", "seed-ac", "seed_ac", "seedac", "putin"}) do
            if GetResourceState(name) == "started" then return 0.08 end
        end
    end
    return 1.0
end

local function seedBlocksInvisibility()
    for _, name in ipairs(_G.AC_BypassesApplied or {}) do
        if name == "Seed" then return true end
    end
    return GetResourceState("seed") == "started"
        or GetResourceState("seed-ac") == "started"
        or GetResourceState("seed_ac") == "started"
        or GetResourceState("seedac") == "started"
end

local SetEntityVisible, SetEntityAlpha = (function()
    local nativeVisible, nativeAlpha = SetEntityVisible, SetEntityAlpha
    return function(entity, visible, ...)
        if not visible and entity == PlayerPedId() and seedBlocksInvisibility() then return end
        return nativeVisible(entity, visible, ...)
    end, function(entity, alpha, ...)
        if alpha < 255 and entity == PlayerPedId() and seedBlocksInvisibility() then return end
        return nativeAlpha(entity, alpha, ...)
    end
end)()

-- Helper pour normaliser les couleurs (0.0..1.0 -> 0..255)
local function _c(v)
    if not v then return 255 end
    if v <= 1.0 and v > 0.0 then
        return math.floor(v * 255.0 + 0.5)
    end
    return math.floor(math.min(255, math.max(0, v)))
end

-- 1. Dessin Rectangles
do
local imageHole
function Lapsus_DrawRect_Filled(x, y, w, h, r, g, b, a, rnd)
    if not L or not L.DrawRect then return end
    local function rect(rx, ry, rw, rh, radius)
        if rw > 0 and rh > 0 then
            L.DrawRect(rx, ry, rw, rh, true, _c(r), _c(g), _c(b), _c(a), radius or 0)
        end
    end
    local hole = imageHole
    if not hole or x+w<=hole[1] or x>=hole[3] or y+h<=hole[2] or y>=hole[4] then
        return rect(x,y,w,h,rnd)
    end
    -- Soustraction en coordonnees pixels, sans etat de clipping du renderer.
    local function strip(sx,sy,sw,sh)
        local left,top=math.max(sx,hole[1]),math.max(sy,hole[2])
        local right,bottom=math.min(sx+sw,hole[3]),math.min(sy+sh,hole[4])
        if left>=right or top>=bottom then return rect(sx,sy,sw,sh) end
        rect(sx,sy,sw,top-sy)
        rect(sx,bottom,sw,sy+sh-bottom)
        rect(sx,top,left-sx,bottom-top)
        rect(right,top,sx+sw-right,bottom-top)
    end
    local radius=math.max(0,math.min(rnd or 0,w/2,h/2))
    if radius==0 then return strip(x,y,w,h) end
    -- Conserver les coins arrondis avec des bandes d'au plus un pixel.
    local rows=math.ceil(radius)
    local step=radius/rows
    for i=0,rows-1 do
        local dy=radius-(i+0.5)*step
        local inset=radius-math.sqrt(math.max(0,radius*radius-dy*dy))
        strip(x+inset,y+i*step,w-2*inset,step)
        strip(x+inset,y+h-(i+1)*step,w-2*inset,step)
    end
    strip(x,y+radius,w,h-2*radius)
end
function Lapsus_OutsideImage_compat(x,y,w,h,draw)
    local previous=imageHole
    imageHole={x,y,x+w,y+h}
    local ok,err=pcall(draw)
    imageHole=previous
    if not ok then error(err) end
end
end

function Lapsus_DrawRect_Border(x, y, w, h, r, g, b, a, rnd, th)
    if not L or not L.DrawRect then return end
    L.DrawRect(x, y, w, h, false, _c(r), _c(g), _c(b), _c(a), rnd or 0.0, th or 1.0)
end

-- 2. Dessin Texte (Calibré avec clamp de taille et coordonnées entières)
function Lapsus_DrawText_compat(x, y, text, size, r, g, b, a)
    if not L or not L.DrawText then return end
    local str = tostring(text or "")
    if #str == 0 then return end
    local fSize = math.floor(math.max(9, tonumber(size) or 14))
    -- Offset vertical fin (+1px) pour calage parfait au pixel
    L.DrawText(str, math.floor(x + 0.5), math.floor(y + 0.5), fSize, _c(r), _c(g), _c(b), _c(a))
end

-- 3. Mesure Texte (Calibré sur la police standard du renderer Lapsus)
function Lapsus_GetTextWidth_compat(text, size)
    local value=tostring(text or ''):gsub('%^%d','')
    local width,sz=0,math.max(9,math.floor(tonumber(size) or 14))
    for ch in value:gmatch('[%z\1-\127\194-\244][\128-\191]*') do
        width=width+sz*(ch==' ' and 0.30 or ch:match("[ilI.,:!|']") and 0.26
            or ch:match('[MW@%%]') and 0.85 or 0.53)
    end
    return width
end
-- Shared UI sizing: the drawing bridge clamps fonts to at least nine pixels.
function Lapsus_FitText_compat(value,size,available,height)
    value=tostring(value or '')
    size=math.max(9,math.floor(math.min(size or 14,height or math.huge)))
    available=math.max(0,available or 0)
    -- Leave a margin because the renderer exposes no exact font metrics.
    while size>9 and Lapsus_GetTextWidth_compat(value,size)*1.12>available do size=size-1 end
    if Lapsus_GetTextWidth_compat(value,size)*1.12<=available then
        return value,size,Lapsus_GetTextWidth_compat(value,size)
    end
    local chars={}
    for ch in value:gmatch('[%z\1-\127\194-\244][\128-\191]*') do chars[#chars+1]=ch end
    while #chars>0 and Lapsus_GetTextWidth_compat(table.concat(chars)..'...',size)*1.12>available do
        chars[#chars]=nil
    end
    value=#chars>0 and table.concat(chars)..'...' or ''
    return value,size,Lapsus_GetTextWidth_compat(value,size)
end
-- 4. Gradients
function Lapsus_DrawRectGradient_compat(x, y, w, h, r1, g1, b1, a1, r2, g2, b2, a2, vertical)
    if not L then return end
    if L.DrawRectMultiColor then
        local cr1, cg1, cb1, ca1 = _c(r1), _c(g1), _c(b1), _c(a1)
        local cr2, cg2, cb2, ca2 = _c(r2), _c(g2), _c(b2), _c(a2)
        if vertical then
            L.DrawRectMultiColor(x, y, w, h, cr1, cg1, cb1, ca1, cr1, cg1, cb1, ca1, cr2, cg2, cb2, ca2, cr2, cg2, cb2, ca2)
        else
            L.DrawRectMultiColor(x, y, w, h, cr1, cg1, cb1, ca1, cr2, cg2, cb2, ca2, cr2, cg2, cb2, ca2, cr1, cg1, cb1, ca1)
        end
    elseif L.DrawRect then
        L.DrawRect(x, y, w, h, true, _c(r1), _c(g1), _c(b1), _c(a1), 0.0)
    end
end

