function Lapsus_DrawReferenceIcon_compat(name,cx,cy,size,color,opacity)
    if not Lapsus_DrawLine_compat then return end
    local function line(a,b,c,d)
        Lapsus_DrawLine_compat(cx+a*size,cy+b*size,cx+c*size,cy+d*size,
            color[1],color[2],color[3],opacity,math.max(1,size*0.13))
    end
    local function circle(x,y,rad)
        for j=0,19 do
            local a,b=j*math.pi/10,(j+1)*math.pi/10
            line(x+math.cos(a)*rad,y+math.sin(a)*rad,x+math.cos(b)*rad,y+math.sin(b)*rad)
        end
    end
    cx=cx+size
    if name=="Player" then
        circle(0,-0.55,0.33);line(-0.70,0.80,-0.55,0.25);line(-0.55,0.25,0.55,0.25);line(0.55,0.25,0.70,0.80);line(-0.70,0.80,0.70,0.80)
    elseif name=="ESP" then
        -- Eye outline and pupil.
        for j=0,11 do
            local x1,x2=-1+j/6,-1+(j+1)/6
            local y1,y2=0.52*(1-x1*x1),0.52*(1-x2*x2)
            line(x1,y1,x2,y2);line(x1,-y1,x2,-y2)
        end
        circle(0,0,0.25)
    elseif name=="Props" or name=="Props >" then
        -- Isometric cube.
        line(0,-0.9,0.85,-0.45);line(0.85,-0.45,0,0)
        line(0,0,-0.85,-0.45);line(-0.85,-0.45,0,-0.9)
        line(-0.85,-0.45,-0.85,0.45);line(-0.85,0.45,0,0.9)
        line(0,0.9,0.85,0.45);line(0.85,0.45,0.85,-0.45);line(0,0,0,0.9)
    elseif name=="Online Menu" then
        circle(0,0,0.85);line(-0.85,0,0.85,0);line(0,-0.85,0,0.85)
        for _,v in ipairs({-0.42,0.42}) do line(v,-0.7,v,0.7) end
    elseif name=="Combat" then
        circle(0,0,0.65);circle(0,0,0.12);line(-1,0,-0.45,0);line(0.45,0,1,0);line(0,-1,0,-0.45);line(0,0.45,0,1)
    elseif name=="Weapon" then
        line(-0.9,-0.4,0.9,-0.4);line(0.9,-0.4,0.75,0);line(0.75,0,-0.35,0);line(-0.35,0,-0.55,0.8);line(-0.55,0.8,-0.95,0.8);line(-0.95,0.8,-0.7,-0.1)
    else
        line(-0.85,0.5,-0.85,-0.1);line(-0.85,-0.1,-0.5,-0.65);line(-0.5,-0.65,0.5,-0.65);line(0.5,-0.65,0.85,-0.1);line(0.85,-0.1,0.85,0.5);line(-0.85,0.5,0.85,0.5);line(-0.8,-0.1,0.8,-0.1);circle(-0.55,0.65,0.15);circle(0.55,0.65,0.15)
    end
end


-- 6. Clavier / Entrees (Lapsus.IsKeyDown accepte les codes VK numeriques !)
function Lapsus_GetAsyncKeyState_compat(vk)
    if not vk then return false end
    if not L then return false end
    if L.IsKeyDown then
        local ok, down = pcall(L.IsKeyDown, vk)
        if ok and down then return true end
    end
    if L.IsKeyPressed then
        local ok, pressed = pcall(L.IsKeyPressed, vk)
        if ok and pressed then return true end
    end
    return false
end

-- 7. Souris
function Lapsus_GetMousePos_compat()
    if GetNuiCursorPosition then
        local nx, ny = GetNuiCursorPosition()
        if nx and ny then
            local sw, sh = 1920, 1080
            if L and L.GetScreenSize then
                local w, h = L.GetScreenSize()
                if w and w > 0 then sw, sh = w, h end
            elseif GetActiveScreenResolution then
                local w, h = GetActiveScreenResolution()
                if w and w > 0 then sw, sh = w, h end
            end
            return nx * sw, ny * sh
        end
    end
    return -1, -1
end

