-- UI-only bridge: FiveM runtime textures, matching the supplied reference.
do
local API=L
local protected=type(API.pcall)=="function" and API.pcall or pcall
local function nativeLong(hash,...)
    API = L
    assert(type(API.InvokeNative)=="function" and Citizen and type(Citizen.ResultAsLong)=="function","Resultat natif 64 bits indisponible")
    local args={...};args[#args+1]=Citizen.ResultAsLong()
    return API.InvokeNative(hash,table.unpack(args))
end
local function imageBase64(bytes)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local parts = {}
    local len = #bytes
    for i = 1, len, 3 do
        local a = bytes:byte(i)
        local b = bytes:byte(i+1)
        local c = bytes:byte(i+2)
        local number = a * 65536 + (b or 0) * 256 + (c or 0)
        local x = math.floor(number / 262144) % 64 + 1
        local y = math.floor(number / 4096) % 64 + 1
        local z = math.floor(number / 64) % 64 + 1
        local t = number % 64 + 1
        parts[#parts + 1] = alphabet:sub(x, x) .. alphabet:sub(y, y) .. (b and alphabet:sub(z, z) or '=') .. (c and alphabet:sub(t, t) or '=')
    end
    return table.concat(parts)
end

local function bannerDimensions(dataUrl)
    local encoded = dataUrl:match('^data:image/[%w]+;base64,(.+)$')
    if not encoded then return nil, nil end
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i = 1, #alphabet do lookup[alphabet:sub(i,i)] = i - 1 end
    local bytes = {}
    local buffer, bits = 0, 0
    for i = 1, math.min(#encoded, 196608) do
        local n = lookup[encoded:sub(i,i)]
        if n then
            buffer = buffer * 64 + n
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                bytes[#bytes + 1] = string.char(math.floor(buffer / 2^bits) % 256)
                buffer = buffer % 2^bits
            end
        end
    end
    local raw = table.concat(bytes)
    local function u16(pos) local a, b = raw:byte(pos, pos + 1); return b and a * 256 + b or nil end
    local function u32(pos) local a, b, c, d = raw:byte(pos, pos + 3); return d and ((a * 256 + b) * 256 + c) * 256 + d or nil end
    local w, h
    if raw:sub(1,8) == '\137PNG\13\10\26\10' then
        w, h = u32(17), u32(21)
    elseif raw:sub(1,2) == '\255\216' then
        local pos = 3
        while pos + 8 <= #raw do
            if raw:byte(pos) ~= 255 then pos = pos + 1
            else
                local marker = raw:byte(pos + 1)
                if marker == 255 then pos = pos + 1
                elseif marker == 0xD9 or marker == 0xDA then break
                elseif marker == 0x01 or (marker >= 0xD0 and marker <= 0xD8) then pos = pos + 2
                else
                    local length = u16(pos + 2)
                    if not length or length < 2 then break end
                    local sof = marker >= 0xC0 and marker <= 0xCF and marker ~= 0xC4 and marker ~= 0xC8 and marker ~= 0xCC
                    if sof and length >= 7 then h, w = u16(pos + 5), u16(pos + 7); break end
                    pos = pos + 2 + length
                end
            end
        end
    end
    if not w or not h or w < 1 or h < 1 or w > 32768 or h > 32768 then return nil, nil end
    return w, h
end

local dictionary, serial = nil, 0
function Lapsus_LoadTexture_compat(data)
    if type(data) ~= "string" or #data == 0 then return nil, 0, 0 end
    local url = data
    if not data:match('^data:image/') then
        local mime = data:sub(1,8) == '\137PNG\13\10\26\10' and 'png'
            or data:sub(1,2) == '\255\216' and 'jpeg' or nil
        if not mime then return nil, 0, 0 end
        url = 'data:image/' .. mime .. ';base64,' .. imageBase64(data)
    end
    local width, height = bannerDimensions(url)
    local ok, texture = pcall(function()
        if not dictionary then
            if type(CreateRuntimeTxd) == 'function' then
                dictionary = CreateRuntimeTxd('mirage_original_ui')
            elseif L and L.InvokeNative then
                dictionary = nativeLong(0x1F3AC778, 'mirage_original_ui')
            end
        end
        assert(dictionary and dictionary ~= 0, 'Texture dictionary unavailable')
        serial = serial + 1
        local name = 'image_' .. serial
        local handle = nil
        if type(CreateRuntimeTextureFromImage) == 'function' then
            handle = CreateRuntimeTextureFromImage(dictionary, name, url)
        elseif L and L.InvokeNative then
            handle = nativeLong(0x786D8BC3, dictionary, name, url)
        end
        assert(handle and handle ~= 0, 'Texture unavailable')
        return {dictionary = 'mirage_original_ui', name = name, ready = true}
    end)
    if not ok or not texture then
        
        return nil, 0, 0
    end
    return texture, width or 512, height or 128
end

function Lapsus_DrawImage_compat(tex, x, y, w, h, r, g, b, a, rounding, u1, v1, u2, v2)
    if not L or type(L.GetScreenSize) ~= "function" or type(L.InvokeNative) ~= "function" then
        return false
    end
    if type(tex) ~= "table" or not tex.ready or not tex.dictionary or not tex.name then
        return false
    end
    local sw, sh = L.GetScreenSize()
    if type(sw) ~= "number" or type(sh) ~= "number"
        or sw <= 0 or sh <= 0 or w <= 0 or h <= 0 then
        return false
    end
    -- Remplir l'ouverture du panneau dans la meme couche native que le PNG.
    -- Le fond noir reste opaque meme lorsque le PNG contient un canal alpha.
    if tex.logoBackdrop then
        L.InvokeNative(0x3A618A217E5154F0,
            (x + w / 2.0) / sw, (y + h / 2.0) / sh,
            w / sw, h / sh, 0, 0, 0, 255)
    end
    if tex.logoBackdrop and tex.sourceWidth and tex.sourceHeight then
        local scale = math.min(w / tex.sourceWidth, h / tex.sourceHeight)
        local fittedW = math.max(1, math.floor(tex.sourceWidth * scale + 0.5))
        local fittedH = math.max(1, math.floor(tex.sourceHeight * scale + 0.5))
        x = math.floor(x + (w - fittedW) / 2 + 0.5)
        y = math.floor(y + (h - fittedH) / 2 + 0.5)
        w, h = fittedW, fittedH
    end
    L.InvokeNative(
        0xE7FFAE5EBF23D890,
        tex.dictionary, tex.name,
        (x + w / 2.0) / sw, (y + h / 2.0) / sh,
        w / sw, h / sh, 0.0,
        _c(r or 1.0), _c(g or 1.0), _c(b or 1.0), _c(a)
    )
    return true
end

end

function Lapsus_LoadFont_compat(data, size) return nil end

-- 9. HTTP
function Lapsus_HttpGet_compat(url, headers, insecure)
    L = rawget(_G, "Lapsus") or L
    if not L or type(L.HttpGet) ~= "function" then return 0, nil end
    local first, second = L.HttpGet(url, headers, insecure)
    if type(first) == "table" then
        return tonumber(first.status or first.statusCode) or (first.success and 200 or 0),
            first.data or first.body or first.error
    end
    if type(first) == "number" then return first, second end
    return 0, nil
end

function Lapsus_HttpPost_compat(url, payload, contentType, insecure)
    if not L or not L.HttpPost then return 0, nil end
    local headers = nil
    if contentType then headers = {["Content-Type"] = contentType} end
    local res = L.HttpPost(url, payload, headers, insecure)
    if type(res) == "table" then
        return res.status or (res.success and 200 or 0), res.data or res.error
    end
    return 0, nil
end
-- PNG fourni par l'utilisateur, embarque sans requete HTTP.
do
local embeddedLogo = [=[data:image/png;base64,]=]
local embeddedLogoEntry, embeddedLogoPending
function Lapsus_LoadLogo_compat(url)
    local function publish(entry)
        _G._miniBannerTex, _G._loadingTex, _G._currentNotifIconTex = entry.tex, entry.tex, entry.tex
        _G._loadingTexW, _G._loadingTexH = entry.w, entry.h
        _G._notifIconTexCache = _G._notifIconTexCache or {}
        _G._notifIconTexCache[url or "embedded"] = entry.tex
    end
    if embeddedLogoEntry then publish(embeddedLogoEntry); return end
    if embeddedLogoPending then return end
    embeddedLogoPending = true
    Citizen.CreateThread(function()
        local lastError = "API indisponible"
        for attempt = 1, 5 do
            L = rawget(_G, "Lapsus") or L
            if L and type(Lapsus_LoadTexture_compat) == "function" then
                local ok, tex, w, h = pcall(Lapsus_LoadTexture_compat, embeddedLogo)
                if ok and tex then
                    tex.logoBackdrop = true
                    tex.sourceWidth, tex.sourceHeight = w, h
                    embeddedLogoEntry = {tex=tex, w=w, h=h}
                    publish(embeddedLogoEntry)
                    embeddedLogoPending = false
                    
                    return
                end
                lastError = ok and "Creation de texture impossible" or tostring(tex)
            end
            if attempt < 5 then Wait(attempt * 1000) end
        end
        embeddedLogoPending = false
        
    end)
end
Lapsus_LoadLogo_compat()
end

-- 10. Fichiers locaux
function Lapsus_SaveFile_compat(path, content)
    if io and io.open then
        local f = io.open(path, "w")
        if f then f:write(content or ""); f:close(); return true end
    end
    return false
end

function Lapsus_LoadFile_compat(path)
    if io and io.open then
        local f = io.open(path, "r")
        if f then local c = f:read("*all"); f:close(); return c end
    end
    return nil
end

-- 11. Gestion des Ressources & Natives
function Lapsus_InjectResource_compat(target, code, threadOpt)
    if not L or not L.InjectResource then return false end
    if target == "any" then target = nil end
    return L.InjectResource(target, code)
end

function Lapsus_BlockServerEvent_compat(block, eventName)
    if not L then return end
    if block then
        if L.AddBlockedEvent then L.AddBlockedEvent(eventName, "server") end
    else
        if L.RemoveBlockedEvent then L.RemoveBlockedEvent(eventName, "server") end
    end
end

function Lapsus_LockCameraPos_compat(lock)
    if not L then return end
    if L.SpoofServerCamera then L.SpoofServerCamera(lock and true or false) end
    if L.BlockCameraRotation then L.BlockCameraRotation(lock and true or false) end
end

do
local nextCheck, putinPresent = 0, false
local spoofEnabled, spoofBlocked = false, false
local function hasPutin()
    if _G._miragePutinDetected then return true end
    local now = type(GetGameTimer) == "function" and GetGameTimer() or 0
    if now < nextCheck then return putinPresent end
    nextCheck = now + 1000
    putinPresent = false
    if type(GetResourceState) == "function" then
        local ok, state = pcall(GetResourceState, "putin")
        if ok and state and state ~= "missing" and state ~= "unknown" then
            putinPresent = true
        end
    end
    -- La liste permet aussi de reconnaitre Putin avec une casse differente.
    if not putinPresent and type(GetNumResources) == "function"
        and type(GetResourceByFindIndex) == "function" then
        local ok, count = pcall(GetNumResources)
        if ok and type(count) == "number" then
            for i=0,count-1 do
                local found,name = pcall(GetResourceByFindIndex,i)
                if found and type(name)=="string" and name:lower()=="putin" then
                    putinPresent=true; break
                end
            end
        end
    end
    return putinPresent
end
function Lapsus_ResetPositionSpoof_compat()
    if Menu and Menu.State and Menu.State.soloSessionFullInvisActive then return end
    if L and type(L.SpoofPosition)=="function" and (spoofEnabled or spoofBlocked) then
        L.SpoofPosition(false)
    end
    spoofEnabled, spoofBlocked = false, false
end
function Lapsus_SetCameraPos_compat(x, y, z)
    if Menu and Menu.State and Menu.State.soloSessionFullInvisActive then return end
    if not L or type(L.SpoofPosition) ~= "function" then return end
    if hasPutin() then
        if not spoofBlocked then L.SpoofPosition(false) end
        spoofEnabled, spoofBlocked = false, true
        return
    end
    spoofBlocked = false
    L.SpoofPosition(true, x, y, z)
    spoofEnabled = true
end
end

function Lapsus_RequestRagdoll_compat(targetId) end

function Lapsus_Unload_compat()
    if Menu and Menu.State and Menu.State.staffAbuseActive and Menu.Actions.SetStaffAbuse then pcall(Menu.Actions.SetStaffAbuse,false) end
    if Menu and Menu.Actions and Menu.Actions.CleanupPunchAll then pcall(Menu.Actions.CleanupPunchAll) end
    if Menu and Menu.Actions and Menu.Actions.StopForcedCrosse then pcall(Menu.Actions.StopForcedCrosse) end
    _G._mirageMenuRunning=nil
    if L and type(L.SetNuiFocus)=='function' then pcall(L.SetNuiFocus,'mirage_live_menu',false) end
    if Menu and Menu.State and Menu.State.antiAimActive and Menu.Actions.SetAntiAim then
        pcall(Menu.Actions.SetAntiAim,false)
    end
    if Menu and Menu.State and Menu.State.weaponSizeActive
        and L and type(L.WeaponSize)=="function" then
        pcall(L.WeaponSize,false)
    end
    if Menu and Menu.State and Menu.State.spoofWeaponActive
        and L and type(L.SpoofServerWeapon)=="function" then
        pcall(L.SpoofServerWeapon,false)
    end
    if L and L.RestartEnvironment then L.RestartEnvironment() end
end

function Lapsus_CreateSpoofedPed_compat(type_, hash, x, y, z, heading, networked, ped)
    if CreatePed then
        return CreatePed(type_, hash, x, y, z, heading, networked or false, ped or false)
    end
    return 0
end


