    [298] = "F12", [300] = "ESC", [344] = "F11", [345] = "ENTER",
    [346] = "RETOUR", [347] = "SPACE",
    [348] = "MOUSE LEFT", [349] = "MOUSE RIGHT", [350] = "MOUSE MIDDLE",
