function Menu.Helpers.DrawHollowBorderRect(x, y, w, h, r, g, b, a, bgA, radius)
    if not Lapsus or not Lapsus_DrawRect_Filled then return end
    local rad   = radius or 6.0
    local thick = 1.0
    local borderAlpha = a or 0.75
    Lapsus_DrawRect_Filled(x - thick, y - thick, w + thick * 2, h + thick * 2, r, g, b, borderAlpha, rad + thick)
    -- Fond interieur : Noir pur 100% opaque (0 reflet)
    Lapsus_DrawRect_Filled(x, y, w, h, 0.0, 0.0, 0.0, 1.0, rad)
end

-- ============================================================
--  SYSTEME AUTH - Ã©tat global partagÃ© avec RenderBindingUI
-- ============================================================
_G.AuthState = {
    active       = false,   -- true = Ã©cran auth affichÃ©
    inputBuffer  = "",      -- ce que l'utilisateur a tapÃ©
    errorMsg     = "",      -- message d'erreur Ã  afficher
    errorTimer   = 0,       -- timestamp fin d'affichage erreur
    cursorBlink  = 0,       -- timer clignotement curseur
    -- Ã‰cran de confirmation IP auto-dÃ©tectÃ©e
    confirmMode  = false,   -- true = IP reconnue, en attente de confirmation
    confirmCode  = "",      -- code trouvÃ© via IP
    confirmName  = "",      -- dernier nom Rockstar liÃ© Ã  ce code
    confirmBtn   = 1,       -- 1 = Confirmer, 2 = Changer
}
-- Verrou global : le menu est INTERDIT tant que l'auth n'est pas validee
_G.AuthDone = false

-- Table VK -> caractere pour la saisie clavier (AZERTY + QWERTY)
local _authVKtoChar = {
    [0x41]="a",[0x42]="b",[0x43]="c",[0x44]="d",[0x45]="e",
    [0x46]="f",[0x47]="g",[0x48]="h",[0x49]="i",[0x4A]="j",
    [0x4B]="k",[0x4C]="l",[0x4D]="m",[0x4E]="n",[0x4F]="o",
    [0x50]="p",[0x51]="q",[0x52]="r",[0x53]="s",[0x54]="t",
    [0x55]="u",[0x56]="v",[0x57]="w",[0x58]="x",[0x59]="y",
    [0x5A]="z",
    [0x30]="0",[0x31]="1",[0x32]="2",[0x33]="3",[0x34]="4",
    [0x35]="5",[0x36]="6",[0x37]="7",[0x38]="8",[0x39]="9",
    -- PavÃ© numÃ©rique
    [0x60]="0",[0x61]="1",[0x62]="2",[0x63]="3",[0x64]="4",
