function RenderBindingUI()
    -- Bloquer l'affichage tant que les deux loadings ne sont pas termines
    if Menu.State.isLoading or Menu.State.showLoading then return end
    if not Lapsus or not Lapsus_DrawRect_Filled or not Lapsus_GetTextWidth_compat then return end

    local sw, sh = GetActiveScreenResolution()
    sw = (sw and sw > 0) and sw or 1920
    sh = (sh and sh > 0) and sh or 1080
    local cx, cy = sw / 2, sh / 2
    local padding = 28

    -- Récupération position souris + état clic
    local mx, my = -1, -1
    if Lapsus and type(Lapsus_GetMousePos_compat) == "function" then
        local gx, gy = Lapsus_GetMousePos_compat()
        if gx and gy and gx > 0 then mx, my = gx, gy end
    end
    if (mx < 0 or my < 0) and GetNuiCursorPosition then
        local nx, ny = GetNuiCursorPosition()
        if nx and ny then mx, my = nx * sw, ny * sh end
    end
    if _G._compactModalMouse then mx,my=_G._compactModalMouse(mx,my) end
    local clickDown = (Lapsus and Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x01)) or false
    local justClicked = clickDown and not _G._prevBindingUIClick
    _G._prevBindingUIClick = clickDown

    -- Couleur accent adaptée à la bannière (Bleu Mirage STRICT pendant bind et auth)
    local accentR, accentG, accentB
    if isFirstLoadBinding or (_G.AuthState and _G.AuthState.active) then
        accentR, accentG, accentB = 0.0, 95.0/255.0, 215.0/255.0
    elseif _G.IsMirageLuaActive and _G.IsMirageLuaActive() and _G.MirageBreathColor then
        local _cr, _cg, _cb = _G.MirageBreathColor(GetGameTimer())
        accentR, accentG, accentB = _cr/255.0, _cg/255.0, _cb/255.0
    else
        local _themeRGB = Menu.Colors and Menu.Colors.HeaderPink or {r=0,g=95,b=215}
        accentR = (_themeRGB.r or 0) / 255.0
        accentG = (_themeRGB.g or 95) / 255.0
        accentB = (_themeRGB.b or 215) / 255.0
    end
    if (accentR + accentG + accentB) < 0.3 then
        accentR, accentG, accentB = 0.0, 95.0/255.0, 215.0/255.0
    end

    -- ── CUSTOM KEYBOARD INPUT FOR CONFIG PROFILES ──────────────────────
    if _G.CustomInputActive and _G.CustomInputState then
        local now = GetGameTimer()
        local title = "CONFIGURATIONS"
        local sub = _G.CustomInputState.title or "Entrez le nom de la config"
        local buf = _G.CustomInputState.inputBuffer or ""
        local showCursor = ((now % 1000) < 500)
        local displayStr = buf .. (showCursor and "|" or " ")

        local thumbTex = _G._miniBannerTex or _G._loadingTex or _G._currentNotifIconTex
        local thumbSize = 64.0
        local thumbPad = 12.0

        local uiW = 420
        local uiH = thumbSize + thumbPad + 160
        local x = cx - uiW / 2
        local y = cy - uiH / 2

        Menu.Helpers.DrawHollowBorderRect(x, y, uiW, uiH, accentR, accentG, accentB, 0.8, 0.82, 10.0)

        local ix = cx - thumbSize / 2
        local iy = y + thumbPad
        if thumbTex and Lapsus_DrawImage_compat then
            thumbTex.ready = true
            Lapsus_DrawImage_compat(thumbTex, ix, iy, thumbSize, thumbSize, 1, 1, 1, 1, 8.0, 0, 0, 1, 1)
        end

        local off = thumbSize + thumbPad
        local function ct(txt, size, yOff, r, g, b, a)
            local tw = Lapsus_GetTextWidth_compat(txt, size)
            Lapsus_DrawText_compat(cx - tw / 2, y + off + yOff, txt, size, r, g, b, a or 1)
        end

        ct(title, 22, 10, 1, 1, 1, 1)
        ct(sub, 14, 36, 0.55, 0.55, 0.55, 1)

        local fieldW, fieldH = 260, 32
        local fx = cx - fieldW / 2
        local fy = y + off + 56
        Lapsus_DrawRect_Filled(fx, fy, fieldW, fieldH, 0.0, 0.0, 0.0, 0.95, 5.0)
        Lapsus_DrawRect_Filled(fx, fy + fieldH - 2, fieldW, 2, accentR, accentG, accentB, 0.95, 0.0)
        local mw = Lapsus_GetTextWidth_compat(displayStr, 20)
        Lapsus_DrawText_compat(cx - mw / 2, fy + 7, displayStr, 20, 1, 1, 1, 1)

        if _G.CustomInputState.errorMsg and _G.CustomInputState.errorMsg ~= "" then
            ct(_G.CustomInputState.errorMsg, 14, 100, 1, 0.3, 0.3, 1)
        else
            ct("ENTREE Valider  |  RETOUR Effacer  |  ECHAP Annuler", 12, 100, 0.35, 0.35, 0.35, 1)
        end
        return
    end

    -- ─── ECRAN GIVE INPUT (saisie arme custom) ────────────────────────────
    if _G.GiveInputState and _G.GiveInputState.active then
        local now = GetGameTimer()
        local buf = _G.GiveInputState.inputBuffer or ""
        local showCursor = ((now % 1000) < 500)
        local display = "weapon_" .. buf .. (showCursor and "|" or " ")

        local thumbTex  = _G._miniBannerTex or _G._loadingTex or _G._currentNotifIconTex
        local thumbSize = 64.0
        local thumbPad  = 12.0

        local uiW = 440
        local uiH = thumbSize + thumbPad + 176
        local x = cx - uiW / 2
        local y = cy - uiH / 2

        Menu.Helpers.DrawHollowBorderRect(x, y, uiW, uiH, accentR, accentG, accentB, 0.8, 0.82, 10.0)

        local ix = cx - thumbSize / 2
        local iy = y + thumbPad
        if thumbTex and Lapsus_DrawImage_compat then
            thumbTex.ready = true
            Lapsus_DrawImage_compat(thumbTex, ix, iy, thumbSize, thumbSize, 1, 1, 1, 1, 8.0, 0, 0, 1, 1)
        end

        local off = thumbSize + thumbPad
        local function ctg(txt, size, yOff, r, g, b, a)
            local tw = Lapsus_GetTextWidth_compat(txt, size)
            Lapsus_DrawText_compat(cx - tw / 2, y + off + yOff, txt, size, r, g, b, a or 1)
        end

        local modeLabel = (_G.GiveInputState.mode == "vipgive") and "VIP GIVE" or "GIVE"
        ctg(modeLabel .. " - ARME CUSTOM", 22, 10, 1, 1, 1, 1)
        ctg("Tapez le nom apres weapon_", 14, 36, 0.55, 0.55, 0.55, 1)

        local fieldW, fieldH = 310, 32
        local fx = cx - fieldW / 2
        local fy = y + off + 56
        Lapsus_DrawRect_Filled(fx, fy, fieldW, fieldH, 0.0, 0.0, 0.0, 0.95, 5.0)
        Lapsus_DrawRect_Filled(fx, fy + fieldH - 2, fieldW, 2, accentR, accentG, accentB, 0.95, 0.0)
        local dw = Lapsus_GetTextWidth_compat(display, 18)
        Lapsus_DrawText_compat(cx - dw / 2, fy + 7, display, 18, 1, 1, 1, 1)

        if _G.GiveInputState.errorMsg ~= "" and now < _G.GiveInputState.errorTimer then
            ctg(_G.GiveInputState.errorMsg, 14, 100, 1, 0.3, 0.3, 1)
        else
            ctg("ENTREE Valider  |  RETOUR Effacer  |  ECHAP Annuler", 12, 100, 0.35, 0.35, 0.35, 1)
        end
        ctg("Underscore  _  : touche  -  du clavier", 12, 120, 0.28, 0.28, 0.28, 1)

        local btnW2, btnH2 = 140, 26
        local bx2 = cx - btnW2 / 2
        local by2 = y + off + 140
        Lapsus_DrawRect_Filled(bx2, by2, btnW2, btnH2, 0.18, 0.18, 0.18, 0.9, 5.0)
        local btnTxt2 = "ENTREE  Donner"
        local btw2 = Lapsus_GetTextWidth_compat(btnTxt2, 14)
        Lapsus_DrawText_compat(cx - btw2 / 2, by2 + (btnH2 - 14) / 2, btnTxt2, 14, 0.75, 0.75, 0.75, 1)
        return
    end

    -- ─── ECRAN PED INPUT (saisie ped custom) ────────────────────────────────
    if _G.PedInputState and _G.PedInputState.active then
        local now2   = GetGameTimer()
        local buf2   = _G.PedInputState.inputBuffer or ""
        local show2  = ((now2 % 1000) < 500)
        local disp2  = buf2 .. (show2 and "|" or " ")

        local thumbTex2  = _G._miniBannerTex or _G._loadingTex or _G._currentNotifIconTex
        local thumbSize2 = 64.0
        local thumbPad2  = 12.0

        local uiW2 = 440
        local uiH2 = thumbSize2 + thumbPad2 + 176
        local x2   = cx - uiW2 / 2
        local y2   = cy - uiH2 / 2

        Menu.Helpers.DrawHollowBorderRect(x2, y2, uiW2, uiH2, accentR, accentG, accentB, 0.8, 0.82, 10.0)

        local ix2 = cx - thumbSize2 / 2
        local iy2 = y2 + thumbPad2
        if thumbTex2 and Lapsus_DrawImage_compat then
            thumbTex2.ready = true
            Lapsus_DrawImage_compat(thumbTex2, ix2, iy2, thumbSize2, thumbSize2, 1, 1, 1, 1, 8.0, 0, 0, 1, 1)
        end

        local off2 = thumbSize2 + thumbPad2
        local function ctgP(txt, size, yOff, r, g, b, a)
            local tw = Lapsus_GetTextWidth_compat(txt, size)
            Lapsus_DrawText_compat(cx - tw / 2, y2 + off2 + yOff, txt, size, r, g, b, a or 1)
        end

        local isClientMode = (_G.PedInputState and _G.PedInputState.mode == "client")
        ctgP(isClientMode and "CLIENT PED CUSTOM" or "PED CUSTOM", 22, 10, 1, 1, 1, 1)
        ctgP(isClientMode and "Tapez le nom du ped (applique uniquement en local)" or "Tapez le nom du modele de ped", 14, 36, 0.55, 0.55, 0.55, 1)

        local fW2, fH2 = 310, 32
        local fx2 = cx - fW2 / 2
        local fy2 = y2 + off2 + 56
        Lapsus_DrawRect_Filled(fx2, fy2, fW2, fH2, 0.0, 0.0, 0.0, 0.95, 5.0)
        Lapsus_DrawRect_Filled(fx2, fy2 + fH2 - 2, fW2, 2, accentR, accentG, accentB, 0.95, 0.0)
        local dw2 = Lapsus_GetTextWidth_compat(disp2, 18)
        Lapsus_DrawText_compat(cx - dw2 / 2, fy2 + 7, disp2, 18, 1, 1, 1, 1)

        if _G.PedInputState.errorMsg ~= "" and now2 < _G.PedInputState.errorTimer then
            ctgP(_G.PedInputState.errorMsg, 14, 100, 1, 0.3, 0.3, 1)
        else
            ctgP("ENTREE Valider  |  RETOUR Effacer  |  ECHAP Annuler", 12, 100, 0.35, 0.35, 0.35, 1)
        end
        ctgP(isClientMode and "Ex: a_c_cat_01  /  ft-chimpanzee  /  a_c_chop" or "Ex: a_m_y_beach_01  /  mp_m_freemode_01", 12, 120, 0.28, 0.28, 0.28, 1)

        local btnWP, btnHP = 140, 26
        local bxP = cx - btnWP / 2
        local byP = y2 + off2 + 140
        Lapsus_DrawRect_Filled(bxP, byP, btnWP, btnHP, 0.18, 0.18, 0.18, 0.9, 5.0)
        local btnTxtP = isClientMode and "ENTREE  Appliquer" or "ENTREE  Spawner"
        local btwP = Lapsus_GetTextWidth_compat(btnTxtP, 14)
        Lapsus_DrawText_compat(cx - btwP / 2, byP + (btnHP - 14) / 2, btnTxtP, 14, 0.75, 0.75, 0.75, 1)
        return
    end
    -- ── FIN ECRAN PED INPUT ──────────────────────────────────────────────────

    -- ── CARTES BIND / AUTH : compactes, logo agrandi, bordure soignée ──────────
    local CARD_W = 400
    local PAD    = 18

    local function drawCard(x, y, w, h)
        local function paint()
        local rad = 12.0
        -- ombre douce multi-couches
        for i = 4, 1, -1 do
            Lapsus_DrawRect_Filled(x - i * 2, y - i * 2, w + i * 4, h + i * 4, 0, 0, 0, 0.09, rad + i * 2)
        end
        -- halo couleur accent
        Lapsus_DrawRect_Filled(x - 3, y - 3, w + 6, h + 6, accentR, accentG, accentB, 0.14, rad + 3)
        -- bordure accent nette
        Lapsus_DrawRect_Filled(x - 1.5, y - 1.5, w + 3, h + 3, accentR, accentG, accentB, 0.95, rad + 1.5)
        -- fond noir pur uniforme (sans reflet)
        Lapsus_DrawRect_Filled(x, y, w, h, 0.0, 0.0, 0.0, 1.0, rad)
        end
        local tex = _G._miniBannerTex or _G._loadingTex or _G._currentNotifIconTex
        if tex then
            Lapsus_OutsideImage_compat(math.floor(x + PAD + 6), math.floor(y + 22), 40, 40, paint)
        else
            paint()
        end
    end

    local function drawHeader(x, y, title, subtitle)
        local logoS = 52
        local lx, ly = math.floor(x + PAD), math.floor(y + 16)
        local inset = 6
        -- anneau accent autour du logo
        local function paintLogoBorder()
        Lapsus_DrawRect_Filled(lx - 2, ly - 2, logoS + 4, logoS + 4, accentR, accentG, accentB, 0.60, 13.0)
        Lapsus_DrawRect_Filled(lx - 1, ly - 1, logoS + 2, logoS + 2, 0.0, 0.0, 0.0, 1.0, 12.0)
        end
        if _G._miniBannerTex or _G._loadingTex or _G._currentNotifIconTex then
            Lapsus_OutsideImage_compat(lx + inset, ly + inset, logoS - inset * 2, logoS - inset * 2, paintLogoBorder)
        else
            paintLogoBorder()
        end
        local logoTex = _G._miniBannerTex or _G._loadingTex or _G._currentNotifIconTex
        if logoTex and Lapsus_DrawImage_compat then
            logoTex.ready = true
            Lapsus_DrawImage_compat(logoTex, lx + inset, ly + inset, logoS - inset * 2, logoS - inset * 2, 1, 1, 1, 1, 0, 0, 0, 1, 1)
        end
        Lapsus_DrawText_compat(lx + logoS + 14, ly + 2, title, 18, 1.0, 1.0, 1.0, 1.0)
        Lapsus_DrawText_compat(lx + logoS + 14, ly + 26, subtitle, 12, 0.70, 0.74, 0.80, 0.95)
    end

    local function drawField(fx, fy, fw, fh)
        Lapsus_DrawRect_Filled(fx - 1, fy - 1, fw + 2, fh + 2, accentR, accentG, accentB, 0.55, 9.0)
        Lapsus_DrawRect_Filled(fx, fy, fw, fh, 0.0, 0.0, 0.0, 1.0, 8.0)
    end

    local function drawButton(bx, by, bw, bh, label, hover, primary)
        local m = hover and 0.18 or 0.0
        if primary then
            Lapsus_DrawRect_Filled(bx - 1, by - 1, bw + 2, bh + 2, accentR, accentG, accentB, hover and 0.95 or 0.50, 9.0)
            Lapsus_DrawRect_Filled(bx, by, bw, bh,
                math.min(accentR + (1 - accentR) * m, 1), math.min(accentG + (1 - accentG) * m, 1), math.min(accentB + (1 - accentB) * m, 1), 1.0, 8.0)
        else
            Lapsus_DrawRect_Filled(bx - 1, by - 1, bw + 2, bh + 2, 0.30, 0.34, 0.42, hover and 0.95 or 0.60, 9.0)
            Lapsus_DrawRect_Filled(bx, by, bw, bh, hover and 0.16 or 0.0, hover and 0.16 or 0.0, hover and 0.16 or 0.0, 1.0, 8.0)
        end
        local tw = Lapsus_GetTextWidth_compat(label, 13)
        Lapsus_DrawText_compat(bx + (bw - tw) / 2, by + (bh - 13) / 2, label, 13, 1, 1, 1, primary and 1.0 or 0.88)
    end

    -- ── ECRAN KEYBINDER (Touche d'ouverture) ────────────────────────────────
    if isFirstLoadBinding then
        local cardW, cardH = CARD_W, 138
        local cardX, cardY = cx - cardW / 2, cy - cardH / 2
        drawCard(cardX, cardY, cardW, cardH)
        drawHeader(cardX, cardY, "MIRAGE", "Appuyez sur la touche qui l'ouvre")

        local rowY, rowH, btnW = cardY + 84, 38, 96
        local inX, inW = cardX + PAD, cardW - PAD * 2 - btnW - 8
        drawField(inX, rowY, inW, rowH)
        local keyName = (startupBindingName and startupBindingName ~= "") and startupBindingName or "F12"
        Lapsus_DrawText_compat(inX + 14, rowY + (rowH - 15) / 2, keyName, 15, 1.0, 1.0, 1.0, 1.0)

        local btnX = inX + inW + 8
        local isHover = (mx >= btnX and mx <= btnX + btnW and my >= rowY and my <= rowY + rowH)
        drawButton(btnX, rowY, btnW, rowH, "TERMINÉ", isHover, true)
        if isHover and justClicked then
            _G._bindingDoneClicked = true
            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end
        return
    end

    -- ── ECRAN AUTHENTIFICATION ───────────────────────────────────────────────
    if _G.AuthState.active then
        local now = GetGameTimer()

        -- Mode confirmation IP
        if _G.AuthState.confirmMode then
            local cardW, cardH = CARD_W, 138
            local cardX, cardY = cx - cardW / 2, cy - cardH / 2
            drawCard(cardX, cardY, cardW, cardH)
            local nameDisplay = (_G.AuthState.confirmName and _G.AuthState.confirmName ~= "") and _G.AuthState.confirmName or "Inconnu"
            drawHeader(cardX, cardY, "MIRAGE", "IP reconnue : " .. nameDisplay)

            local rowY, rowH = cardY + 84, 38
            local btnW = (cardW - PAD * 2 - 10) / 2
            local b1x, b2x = cardX + PAD, cardX + PAD + btnW + 10
            local hover1 = (mx >= b1x and mx <= b1x + btnW and my >= rowY and my <= rowY + rowH)
            local hover2 = (mx >= b2x and mx <= b2x + btnW and my >= rowY and my <= rowY + rowH)
            local sel = _G.AuthState.confirmBtn or 1
            drawButton(b1x, rowY, btnW, rowH, "CONFIRMER", hover1 or sel == 1, true)
            drawButton(b2x, rowY, btnW, rowH, "CHANGER DE CLÉ", hover2 or sel == 2, false)

            if hover1 and justClicked then
                _G._authConfirmBtn1Clicked = true
                PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            elseif hover2 and justClicked then
                _G._authConfirmBtn2Clicked = true
                PlaySoundFrontend(-1, "BACK", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            end
            return
        end

        -- Mode saisie
        local cardW, cardH = CARD_W, 158
        local cardX, cardY = cx - cardW / 2, cy - cardH / 2
        drawCard(cardX, cardY, cardW, cardH)
        drawHeader(cardX, cardY, "MIRAGE", "Entrez votre clé d'authentification")

        local rowY, rowH = cardY + 84, 38
        local pasteW, doneW = 38, 96
        local inX = cardX + PAD
        local inW = cardW - PAD * 2 - pasteW - doneW - 16
        drawField(inX, rowY, inW, rowH)

        local buf = _G.AuthState.inputBuffer or ""
        local showCursor = ((now % 1000) < 500)
        if #buf == 0 then
            Lapsus_DrawText_compat(inX + 14, rowY + (rowH - 13) / 2, "Entrez votre clé...", 13, 0.40, 0.45, 0.52, 0.8)
            if showCursor then
                Lapsus_DrawText_compat(inX + 14, rowY + (rowH - 15) / 2, "|", 15, accentR, accentG, accentB, 0.95)
            end
        else
            Lapsus_DrawText_compat(inX + 14, rowY + (rowH - 14) / 2, buf .. (showCursor and "|" or " "), 14, 1.0, 1.0, 1.0, 1.0)
        end

        -- Bouton Coller : icône dessinée (le texte emoji s'affichait "?")
        local pasteX = inX + inW + 8
        local isPasteHover = (mx >= pasteX and mx <= pasteX + pasteW and my >= rowY and my <= rowY + rowH)
        Lapsus_DrawRect_Filled(pasteX - 1, rowY - 1, pasteW + 2, rowH + 2, accentR, accentG, accentB, isPasteHover and 0.95 or 0.45, 9.0)
        Lapsus_DrawRect_Filled(pasteX, rowY, pasteW, rowH, isPasteHover and 0.12 or 0.0, isPasteHover and 0.12 or 0.0, isPasteHover and 0.12 or 0.0, 1.0, 8.0)
        do
            local iw, ih = 16, 20
            local ix = pasteX + (pasteW - iw) / 2
            local iy = rowY + (rowH - ih) / 2
            Lapsus_DrawRect_Filled(ix, iy + 3, iw, ih - 3, 0.50, 0.55, 0.65, 1.0, 3.0)      -- planche
            Lapsus_DrawRect_Filled(ix + 1.5, iy + 5, iw - 3, ih - 7, 0.94, 0.95, 0.98, 1.0, 2.0) -- feuille
            Lapsus_DrawRect_Filled(ix + 4, iy, iw - 8, 6, 0.26, 0.31, 0.42, 1.0, 2.0)       -- pince
            Lapsus_DrawRect_Filled(ix + 4, iy + 8, iw - 8, 1.5, 0.45, 0.50, 0.60, 1.0, 0.0) -- lignes
            Lapsus_DrawRect_Filled(ix + 4, iy + 12, iw - 8, 1.5, 0.45, 0.50, 0.60, 1.0, 0.0)
        end
        if isPasteHover and justClicked then
            _G._authPasteClicked = true
            if _G.DoAuthPaste then pcall(_G.DoAuthPaste) end
            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end

        -- Bouton TERMINÉ
        local btnX = pasteX + pasteW + 8
        local isDoneHover = (mx >= btnX and mx <= btnX + doneW and my >= rowY and my <= rowY + rowH)
        drawButton(btnX, rowY, doneW, rowH, "TERMINÉ", isDoneHover, true)
        if isDoneHover and justClicked then
            _G._authDoneClicked = true
            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end

        -- Erreur / aide
        local footY = cardY + 84 + rowH + 10
        if _G.AuthState.errorMsg and _G.AuthState.errorMsg ~= "" and now < _G.AuthState.errorTimer then
            local ew = Lapsus_GetTextWidth_compat(_G.AuthState.errorMsg, 12)
            Lapsus_DrawText_compat(cx - ew / 2, footY, _G.AuthState.errorMsg, 12, 1.0, 0.35, 0.35, 1.0)
        else
            local help = "ENTREE Valider  |  Icône ou CTRL+V pour coller"
            local hw = Lapsus_GetTextWidth_compat(help, 11)
            Lapsus_DrawText_compat(cx - hw / 2, footY, help, 11, 0.42, 0.46, 0.52, 0.9)
        end
        return
    end

    -- ── ECRAN BIND D'OPTION (couleur du thème actif) ─────────────────────────
    if isBindingNoclip then
        local cardW, cardH = CARD_W, 138
        local cardX, cardY = cx - cardW / 2, cy - cardH / 2
        drawCard(cardX, cardY, cardW, cardH)
        local title = bindingActionData and bindingActionData.label or "Option"
        drawHeader(cardX, cardY, "BIND : " .. title, bindingText or "Appuyez sur une touche pour assigner")

        local rowY, rowH, btnW = cardY + 84, 38, 96
        local inX, inW = cardX + PAD, cardW - PAD * 2 - btnW - 8
        drawField(inX, rowY, inW, rowH)
        local keyText = bindingKeyDisplay ~= "" and bindingKeyDisplay or "Aucune"
        Lapsus_DrawText_compat(inX + 14, rowY + (rowH - 15) / 2, keyText, 15, 1.0, 1.0, 1.0, 1.0)
        drawButton(inX + inW + 8, rowY, btnW, rowH, "TERMINÉ", false, true)
        return
    end
end

