local dynastyNotifications = {}

function Menu.Helpers.ShortNotification(value)
    local text=tostring(value or ''):gsub('~[^~]+~',''):gsub('%s+',' ')
    local category,body=text:match('^%s*%[%s*(.-)%s*%]%s*(.*)$')
    category=category and category:match('^%s*(.-)%s*$')
    body=(body or text):match('^%s*(.-)%s*$')
    if category and category:upper()=='REDSIDE' then return category .. ' : ' .. body end
    local generic={AC=true,SESSION=true,PED=true,CONFIG=true,BIND=true,ERREUR=true,STYLE=true,VEHICLE=true,TELEPORT=true}
    local lower=body:lower()
    local label=category and not generic[category:upper()] and category or nil
    if lower:find('erreur',1,true) or lower:find('echec',1,true) or lower:find('refus',1,true)
        or lower:find('impossible',1,true) or lower:find('introuvable',1,true) then
        return (label or category or 'Action')..' : echec'
    end
    local toggle=body:match('%f[%a](ON)%f[%A]') or body:match('%f[%a](OFF)%f[%A]')
    if toggle then
        local name=label or body:gsub('%f[%a]ON%f[%A]',''):gsub('%f[%a]OFF%f[%A]','')
        name=name:gsub('%b()',''):gsub('[%[%]:]',''):match('^%s*(.-)%s*$')
        if name=='' then name=category or 'Option' end
        return name..' '..toggle
    end
    body=body:gsub('Chargement demande%s*:%s*',''):gsub('Restauration demandee','Ped normal')
        :gsub(' detecte.*$',' detecte'):gsub(' neutralise.*$',' OK')
        :gsub(' —.*$',''):gsub('%s*|.*$',''):gsub('%.%.%.$','')
    if label and (lower:find('activ',1,true) or lower=='ok') then return label..' ON' end
    if label and body~='' then return label..' : '..body end
    return body~='' and body or category or 'OK'
end

function ShowDynastyNotification(text)
    if not text or text == "?" or text:match("^%?$") then return end
    local cleanText = Menu.Helpers.ShortNotification(text)
    dynastyNotifications = {}
    table.insert(dynastyNotifications, {
        text = cleanText,
        time = GetGameTimer(),
    })
end

function DrawDynastyNotify()
    if not dynastyNotifications or #dynastyNotifications == 0 then return end

    local sw, sh = GetActiveScreenResolution()
    local x_root = sw * 0.015
    local y_root = sh * 0.74
    local rowH = 44.0
    local spacing = 49.0
    local currentTime = GetGameTimer()
    local totalLifetime = 3000

    for i = #dynastyNotifications, 1, -1 do
        local n = dynastyNotifications[i]
        local elapsed = currentTime - n.time

        if elapsed > totalLifetime then
            table.remove(dynastyNotifications, i)
        else
            local alpha = 1.0
            if elapsed > (totalLifetime - 300) then alpha = 1.0 - (elapsed - (totalLifetime - 300)) / 300 end

            local label = n.text:gsub("~[^~]+~", "")
            if not label or label == "" or label == "?" then
                table.remove(dynastyNotifications, i)
                goto continue_notify
            end

            -- Couleur accent = theme banniere active (MIRAGE breathing si MirageLua)
            local ar, ag, ab
            if _G.IsMirageLuaActive and _G.IsMirageLuaActive() and _G.MirageBreathColor then
                local cr, cg, cb = _G.MirageBreathColor(currentTime)
                ar, ag, ab = cr/255.0, cg/255.0, cb/255.0
            else
                local rgb = Menu.Colors.SelectedBg or {r=255, g=255, b=255}
                ar = (rgb.r or 255) / 255.0
                ag = (rgb.g or 255) / 255.0
                ab = (rgb.b or 255) / 255.0
            end

            -- Icone de notification propre a la banniere active (ou M officiel, JAMAIS la banniere etiree)
            local thumbTex  = _G._currentNotifIconTex or _G._loadingTex
            local _activeBanner = Menu.AvailableBanners and Menu.AvailableBanners[Menu.BannerIndex]
            local thumbSize = math.min(34, ((_activeBanner and _activeBanner.notifIconSize) or 42) * 0.90)
            local iconPad   = thumbSize + 6.0

            local minW = 160.0
            local w = minW
            if Lapsus and Lapsus_GetTextWidth_compat then
                w = math.max(minW, Lapsus_GetTextWidth_compat(label, 17) + 16.0 + iconPad + 14.0)
            end

            w=math.min(w,420,sw-x_root-16)
            local displayLabel,displaySize=Lapsus_FitText_compat(label,17,w-iconPad-24,rowH-20)
            local curX = x_root
            local curY = y_root + (#dynastyNotifications - i) * spacing

            if Lapsus and Lapsus_DrawRect_Filled and Lapsus_DrawText_compat then
                local radius = 6.0
                -- Contour neon externe
                local function drawNotificationPanel()
                    Menu.Helpers.DrawHollowBorderRect(curX, curY, w, rowH, ar, ag, ab, 0.65 * alpha, 0.82 * alpha, radius)
                end
                local iconX = curX + 6.0
                local iconY = curY + (rowH - thumbSize) / 2
                Lapsus_OutsideImage_compat(iconX, iconY, thumbSize, thumbSize, drawNotificationPanel)

                -- Mini-bannière officielle (https://i.imgur.com/JfO3bzD.png)
                local notifBannerTex = _G._miniBannerTex or thumbTex or _G._loadingTex
                local drawn = false
                if notifBannerTex and Lapsus_DrawImage_compat then
                    notifBannerTex.ready = true
                    drawn = Lapsus_DrawImage_compat(notifBannerTex, iconX, iconY, thumbSize, thumbSize, 1, 1, 1, alpha, 6.0, 0, 0, 1, 1)
                end
                if not drawn then
                    -- Secours visuel garanti : logo stylisé avec contour accent (jamais de carré noir vide)
                    Lapsus_DrawRect_Filled(iconX, iconY, thumbSize, thumbSize, 0.05, 0.06, 0.08, 0.95 * alpha, 6.0)
                    Lapsus_DrawRect_Border(iconX, iconY, thumbSize, thumbSize, ar, ag, ab, 0.80 * alpha, 6.0, 1.5)
                    local mSz = math.floor(thumbSize * 0.58)
                    local mW  = (Lapsus_GetTextWidth_compat and Lapsus_GetTextWidth_compat("M", mSz)) or (mSz * 0.6)
                    local mx  = iconX + (thumbSize - mW) * 0.5
                    local my  = iconY + (thumbSize - mSz) * 0.45
                    Lapsus_DrawText_compat(mx + 1, my + 1, "M", mSz, 0.0, 0.0, 0.0, 0.7 * alpha)
                    Lapsus_DrawText_compat(mx, my, "M", mSz, ar, ag, ab, 1.0 * alpha)
                end

                -- Texte centre verticalement
                local textOffX = curX + 6.0 + iconPad
                local textY    = curY + (rowH - displaySize) / 2 - 2
                Lapsus_DrawText_compat(textOffX, textY, displayLabel, displaySize, 0.98, 0.98, 0.98, alpha)

                -- Barre de progression : longueur = largeur du texte seulement
                local barStartX = textOffX
                local labelW    = (Lapsus_GetTextWidth_compat and Lapsus_GetTextWidth_compat(displayLabel, displaySize)) or 80.0
                local maxBarW   = labelW
                local progress  = 1.0 - (elapsed / totalLifetime)
                local barW      = math.max(2.0, maxBarW * progress)
                local barY      = curY + rowH - 14.0
                Lapsus_DrawRect_Filled(barStartX, barY, maxBarW, 2.0, 0.18, 0.18, 0.18, 0.6 * alpha, 1.0)
                Lapsus_DrawRect_Filled(barStartX, barY, barW, 2.0, ar, ag, ab, 0.95 * alpha, 1.0)
            end
        end
        ::continue_notify::
    end
end

function Menu.Helpers.DrawTextCustom(text, x, y, scale, font, r, g, b, a, center)
    a = math.max(0, math.min(255, math.floor(a or 255)))
    SetTextFont(font or 0)
    SetTextScale(scale, scale)
    SetTextColour(r, g, b, math.floor(a * (Menu.State.menuAlpha / 255)))
    if center then SetTextCentre(true) end
    BeginTextCommandDisplayText("STRING")
    AddTextComponentSubstringPlayerName(text)
    EndTextCommandDisplayText(x, y)
end

