-- Résout l'état ON/OFF d'un bind à partir de son menu + index
local function GetBindToggleState(menu, index)
    local S = Menu.State
    if menu=="VIP_GIVE" or (menu=="WEAPON" and S.weaponTab==2) then
        local list=menu=="VIP_GIVE" and Menu.Helpers.GetDynaGiveOptions() or Menu.Helpers.GetWeaponGiveOptions()
        local item=list[index]
        if type(item)=="table" and item.id=="spoof_weapon" then return true,S.spoofWeaponActive end
    end
    if menu == "MOVEMENT" then
        if index == 1 then return true, S.noclipActive
        elseif index == 3 then return true, S.slideActive
        elseif index == 5 then return true, (_G.freecam_active or false)
        elseif index == 7 then return true, (S.freecamInfoVisible ~= false)
        end
    elseif menu == "MAIN" then
        return false,false
    elseif menu == "COMBAT" then
        if index == 1 then return true, S.shootVisionActive
        elseif index == 2 then return true, S.rapidFireActive
        elseif index == 3 then return true, S.damageBoostActive
        elseif index == 4 then return true, S.fastPunchActive
        elseif index == 5 then return true, S.magicBulletActive
        end
    elseif menu == "WEAPON" then
        if index == 2 then return true, S.noReloadActive
        elseif index == 3 then return true, S.infiniteAmmoActive
        elseif index == 4 then return true, S.noSpreadActive
        elseif index == 5 then return true, S.noRecoilActive
        end
    elseif menu == "VEHICLE" then
        if index == 1 then return true, S.easyHandlingActive
        elseif index == 2 then return true, S.carryActive
        elseif index == 3 then return true, (shiftBoostActive or false)
        elseif index == 4 then return true, S.fovWarpActive
        end
    end
    -- Pas de toggle connu pour ce bind
    return false, false
end


-- ===================================================================
-- SPECTATOR LIST HUD (Affiche en temps réel les joueurs qui vous regardent)
-- ===================================================================
function Menu.Helpers.GetSpectatorList()
    local spectators = {}
    local localPlayer = PlayerId()
    local localPed = PlayerPedId()
    if not DoesEntityExist(localPed) then return spectators end
    local localCoords = GetEntityCoords(localPed)

    for _, pid in ipairs(GetActivePlayers()) do
        if pid ~= localPlayer then
            local pPed = GetPlayerPed(pid)
            if pPed and pPed ~= 0 and DoesEntityExist(pPed) then
                local isSpec = false

                -- 1. Native FiveM Spectating Check
                if NetworkIsPlayerSpectating and NetworkIsPlayerSpectating(pid) then
                    isSpec = true
                -- 2. Direct Targetting / Aiming Check
                elseif IsPlayerTargettingEntity and IsPlayerTargettingEntity(pid, localPed) then
                    isSpec = true
                -- 3. Native IsPedSpectating
                elseif IsPedSpectating and IsPedSpectating(pPed) then
                    isSpec = true
                -- 4. Spectator Proximity & Invisibility / Freecam / Attachment Check
                else
                    local pCoords = GetEntityCoords(pPed)
                    local dist = #(localCoords - pCoords)
                    if dist < 25.0 and (not IsEntityVisible(pPed) or not IsPedOnFoot(pPed) or IsPedInAnyVehicle(pPed, false)) then
                        isSpec = true
                    end
                end

                if isSpec then
                    local name = GetPlayerName(pid) or ("Joueur " .. pid)
                    table.insert(spectators, { id = pid, name = name })
                end
            end
        end
    end
    return spectators
end

function DrawSpectatorListHUD()
    if not _G.AuthDone then return end
    if not Menu.State.spectatorListVisible then return end
    if not Lapsus or not Lapsus_DrawRect_Filled or not Lapsus_DrawText_compat then return end

    local specs = Menu.Helpers.GetSpectatorList()

    -- Alerte notification si un nouveau spectateur commence a nous regarder
    _G._lastSpecList = _G._lastSpecList or {}
    local currentSpecIds = {}
    for _, s in ipairs(specs) do
        currentSpecIds[s.id] = s.name
        if not _G._lastSpecList[s.id] then
            ShowDynastyNotification("[ SPECTATEUR ] " .. s.name .. " vous regarde !")
        end
    end
    _G._lastSpecList = currentSpecIds

    local w, h     = GetActiveScreenResolution()
    local resScale = (h / 1080.0) * 0.95
    local menuSc   = (_G.menuScale or 1.0) * resScale
    local fontSize = math.floor(17.0 * menuSc)
    local lineH    = math.floor(25.0 * menuSc)
    local padX     = math.floor(10.0 * menuSc)
    local padY     = math.floor(8.0  * menuSc)
    local margin   = math.floor(14.0 * menuSc)

    -- Couleur theme
    local rgb = Menu.Colors.SelectedBg or {r=0, g=95, b=215}
    local tr = (rgb.r or 0) / 255.0
    local tg = (rgb.g or 95) / 255.0
    local tb = (rgb.b or 215) / 255.0

    local titleText = string.format("[ SPECTATEURS : %d ]", #specs)
    local displayLines = math.max(1, #specs)
    local totalLines   = displayLines + 1
    local boxH = totalLines * lineH + padY * 2
    local boxW = math.floor(220.0 * menuSc)

    -- Positionnement au milieu en haut
    local bx = (w - boxW) / 2.0
    local by = math.floor(15.0 * menuSc)

    -- Fond 0.98 opaque + Vrai contour arrondi aux couleurs du theme (style notification)
    if Menu.Helpers and Menu.Helpers.DrawHollowBorderRect then
        Menu.Helpers.DrawHollowBorderRect(bx, by, boxW, boxH, tr, tg, tb, 0.75, 0.80, 6.0)
    else
        Lapsus_DrawRect_Filled(bx, by, boxW, boxH, 0.0, 0.0, 0.0, 0.98, 6.0)
    end

    -- Titre
    if Lapsus_GetTextWidth_compat then
        local tW = Lapsus_GetTextWidth_compat(titleText, fontSize)
        Lapsus_DrawText_compat(bx + (boxW - tW) / 2.0, by + padY, titleText, fontSize, tr, tg, tb, 0.95)
    else
        Lapsus_DrawText_compat(bx + padX, by + padY, titleText, fontSize, tr, tg, tb, 0.95)
    end

    -- Liste des spectateurs
    if #specs == 0 then
        local lineY = by + padY + lineH
        Lapsus_DrawText_compat(bx + padX, lineY, "Aucun spectateur", fontSize - 2, 0.55, 0.55, 0.55, 0.85)
    else
        for i, s in ipairs(specs) do
            local lineY = by + padY + i * lineH
            local textStr = string.format("%s", s.name)
            Lapsus_DrawText_compat(bx + padX, lineY, textStr, fontSize - 1, 0.95, 0.95, 0.95, 0.95)
        end
    end
end

function DrawActiveBindsHUD()
    if not _G.AuthDone then return end
    if not Menu.State.hudBindsVisible then _G._hudBindHitboxes = {}; return end
    if not _G.UniversalKeyBinds then return end
    if type(Lapsus_DrawText_compat) ~= "function" then return end

    local binds = {}
    for ctrlId, bd in pairs(_G.UniversalKeyBinds) do
        local keyName = Menu.Helpers.GetKeyName(bd.vk, ctrlId)
        local label   = bd.label or "?"
        local isToggle, active = GetBindToggleState(bd.menu, bd.index)
        table.insert(binds, { key = keyName, label = label, isToggle = isToggle, active = active, menu = bd.menu, index = bd.index })
    end
    if #binds == 0 then _G._hudBindHitboxes = {}; return end
    table.sort(binds, function(a, b) return a.label < b.label end)

    local w, h     = GetActiveScreenResolution()
    local resScale = (h / 1080.0) * 0.95
    local menuSc   = (_G.menuScale or 1.0) * resScale
    local fontSize = math.max(12, math.floor(18.0 * menuSc))
    local lineH    = math.max(fontSize + 10, math.floor(28.0 * menuSc))
    local padX     = math.floor(10.0 * menuSc)
    local padY     = math.max(8, math.floor(10.0 * menuSc))
    local margin   = math.floor(14.0 * menuSc)

    -- Couleur thème
    local tr, tg, tb = 0.86, 0.86, 0.86
    if _G.IsMirageLuaActive and _G.IsMirageLuaActive() and _G.MirageBreathColor then
        local cr, cg, cb = _G.MirageBreathColor(GetGameTimer())
        tr, tg, tb = cr/255.0, cg/255.0, cb/255.0
    else
        local rgb = Menu.Colors.SelectedBg or {r=220, g=220, b=220}
        tr = (rgb.r or 220) / 255.0
        tg = (rgb.g or 220) / 255.0
        tb = (rgb.b or 220) / 255.0
    end

    local titleText = "[ BINDS ACTIFS ]"
    local totalLines = #binds + 1  -- +1 pour le titre

    -- Calcul dynamique de la largeur des colonnes pour zéro chevauchement
    local maxKeyW = 0
    local maxLabelW = 0
    if type(Lapsus_GetTextWidth_compat) == "function" then
        for _, bd in ipairs(binds) do
            local keyStr = string.format("[%s]", bd.key)
            local kw = Lapsus_GetTextWidth_compat(keyStr, fontSize)
            if kw > maxKeyW then maxKeyW = kw end
            local lw = Lapsus_GetTextWidth_compat(bd.label, fontSize)
            if lw > maxLabelW then maxLabelW = lw end
        end
    else
        maxKeyW = 60.0 * menuSc
        maxLabelW = 140.0 * menuSc
    end

    local keyColW   = math.max(math.floor(55.0 * menuSc), math.ceil(maxKeyW * 1.25 + 16.0 * menuSc))
    local labelColW = math.max(math.floor(130.0 * menuSc), math.ceil(maxLabelW * 1.20 + 18.0 * menuSc))
    local badgeW    = math.max(38, math.floor(40.0 * menuSc))
    local badgeH    = math.max(fontSize + 2, math.floor(20.0 * menuSc))
    local badgePadX = math.floor(5.0 * menuSc)

    local boxH = totalLines * lineH + padY * 2
    local boxW = math.max(math.floor(260.0 * menuSc), math.floor(padX * 2 + keyColW + labelColW + badgeW + 10.0 * menuSc))

    -- Coin bas-droit
    local bx = w - boxW - margin
    local by = h - boxH - margin

    -- Fond opaque + Vrai contour arrondi aux couleurs du thème (style notification)
    if Menu.Helpers and Menu.Helpers.DrawHollowBorderRect then
        Menu.Helpers.DrawHollowBorderRect(bx, by, boxW, boxH, tr, tg, tb, 0.75, 0.80, 6.0)
    elseif type(Lapsus_DrawRect_Filled) == "function" then
        local thick = 1.0
        Lapsus_DrawRect_Filled(bx - thick, by - thick, boxW + thick * 2, boxH + thick * 2, tr, tg, tb, 0.65, 7.0)
        Lapsus_DrawRect_Filled(bx, by, boxW, boxH, 0.0, 0.0, 0.0, 0.98, 6.0)
    end

    -- Titre
    Lapsus_DrawText_compat(bx + padX, by + padY, titleText, fontSize, tr, tg, tb, 0.9)

    -- Réinitialiser les hitboxes de cette frame
    _G._hudBindHitboxes = {}

    -- Souris : position normalisée → pixel
    local mx, my = -1, -1
    if GetNuiCursorPosition then
        local nx, ny = GetNuiCursorPosition()
        mx = nx * w
        my = ny * h
    end

    for i, bd in ipairs(binds) do
        local lineY  = by + padY + i * lineH
        local keyStr = string.format("[%s]", bd.key)

        -- Stocker hitbox pour clic
        local hbox = { x = bx, y = lineY - math.floor(3 * menuSc), w = boxW, h = lineH, menu = bd.menu, index = bd.index, label = bd.label }
        table.insert(_G._hudBindHitboxes, hbox)

        -- Highlight au survol (menu fermé uniquement)
        local isHovered = (not Menu.State.menuOpen) and mx >= hbox.x and mx <= hbox.x + hbox.w and my >= hbox.y and my <= hbox.y + hbox.h
        if isHovered and type(Lapsus_DrawRect_Filled) == "function" then
            Lapsus_DrawRect_Filled(bx, hbox.y, boxW, lineH, tr, tg, tb, 0.12, 4.0)
        end

        -- Touche (couleur thème)
        Lapsus_DrawText_compat(bx + padX, lineY, keyStr, fontSize, tr, tg, tb, 0.85)

        -- Label (blanc atténué, plus brillant si survolé) - positionné EXACTEMENT après la touche
        local labelA = isHovered and 1.0 or 0.75
        Lapsus_DrawText_compat(bx + padX + keyColW, lineY, bd.label, fontSize, 0.85, 0.85, 0.85, labelA)

        -- Badge ON/OFF
        if bd.isToggle then
            local badgeX = bx + padX + keyColW + labelColW
            local badgeY = lineY - 1
            if bd.active then
                -- Fond couleur du theme actuel + texte ON
                if type(Lapsus_DrawRect_Filled) == "function" then
                    Lapsus_DrawRect_Filled(badgeX, badgeY, badgeW, badgeH, tr, tg, tb, 0.90, 4.0)
                end
                Lapsus_DrawText_compat(badgeX + badgePadX, badgeY + math.floor(1.0 * menuSc), "ON", fontSize - 2, 1.0, 1.0, 1.0, 1.0)
            else
                -- Fond gris neutre + texte OFF (remplace le rouge)
                if type(Lapsus_DrawRect_Filled) == "function" then
                    Lapsus_DrawRect_Filled(badgeX, badgeY, badgeW + 6, badgeH, 0.30, 0.30, 0.30, 0.85, 4.0)
                end
                Lapsus_DrawText_compat(badgeX + badgePadX, badgeY + math.floor(1.0 * menuSc), "OFF", fontSize - 2, 0.70, 0.70, 0.70, 0.85)
            end
        end
    end
end

-- Thread : clic gauche sur une ligne du HUD Binds = toggle direct (menu fermé)
Citizen.CreateThread(function()
    local _prevClick = false
    while true do
        Wait(0)
        if not Menu.State.hudBindsVisible or Menu.State.menuOpen then
            _prevClick = false
            Wait(50)
            goto continue_hud_click
        end
        if not Lapsus or not Lapsus_GetAsyncKeyState_compat then goto continue_hud_click end

        local clickDown = Lapsus_GetAsyncKeyState_compat(0x01) -- clic gauche
        local clickJust = clickDown and not _prevClick
        _prevClick = clickDown

        if clickJust and _G._hudBindHitboxes and #_G._hudBindHitboxes > 0 then
            local w, h = GetActiveScreenResolution()
            if GetNuiCursorPosition then
                local nx, ny = GetNuiCursorPosition()
                local mx, my = nx * w, ny * h
                for _, hb in ipairs(_G._hudBindHitboxes) do
                    if mx >= hb.x and mx <= hb.x + hb.w and my >= hb.y and my <= hb.y + hb.h then
                        if hb.menu and hb.index then
                            Menu.Helpers.MigrateReorganizedBind(hb)
                            ExecuteMenuAction(hb.menu, hb.index)
                            local _, isNowActive = GetBindToggleState(hb.menu, hb.index)
                            local stateStr = isNowActive and "ON" or "OFF"
                            ShowDynastyNotification("[ BIND ] " .. (hb.label or "bind") .. ": " .. stateStr)
                            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        end
                        break
                    end
                end
            end
        end

        ::continue_hud_click::
    end
end)

-- Crosshair freecam : German (manji 卍), Cross (avec gap), Carre (4 coins)
-- cx/cy = centre ecran en pixels, resH = hauteur ecran pour scaling
local function DrawFreecamCrosshair(cx, cy, resH, tr, tg, tb)
    if not Lapsus or not Lapsus.DrawLine then return end
    if not (Menu.State.freecamCrosshairActive ~= false) then return end

    local rs = resH / 1080.0
    local S  = math.floor(6 * rs)   -- demi-bras croix / german
    local C  = math.floor(4 * rs)   -- longueur crochet german
    local H  = math.floor(6 * rs)   -- demi-cote carre
    local W  = 1.2

    local function L(x1, y1, x2, y2)
        Lapsus_DrawLine_compat(x1, y1, x2, y2, tr, tg, tb, 1.0, W)
    end

    local ctype = Menu.State.freecamCrosshairType or 2

    if ctype == 1 then
        -- German (manji 卍) : croix + crochets colles aux bouts, sens horaire
        -- bras H et V
        L(cx - S, cy,     cx + S, cy)
        L(cx,     cy - S, cx,     cy + S)
        -- crochet extremite HAUT   → droite
        L(cx,     cy - S, cx + C, cy - S)
        -- crochet extremite BAS    → gauche
        L(cx,     cy + S, cx - C, cy + S)
        -- crochet extremite GAUCHE → haut
        L(cx - S, cy,     cx - S, cy - C)
        -- crochet extremite DROITE → bas
        L(cx + S, cy,     cx + S, cy + C)

    elseif ctype == 2 then
        -- Cross : + plein, bras qui se superposent au centre
        L(cx - S, cy,     cx + S, cy)
        L(cx,     cy - S, cx,     cy + S)

    elseif ctype == 3 then
        -- Carre : 4 cotes pleins formant un vrai rectangle
        L(cx - H, cy - H, cx + H, cy - H)  -- haut
        L(cx + H, cy - H, cx + H, cy + H)  -- droite
        L(cx + H, cy + H, cx - H, cy + H)  -- bas
        L(cx - H, cy + H, cx - H, cy - H)  -- gauche
    end
end

function Menu.Helpers.DrawFreecamOutlinedText(x,y,text,size,r,g,b,a)
    local alpha=a or 1.0
    -- A one-pixel silhouette around the final glyphs, not each glow layer.
    Lapsus_DrawText_compat(x-1,y-1,text,size,0,0,0,alpha)
    Lapsus_DrawText_compat(x+1,y-1,text,size,0,0,0,alpha)
    Lapsus_DrawText_compat(x-1,y+1,text,size,0,0,0,alpha)
    Lapsus_DrawText_compat(x+1,y+1,text,size,0,0,0,alpha)
    Lapsus_DrawText_compat(x,y,text,size,r,g,b,alpha)
end

function DrawFreecamHint()
    if not freecam_active or Menu.State.freecamInfoVisible == false then
        return
    end
    if not Lapsus or type(Lapsus_DrawText_compat) ~= "function" then return end
    local FreecamOptions = _G.FreecamOptions or { "Launch", "Teleport", "Shoot Vision", "Spawn Props Model", "NPC Hijack", "Ragdoll", "Attach", "Warp", "TP Passenger", "Physgun", "Delete Entity", "Launch Vehicle", "Bug Vehicle", "Black Hole", "Magneto", "Massacre Player", "Shoot Car" }
    local w, h = GetActiveScreenResolution()
    w = (w and w > 0) and w or 1920
    h = (h and h > 0) and h or 1080
    local cx = w / 2.0
    local cy = h / 2.0
    local resScale = (h / 1080.0) * 0.95
    local menuSc   = (_G.menuScale or 1.0) * resScale
    local sizeSel  = math.floor(28.0 * menuSc)
    local sizeNorm = math.floor(18.0 * menuSc)
    local spacing  = math.floor(38.0 * menuSc)
    local startY   = h - math.floor(190.0 * menuSc)

    -- Couleur theme banniere active (MIRAGE breathing si MirageLua)
    local tr, tg, tb
    if _G.IsMirageLuaActive and _G.IsMirageLuaActive() and _G.MirageBreathColor then
        local cr, cg, cb = _G.MirageBreathColor(GetGameTimer())
        tr, tg, tb = cr/255.0, cg/255.0, cb/255.0
    else
        local rgb = Menu.Colors.SelectedBg or {r=255, g=255, b=255}
        tr = (rgb.r or 255) / 255.0
        tg = (rgb.g or 255) / 255.0
        tb = (rgb.b or 255) / 255.0
    end

    local rNorm, gNorm, bNorm = 0.60, 0.60, 0.60

    -- Crosshair freecam
    DrawFreecamCrosshair(cx, cy, h, tr, tg, tb)

    local total    = #FreecamOptions
    local selected = _G.FreecamSelectedOption or 1
    local maxTextRight = cx + 80.0 * menuSc

    for slot = 1, total do
        local optIdx = ((selected - 1 + slot - 1) % total) + 1
        local isSelected = (slot == 1)

        local size = isSelected and sizeSel or sizeNorm
        local y    = startY + (slot - 1) * spacing
        if y > h then break end  -- hors écran : inutile de dessiner

        local text = FreecamOptions[optIdx]
        if text == "Launch" then
            local modes = _G.FreecamLaunchModes or { "V1", "V2" }
            local mIdx = _G.FreecamLaunchModeIdx or 1
            text = "Launch [" .. (modes[mIdx] or "V1") .. "]"
        elseif text == "Attach" then
            local modes = _G.FreecamAttachModes or { "Full Box", "Wall", "Single", "Rampe", "Tour" }
            local mIdx = _G.FreecamAttachModeIdx or 1
            text = "Attach [" .. (modes[mIdx] or "Full Box") .. "]"
        elseif text == "Spawn Props Model" then
            local modelDisplay = _G.FreecamModels[_G.FreecamModelIdx or 2].display
            text = text .. " [" .. modelDisplay .. "]"
        elseif text == "Delete Entity" then
            local deleteModeNames = { "VEHICLE", "NPC", "PROP" }
            local dMode = Menu.State.deleteEntityMode or 1
            text = text .. " [" .. (deleteModeNames[dMode] or "?") .. "]"
        elseif text == "TP Passenger" then
            local di = _G.TpPassengerDestIdx or 1
            local dests = _G.TpPassengerDestinations
            local destLabel = (dests and dests[di]) and dests[di].name or "Ocean"
            text = text .. " [" .. destLabel .. "]"
        elseif text == "Launch Vehicle" then
            text = "Launch Vehicle  [" .. (Menu.State.bugVehicleForce or 50) .. "]"
        elseif text == "Bug Vehicle" then
            local modes = _G.FreecamBugVehicleModes or { "V1", "V2" }
            local mIdx = _G.FreecamBugVehicleModeIdx or 1
            text = "Bug Véhicule [" .. (modes[mIdx] or "V1") .. "]"
        elseif text == "NPC Hijack" then
            local modes = _G.FreecamNPCHijackModes or { "V1", "V2" }
            local mIdx = _G.FreecamNPCHijackModeIdx or 1
            text = "NPC Hijack [" .. (modes[mIdx] or "V1") .. "]"
        elseif text == "Black Hole" then
            text = _G.FreecamBHHold_active and "Black Hole  [ACTIF]" or "Black Hole"
        elseif text == "Magneto" then
            text = _G.FreecamMagneto_active and "Magneto  [ACTIF]" or "Magneto"
        elseif text == "Shoot Car" then
            local modes  = _G.ShootCarModes  or { "Nearest", "Model" }
            local models = _G.ShootCarModels or {}
            local modeLabel  = modes[_G.ShootCarModeIdx  or 1] or "Nearest"
            local modelLabel = (models[_G.ShootCarModelIdx or 1] and models[_G.ShootCarModelIdx or 1].display) or ""
            if modeLabel == "Model" and modelLabel ~= "" then
                text = "Shoot Car [" .. modeLabel .. " : " .. modelLabel .. "]"
            else
                text = "Shoot Car [" .. modeLabel .. "]"
            end
        elseif text == "Shoot Vision" then
            local modes = _G.ShootVisionModes or { "Normal", "Natif" }
            local mIdx = _G.ShootVisionModeIdx or 1
            local active = (shootVisionActive == true or (Menu.State and Menu.State.shootVisionActive == true))
            local statusStr = active and " [ON]" or ""
            text = "Shoot Vision [" .. (modes[mIdx] or "Normal") .. "]" .. statusStr
        elseif text == "Physgun" then
            local PS = _G.PhysgunState
            if PS and PS.active then
                text = "Physgun  [SAISI] " .. math.floor(PS.distance) .. "m"
            else
                text = "Physgun"
                -- Afficher le hint uniquement quand cette option est sélectionnée (slot == 1)
                if isSelected then
                    if not _G._physgunHintShown then
                        ShowDynastyNotification("[ PHYSGUN ] Clic droit=Saisir  Clic gauche=Lancer")
                        _G._physgunHintShown = true
                    end
                else
                    _G._physgunHintShown = false
                end
            end
        end

        local textX = cx - 80.0 * menuSc
        local textW = 160.0 * menuSc
        if type(Lapsus_GetTextWidth_compat) == "function" then
            textW = Lapsus_GetTextWidth_compat(text, size)
            textX = cx - textW / 2.0
            if (textX + textW) > maxTextRight then
                maxTextRight = textX + textW
            end
        end

        -- Effet GLOW / Brillance + Ombre portée pour l'option sélectionnée
        if isSelected then
            local glowPulse = 0.75 + 0.25 * math.sin(GetGameTimer() / 280.0)
            local g3 = 3.0 * menuSc
            local g2 = 2.0 * menuSc
            local g1 = 1.0 * menuSc
            -- Halo large
            Lapsus_DrawText_compat(textX - g3, y, text, size, tr, tg, tb, 0.23 * glowPulse)
            Lapsus_DrawText_compat(textX + g3, y, text, size, tr, tg, tb, 0.23 * glowPulse)
            Lapsus_DrawText_compat(textX, y - g3, text, size, tr, tg, tb, 0.23 * glowPulse)
            Lapsus_DrawText_compat(textX + g3, y, text, size, tr, tg, tb, 0.23 * glowPulse)
            -- Halo intermédiaire
            Lapsus_DrawText_compat(textX - g2, y, text, size, tr, tg, tb, 0.42 * glowPulse)
            Lapsus_DrawText_compat(textX + g2, y, text, size, tr, tg, tb, 0.42 * glowPulse)
            Lapsus_DrawText_compat(textX, y - g2, text, size, tr, tg, tb, 0.42 * glowPulse)
            Lapsus_DrawText_compat(textX + g2, y, text, size, tr, tg, tb, 0.42 * glowPulse)
            -- Halo intense proche
            Lapsus_DrawText_compat(textX - g1, y, text, size, tr, tg, tb, 0.67 * glowPulse)
            Lapsus_DrawText_compat(textX + g1, y, text, size, tr, tg, tb, 0.67 * glowPulse)
            Lapsus_DrawText_compat(textX, y - g1, text, size, tr, tg, tb, 0.67 * glowPulse)
            Lapsus_DrawText_compat(textX + g1, y, text, size, tr, tg, tb, 0.67 * glowPulse)
            -- Halo Glow discret et élégant


            -- Ombre noire d'ancrage
        end

        -- Texte : sélectionné = légèrement plus grand + glow + couleur thème, non sélectionné = discret + gris
        local fR = isSelected and (tr * .7 + .3) or rNorm
        local fG = isSelected and (tg * .7 + .3) or gNorm
        local fB = isSelected and (tb * .7 + .3) or bNorm
        local fA = isSelected and 1.0 or 0.55
        Menu.Helpers.DrawFreecamOutlinedText(textX, y, text, size, fR, fG, fB, fA)
    end

    -- ── AFFICHAGE COMPTEUR FREECAM (PARFAITEMENT CENTRÉ SOUS LES OPTIONS) ──
    local counterStr = string.format("%d / %d", selected, total)
    local cFontSize  = math.floor(16.0 * menuSc)
    local cTextW     = (type(Lapsus_GetTextWidth_compat) == "function") and Lapsus_GetTextWidth_compat(counterStr, cFontSize) or (45.0 * menuSc)
    local badgeW     = cTextW + math.floor(18.0 * menuSc)
    local badgeH     = cFontSize + math.floor(8.0 * menuSc)
    -- Compteur d'option Freecam : décalé légèrement vers la droite par rapport au centre des options
    local badgeShiftRight = math.floor(130.0 * menuSc)
    local badgeX     = cx - (badgeW / 2.0) + badgeShiftRight
    local badgeY     = startY + (total * spacing) + math.floor(6.0 * menuSc)
    if badgeY > (h - math.floor(25.0 * menuSc)) then
        badgeY = h - math.floor(25.0 * menuSc)
    end

    if type(Lapsus_DrawRect_Filled) == "function" then
        local pulse = 0.75 + 0.25 * math.sin(GetGameTimer() / 400.0)
        local b = 1.0
        Lapsus_DrawRect_Filled(badgeX - b, badgeY - b, badgeW + b * 2, badgeH + b * 2, tr, tg, tb, 0.75 * pulse, 4.0)
        Lapsus_DrawRect_Filled(badgeX, badgeY, badgeW, badgeH, 0.05, 0.05, 0.05, 0.92, 4.0)
        local tx = badgeX + (badgeW - cTextW) / 2.0
        local ty = badgeY + (badgeH - cFontSize) / 2.0
        Menu.Helpers.DrawFreecamOutlinedText(tx, ty, counterStr, cFontSize, 0.95, 0.95, 0.95, 1.0)
    else
        Menu.Helpers.DrawFreecamOutlinedText(badgeX, badgeY, counterStr, cFontSize, 0.95, 0.95, 0.95, 1.0)
    end
end

