-- Applique le JSON de theme recu (string) directement sans re-lire le fichier
local function _applyThemeJson(themeStr)
    if not themeStr or #themeStr == 0 then return false end
    -- Nettoyage du BOM UTF-8 (\239\187\191) si présent (évite crash de json.decode)
    if themeStr:sub(1, 3) == "\239\187\191" then
        themeStr = themeStr:sub(4)
    end
    themeStr = themeStr:match("^%s*(.-)%s*$")
    if not themeStr or #themeStr == 0 then return false end

    if not json or not json.decode then return false end
    local ok, t = pcall(json.decode, themeStr)
    if not ok or type(t) ~= "table" then return false end

    -- Supporte à la fois { "config": { ... } } de ghostshop.fr et { "r": ... } local
    if t.config and type(t.config) == "table" then
        t = t.config
    end

    -- Bannière Cloud dynamique depuis ghostshop.fr
    if t.banner_url and type(t.banner_url) == "string" and #t.banner_url > 4 then
        local bUrl = t.banner_url
        if bUrl:find("imgur%.com") and not bUrl:find("i%.imgur%.com") then
            local id = bUrl:match("imgur%.com/([%w]+)")
            if id then bUrl = "https://i.imgur.com/" .. id .. ".png" end
        end

        for _, b in ipairs(Menu.AvailableBanners) do
            if b.name == "Perso" then
                b.url = bUrl
            end
        end

        Menu.Banner.imageUrl = bUrl
        bannerCurrentUrl = bUrl

        -- Sélectionne la bannière Perso (Cloud) par défaut
        for idx, b in ipairs(Menu.AvailableBanners) do
            if b.name == "Perso" then
                Menu.BannerIndex = idx
                break
            end
        end

        if Menu.LoadBannerTexture then
            Menu.LoadBannerTexture(bUrl, true)
        end
    end

    -- Couleur : utiliser tonumber pour eviter le piege r=0 falsy
    local curB = Menu.AvailableBanners and Menu.AvailableBanners[Menu.BannerIndex]
    local isMirageCur = (curB and curB.name == "Mirage")
    if isMirageCur then
        Menu.Colors.HeaderPink = { r = 125, g = 125, b = 125 }
        Menu.Colors.SelectedBg = { r = 125, g = 125, b = 125, a = 0.9 }
        _G.customThemeLoaded = false
    else
        local tr = tonumber(t.r)
        local tg = tonumber(t.g)
        local tb = tonumber(t.b)
        if tr ~= nil and tg ~= nil and tb ~= nil then
            Menu.Colors.HeaderPink = { r = math.floor(tr), g = math.floor(tg), b = math.floor(tb) }
            Menu.Colors.SelectedBg = { r = math.floor(tr), g = math.floor(tg), b = math.floor(tb), a = 0.9 }
            _G.customThemeLoaded = true
        elseif t.theme and type(t.theme) == "string" then
            Menu.ApplyTheme(t.theme)
            _G.customThemeLoaded = true
        end
    end

    -- Titre et options
    if t.title and type(t.title) == "string" then
        _G.customBannerTitle = t.title
    end
    if t.hide_title ~= nil then
        _G.customBannerHideTitle = t.hide_title
    end
    if t.font ~= nil then
        _G.customBannerFont = tonumber(t.font) or 0
    end
    if t.baked ~= nil then
        _G.customBannerBaked = (t.baked == true)
    end

    -- Style de bordure Cloud depuis ghostshop.fr
    if t.border_style then
        local b = tostring(t.border_style):lower()
        if b == "simple" or b == "solid" then
            Menu.State.menuBorderStyle = 1
            Menu.State.menuBorderActive = true
        elseif b == "glow" then
            Menu.State.menuBorderStyle = 2
            Menu.State.menuBorderActive = true
        elseif b == "anim" then
            Menu.State.menuBorderStyle = 3
            Menu.State.menuBorderActive = true
        elseif b == "off" then
            Menu.State.menuBorderActive = false
        end
    end

    _lastThemeApplied = GetGameTimer()
    return true
end

function Menu.LoadLocalTheme()
    local themeStr = nil

    -- 1. PRIORITÉ ABSOLUE : API Cloud GhostShop (https://ghostshop.fr/api/mirage/config)
    if Lapsus and type(Lapsus_HttpGet_compat) == "function" then
        local userKey = (_G.AuthedCode and #tostring(_G.AuthedCode) >= 8) and tostring(_G.AuthedCode) or nil
        if not userKey and io and type(io.open) == "function" then
            local kf = io.open("c_auth_key.txt", "r")
            if kf then userKey = kf:read("*a"); kf:close() end
        end
        if userKey then userKey = userKey:match("^%s*(.-)%s*$") end

        local apiUrl = "https://ghostshop.fr/api/mirage/config"
        if userKey and #userKey >= 8 then
            apiUrl = "https://ghostshop.fr/api/mirage/config?key=" .. userKey
        end

        local ok, status, data = pcall(Lapsus_HttpGet_compat, apiUrl)
        if ok and status == 200 and data and #data > 4 then
            themeStr = data
        elseif apiUrl ~= "https://ghostshop.fr/api/mirage/config" then
            local ok2, status2, data2 = pcall(Lapsus_HttpGet_compat, "https://ghostshop.fr/api/mirage/config")
            if ok2 and status2 == 200 and data2 and #data2 > 4 then
                themeStr = data2
            end
        end
    end

    -- 2. SECOURS : Localhost ou fichier local si indisponible
    if (not themeStr or #themeStr == 0) and Lapsus and type(Lapsus_HttpGet_compat) == "function" then
        local ok, status, data = pcall(Lapsus_HttpGet_compat, "http://127.0.0.1:8080/get_theme")
        if ok and status == 200 and data and #data > 4 then
            themeStr = data
        end
    end

    if (not themeStr or #themeStr == 0) and io and type(io.open) == "function" then
        local ok, f = pcall(io.open, "c:/Users/torre/Downloads/dash/theme.json", "r")
        if not ok or not f then ok, f = pcall(io.open, "c:/Users/torre/Downloads/banner/theme.json", "r") end
        if not ok or not f then ok, f = pcall(io.open, "theme.json", "r") end
        if ok and f then
            themeStr = f:read("*a")
            f:close()
        end
    end

    return _applyThemeJson(themeStr)
end
