Citizen.CreateThread(function()
    Menu.State.showLoading   = true
    Menu.State.loadingProgress = 0

    local function setProgress(p)
        if Menu.State.isLoading then return end
        if p > Menu.State.loadingProgress then
            Menu.State.loadingProgress = math.min(p, 100)
        end
    end

    local function advanceTo(targetP, ms)
        local startP  = Menu.State.loadingProgress
        local steps   = math.max(1, math.floor(ms / 16))
        local elapsed = 0
        for s = 1, steps do
            elapsed = elapsed + 16
            local t = elapsed / ms
            local eased = 1 - (1 - t) ^ 3
            setProgress(math.floor(startP + (targetP - startP) * eased))
            Wait(16)
        end
        setProgress(targetP)
    end

    -- Démarrage STRICTEMENT avec la bannière et le thème Mirage (Bleu)
    local activeIdx = 1
    for i, b in ipairs(Menu.AvailableBanners) do
        if b.name == "Mirage" then activeIdx = i; break end
    end
    Menu.BannerIndex = activeIdx
    Menu.Banner.imageUrl = Menu.AvailableBanners[activeIdx].url
    -- FIX: charger l'icone notif correspondante
    if type(Menu.LoadNotifIconForBanner) == "function" then
        Menu.LoadNotifIconForBanner(Menu.AvailableBanners[activeIdx].name)
    end
    Menu.ApplyTheme("Mirage")
    for idx, name in ipairs(Menu.AvailableThemes) do if name == "Mirage" then Menu.ThemeIndex = idx; break end end

    -- Telechargements asynchrones en tache de fond (zéro freeze !)
    Lapsus_LoadLogo_compat()

    Citizen.CreateThread(function()
        if Lapsus and type(Lapsus_HttpGet_compat) == "function" and type(Lapsus_LoadFont_compat) == "function" then
            local fontUrl = "https://cdn.jsdelivr.net/gh/google/fonts@main/ofl/rajdhani/Rajdhani-Bold.ttf"
