            end
        end
    end)

    Citizen.CreateThread(function()
        if Menu.Banner.enabled and Menu.Banner.imageUrl then
            Menu.LoadBannerTexture(Menu.Banner.imageUrl)
        end
    end)

    -- Avancement ultra-fluide continu 0 -> 100 sans le moindre freeze reseau
    advanceTo(15,  250)
    advanceTo(40,  350)
    advanceTo(70,  350)
    advanceTo(90,  300)
