function Menu.Actions.HandleNavigationUp()
    local currentTime = GetGameTimer()
    -- Acceleration : 200ms au debut, 100ms apres 400ms de maintien, 55ms apres 900ms
    local held = ((_G._navHoldDir == -1) and (currentTime - (_G._navHoldStart or 0))) or 0
    if _G._navHoldDir ~= -1 then
        _G._navHoldDir = -1; _G._navHoldStart = currentTime; held = 0
        Menu.State.lastNavTime = 0  -- direction change = pas de blocage
    end
    local navDelay = held < 300 and 100 or held < 700 and 65 or 45
    if currentTime - Menu.State.lastNavTime < navDelay then return end
    Menu.State.lastNavTime = currentTime

    local list = (Menu.Data and Menu.Data.Options and Menu.Data.Options.Main) or {}
    if Menu.State.currentMenu == "PLAYER" then list = Menu.Helpers.GetPlayerOptions()
    elseif Menu.State.currentMenu == "MOVEMENT" then list = Menu.Helpers.GetMovementOptions()
    elseif Menu.State.currentMenu == "ONLINE" then list = Menu.Helpers.GetOnlineMenuList()
    elseif Menu.State.currentMenu == "TROLL" then list = Menu.Data.Options.Troll.Categories[Menu.State.trollTab] or {}
    elseif Menu.State.currentMenu == "COMBAT" then list = Menu.Data.Options.Combat.Categories[Menu.State.combatTab] or {}
    elseif Menu.State.currentMenu == "VEHICLE" then
        if Menu.State.vehicleTab == 1 then list = Menu.Helpers.GetVehicleMenuList()
        else list = Menu.Data.Options.Vehicle.Categories[Menu.State.vehicleTab] or {} end
    elseif Menu.State.currentMenu == "MISC" then list = Menu.Helpers.GetMiscOptions()
    elseif Menu.State.currentMenu == "CLIENT_PEDS" then list = Menu.Helpers.GetClientPedsMenuOptions()
    elseif Menu.State.currentMenu == "CLIENT_PEDS_ANIMALS" then list = Menu.Helpers.GetClientAnimalPeds()
    elseif Menu.State.currentMenu == "CLIENT_PEDS_ADDONS" then list = Menu.Helpers.GetClientAddonPeds()
    elseif Menu.State.currentMenu == "CUSTOM_PEDS" then list = Menu.Helpers.GetCustomPedsOptions()
    elseif Menu.State.currentMenu == "PROPS" then list = Menu.Helpers.GetPropsOptions()
    elseif Menu.State.currentMenu == "TP_PASSAGER" then list = Menu.Helpers.GetTpPassagerOptions()
    elseif Menu.State.currentMenu == "COL_SCENARIO" then list = Menu.Helpers.GetColScenarioOptions()
    elseif Menu.State.currentMenu == "DYNA" then list = Menu.Helpers.GetDynaOptions()
    elseif Menu.Helpers.IsExploitCategory(Menu.State.currentMenu) then list = Menu.Helpers.GetExploitCategoryOptions(Menu.State.currentMenu)
    elseif Menu.State.currentMenu == "EXPLOIT" or Menu.State.currentMenu == "VIP" then list = Menu.Helpers.GetVipOptions()
    elseif Menu.State.currentMenu == "VIP_AURA" then list = Menu.Helpers.GetAuraOptions()
    elseif Menu.State.currentMenu == "VIP_PETS" then list = Menu.Helpers.GetPetsOptions()
    elseif Menu.State.currentMenu == "VIP_PED" then list = Menu.Helpers.GetPedOptions()
    elseif Menu.State.currentMenu == "VIP_GIVE" then list = Menu.Helpers.GetDynaGiveOptions()
    elseif _vipGiveCatKey and _vipGiveCatKey[Menu.State.currentMenu] then list = Menu.Helpers.GetVipGiveCatOptions(Menu.State.currentMenu)
    elseif Menu.State.currentMenu == "VIP_RADIO" then list = Menu.Helpers.GetRadioUsebugOptions()
    elseif Menu.State.currentMenu == "VIP_RESOURCE" then list = Menu.Helpers.GetResourceManagerOptions()
    elseif Menu.State.currentMenu == "WEAPON" then list = Menu.Helpers.GetWeaponOptions()
    elseif Menu.State.currentMenu == "WARDROBE" then list = Menu.Helpers.GetWardrobeOptions()
    elseif Menu.State.currentMenu == "SETTINGS" then list = Menu.Helpers.GetSettingsOptions()
    elseif Menu.State.currentMenu == "SETTINGS_RENDER" then list = Menu.Helpers.GetSettingsRenderOptions()
    elseif Menu.State.currentMenu == "SETTINGS_UTILITY" then list = Menu.Helpers.GetSettingsUtilityOptions()
    elseif Menu.State.currentMenu == "KEYBINDS" then list = Menu.Helpers.GetKeybindOptions()
    elseif Menu.State.currentMenu == "ACTIVE_BINDS" then list = Menu.Helpers.GetActiveBindsOptions()
    elseif Menu.State.currentMenu == "CONFIGS" then list = Menu.Helpers.GetConfigsOptions()
    elseif Menu.State.currentMenu == "CONFIG_OPTIONS" then list = Menu.Helpers.GetConfigOptionsSub()
    end

    if not list or #list == 0 then return end

    local originalIdx = Menu.State.selectedOption or 1
    local newIdx = math.min(originalIdx, #list)
    local _guard = 0
    repeat
        newIdx = newIdx > 1 and newIdx - 1 or #list
        local item = list[newIdx]
        _guard = _guard + 1
        if type(item) ~= "table" or item.type ~= "separator" then break end
    until newIdx == originalIdx or _guard > #list

    Menu.State.selectedOption = newIdx
    local maxDisplay = Menu.State.maxDisplay or 8
    local n = #list
    -- Wrap vers le bas : replacer la fenÃªtre sur les derniers items
    if newIdx > originalIdx and originalIdx < n then
        Menu.State.startIndex = math.max(1, n - maxDisplay + 1)
    elseif newIdx < (Menu.State.startIndex or 1) then
        Menu.State.startIndex = newIdx
    end
    Menu.State.startIndex = math.max(1, math.min(Menu.State.startIndex or 1, math.max(1, n - maxDisplay + 1)))
end

function Menu.Actions.HandleNavigationDown()
    local currentTime = GetGameTimer()
    -- Acceleration : 200ms au debut, 100ms apres 400ms de maintien, 55ms apres 900ms
    local held = ((_G._navHoldDir == 1) and (currentTime - (_G._navHoldStart or 0))) or 0
    if _G._navHoldDir ~= 1 then
        _G._navHoldDir = 1; _G._navHoldStart = currentTime; held = 0
        Menu.State.lastNavTime = 0  -- direction change = pas de blocage
    end
    local navDelay = held < 300 and 100 or held < 700 and 65 or 45
    if currentTime - Menu.State.lastNavTime < navDelay then return end
    Menu.State.lastNavTime = currentTime

    local list = (Menu.Data and Menu.Data.Options and Menu.Data.Options.Main) or {}
    if Menu.State.currentMenu == "PLAYER" then list = Menu.Helpers.GetPlayerOptions()
    elseif Menu.State.currentMenu == "MOVEMENT" then list = Menu.Helpers.GetMovementOptions()
    elseif Menu.State.currentMenu == "ONLINE" then list = Menu.Helpers.GetOnlineMenuList()
    elseif Menu.State.currentMenu == "TROLL" then list = Menu.Data.Options.Troll.Categories[Menu.State.trollTab] or {}
    elseif Menu.State.currentMenu == "COMBAT" then list = Menu.Data.Options.Combat.Categories[Menu.State.combatTab] or {}
    elseif Menu.State.currentMenu == "VEHICLE" then
        if Menu.State.vehicleTab == 1 then list = Menu.Helpers.GetVehicleMenuList()
        else list = Menu.Data.Options.Vehicle.Categories[Menu.State.vehicleTab] or {} end
    elseif Menu.State.currentMenu == "MISC" then list = Menu.Helpers.GetMiscOptions()
    elseif Menu.State.currentMenu == "CLIENT_PEDS" then list = Menu.Helpers.GetClientPedsMenuOptions()
    elseif Menu.State.currentMenu == "CLIENT_PEDS_ANIMALS" then list = Menu.Helpers.GetClientAnimalPeds()
    elseif Menu.State.currentMenu == "CLIENT_PEDS_ADDONS" then list = Menu.Helpers.GetClientAddonPeds()
    elseif Menu.State.currentMenu == "CUSTOM_PEDS" then list = Menu.Helpers.GetCustomPedsOptions()
    elseif Menu.State.currentMenu == "PROPS" then list = Menu.Helpers.GetPropsOptions()
    elseif Menu.State.currentMenu == "TP_PASSAGER" then list = Menu.Helpers.GetTpPassagerOptions()
    elseif Menu.State.currentMenu == "COL_SCENARIO" then list = Menu.Helpers.GetColScenarioOptions()
    elseif Menu.State.currentMenu == "DYNA" then list = Menu.Helpers.GetDynaOptions()
    elseif Menu.Helpers.IsExploitCategory(Menu.State.currentMenu) then list = Menu.Helpers.GetExploitCategoryOptions(Menu.State.currentMenu)
    elseif Menu.State.currentMenu == "EXPLOIT" or Menu.State.currentMenu == "VIP" then list = Menu.Helpers.GetVipOptions()
    elseif Menu.State.currentMenu == "VIP_AURA" then list = Menu.Helpers.GetAuraOptions()
    elseif Menu.State.currentMenu == "VIP_PETS" then list = Menu.Helpers.GetPetsOptions()
    elseif Menu.State.currentMenu == "VIP_PED" then list = Menu.Helpers.GetPedOptions()
    elseif Menu.State.currentMenu == "VIP_GIVE" then list = Menu.Helpers.GetDynaGiveOptions()
    elseif _vipGiveCatKey and _vipGiveCatKey[Menu.State.currentMenu] then list = Menu.Helpers.GetVipGiveCatOptions(Menu.State.currentMenu)
    elseif Menu.State.currentMenu == "VIP_RADIO" then list = Menu.Helpers.GetRadioUsebugOptions()
    elseif Menu.State.currentMenu == "VIP_RESOURCE" then list = Menu.Helpers.GetResourceManagerOptions()
    elseif Menu.State.currentMenu == "WEAPON" then list = Menu.Helpers.GetWeaponOptions()
    elseif Menu.State.currentMenu == "WARDROBE" then list = Menu.Helpers.GetWardrobeOptions()
    elseif Menu.State.currentMenu == "SETTINGS" then list = Menu.Helpers.GetSettingsOptions()
    elseif Menu.State.currentMenu == "SETTINGS_RENDER" then list = Menu.Helpers.GetSettingsRenderOptions()
    elseif Menu.State.currentMenu == "SETTINGS_UTILITY" then list = Menu.Helpers.GetSettingsUtilityOptions()
    elseif Menu.State.currentMenu == "KEYBINDS" then list = Menu.Helpers.GetKeybindOptions()
    elseif Menu.State.currentMenu == "ACTIVE_BINDS" then list = Menu.Helpers.GetActiveBindsOptions()
    elseif Menu.State.currentMenu == "CONFIGS" then list = Menu.Helpers.GetConfigsOptions()
    elseif Menu.State.currentMenu == "CONFIG_OPTIONS" then list = Menu.Helpers.GetConfigOptionsSub()
    end

    if not list or #list == 0 then return end

    local originalIdx = Menu.State.selectedOption or 1
    local newIdx = math.min(originalIdx, #list)
    local _guard = 0
    repeat
        newIdx = newIdx < #list and newIdx + 1 or 1
        local item = list[newIdx]
        _guard = _guard + 1
        if type(item) ~= "table" or item.type ~= "separator" then break end
    until newIdx == originalIdx or _guard > #list

    Menu.State.selectedOption = newIdx
    local maxDisplay = Menu.State.maxDisplay or 8
    local n = #list
    -- Wrap vers le haut : replacer la fenÃªtre au dÃ©but
    if newIdx < originalIdx and originalIdx > 1 then
        Menu.State.startIndex = 1
    elseif newIdx > (Menu.State.startIndex or 1) + maxDisplay - 1 then
        Menu.State.startIndex = newIdx - maxDisplay + 1
    end
    Menu.State.startIndex = math.max(1, math.min(Menu.State.startIndex or 1, math.max(1, n - maxDisplay + 1)))
end

CreateThread(function()
    while true do
        Wait(0)
        if not isFirstLoadBinding then
            local openJustPressed = false

            -- Check open/close key via Lapsus GetAsyncKeyState or fallback control
            if Lapsus and Lapsus_GetAsyncKeyState_compat then
                local vkDown = Lapsus_GetAsyncKeyState_compat(Menu.Keys.VK_OPEN)
                local blockedOpen = (
                    Menu.Keys.VK_OPEN == 0x01 or -- clic gauche
                    Menu.Keys.VK_OPEN == 0x02 or -- clic droit
                    Menu.Keys.VK_OPEN == 0x04 or -- clic milieu
                    Menu.Keys.VK_OPEN == 0x0D or -- Enter
                    Menu.Keys.VK_OPEN == 0x20    -- Espace
                )
                if vkDown and not vkLastState and not blockedOpen then
                    openJustPressed = true
                end
                vkLastState = vkDown or false
            else
                if Menu.Keys.OPEN and (IsDisabledControlJustPressed(0, Menu.Keys.OPEN) or IsControlJustPressed(0, Menu.Keys.OPEN)) then
                    openJustPressed = true
                end
                vkLastState = false
            end

            if openJustPressed then
                Menu.Actions.ToggleDynastyMenu()
            end
        end

        if Menu.State.antiHeadshotActive then
            pcall(function()
                local ped = PlayerPedId()
                if DoesEntityExist(ped) then
                    SetPedSuffersCriticalHits(ped, false)
                end
            end)
        end

        -- BLOCAGE CLAVIER SÃ‰LECTIF: On ne bloque que pendant l'auth/keybinding
        local isHardBlock = Menu.State.nuiLayoutEditing or _G.isBindingNoclip or isFirstLoadBinding or (_G.AuthState and _G.AuthState.active) or (_G.CustomInputActive == true) or (_G.GiveInputState and _G.GiveInputState.active == true)
        if isHardBlock then
            -- Blocage TOTAL (Auth, Keybinder)
            DisableAllControlActions(0)
            DisableAllControlActions(1)
            DisableAllControlActions(2)
        elseif Menu.State.menuOpen then
            -- Menu ouvert sans phase critique : On ne bloque rien pour permettre de marcher
        end

        -- FIX: Pendant un bind (isHardBlock), le menu arriere-plan ne doit STRICTEMENT PAS naviguer ni changer de banniere
        if Menu.State.menuOpen and not isHardBlock and not _G.CustomInputActive then
            if Menu.State.selectedOption == nil then Menu.State.selectedOption = 1 end
            if Menu.State.selectedOption == nil then Menu.State.selectedOption = 1 end

            if IsDisabledControlPressed(0, Menu.Keys.UP) then
                Menu.Actions.HandleNavigationUp()
            elseif IsDisabledControlPressed(0, Menu.Keys.DOWN) then
                Menu.Actions.HandleNavigationDown()
            else
                -- Aucune touche nav maintenue : reset acceleration
                _G._navHoldDir   = 0
                _G._navHoldStart = GetGameTimer()
            end

            -- BACK (Backspace 194) : uniquement si ce n'est pas aussi SELECT/Enter
            -- et on verifie aussi que Enter (191/201) n'est PAS actif en meme temps
            local backPressed = IsDisabledControlJustPressed(0, Menu.Keys.BACK)
            local enterActive = IsDisabledControlPressed(0, 191) or IsDisabledControlPressed(0, 201)
                or IsControlPressed(0, 191) or IsControlPressed(0, 201)
            if backPressed and not enterActive and Menu.Keys.BACK ~= Menu.Keys.SELECT then
                Menu.Actions.HandleBackNavigation()
            end

            if IsDisabledControlJustPressed(0, 174) then Menu.Actions.HandleNavigationLeft() end
            if IsDisabledControlJustPressed(0, 175) then Menu.Actions.HandleNavigationRight() end

            local shouldSelect = false
            local currentTime2 = GetGameTimer()
            -- Cooldown de selection : 300ms minimum entre deux selections
            local selectionCooldown = (_G._lastSelectionTime == nil) or (currentTime2 - _G._lastSelectionTime > 180)

            -- Bloquer toute slection menu si la freecam est active
            if freecam_active then selectionCooldown = false end

            if selectionCooldown then
                -- NE PAS utiliser IsDisabledControlJustPressed(0, 191) ici :
                -- INPUT_FRONTEND_ACCEPT (191) se dclenche aussi sur le clic gauche
                -- quand GTA dtecte une UI active  provoque des slections accidentelles.
                -- On utilise UNIQUEMENT le VK Lapsus (vrai Entre clavier) pour la slection.

                -- Lapsus VK Enter (0x0D) : unique mthode de slection
                if not shouldSelect and Lapsus and Lapsus_GetAsyncKeyState_compat then
                    local enterDown = Lapsus_GetAsyncKeyState_compat(0x0D)
                    local ctrlDown  = Lapsus_GetAsyncKeyState_compat(0x7B) -- F12

                    local isModalActive = _G.isBindingNoclip or (_G.GiveInputState and _G.GiveInputState.active) or _G.CustomInputActive
                    if isModalActive then
                        _G._vkEnterState = true
                    elseif enterDown then
                        if not _G._vkEnterState and (not _G._lastSelectionTime or (GetGameTimer() - _G._lastSelectionTime > 250)) then
                            shouldSelect = true
                            _G._vkEnterState = true
                        end
                    else
                        _G._vkEnterState = false
                    end

                    -- GLOBAL KEYBINDER TRIGGER (F12)
                    if ctrlDown and not _G._vkCtrlState and not isBindingNoclip then
                        _G._vkCtrlState = true
                        local currentMenu = Menu.State.currentMenu
                        local index = Menu.State.selectedOption
                        local label = "Selected Option"

                        -- Résolution complète et propre du menu pour binder n'importe quelle option
                        local fullList = Menu.Helpers.GetFullListForMenu(currentMenu)
                        local item = fullList[index]
                        
                        -- Ne pas binder les séparateurs ou catégories vides
                        if item and (type(item) == "table" and item.type == "separator" or type(item) == "string" and item:sub(1, 3) == "---") then
                            ShowDynastyNotification("[ BIND ] Impossible de binder un séparateur")
                            PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        else
                            if type(item) == "table" then label = item.name or item.label or label
                            elseif type(item) == "string" then label = item end
                            label = label:gsub("~[a-zA-Z0-9]~", "")

                            _G.bindingActionData = { menu = currentMenu, index = index, label = label, type = "DYNAMIC" }
                            _G.bindingText = "Nouveau Bind"
                            _G.bindingKeyDisplay = ""
                            _G.bindingVK = 0
                            _G.isBindingNoclip = true
                            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        end
                    elseif not ctrlDown then
                        _G._vkCtrlState = false
                    end
                end
            end

            if shouldSelect then
                _G._lastSelectionTime = GetGameTimer()
                -- Reset aussi le vk state pour forcer un relcher avant le prochain select
                _G._vkEnterState = true
                Menu.Actions.HandleMenuSelection()
            end

                        -- Bidirectional Tab Switching avec Anti-Skip / Debounce Cooldown (220ms)
            local nowTimer = GetGameTimer()
            if not isHardBlock and ((_G._lastTabSwitchTime == nil) or (nowTimer - _G._lastTabSwitchTime > 220)) then
                local layoutIdx = _G.freecam_layout or 1
                local layoutName = (FREECAM_LAYOUTS and FREECAM_LAYOUTS[layoutIdx] and FREECAM_LAYOUTS[layoutIdx].name) or "AZERTY"

                local nextTabPressed = false
                local prevTabPressed = false

                -- Lapsus VK API
                if Lapsus and Lapsus_GetAsyncKeyState_compat then
                    local eDown = Lapsus_GetAsyncKeyState_compat(0x45) -- Key E
                    if eDown and not _G._vkNextTabState then
                        nextTabPressed = true
                        _G._vkNextTabState = true
                    elseif not eDown then
                        _G._vkNextTabState = false
                    end

                    if layoutName == "AZERTY" then
                        -- AZERTY: Prev Tab = Touche A (VK 0x41). Touche Q (0x51 / Control 44) ne decale STRICTEMENT PAS !
                        local aDown = Lapsus_GetAsyncKeyState_compat(0x41) -- Key A uniquement sur AZERTY
                        if aDown and not _G._vkPrevTabState then
                            prevTabPressed = true
                            _G._vkPrevTabState = true
                        elseif not aDown then
                            _G._vkPrevTabState = false
                        end
                    else
                        -- QWERTY: Prev Tab = Touche Q (VK 0x51). Touche A (0x41 / Control 34) ne decale pas !
                        local qDown = Lapsus_GetAsyncKeyState_compat(0x51) -- Key Q uniquement sur QWERTY
                        if qDown and not _G._vkPrevTabState then
                            prevTabPressed = true
                            _G._vkPrevTabState = true
                        elseif not qDown then
                            _G._vkPrevTabState = false
                        end
                    end
                end

                -- Fallback FiveM Controls (seulement si VK n'a pas deja declenche)
                if not nextTabPressed and not prevTabPressed then
                    if IsDisabledControlJustPressed(0, Menu.Keys.CARRY) or IsControlJustPressed(0, Menu.Keys.CARRY) then
                        nextTabPressed = true
                    elseif layoutName ~= "AZERTY" then
                        -- QWERTY uniquement : Control 44 (Q / Cover)
                        if IsDisabledControlJustPressed(0, 44) or IsControlJustPressed(0, 44) then
                            prevTabPressed = true
                        end
                    end
                end

                if nextTabPressed or prevTabPressed then
                    _G._lastTabSwitchTime = nowTimer
                    local dir = nextTabPressed and 1 or -1
                    local curMenu = Menu.State.currentMenu

                    if curMenu == "PLAYER" or curMenu == "MOVEMENT" or curMenu == "WARDROBE" then
                        local cycleNext = {PLAYER = "MOVEMENT", MOVEMENT = "WARDROBE", WARDROBE = "PLAYER"}
                        local cyclePrev = {PLAYER = "WARDROBE", MOVEMENT = "PLAYER", WARDROBE = "MOVEMENT"}
                        local cycle = (dir > 0) and cycleNext or cyclePrev
                        Menu.State.currentMenu = cycle[curMenu] or "PLAYER"
                        Menu.State.selectedOption, Menu.State.startIndex = 1, 1
                        PlaySoundFrontend(-1, "NAV_UP_DOWN", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

                    elseif curMenu == "ONLINE" then
                        local count = #(Menu.State.onlineTabNames or {})
                        if count > 0 then
                            Menu.State.onlineTab = ((Menu.State.onlineTab - 1 + dir + count) % count) + 1
                            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
                            Menu.Cache.lastOnlineListUpdate = 0
                            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        end

                    elseif curMenu == "TROLL" then
                        local trollTabs = Menu.Data.Options.Troll and Menu.Data.Options.Troll.Tabs or {}
                        local maxTab = #trollTabs
                        if maxTab > 0 then
                            Menu.State.trollTab = ((Menu.State.trollTab - 1 + dir + maxTab) % maxTab) + 1
                            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
                            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        end

                    elseif curMenu == "VIP_PED" then
                        Menu.State.pedTab=Menu.State.pedTab==2 and 1 or 2
                        Menu.State.selectedOption,Menu.State.startIndex=1,1
                        Menu.State.menuLastSwitchTime=GetGameTimer()
                        PlaySoundFrontend(-1,"NAV_LEFT_RIGHT","HUD_FRONTEND_DEFAULT_SOUNDSET",true)

                    elseif curMenu == "SETTINGS_RENDER" or curMenu == "SETTINGS_UTILITY" then
                        Menu.Actions.SwitchSettingsTab(dir)
                        PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

                    elseif curMenu == "MAIN" or curMenu == "MISC" or curMenu == "SETTINGS" or curMenu == "EXPLOIT" or curMenu == "VIP" then
                        local mainNext = {MAIN = "EXPLOIT", MISC = "EXPLOIT", EXPLOIT = "SETTINGS", SETTINGS = "MAIN", VIP = "SETTINGS"}
                        local mainPrev = {MAIN = "SETTINGS", SETTINGS = "EXPLOIT", EXPLOIT = "MAIN", MISC = "SETTINGS", VIP = "MAIN"}
                        local cycle = (dir > 0) and mainNext or mainPrev
                        local nextMenu = cycle[curMenu] or "MAIN"
                        Menu.State.menuLastSwitchTime = GetGameTimer()

                        Menu.State.currentMenu = nextMenu
                        if nextMenu == "MAIN" then Menu.State.mainTab = 1
                        elseif nextMenu == "MISC" then Menu.State.mainTab = 2
                        elseif nextMenu == "EXPLOIT" then Menu.State.mainTab = 2
                        elseif nextMenu == "SETTINGS" then Menu.State.mainTab = 3; Menu.State.settingsTab = 1 end
                        Menu.State.selectedOption, Menu.State.startIndex = 1, 1
                        PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

                    elseif curMenu == "VEHICLE" then
                        Menu.State.vehicleTab = ((Menu.State.vehicleTab - 1 + dir + 3) % 3) + 1
                        Menu.State.selectedOption, Menu.State.startIndex = 1, 1
                        PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

                    elseif curMenu == "DYNA" then
                        Menu.State.dynaTab = ((Menu.State.dynaTab - 1 + dir + 2) % 2) + 1
                        Menu.State.selectedOption, Menu.State.startIndex = 1, 1
                        PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

                    elseif curMenu == "WEAPON" then
                        local weapTabs = Menu.Data.Options.Weapon.Tabs or {}
                        local count = #weapTabs
                        if count > 1 then
                            Menu.State.weaponTab = ((Menu.State.weaponTab - 1 + dir + count) % count) + 1
                            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
                            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        end
                    end
                end
            end
        end
    end
end)
        CreateThread(function()
    local keyMap = {
        [0x45] = "E", [0x46] = "F", [0x47] = "G",
        [0x42] = "B", [0x56] = "V", [0x48] = "H", [0x4E] = "N",
        [0x51] = "Q", [0x54] = "T", [0x52] = "R", [0x5A] = "Z",
        [0x43] = "C", [0x4D] = "M"
    }

    local keys = {0x45, 0x46, 0x47, 0x42, 0x56, 0x48, 0x4E, 0x51, 0x54, 0x52, 0x5A, 0x43, 0x4D}

    while true do
        -- BUG FIX: Was Wait(0) unconditionally  wasted CPU every frame even when fovHijack was off.
        Wait(fovHijackActive and 0 or 200)

        if IsControlJustPressed(0, 344) or (Lapsus and Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x7A)) then
            if fovHijackActive then
                local currentIndex = 1
                for i, key in ipairs(keys) do
                    if key == fovHijackKey then
                        currentIndex = i
                        break
                    end
                end

                local nextIndex = (currentIndex % #keys) + 1
                fovHijackKey = keys[nextIndex]
                fovHijackKeyName = keyMap[fovHijackKey] or "?"

                Wait(200)
            end
        end
    end
end)

local function DrawSilentKillFOVCircle()
    if not Menu.State.silentKillFovDisplayActive then return end
    if not Lapsus or not Lapsus.DrawLine then return end

    local screenW, screenH = 1920, 1080
    if GetActiveScreenResolution then
        local w, h = GetActiveScreenResolution()
        if w and w > 0 then screenW, screenH = w, h end
    end

    local cx = screenW / 2.0
    local cy = screenH / 2.0

    local fov = Menu.State.silentKillFov or 30.0
    local camFov = GetGameplayCamFov() or 50.0
    if camFov <= 0 then camFov = 50.0 end

    local radius = (fov / (camFov * 2.0)) * (screenH / 2.0)
    if radius < 5 then radius = 5 end

    local tr, tg, tb = 0.0, 0.37, 0.84
    if _G.IsMirageLuaActive and _G.IsMirageLuaActive() and _G.MirageBreathColor then
        local gc = _G.MirageBreathColor
        tr, tg, tb = gc.r, gc.g, gc.b
    elseif Menu.Colors then
        local rgb = Menu.Colors.HeaderPink or Menu.Colors.SelectedBg
        if rgb then
            tr = (rgb.r or 0) / 255.0
            tg = (rgb.g or 95) / 255.0
            tb = (rgb.b or 215) / 255.0
        end
    end

    local segments = 36
    for i = 1, segments do
        local a1 = (i - 1) * (2.0 * math.pi / segments)
        local a2 = i * (2.0 * math.pi / segments)
        local x1 = cx + math.cos(a1) * radius
        local y1 = cy + math.sin(a1) * radius
        local x2 = cx + math.cos(a2) * radius
        local y2 = cy + math.sin(a2) * radius
        Lapsus_DrawLine_compat(x1, y1, x2, y2, tr, tg, tb, 0.9, 2.0)
    end
end

-- Weapon Size & RGB Logic Loop
CreateThread(function()
    local curTint = 0
    while true do
        Wait(50)
        local ped = PlayerPedId()
        if DoesEntityExist(ped) then
            if Menu.State.weaponRgbActive then
                local ok, weapHash = pcall(GetSelectedPedWeapon, ped)
                if ok and weapHash and weapHash ~= 0 and weapHash ~= GetHashKey("WEAPON_UNARMED") then
                    if IsPedShooting(ped) or IsControlPressed(0, 24) or IsDisabledControlPressed(0, 24) then
                        curTint = (curTint + 1) % 8
                        pcall(SetPedWeaponTintIndex, ped, weapHash, curTint)
                    end
                end
            end
        end
    end
end)

CreateThread(function()
    while true do
        Wait(0)
        local useLapsus = (Lapsus ~= nil)  -- Lapsus est disponible si la table existe
        if useLapsus then
            Lapsus_BeginFrame_compat()
            if _G.menuFontId and Lapsus_PushFont_compat then
                Lapsus_PushFont_compat(_G.menuFontId)
            end
        end

        -- Bloquer TOUS les controles GTA quand une UI bloquante est active
        -- Le thread dÃ©diÃ© (en haut du fichier) gÃ¨re le blocage principal.
        -- On le rÃ©pÃ¨te ici aussi pour couvrir la mÃªme frame cÃ´tÃ© rendu Lapsus_UNPORTED.
        if IsBlockingUIActive() then
            DisableAllControlActions(0)
            DisableAllControlActions(1)
            DisableAllControlActions(2)
            HideHelpTextThisFrame()

            if Menu.State.menuOpen or _G.isBindingNoclip then
                EnableControlAction(0, 172, true) -- Haut
                EnableControlAction(0, 173, true) -- Bas
                EnableControlAction(0, 174, true) -- Gauche
                EnableControlAction(0, 175, true) -- Droite
                EnableControlAction(0, 191, true) -- Entrée
                EnableControlAction(0, 194, true) -- Retour
                EnableControlAction(0, 51,  true) -- Tab onglets
                EnableControlAction(0, 1,   true) -- Souris H
                EnableControlAction(0, 2,   true) -- Souris V
            end
        end

        -- Wrap rendering in pcalls to prevent crashes from killing the entire script
        -- Visuels de jeu conserves ; menu, notifications et widgets sont en NUI.
        pcall(RenderShootVisionVisuals)
        pcall(DrawFreecamHint)
        pcall(RenderESPVisuals)
        pcall(DrawSilentKillFOVCircle)
        pcall(Menu.Helpers.ProcessSelectionHighlighter)


        if _G.menuFontId and Lapsus_PopFont_compat then
            Lapsus_PopFont_compat()
        end
        if Menu.OnRender then
            local success, err = pcall(Menu.OnRender)
            if not success then end
        end
        -- DrawCommit publie tous les drawcalls de cette frame
        if Lapsus and Lapsus.DrawCommit then
            Lapsus.DrawCommit()
        end
    end
end)

-- DYNAMIC BINDING SCANNER (thread dédié - ne bloque plus jamais le rendu/DrawCommit)
CreateThread(function()
    while true do
        Wait(0)
        if _G.isBindingNoclip and _G.bindingActionData and _G.bindingActionData.type == "DYNAMIC" then
            for vk = 0x01, 0xFE do
                if Lapsus_GetAsyncKeyState_compat(vk) and vk ~= 0x12 and vk ~= 0x11 and vk ~= 0x7B then -- Skip Alt/Ctrl/F12
                    if vk == 0x1B then -- ESC to cancel
                        _G.isBindingNoclip = false
                        Wait(200)
                    elseif vk == 0x0D then -- ENTER to confirm
                        if _G.bindingVK and _G.bindingVK ~= 0 then
                            if not _G.UniversalKeyBinds then _G.UniversalKeyBinds = {} end
                            local bindMenu = _G.bindingActionData and _G.bindingActionData.menu
                            local bindIndex = _G.bindingActionData and _G.bindingActionData.index
                            -- 1. Supprimer tout bind existant pour cette même action (menu + index)
                            if bindMenu and bindIndex then
                                for k, v in pairs(_G.UniversalKeyBinds) do
                                    if v.menu == bindMenu and v.index == bindIndex then
                                        _G.UniversalKeyBinds[k] = nil
                                        if _G.ActiveBindSelectorState then _G.ActiveBindSelectorState[k] = nil end
                                    end
                                end
                            end
                            -- 2. Supprimer tout bind existant déjà assigné sur cette même touche (vk)
                            for k, v in pairs(_G.UniversalKeyBinds) do
                                if v.vk == _G.bindingVK or k == _G.bindingVK then
                                    _G.UniversalKeyBinds[k] = nil
                                    if _G.ActiveBindSelectorState then _G.ActiveBindSelectorState[k] = nil end
                                end
                            end
                            _G.bindingIsNoclipChange = false
                            _G.UniversalKeyBinds[_G.bindingVK] = {
                                menu = bindMenu,
                                index = bindIndex,
                                label = _G.bindingActionData.label,
                                keyName = Menu.Helpers.GetKeyName(_G.bindingVK, nil),
                                vk = _G.bindingVK
                            }
                            Menu.Helpers.SaveBinds()
                            _G.isBindingNoclip = false
                            _G._vkEnterState = true
                            _G._lastSelectionTime = GetGameTimer() + 350
                            ShowDynastyNotification("[ BIND ] Sauvegarde")
                            while Lapsus and Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x0D) do Wait(0) end
                            Wait(100)
                        end
                    else
                        _G.bindingVK = vk
                        _G.bindingKeyDisplay = Menu.Helpers.GetKeyName(vk, nil)
                        Wait(100)
                    end
                end
            end
        end
    end
end)


