-- Sauvegarde toutes les options actives sous un nom choisi par l'utilisateur
-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
-- SYSTÃˆME CONFIG AUTOSAVE â€” fichier unique par joueur
-- Sauvegarde silencieuse Ã  chaque fermeture de menu + changement option
-- Chargement automatique au login
-- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
local _CFG_FILE = "dynasty_config.txt"

function Menu.Helpers.PromptKeyboardInput(title, defaultText, maxLen)
    _G.CustomInputActive = true
    _G.CustomInputState = {
        title = title,
        inputBuffer = defaultText or "",
        errorMsg = ""
    }

    local inputVKtoChar = {
        [0x41]="a",[0x42]="b",[0x43]="c",[0x44]="d",[0x45]="e",
        [0x46]="f",[0x47]="g",[0x48]="h",[0x49]="i",[0x4A]="j",
        [0x4B]="k",[0x4C]="l",[0x4D]="m",[0x4E]="n",[0x4F]="o",
        [0x50]="p",[0x51]="q",[0x52]="r",[0x53]="s",[0x54]="t",
        [0x55]="u",[0x56]="v",[0x57]="w",[0x58]="x",[0x59]="y",
        [0x5A]="z",
        [0x30]="0",[0x31]="1",[0x32]="2",[0x33]="3",[0x34]="4",
        [0x35]="5",[0x36]="6",[0x37]="7",[0x38]="8",[0x39]="9",
        [0x60]="0",[0x61]="1",[0x62]="2",[0x63]="3",[0x64]="4",
        [0x65]="5",[0x66]="6",[0x67]="7",[0x68]="8",[0x69]="9",
        [0x20]=" ", [0xBD]="-", [0x6D]="-"
    }

    local prevVK = {}
    local bsPrev = false
    local enterPrev = false
    local escapePrev = false

    local result = nil
    local shouldExit = false

    while not shouldExit do
        Wait(0)
        HideHelpTextThisFrame()
        DisableAllControlActions(0)
        DisableAllControlActions(1)
        DisableAllControlActions(2)

        if not Lapsus or not Lapsus_GetAsyncKeyState_compat then
            shouldExit = true
            break
        end

        local now = GetGameTimer()
        local shiftDown = Lapsus_GetAsyncKeyState_compat(0x10) or Lapsus_GetAsyncKeyState_compat(0xA0) or Lapsus_GetAsyncKeyState_compat(0xA1)

        -- Backspace (VK_BACK = 0x08)
        local bsDown = Lapsus_GetAsyncKeyState_compat(0x08)
        if bsDown and not bsPrev then
            local buf = _G.CustomInputState.inputBuffer
            if #buf > 0 then
                _G.CustomInputState.inputBuffer = buf:sub(1, #buf - 1)
                PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            end
        end
        bsPrev = bsDown

        -- Keystrokes
        for vk, ch in pairs(inputVKtoChar) do
            local down = Lapsus_GetAsyncKeyState_compat(vk)
            if down and not prevVK[vk] then
                if #_G.CustomInputState.inputBuffer < (maxLen or 20) then
                    local finalChar = ch
                    if shiftDown then
                        finalChar = ch:upper()
                        if ch == "-" then finalChar = "_" end -- Shift + Hyphen is Underscore
                    else
                        finalChar = ch:lower()
                    end
                    _G.CustomInputState.inputBuffer = _G.CustomInputState.inputBuffer .. finalChar
                    PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                end
            end
            prevVK[vk] = down
        end

        -- Enter (VK_RETURN = 0x0D)
        local enterDown = Lapsus_GetAsyncKeyState_compat(0x0D)
        if enterDown and not enterPrev then
            local buf = _G.CustomInputState.inputBuffer
            buf = buf:gsub("^%s*(.-)%s*$", "%1") -- clean spaces
            if buf ~= "" then
                result = buf
                shouldExit = true
                _G._vkEnterState = true
                _G._lastSelectionTime = GetGameTimer() + 350
                PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                while Lapsus and Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x0D) do Wait(0) end
            else
                _G.CustomInputState.errorMsg = "Nom vide !"
                PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            end
        end
        enterPrev = enterDown

        -- Escape (VK_ESCAPE = 0x1B)
        local escapeDown = Lapsus_GetAsyncKeyState_compat(0x1B)
        if escapeDown and not escapePrev then
            shouldExit = true
            PlaySoundFrontend(-1, "BACK", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end
        escapePrev = escapeDown
    end

    _G.CustomInputActive = false
    _G.CustomInputState = nil
    return result
end

-- Demande une confirmation Oui/Non (ENTREE = oui, ECHAP = non)
function Menu.Helpers.PromptConfirm(message)
    _G.CustomInputActive = true
    _G.CustomInputState  = { title = message, inputBuffer = "", errorMsg = "ENTREE = Confirmer   ECHAP = Annuler" }
    -- Attendre que Enter et Escape soient relaches (evite declenchement immediat)
    if Lapsus and Lapsus_GetAsyncKeyState_compat then
        while Lapsus_GetAsyncKeyState_compat(0x0D) or Lapsus_GetAsyncKeyState_compat(0x1B) do
            Wait(16)
        end
    end
    Wait(80) -- petit buffer supplementaire
    local result = false
    local enterPrev = false
    local escapePrev = false
    while true do
        Wait(0)
        HideHelpTextThisFrame()
        DisableAllControlActions(0); DisableAllControlActions(1); DisableAllControlActions(2)
        if not Lapsus or not Lapsus_GetAsyncKeyState_compat then break end
        local enterDown  = Lapsus_GetAsyncKeyState_compat(0x0D)
        local escapeDown = Lapsus_GetAsyncKeyState_compat(0x1B)
        if enterDown and not enterPrev then
            result = true
            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            while Lapsus_GetAsyncKeyState_compat(0x0D) do Wait(0) end
            break
        end
        if escapeDown and not escapePrev then
            PlaySoundFrontend(-1, "BACK", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            break
        end
        enterPrev  = enterDown
        escapePrev = escapeDown
    end
    _G.CustomInputActive = false
    _G.CustomInputState  = nil
    return result
end

function Menu.Helpers.SaveConfigProfile(name)
    local ok, err = pcall(function()
        if not Lapsus then
            ShowDynastyNotification("[ CONFIG ] Executeur manquant")
            return
        end
        local cfg = {
            sidebarSide     = Menu.State.sidebarSide or "right",
            menuScale       = _G.menuScale or 1.0,
            themeIndex      = Menu.ThemeIndex or 1,
            bannerIndex     = Menu.BannerIndex or 1,
            freecam_layout  = _G.freecam_layout or 1,
            fullGodMode     = Menu.State.fullGodModeActive,
            semiGodMode     = Menu.State.semiGodModeActive,
            noWanted        = Menu.State.noWantedActive,
            noReload        = Menu.State.noReloadActive,
            infiniteAmmo    = Menu.State.infiniteAmmoActive,
            superJump       = Menu.State.superJumpActive,
            ragdollOff      = Menu.State.ragdollOffActive,
            playerInvisible = Menu.State.playerInvisible,
            shiftBoost      = Menu.State.shiftBoostActive,
            noclipInvisible    = Menu.State.noclipInvisible,
            noclipPose         = Menu.State.noclipPose,
            noclipSpeed        = Menu.State.noclipSpeed,
            slide              = Menu.State.slideActive,
            antiCollision      = Menu.State.antiCollisionActive,
            damageBoost        = Menu.State.damageBoostActive,
            rapidFire          = Menu.State.rapidFireActive,
            noClip             = Menu.State.noclipActive,
            highlighterSizeIdx = Menu.State.highlighterSizeIdx,
        }

        -- Inclure les binds dans la config
        local bindsStr = "{"
        if _G.UniversalKeyBinds then
            for k, v in pairs(_G.UniversalKeyBinds) do
                bindsStr = bindsStr .. string.format("[%d]={menu=%q,index=%d,label=%q,vk=%d},", k, v.menu or "", v.index or 0, v.label or "", v.vk or 0)
            end
        end
        bindsStr = bindsStr .. "}"
        cfg.binds = bindsStr

        -- Serialiser la config
        local str = "{"
        for k, v in pairs(cfg) do
            if type(v) == "string" then
                str = str .. string.format("[%q]=%q,", k, v)
            elseif type(v) == "boolean" then
                str = str .. string.format("[%q]=%s,", k, tostring(v))
            else
                str = str .. string.format("[%q]=%s,", k, tostring(v))
            end
        end
        str = str .. "}"

        -- Enregistrer dans notre table locale de profils
        if not Menu.CloudConfigs then Menu.CloudConfigs = { profiles = {} } end
        if not Menu.CloudConfigs.profiles then Menu.CloudConfigs.profiles = {} end
        Menu.CloudConfigs.profiles[name] = str

        -- Serialiser la table complete de profils pour le cloud / local
        local fullSerialized = "{"
        fullSerialized = fullSerialized .. '["profiles"]={'
        for pName, pStr in pairs(Menu.CloudConfigs.profiles) do
            fullSerialized = fullSerialized .. string.format("[%q]=%q,", pName, pStr)
        end
        fullSerialized = fullSerialized .. "}}"

        -- Sauvegarde locale desactivee (uniquement Railway)
        local localOk = false

        -- Sauvegarde cloud via POST
        if _G.AuthedCode and _G.AuthedCode ~= "" and Lapsus_HttpPost_compat then
            local AUTH_API = "https://fpsbn-auth-production.up.railway.app"
            local safeConfig = fullSerialized:gsub('\\', '\\\\'):gsub('"', '\\"')
            local jsonBody = '{"code":"' .. _G.AuthedCode .. '","config":"' .. safeConfig .. '"}'
            local status, resp = Lapsus_HttpPost_compat(AUTH_API .. "/config/save", jsonBody, "application/json")
            if status == 200 then
                if resp and resp:find('"ok":true') then
                    ShowDynastyNotification("[ CONFIG ] '" .. name .. "' sauvegarde")
                else
                    local reason = resp and resp:match('"reason"%s*:%s*"([^"]+)"') or "erreur serveur"
                    ShowDynastyNotification("[ CONFIG ] Refus : " .. reason)
                end
            else
                ShowDynastyNotification("[ CONFIG ] Erreur " .. tostring(status))
            end
        elseif not localOk then
            ShowDynastyNotification("[ CONFIG ] Non connecte")
        else
            ShowDynastyNotification("[ CONFIG ] '" .. name .. "' sauvegarde")
        end
    end)
    if not ok then
        
        ShowDynastyNotification("[ CRASH ] Erreur")
    end
end

function Menu.Helpers.DeleteConfigProfile(name)
    if not Menu.CloudConfigs or not Menu.CloudConfigs.profiles or not Menu.CloudConfigs.profiles[name] then
        ShowDynastyNotification("[ CONFIG ] Profil inconnu")
        return
    end

    Menu.CloudConfigs.profiles[name] = nil

    -- Serialiser la table complete de profils pour le cloud / local
    local fullSerialized = "{"
    fullSerialized = fullSerialized .. '["profiles"]={'
    for pName, pStr in pairs(Menu.CloudConfigs.profiles) do
        fullSerialized = fullSerialized .. string.format("[%q]=%q,", pName, pStr)
    end
    fullSerialized = fullSerialized .. "}}"

    -- Sauvegarde locale desactivee
    local localOk = false

    -- Sauvegarde cloud via POST
    if _G.AuthedCode and _G.AuthedCode ~= "" and Lapsus_HttpPost_compat then
        local AUTH_API = "https://fpsbn-auth-production.up.railway.app"
        local safeConfig = fullSerialized:gsub('\\', '\\\\'):gsub('"', '\\"')
        local jsonBody = '{"code":"' .. _G.AuthedCode .. '","config":"' .. safeConfig .. '"}'
        local status, resp = Lapsus_HttpPost_compat(AUTH_API .. "/config/save", jsonBody, "application/json")
        if status == 200 then
            if resp and resp:find('"ok":true') then
                ShowDynastyNotification("[ CONFIG ] '" .. name .. "' supprime")
            else
                local reason = resp and resp:match('"reason"%s*:%s*"([^"]+)"') or "erreur serveur"
                ShowDynastyNotification("[ CONFIG ] Refus : " .. reason)
            end
        else
            ShowDynastyNotification("[ CONFIG ] Erreur " .. tostring(status))
        end
    elseif not localOk then
        ShowDynastyNotification("[ CONFIG ] Non connecte")
    else
        ShowDynastyNotification("[ CONFIG ] '" .. name .. "' supprime")
    end
end

function Menu.Helpers.LoadConfigProfile(name)
    if not Menu.CloudConfigs or not Menu.CloudConfigs.profiles or not Menu.CloudConfigs.profiles[name] then
        ShowDynastyNotification("[ CONFIG ] Profil inconnu")
        return
    end

    local content = Menu.CloudConfigs.profiles[name]
    local fn, err = load("return " .. content)
    if fn then
        local ok, data = pcall(fn)
        if ok and type(data) == "table" then
            Menu.Helpers.ApplyConfigData(data)
            ShowDynastyNotification("[ CONFIG ] '" .. name .. "' charge")
        else
            ShowDynastyNotification("[ CONFIG ] Echec chargement")
        end
    else
        ShowDynastyNotification("[ CONFIG ] Profil corrompu")
    end
end

function Menu.Helpers.GetConfigsOptions()
    local options = { "Create new config..." }
    if Menu.CloudConfigs and Menu.CloudConfigs.profiles then
        local sortedNames = {}
        for pName in pairs(Menu.CloudConfigs.profiles) do
            table.insert(sortedNames, pName)
        end
        table.sort(sortedNames)
        
        if #sortedNames > 0 then
            table.insert(options, { type = "separator", name = "--- SAVED PROFILES ---" })
            for _, pName in ipairs(sortedNames) do
                table.insert(options, pName)
            end
        end
    end
    return options
end

function Menu.Helpers.GetConfigOptionsSub()
    local name = Menu.State.selectedProfileName or "Config"
    return {
        "Load profile: " .. name,
        "Delete profile",
        "Back"
    }
end

function Menu.Helpers.ApplyConfigData(data)
    if type(data) ~= "table" then return end
    if data.sidebarSide    then Menu.State.sidebarSide = data.sidebarSide end
    if data.menuScale      then _G.menuScale = (data.menuScale==0.80 and 0.83 or data.menuScale); Menu.Cache.lastResCheck = 0 end
    if data.freecam_layout then _G.freecam_layout = data.freecam_layout end

    if data.themeIndex and Menu.Themes and Menu.Themes[data.themeIndex] then
        Menu.ThemeIndex = data.themeIndex
        local theme = Menu.Themes[data.themeIndex]
        if theme then Menu.Colors = theme end
    end
    if data.bannerIndex and Menu.AvailableBanners and Menu.AvailableBanners[data.bannerIndex] then
        Menu.BannerIndex = data.bannerIndex
        local b = Menu.AvailableBanners[data.bannerIndex]
        Menu.Banner.imageUrl = b.url
        if type(Menu.LoadNotifIconForBanner) == "function" then Menu.LoadNotifIconForBanner(b.name) end
        if type(Menu.LoadBannerTexture) == "function" then Menu.LoadBannerTexture(b.url) end
        if type(Menu.ApplyBannerTheme)  == "function" then Menu.ApplyBannerTheme(b.name) end
    end

    if data.fullGodMode     ~= nil then Menu.State.fullGodModeActive   = data.fullGodMode     end
    if data.semiGodMode     ~= nil then Menu.State.semiGodModeActive   = data.semiGodMode     end
    if data.noWanted        ~= nil then Menu.State.noWantedActive       = data.noWanted        end
    if data.noReload        ~= nil then Menu.State.noReloadActive       = data.noReload        end
    if data.infiniteAmmo    ~= nil then Menu.State.infiniteAmmoActive   = data.infiniteAmmo    end
    if data.superJump       ~= nil then Menu.State.superJumpActive      = data.superJump       end
    if data.ragdollOff      ~= nil then Menu.State.ragdollOffActive     = data.ragdollOff      end
    if data.playerInvisible ~= nil then Menu.State.playerInvisible      = data.playerInvisible end
    if data.shiftBoost      ~= nil then Menu.State.shiftBoostActive     = data.shiftBoost      end
    if data.noclipInvisible ~= nil then Menu.State.noclipInvisible      = data.noclipInvisible end
    if data.noclipPose      ~= nil then Menu.State.noclipPose           = data.noclipPose      end
    if data.noclipSpeed     ~= nil then Menu.State.noclipSpeed          = data.noclipSpeed     end
    if data.slide           ~= nil then Menu.State.slideActive          = data.slide           end
    if data.antiCollision   ~= nil then Menu.State.antiCollisionActive  = data.antiCollision   end
    if data.damageBoost     ~= nil then Menu.State.damageBoostActive    = data.damageBoost     end
    if data.rapidFire       ~= nil then Menu.State.rapidFireActive      = data.rapidFire       end
    if data.highlighterSizeIdx ~= nil then
        Menu.State.highlighterSizeIdx = data.highlighterSizeIdx
        local sizes = { 1.0, 2.0, 3.5 }
        Menu.State.highlighterThickness = sizes[data.highlighterSizeIdx] or 1.0
    end

    -- Restaurer les binds
    if data.binds and data.binds ~= "" then
        local fn, err = load("return " .. data.binds)
        if fn then
            local ok, bindsData = pcall(fn)
            if ok and type(bindsData) == "table" then
                if not _G.UniversalKeyBinds then _G.UniversalKeyBinds = {} end
                for k, v in pairs(bindsData) do
                    -- Ne pas ecraser les binds fixes (M=244, H=251)
                    if k ~= 244 and k ~= 251 then
                        _G.UniversalKeyBinds[k] = v
                    end
                end
            end
        end
    end
end

