function Menu.Helpers.GetWeaponAttachOptions()
    local ped = PlayerPedId()
    local weapHash = GetSelectedPedWeapon(ped)
    if not weapHash or weapHash == 0 or weapHash == GetHashKey("WEAPON_UNARMED") then
        return {{ type = "attach", name = "Aucune arme equipee", id = "none", weapHash = 0, toggleActive = false }}
    end
    local result = {}
    local catCounts = {}
    for _, def in ipairs(_ATTACH_DEFS) do
        for _, compName in ipairs(def.comps) do
            local compHash = GetHashKey(compName)
            local compatible = false
            local has = false
            local ok, hasNow = pcall(HasPedGotWeaponComponent, ped, weapHash, compHash)
            if ok and hasNow then
                compatible = true
                has = true
            else
                pcall(GiveWeaponComponentToPed, ped, weapHash, compHash)
                local ok2, nowHas = pcall(HasPedGotWeaponComponent, ped, weapHash, compHash)
                if ok2 and nowHas then
                    compatible = true
                    pcall(RemoveWeaponComponentFromPed, ped, weapHash, compHash)
                end
            end
            if compatible then
                catCounts[def.id] = (catCounts[def.id] or 0) + 1
                table.insert(result, {
                    type = "attach",
                    name = def.name .. " " .. catCounts[def.id],
                    id = compName,
                    weapHash = weapHash,
                    toggleActive = has,
                })
            end
        end
    end
    if #result == 0 then
        table.insert(result, { type = "attach", name = "Aucun accessoire disponible", id = "none", weapHash = weapHash, toggleActive = false })
    end

    table.insert(result, { type = "separator", name = "--- Mods ---", label = "--- Mods ---" })
    table.insert(result, {
        type = "weapon_size",
        name = "Weapon Size",
        id = "weapon_size",
        state = "weaponSizeActive"
    })
    table.insert(result, {
        type = "toggle",
        name = "Weapon RGB",
        id = "weapon_rgb",
        state = "weaponRgbActive"
    })

    return result
end

-- Weapon Size utilise les unites natives Lapsus (10 par defaut, maximum 100).
Menu.State.weaponSizeActive = false
Menu.State.weaponSizeValue = 10
function Menu.Actions.SetWeaponSize(enable,value)
    enable=not not enable
    value=tonumber(value or Menu.State.weaponSizeValue or 10)
    if not value or value~=value or value==math.huge or value==-math.huge or value<=0 then
        ShowDynastyNotification('Weapon Size : valeur invalide'); return false
    end
    value=math.max(1,math.min(100,math.floor(value+0.5)))
    if type(Lapsus)~='table' or type(Lapsus.WeaponSize)~='function' then
        ShowDynastyNotification('Weapon Size : API indisponible'); return false
    end
    local ok,accepted,reason
    if enable then ok,accepted,reason=pcall(Lapsus.WeaponSize,true,value)
    else ok,accepted,reason=pcall(Lapsus.WeaponSize,false) end
    if not ok or not accepted then
        
        ShowDynastyNotification('Weapon Size : echec'); return false
    end
    Menu.State.weaponSizeActive=enable
    Menu.State.weaponSizeValue=value
    return true
end

-- Spoof de l'arme equipee, partage entre les menus Give.
Menu.State.spoofWeaponActive = false
function Menu.Actions.SetSpoofWeapon(enable)
    if type(Lapsus)~='table' or type(Lapsus.SpoofServerWeapon)~='function' then
        ShowDynastyNotification('Spoof Weapon : API indisponible')
        return false
    end
    enable=not not enable
    local ok,success=pcall(Lapsus.SpoofServerWeapon,enable)
    if not ok or not success then
        
        ShowDynastyNotification('Spoof Weapon : echec')
        return false
    end
    Menu.State.spoofWeaponActive=enable
    ShowDynastyNotification('Spoof Weapon '..(enable and 'ON' or 'OFF'))
    return true
end
function Menu.Actions.ToggleSpoofWeapon()
    return Menu.Actions.SetSpoofWeapon(not Menu.State.spoofWeaponActive)
end

