function Menu.Helpers.GetPedSkin(ped)
    return {
        sex = GetEntityModel(ped) == GetHashKey("mp_m_freemode_01") and 0 or 1,
        face = 0,
        skin = 0,
        hair_1 = GetPedDrawableVariation(ped, 2),
        hair_2 = GetPedTextureVariation(ped, 2),
        hair_color_1 = 0,
        hair_color_2 = 0,
        decals_1 = GetPedDrawableVariation(ped, 10),
        decals_2 = GetPedTextureVariation(ped, 10),
        tshirt_1 = GetPedDrawableVariation(ped, 8),
        tshirt_2 = GetPedTextureVariation(ped, 8),
        torso_1 = GetPedDrawableVariation(ped, 11),
        torso_2 = GetPedTextureVariation(ped, 11),
        arms = GetPedDrawableVariation(ped, 3),
        arms_2 = GetPedTextureVariation(ped, 3),
        pants_1 = GetPedDrawableVariation(ped, 4),
        pants_2 = GetPedTextureVariation(ped, 4),
        shoes_1 = GetPedDrawableVariation(ped, 6),
        shoes_2 = GetPedTextureVariation(ped, 6),
        mask_1 = GetPedDrawableVariation(ped, 1),
        mask_2 = GetPedTextureVariation(ped, 1),
        helmet_1 = GetPedPropIndex(ped, 0),
        helmet_2 = math.max(0, GetPedPropTextureIndex(ped, 0)),
        bproof_1 = GetPedDrawableVariation(ped, 9),
        bproof_2 = GetPedTextureVariation(ped, 9),
        bags_1 = GetPedDrawableVariation(ped, 5),
        bags_2 = GetPedTextureVariation(ped, 5),
        beard_1 = 0,
        beard_2 = 0,
        beard_3 = 0,
        beard_4 = 0,
        chain_1 = GetPedDrawableVariation(ped, 7),
        chain_2 = GetPedTextureVariation(ped, 7),
        glasses_1 = GetPedPropIndex(ped, 1),
        glasses_2 = math.max(0, GetPedPropTextureIndex(ped, 1))
    }
end

function Menu.Actions.LoadOutfit(data)
    if not data then return end -- safety: nil data would crash skin application
    local compToSkinchanger = {
        [1] = {"mask_1", "mask_2"},
        [2] = {"hair_1", "hair_2"},
        [3] = {"arms", "arms_2"},
        [4] = {"pants_1", "pants_2"},
        [5] = {"bags_1", "bags_2"},
        [6] = {"shoes_1", "shoes_2"},
        [7] = {"chain_1", "chain_2"},
        [8] = {"tshirt_1", "tshirt_2"},
        [9] = {"bproof_1", "bproof_2"},
        [10] = {"decals_1", "decals_2"},
        [11] = {"torso_1", "torso_2"}
    }

    local propToSkinchanger = {
        [0] = {"helmet_1", "helmet_2"},
        [1] = {"glasses_1", "glasses_2"},
        [2] = {"ears_1", "ears_2"}
    }

    local skin = Menu.Helpers.GetPedSkin(PlayerPedId())
    if not skin then
        ShowDynastyNotification("[ STYLE ] Chargement echoue")
        return
    end

    if data.components then
        for _, comp in ipairs(data.components) do
            local keys = compToSkinchanger[comp[1]]
            if keys then
                skin[keys[1]] = comp[2]
                skin[keys[2]] = comp[3]
            end
        end
    end

    if data.props then
        for _, prop in ipairs(data.props) do
            local keys = propToSkinchanger[prop[1]]
            if keys then
                local propTex = prop[3]
                if prop[2] == -1 then propTex = 0 end
                skin[keys[1]] = prop[2]
                skin[keys[2]] = propTex
            end
        end
    end

    TriggerEvent('skinchanger:loadSkin', skin)
    ShowDynastyNotification("[ OUTFIT ] " .. data.name)
end

function Menu.Actions.RandomOutfit()
    local ped = PlayerPedId()
    if not DoesEntityExist(ped) then return end

    -- 1. Randomize Hair & Colors
    local hairCount = GetNumberOfPedDrawableVariations(ped, 2)
    local hair_1 = hairCount > 0 and math.random(0, hairCount-1) or 0

    local hairColor = math.random(0, 63)
    local highlightColor = math.random(0, 63)

    local masks = {
        {115, 6}, {256, 0}, {0, 0}, {0, 0}, {0, 0}
    }

    -- Safe Upper Body Combinations (Fixed Geometry, Random Texture where possible)
    -- Format: {Torso, Txt, Tshirt, Txt, Arms, Txt, Vest, Txt, Bag, Txt, Chain, Txt}
    local tops = {
        -- Alkaida (Tactical) - Fixed
        {310, 4, 15, 0, 14, 0, 11, 1, 0, 0, 0, 0},
        -- J-Y (Custom) - Fixed
        {924, 0, 15, 0, 78, 0, 0, 0, 152, 0, 180, 0},
        -- Luxe Classy (Suit) - Allow Texture Var for Jacket(11) & Pants(4)
        {32, -1, 31, 1, 4, 0, 0, 0, 0, 0, 22, 0},
        -- Hood (Hoodie) - Allow Texture Var
        {84, -1, 15, 0, 14, 0, 0, 0, 0, 0, 0, 0},
        -- Casual Clean (T-Shirt) - Allow Texture Var
        {4, -1, 9, 0, 0, 0, 0, 0, 0, 0, 0, 0},
        -- Street Dark (Arms 1) - Allow Texture Var
        {111, -1, 15, 0, 1, 0, 0, 0, 0, 0, 0, 0},
        -- Ombre du rif (New)
        {0, 2, 15, 0, 30, 0, 0, 0, 0, 0, 0, 0},
        -- Royal Mafia (New)
        {0, 2, 171, 8, 0, 0, 0, 0, 0, 0, 0, 0}
    }

    local pants = {
        {119, 4}, -- Alkaida
        {16, 3},  -- J-Y
        {24, -1}, -- Luxe (Random Color)
        {47, -1}, -- Hood (Random Color)
        {1, -1},  -- Casual (Random Color)
        {28, -1}, -- Street (Random Color)
        {142, 0}, -- Ombre du rif (Pants)
        {9, 11}   -- Royal Mafia
    }

    local shoes = {
        {34, 0}, {208, 5}, {10, -1}, {6, -1}, {1, -1}, {250, 0}
    }

    local props = {
        {-1, 0, 0, 0}, {244, 0, 71, 0}, {-1, 0, 5, -1}, {-1, 0, 2, -1}
    }

    -- Random Selections
    local m = masks[math.random(#masks)]
    local t = tops[math.random(#tops)]
    local p = pants[math.random(#pants)]
    local s = shoes[math.random(#shoes)]
    local pr = props[math.random(#props)]

    -- Clamp Helper for Components
    local function clampComponent(compID, drawID)
        local count = GetNumberOfPedDrawableVariations(ped, compID)
        if count <= 0 then return 0 end
        if drawID < 0 or drawID >= count then
            return math.random(0, count - 1)
        end
        return drawID
    end

    -- Clamp Helper for Props
    local function clampProp(propID, drawID)
        local count = GetNumberOfPedPropDrawableVariations(ped, propID)
        if count <= 0 then return -1 end
        if drawID < -1 or drawID >= count then
            return -1
        end
        return drawID
    end

    -- Helper for Random/Safe Texture
    local function getTex(compID, drawID, defaultTex)
        local maxDrawables = GetNumberOfPedDrawableVariations(ped, compID)
        if drawID < 0 or drawID >= maxDrawables then
            return 0
        end
        local texCount = GetNumberOfPedTextureVariations(ped, compID, drawID)
        if texCount <= 0 then return 0 end
        if defaultTex == -1 then
            return math.random(0, texCount - 1)
        else
            if defaultTex >= 0 and defaultTex < texCount then
                return defaultTex
            else
                return 0
            end
        end
    end

    -- Helper for Random/Safe Prop Texture
    local function getPropTex(propID, drawID, defaultTex)
        local maxDrawables = GetNumberOfPedPropDrawableVariations(ped, propID)
        if drawID < 0 or drawID >= maxDrawables then
            return 0
        end
        local texCount = GetNumberOfPedPropTextureVariations(ped, propID, drawID)
        if texCount <= 0 then return 0 end
        if defaultTex == -1 then
            return math.random(0, texCount - 1)
        else
            if defaultTex >= 0 and defaultTex < texCount then
                return defaultTex
            else
                return 0
            end
        end
    end

    -- Clamp chosen drawables first
    local finalMask = clampComponent(1, m[1])
    local finalTorso = clampComponent(11, t[1])
    local finalTshirt = clampComponent(8, t[3])
    local finalArms = clampComponent(3, t[5])
    local finalBproof = clampComponent(9, t[7])
    local finalBags = clampComponent(5, t[9])
    local finalChain = clampComponent(7, t[11])
    local finalPants = clampComponent(4, p[1])
    local finalShoes = clampComponent(6, s[1])

    local finalHelmet = clampProp(0, pr[1])
    local finalGlasses = clampProp(1, pr[3])

    local changes = {
        mask_1 = finalMask,
        mask_2 = getTex(1, finalMask, m[2]),
        torso_1 = finalTorso,
        torso_2 = getTex(11, finalTorso, t[2]),
        tshirt_1 = finalTshirt,
        tshirt_2 = getTex(8, finalTshirt, t[4]),
        arms = finalArms,
        arms_2 = getTex(3, finalArms, t[6]),
        bproof_1 = finalBproof,
        bproof_2 = getTex(9, finalBproof, t[8]),
        bags_1 = finalBags,
        bags_2 = getTex(5, finalBags, t[10]),
        chain_1 = finalChain,
        chain_2 = getTex(7, finalChain, t[12]),
        pants_1 = finalPants,
        pants_2 = getTex(4, finalPants, p[2]),
        shoes_1 = finalShoes,
        shoes_2 = getTex(6, finalShoes, s[2]),
        hair_1 = hair_1,
        hair_2 = 0,
        hair_color_1 = hairColor,
        hair_color_2 = highlightColor,
        beard_1 = GetNumHeadOverlayValues(1) > 0 and math.random(0, GetNumHeadOverlayValues(1)-1) or 0,
        beard_2 = 10,
        beard_3 = hairColor,
        beard_4 = highlightColor,
        eyebrows_1 = GetNumHeadOverlayValues(2) > 0 and math.random(0, GetNumHeadOverlayValues(2)-1) or 0,
        eyebrows_2 = 10,
        eyebrows_3 = hairColor,
        eyebrows_4 = highlightColor
    }

    if finalHelmet ~= -1 then
        changes.helmet_1 = finalHelmet
        changes.helmet_2 = getPropTex(0, finalHelmet, pr[2])
    else
        changes.helmet_1 = -1
        changes.helmet_2 = 0
    end

    if finalGlasses ~= -1 then
        changes.glasses_1 = finalGlasses
        changes.glasses_2 = getPropTex(1, finalGlasses, pr[4])
    else
        changes.glasses_1 = -1
        changes.glasses_2 = 0
    end

    local skin = Menu.Helpers.GetPedSkin(ped)
    if skin then
        for k, v in pairs(changes) do
            skin[k] = v
        end
        TriggerEvent('skinchanger:loadSkin', skin)
    else
        ShowDynastyNotification("[ STYLE ] Chargement echoue")
    end

    ShowDynastyNotification("[ STYLE ] Aleatoire applique")
end

