local Bypass = {}
local function hookNativeSafe(hash, cb)
    if Lapsus and Lapsus.HookNative then
        Lapsus.HookNative(hash, cb)
    end
end

local function getAllResources()
    local resources = {}
    for i = 0, GetNumResources() - 1 do
        resources[#resources + 1] = GetResourceByFindIndex(i)
    end
    return resources
end

local function InjectPayload(res, code)
    if Lapsus and Lapsus_InjectResource_compat then
        Lapsus_InjectResource_compat(res, code)
    end
end

-- 1. FiveGuard Bypass
function Bypass.Fiveguard(resource)
    -- Native Spoofing pour FG (Leur faire croire que tout est normal)
    hookNativeSafe(0xFAEE099C6F890BB8, function(entity) -- GetEntityProofs
        if entity == PlayerPedId() then return false, false, false, false, false, false, false, false end
        return true
    end)
    hookNativeSafe(0xB7215396, function(player) -- IsPlayerInvincible
        if player == PlayerId() then return false end
        return true
    end)

    InjectPayload(resource, [[
        -- Neutralisation des tables FG
        _G.FG = nil; _G.FiveGuard = nil; _G.FG_AC = nil
        
        -- Proxy pour bloquer les exports FG
        if exports then
            local old_ex = exports
            _G.exports = setmetatable({}, {
                __index = function(t, k)
                    if k:lower():find("fiveguard") or k:lower():find("fg") then
                        return setmetatable({}, {
                            __index = function(_, m) return function() return true end end
                        })
                    end
                    return old_ex[k]
                end
            })
        end

        -- Blocage des events FG
        local _ts = TriggerServerEvent
        _G.TriggerServerEvent = function(ev, ...)
            if type(ev) == "string" and (ev:find("FiveGuard") or ev:find("fg:")) then return end
            return _ts(ev, ...)
        end

        -- Kill all FG related threads
        local threads = debug.getregistry()._threads or {}
        for i = #threads, 1, -1 do
            local info = debug.getinfo(threads[i])
            if info and info.source and (info.source:find("FiveGuard") or info.source:find("fg_")) then
                pcall(coroutine.close, threads[i])
            end
        end

        -- Cacher le menu aux scans de FiveGuard
        local raw_G = _G
        setmetatable(_G, {
            __index = function(t, k)
                if k == "Lapsus" or k == "Menu" then
                    local src = debug.getinfo(2, "S").source
                    if src and src:find("FiveGuard") then return nil end
                end
                return raw_G[k]
            end
        })
    ]])
    ShowDynastyNotification("[ FiveGuard ] Bypass OK")
end

-- 2. ReaperV4 Bypass
function Bypass.ReaperV4(resource)
    -- Spoofing Natives pour Reaper
    hookNativeSafe(0xFAEE099C6F890BB8, function(entity) -- GetEntityProofs
        if entity == PlayerPedId() then return false, false, false, false, false, false, false, false end
        return true
    end)
    hookNativeSafe(0x5A4F9EDF1670F7F4, function() return false end) -- SetEntityInvincible

    InjectPayload(resource, [[
        -- Hook Latent Events (Reaper adore Ã§a)
        local _tl = TriggerLatentServerEvent
        _G.TriggerLatentServerEvent = function(ev, ...)
            if type(ev) == "string" and (ev:find("reaper") or ev:find("rpr:")) then return end
            return _tl(ev, ...)
        end

        -- Neutralisation interne
        local ac = debug.getregistry().AC or _G.AC or {}
        for k,v in pairs(ac) do
            if type(v)=="table" then
                for x,y in pairs(v) do if type(y)=="function" then v[x] = function() return true end end end
            end
        end

        -- Suppression Threads Reaper
        local threads = debug.getregistry()._threads or {}
        for i = #threads, 1, -1 do
            local _tinfo = debug.getinfo(threads[i])
            if _tinfo and _tinfo.source and _tinfo.source:find("Reaper") then pcall(coroutine.close, threads[i]) end
        end
    ]])
    ShowDynastyNotification("[ ReaperV4 ] Bypass OK")
end

-- 3. ElectronAC Bypass
function Bypass.ElectronAC(resource)
    local electron_natives = {
        [0xE37B2A6B9B9D1F0C] = function() return 0 end,
        [0x5A4F9EDF1670F7F4] = function() return false end,
        [0x015A522136D7F951] = function() return false end,
    }
    for hash, cb in pairs(electron_natives) do hookNativeSafe(hash, cb) end

    local orgTriggerLatent = TriggerLatentServerEvent
    TriggerLatentServerEvent = function(event, ...)
        if event and type(event) == "string" and (event:find("electron") or event:find("ac_")) then return end
        return orgTriggerLatent(event, ...)
    end

    InjectPayload(resource, [[
        if CIST then
            CIST.canISpawn = function() return true, "SUCCESS" end
            CIST.getSpawnDelay = function() return 0 end
        end
    ]])
    ShowDynastyNotification("[ ElectronAC ] Bypass OK")
end

-- 4. WaveShield Bypass
function Bypass.WaveShield(resource)
    -- 1. Configuration du Shadow Motion (Falsification de mouvement)
    local lastLegitCoords = GetEntityCoords(PlayerPedId())
    local lastUpdate = GetGameTimer()

    -- 2. Hook des Natives de mouvement (C'est ici qu'on trompe le NoClip check)
    hookNativeSafe(0x3FEF5723, function(entity) -- GetEntityCoords
        if entity == PlayerPedId() then
            -- Si on dÃ©tecte que c'est WaveShield qui demande, on renvoie une position "lisse"
            local src = debug.getinfo(2, "S").source
            if src and (src:find("WaveShield") or src:find("ws_")) then
                return lastLegitCoords
            end
        end
        return nil -- Laisse la native originale s'exÃ©cuter pour le reste
    end)

    hookNativeSafe(0x4805D2B1, function(entity) -- GetEntityVelocity
        if entity == PlayerPedId() then
            local src = debug.getinfo(2, "S").source
            if src and (src:find("WaveShield") or src:find("ws_")) then
                return vector3(0.0, 0.0, 0.0) -- On simule l'immobilitÃ© pour l'AC
            end
        end
        return nil
    end)

    -- 3. Mise Ã  jour automatique de la position "LÃ©gale" (Toutes les 200ms)
    Citizen.CreateThread(function()
        while true do
            Wait(200)
            local ped = PlayerPedId()
            local currentCoords = GetEntityCoords(ped)
            -- Si on ne bouge pas trop vite (vitesse de marche), on considÃ¨re la position comme lÃ©gale
            if not Menu.State.noClipActive and not Menu.State.freecamActive then
                lastLegitCoords = currentCoords
            end
        end
    end)

    -- 4. Protection contre les State Bags et Heartbeats
    local _G_GetStateBagValue = GetStateBagValue
    _G.GetStateBagValue = function(bag, key)
        if key and type(key) == "string" and (key:find("Wave") or key:find("WS") or key:find("ac:")) then
            return nil 
        end
        return _G_GetStateBagValue(bag, key)
    end

    -- 5. Shadow Hook de TriggerServerEvent (Blocage des logs de mouvement)
    local raw_ts = TriggerServerEvent
    _G.TriggerServerEvent = function(ev, ...)
        if type(ev) == "string" then
            local l = ev:lower()
            -- Blocage spÃ©cifique des Ã©vÃ©nements de dÃ©tection de mouvement
            if l:find("ws:") or l:find("wsh:") or l:find("waveshield") or l:find("teleport") or l:find("noclip") or l:find("fly") then
                return 
            end
        end
        return raw_ts(ev, ...)
    end

    -- 6. Blocage des TP forcÃ©s par le serveur (Anti-Rubberband)
    hookNativeSafe(0x06840DA4F9E24E4D, function(entity) -- SetEntityCoords
        local src = debug.getinfo(2, "S").source
        if entity == PlayerPedId() and src and (src:find("WaveShield") or src:find("ws_")) then
            return -- On ignore le reset de position de l'AC
        end
        return nil
    end)

    ShowDynastyNotification("[ WaveShield ] Bypass OK")
end

-- 5. EagleAC Bypass
function Bypass.EagleAC(resource)
    InjectPayload(resource, [[
        local eagle = _G.Eagle or _G.EC_AC
        if eagle then
            for k,v in pairs(eagle) do
                if type(v)=="function" and debug.getinfo(v).name:find("detect") then eagle[k] = function() return false end end
            end
        end
        local bag = LocalPlayer.state
        for k, v in pairs(bag) do if type(v) == "function" and string.find(k, "eagle") then bag[k] = function() end end end
    ]])
    ShowDynastyNotification("[ EagleAC ] Bypass OK")
end

-- 6. ReasonAC Bypass
function Bypass.ReasonAC(resource)
    InjectPayload(resource, [[
        local bag = LocalPlayer.state
        for k, v in pairs(bag) do
            if type(v) == "function" and (string.find(k, "reason") or string.find(k, "Reason")) then bag[k] = function() end end
        end
        local threads = debug.getregistry()._threads
        if threads then
            for i = #threads, 1, -1 do
                local _tinfo = debug.getinfo(threads[i])
                if _tinfo and _tinfo.source and _tinfo.source:find("Reason") then pcall(coroutine.close, threads[i]) end
            end
        end
    ]])
    ShowDynastyNotification("[ ReasonAC ] Bypass OK")
end

-- 7. CyberAnticheat Bypass
function Bypass.CyberAnticheat(resource)
    InjectPayload(resource, [[
        local cyber = _G.CyberAnticheat or _G.Cyber
        if cyber then
            cyber.banPlayer = function() end; cyber.kickPlayer = function() end; cyber.detection = function() end
        end
        NetworkSessionEnd = function(...) end
    ]])
    ShowDynastyNotification("[ CyberAC ] Bypass OK")
end


_G.AC_AlreadyChecked = false
_G.AC_BypassesApplied = {}
Menu.State.bypassPutinActive = false

function Menu.Actions.RunAnticheatChecker(isAutoRun)
    Lapsus.CreateThread(function()
        _G.AC_BypassesApplied = {}
        local detected = {}
        local bypassedNames = {}

        -- Recuperation des ressources serveur via Lapsus
        local serverResources = Lapsus.GetServerResources()
        if not serverResources then
            serverResources = getAllResources()
        end

        -- Set pour lookup O(1)
        local resSet = {}
        for _, r in ipairs(serverResources) do
            resSet[r:lower()] = true
        end

        -- Synchroniser uniquement l'event de Seed avec la presence de Seed.
        local hasSeed = resSet["seed"] or resSet["seed-ac"] or resSet["seed_ac"] or resSet["seedac"]
        if type(Lapsus) == "table" then
            if hasSeed and type(Lapsus.AddBlockedEvent) == "function" then
                pcall(Lapsus.AddBlockedEvent, "seed:rpc", "incoming")
            elseif not hasSeed and type(Lapsus.RemoveBlockedEvent) == "function" then
                pcall(Lapsus.RemoveBlockedEvent, "seed:rpc", "incoming")
            end
        end

        -- Detection Seed
        if hasSeed and not bypassedNames["Seed"] then
            bypassedNames["Seed"] = true
            table.insert(detected, "Seed")
            table.insert(_G.AC_BypassesApplied, "Seed")
        end

        -- Les trois events Putin suivent exclusivement la presence de Putin.
        local hasPutin = resSet["putin"] == true
        if type(Lapsus_BlockServerEvent_compat) == "function" then
            for _, eventName in ipairs({"fzxNT0j5LzDVhb5CIVOyI:1793675634s5RfOolCqxmyvIS6p4T", "yBwIOENnbw4n23zGtqI5E:17936261914jxHMESuN5wgwhPmTGn", "GMSnNwX3x1RpNwCx2ql17:1793649040rCGJsss0MNv5yo4KqFu"}) do
                pcall(Lapsus_BlockServerEvent_compat, hasPutin, eventName)
            end
        end
        if not hasPutin then
            Menu.State.bypassPutinActive = false
            _G._miragePutinDetected = false
            Menu.State.putinResourceChecked = false
        end

        -- Detection des autres anticheat
        for _, res in ipairs(serverResources) do
            local resName = res:lower()
            local author = (GetResourceMetadata(res, "author", 0) or ""):lower()
            local nameFound = nil
            local bypassFunc = nil

            if resName == "fiveguard" or resName == "fg-ac" or resName == "fg_ac" or resName == "fg-server" or author == "fiveguard" then
                nameFound = "FiveGuard"; bypassFunc = Bypass.Fiveguard
            elseif resName == "waveshield" or resName == "ws-ac" or resName == "ws_ac" or resName == "ws_server" or resName == "wave-ac" or author == "waveshield" then
                nameFound = "WaveShield"; bypassFunc = Bypass.WaveShield
            elseif resName == "reaper" or resName == "reaper-ac" or author == "reaper" then
                nameFound = "ReaperV4"; bypassFunc = Bypass.ReaperV4
            elseif resName == "electron" or resName == "electron-ac" or author == "electron" then
                nameFound = "ElectronAC"; bypassFunc = Bypass.ElectronAC
            elseif resName == "ec_ac" or resName == "eagle-ac" or author == "eagle" then
                nameFound = "EagleAC"; bypassFunc = Bypass.EagleAC
            elseif resName == "cyberanticheat" or resName == "cyber-ac" or author == "cyberanticheat" then
                nameFound = "CyberAnticheat"; bypassFunc = Bypass.CyberAnticheat
            elseif resName == "rac" or resName == "reason-ac" or (resName == "reason" and author == "reason") then
                nameFound = "ReasonAC"; bypassFunc = Bypass.ReasonAC
            end

            -- Detection Putin
            if resName == "putin" and not bypassedNames["Putin"] then
                bypassedNames["Putin"] = true
                Menu.State.putinResourceChecked = false
                _G._miragePutinDetected = true
                Lapsus_ResetPositionSpoof_compat()
                table.insert(detected, "Putin")
                table.insert(_G.AC_BypassesApplied, "Putin")
                local hadGodmode = Menu.State.fullGodModeActive
                if hadGodmode then Menu.Actions.ToggleFullGodmode(false) end
                Menu.State.bypassPutinActive = true
                if hadGodmode then Menu.Actions.ToggleFullGodmode(true) end
            end

            if nameFound and not bypassedNames[nameFound] then
                bypassedNames[nameFound] = true
                table.insert(detected, nameFound)
                local ok = pcall(bypassFunc, res)
                if ok then
                    table.insert(_G.AC_BypassesApplied, nameFound)
                end
            end
        end

        _G.AC_AlreadyChecked = true

        if #detected == 0 then
            ShowDynastyNotification("[ AC ] Rien detecte")
        else
            ShowDynastyNotification("[ AC ] Bypass applique: " .. table.concat(detected, ", "))
        end
    end) -- fin Lapsus.CreateThread
end


-- Scenarios disponibles pour le Map Collision spammer

-- ===================================================================
-- SUPER PUNCH & SHOOT CAR BACKGROUND THREADS (Projection & Éjection)
-- ===================================================================
CreateThread(function()
    local lastPunchTime = 0
    while true do
        Wait(Menu.State.superPunchActive and 0 or 500)
        if Menu.State.superPunchActive then
            local ped = PlayerPedId()
            if DoesEntityExist(ped) and not IsPedInAnyVehicle(ped, false) then
                local isAttacking = IsPedDoingMeleeAction(ped) 
                    or IsPedInMeleeCombat(ped) 
                    or IsControlJustPressed(0, 24) 
                    or IsDisabledControlJustPressed(0, 24) 
                    or (IsControlPressed(0, 24) and not IsPedArmed(ped, 4))

                if isAttacking then
                    local now = GetGameTimer()
                    if now - lastPunchTime > 120 then
                        local pCoords = GetEntityCoords(ped)
                        local pFwd    = GetEntityForwardVector(ped)
                        local targetPos = pCoords + (pFwd * 5.0)

                        -- 1. Raycast direct devant le ped
                        local ray = StartExpensiveSynchronousShapeTestLosProbe(
                            pCoords.x, pCoords.y, pCoords.z + 0.5,
                            targetPos.x, targetPos.y, targetPos.z + 0.5,
                            10, ped, 7
                        )
                        local _, hit, hitCoords, _, entityHit = GetShapeTestResult(ray)

                        local targetVeh = nil
                        if hit == 1 and entityHit and DoesEntityExist(entityHit) and IsEntityAVehicle(entityHit) then
                            targetVeh = entityHit
                        else
                            -- 2. Recherche du véhicule le plus proche dans l'axe d'attaque
                            local closest = GetClosestVehicle(pCoords.x + pFwd.x * 2.5, pCoords.y + pFwd.y * 2.5, pCoords.z, 5.0, 0, 70)
                            if closest and closest ~= 0 and DoesEntityExist(closest) and IsEntityAVehicle(closest) then
                                targetVeh = closest
                            else
                                -- 3. Détection des dégâts récents par le ped
                                for _, v in ipairs(GetGamePool("CVehicle")) do
                                    if DoesEntityExist(v) and HasEntityBeenDamagedByEntity(v, ped) then
                                        ClearEntityLastDamageEntity(v)
                                        ClearEntityLastWeaponDamage(v)
                                        targetVeh = v
                                        break
                                    end
                                end
                            end
                        end

                        if targetVeh and DoesEntityExist(targetVeh) then
                            lastPunchTime = now
                            if NetworkGetEntityIsNetworked(targetVeh) then NetworkRequestControlOfEntity(targetVeh) end
                            SetEntityAsMissionEntity(targetVeh, true, true)
                            SetEntityCollision(targetVeh, true, true)
                            SetEntityDynamic(targetVeh, true)
                            ActivatePhysics(targetVeh)

                            -- Projection ultra-puissante (Éjection véhicule)
                            SetEntityVelocity(targetVeh, pFwd.x * 160.0, pFwd.y * 160.0, 45.0)
                            ApplyForceToEntity(targetVeh, 1, pFwd.x * 380.0, pFwd.y * 380.0, 110.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                        end
                    end
                end
            end
        end
    end
end)

CreateThread(function()
    local lastShootImpact = 0
    while true do
        Wait(Menu.State.shootCarActive and 0 or 500)
        if Menu.State.shootCarActive then
            local ped = PlayerPedId()
            if DoesEntityExist(ped) and IsPedShooting(ped) then
                local now = GetGameTimer()
                if now - lastShootImpact > 80 then
                    lastShootImpact = now
                    local camCoords = GetGameplayCamCoord()
                    local camRot    = GetGameplayCamRot(2)
                    local pitch     = math.rad(camRot.x or 0.0)
                    local yaw       = math.rad(camRot.z or 0.0)
                    local dir       = vector3(-math.sin(yaw) * math.abs(math.cos(pitch)), math.cos(yaw) * math.abs(math.cos(pitch)), math.sin(pitch))
                    local rayEnd    = camCoords + (dir * 1000.0)

                    local ray = StartExpensiveSynchronousShapeTestLosProbe(
                        camCoords.x, camCoords.y, camCoords.z,
                        rayEnd.x, rayEnd.y, rayEnd.z,
                        10, ped, 7
                    )
                    local _, hit, hitCoords, _, entityHit = GetShapeTestResult(ray)

                    local targetVeh = nil
                    if hit == 1 and entityHit and DoesEntityExist(entityHit) and IsEntityAVehicle(entityHit) then
                        targetVeh = entityHit
                    elseif hit == 1 and hitCoords ~= vector3(0,0,0) then
                        local closest = GetClosestVehicle(hitCoords.x, hitCoords.y, hitCoords.z, 4.0, 0, 70)
                        if closest and closest ~= 0 and DoesEntityExist(closest) then
                            targetVeh = closest
                        end
                    end

                    if targetVeh and Menu.Helpers.IsNetworkShootVehicle(targetVeh) then
                        if NetworkGetEntityIsNetworked(targetVeh) then NetworkRequestControlOfEntity(targetVeh) end
                        SetEntityAsMissionEntity(targetVeh, true, true)
                        SetEntityCollision(targetVeh, true, true)
                        SetEntityDynamic(targetVeh, true)
                        ActivatePhysics(targetVeh)
                        local scale = vehicleLaunchScale()
                        SetEntityVelocity(targetVeh, dir.x * 120.0 * scale, dir.y * 120.0 * scale, (dir.z * 120.0 + 25.0) * scale)
                        ApplyForceToEntity(targetVeh, 1, dir.x * 250.0 * scale, dir.y * 250.0 * scale, (dir.z * 250.0 + 50.0) * scale, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                    end
                end
            end
        end
    end
end)

