-- MIC ESP : micro vert sous les autres joueurs qui parlent.
Menu.State.micEspActive = false
local MicESPConfig = { maxDistance = 150.0, heightOffset = -1.15, scale = 0.38 }
local function DrawMicESP(x, y, z)
    if not HasStreamedTextureDictLoaded("mpleaderboard") then
        RequestStreamedTextureDict("mpleaderboard", true)
        return
    end
    local visible, sx, sy = World3dToScreen2d(x, y, z)
    if not visible then return end
    local aspect = GetAspectRatio(false)
    if aspect <= 0 then aspect = 1.777778 end
    local size = 0.042
    DrawSprite("mpleaderboard", "leaderboard_audio_3", sx, sy, size / aspect, size, 0.0, 0, 255, 60, 255)
end
Citizen.CreateThread(function()
    while true do
        if Menu.State.micEspActive then
            local myPed = PlayerPedId()
            if DoesEntityExist(myPed) then
                local myCoords = GetEntityCoords(myPed)
                local myPlayer = PlayerId()
                for _, player in ipairs(GetActivePlayers()) do
                    if player ~= myPlayer and NetworkIsPlayerActive(player) and NetworkIsPlayerTalking(player) then
                        local ped = GetPlayerPed(player)
                        if ped ~= 0 and DoesEntityExist(ped) then
                            local coords = GetEntityCoords(ped)
                            local dx, dy, dz = myCoords.x - coords.x, myCoords.y - coords.y, myCoords.z - coords.z
                            if dx * dx + dy * dy + dz * dz <= MicESPConfig.maxDistance * MicESPConfig.maxDistance then
                                DrawMicESP(coords.x, coords.y, coords.z + MicESPConfig.heightOffset)
                            end
                        end
                    end
                end
            end
            Wait(0)
        else
            Wait(250)
        end
    end
end)
