do
local catalog, catalogError, busy = {}, nil, false
function Menu.Actions.RefreshCustomPeds()
    catalog, catalogError = {}, nil
    if type(Lapsus)~="table" or type(Lapsus.GetCustomPeds)~="function" then
        catalogError="API GetCustomPeds indisponible"; return
    end
    local ok,peds,err=pcall(Lapsus.GetCustomPeds)
    if not ok or type(peds)~="table" then
        catalogError=tostring(ok and (err or "Catalogue indisponible") or peds)
        ; return
    end
    for _,ped in ipairs(peds) do
        if type(ped)=="table" then catalog[#catalog+1]=ped end
    end
    table.sort(catalog,function(a,b)
        return tostring(a.name or a.id or ''):lower()<tostring(b.name or b.id or ''):lower()
    end)
end
function Menu.Helpers.GetCustomPedsOptions()
    local rows={
        {type="action",name="Actualiser le catalogue",id="custom_peds_refresh"},
        {type="action",name="Revenir au ped normal",id="custom_peds_reset"}
    }
    if catalogError then
        rows[#rows+1]={type="action",name="Catalogue indisponible",message=catalogError}
    elseif #catalog==0 then
        rows[#rows+1]={type="action",name="Aucun custom ped disponible",message="Actualise le catalogue Lapsus"}
    end
    for _,ped in ipairs(catalog) do
        rows[#rows+1]={type="action",name=tostring(ped.name or ped.id or 'Ped'),ped=ped}
    end
    return rows
end
local function refreshAfterRequest()
    Menu.Actions.RefreshCustomPeds()
    Citizen.CreateThread(function()
        for _,delay in ipairs({250,750,2000}) do
            Wait(delay)
            Menu.Actions.RefreshCustomPeds()
        end
    end)
end
local function requestLocalPed(enable,id,label)
    if busy then ShowDynastyNotification('[ PED ] Requete deja en cours'); return false end
    if type(Lapsus)~='table' or type(Lapsus.SetLocalPed)~='function' then
        ShowDynastyNotification('[ PED ] API SetLocalPed indisponible'); return false
    end
    busy=true
    local ok,accepted,err
    if enable then
        ok,accepted,err=pcall(Lapsus.SetLocalPed,true,id)
    else
        -- Ne pas transmettre d'identifiant lors de la restauration.
        ok,accepted,err=pcall(Lapsus.SetLocalPed,false)
    end
    busy=false
    if not ok or not accepted then
        local reason=tostring(ok and (err or 'Requete refusee') or accepted)
        
        ShowDynastyNotification('[ PED ] '..reason)
        return false
    end
    -- true confirme l'acceptation de la requete, pas la fin du chargement.
    ShowDynastyNotification(enable and ('[ PED ] Chargement demande : '..label)
        or '[ PED ] Restauration demandee')
    refreshAfterRequest()
    return true
end
function Menu.Actions.ResetCustomPed()
    return requestLocalPed(false)
end
function Menu.Actions.ApplyCustomPed(ped)
    if type(ped)~='table' then return false end
    if ped.error and ped.error~='' then
        ShowDynastyNotification('[ PED ] '..tostring(ped.error)); return false
    end
    if not ped.ready then
        ShowDynastyNotification('[ PED ] Fichiers non valides : actualise le catalogue'); return false
    end
    local id=ped.id
    if type(id)~='string' or id=='' then id=ped.model end
    if type(id)~='string' or id=='' then
        ShowDynastyNotification('[ PED ] Identifiant absent du catalogue'); return false
    end
    return requestLocalPed(true,id,tostring(ped.name or id))
end
end

