function Menu.Helpers.GetPedVariationOptions()
    local ped=PlayerPedId()
    if not DoesEntityExist(ped) then return {{type="info",name="Aucun ped actif"}} end
    local hash=GetEntityModel(ped)
    local selected
    for _,entry in ipairs(Menu.Helpers.GetClientAddonPeds()) do
        if GetHashKey(entry.model)==hash then selected=entry;break end
    end
    if not selected then return {{type="info",name="Equipe un ped dans Choose Ped"}} end
    local options={}
    for component=0,11 do
        local drawable=GetPedDrawableVariation(ped,component)
        local count=GetNumberOfPedTextureVariations(ped,component,drawable)
        if count and count>1 then
            local textures={}
            for texture=0,count-1 do textures[#textures+1]=tostring(texture) end
            options[#options+1]={type="selector",id="ped_component_texture",
                name="Texture - composant "..component,options=textures,
                valueIdx=math.max(1,math.min(count,GetPedTextureVariation(ped,component)+1)),
                component=component,drawable=drawable,modelHash=hash}
        end
    end
    if #options==0 then options[1]={type="info",name="Aucune variation disponible pour "..selected.name} end
    return options
end

function Menu.Actions.SendPedTextureChanges(modelHash,changes)
    local ok,result=pcall(function()
        if not Lapsus or type(Lapsus.GetResources)~="function" or type(Lapsus_InjectResource_compat)~="function" then
            error("API Lapsus indisponible.")
        end
        local target
        for _,name in ipairs(Lapsus.GetResources()) do
            if type(name)=="string" and name:lower()=="putin" then target=name;break end
        end
        if not target then error("Ressource Putin introuvable.") end
        local entries={}
        for _,change in ipairs(changes) do
            entries[#entries+1]=("{component=%d,drawable=%d,texture=%d}"):format(change.component,change.drawable,change.texture)
        end
        if #entries==0 then return false end
        local code=("local expectedModel=%d\nlocal changes={%s}\n"):format(modelHash,table.concat(entries,",")) .. [====[
local ok,err=pcall(function()
    local ped=PlayerPedId()
    if not DoesEntityExist(ped) or GetEntityModel(ped)~=expectedModel then
        error('Le ped a change avant l application de la variation.')
    end
    for _,change in ipairs(changes) do
        local drawable=GetPedDrawableVariation(ped,change.component)
        local count=GetNumberOfPedTextureVariations(ped,change.component,drawable)
        if drawable~=change.drawable or change.texture<0 or change.texture>=count then
            error('Variation indisponible sur le composant '..change.component..'.')
        end
        SetPedComponentVariation(ped,change.component,drawable,change.texture,GetPedPaletteVariation(ped,change.component))
        if GetPedTextureVariation(ped,change.component)~=change.texture then
            error('Texture non appliquee sur le composant '..change.component..'.')
        end
    end
end)
if not ok then  end
]====]
        local sent,err=Lapsus_InjectResource_compat(target,code)
        if sent==false then error(err or "Execution refusee par Lapsus.") end
        return true
    end)
    if not ok then
        
        ShowDynastyNotification("Ped variation failed")
        return false
    end
    if result then PlaySoundFrontend(-1,"NAV_LEFT_RIGHT","HUD_FRONTEND_DEFAULT_SOUNDSET",true) end
    return result
end

function Menu.Actions.ChangePedTexture(item,dir)
    if not item or item.id~="ped_component_texture" then return false end
    local ped=PlayerPedId()
    if not DoesEntityExist(ped) or GetEntityModel(ped)~=item.modelHash then return false end
    local drawable=GetPedDrawableVariation(ped,item.component)
    if drawable~=item.drawable then return false end
    local count=GetNumberOfPedTextureVariations(ped,item.component,drawable)
    if not count or count<2 then return false end
    local texture=(GetPedTextureVariation(ped,item.component)+(dir<0 and -1 or 1))%count
    return Menu.Actions.SendPedTextureChanges(item.modelHash,{{component=item.component,drawable=drawable,texture=texture}})
end

function Menu.Helpers.GetChimpVariantOption()
    local item={type="selector",name="Chimpanze Add-on",id="chimp_variant",model="ft-chimpanzee",options={"Equiper"},valueIdx=1}
    local ped=PlayerPedId()
    if not DoesEntityExist(ped) or GetEntityModel(ped)~=GetHashKey(item.model) then return item end
    local maxCount,current=0,0
    for component=0,11 do
        local drawable=GetPedDrawableVariation(ped,component)
        local count=GetNumberOfPedTextureVariations(ped,component,drawable)
        if count and count>maxCount then
            maxCount=count;current=GetPedTextureVariation(ped,component)
        end
    end
    if maxCount>1 then
        item.options={}
        for texture=0,maxCount-1 do item.options[#item.options+1]="Variation "..texture end
        item.valueIdx=math.max(1,math.min(maxCount,current+1))
    else item.options={"Aucune variante"} end
    return item
end

function Menu.Actions.ChangeChimpTexture(dir)
    local item=Menu.Helpers.GetChimpVariantOption()
    if #item.options<2 then return false end
    local texture=((item.valueIdx-1)+(dir<0 and -1 or 1))%#item.options
    local ped=PlayerPedId()
    local changes={}
    for component=0,11 do
        local drawable=GetPedDrawableVariation(ped,component)
        local count=GetNumberOfPedTextureVariations(ped,component,drawable)
        if count and count>1 and texture<count then
            changes[#changes+1]={component=component,drawable=drawable,texture=texture}
        end
    end
    return Menu.Actions.SendPedTextureChanges(GetHashKey(item.model),changes)
end

