function Menu.Actions.SetAura(aura)
    if not Lapsus or type(Lapsus.GetResources) ~= "function" or type(Lapsus_InjectResource_compat) ~= "function" then
        
        return
    end
    local target
    for _, name in ipairs(Lapsus.GetResources()) do
        if name:lower() == 'putin' then target = name; break end
    end
    if not target then ; return end
    local payload = [====[
local aura = %q
local ok, err = pcall(function()
    assert(LocalPlayer and LocalPlayer.state, 'LocalPlayer.state absent')
    local state = LocalPlayer.state
    if not _auraSyncStopRegistered then
        RegisterCommand('stopaura', function()
            local saved = _auraSyncPersistent
            if not saved then ; return end
            local stopped, stopErr = pcall(function()
                local currentState = LocalPlayer.state
                if currentState.playerEffect == saved.aura then
                    currentState:set('playerEffect', saved.previous, true)
                    if saved.previous then
                        TriggerEvent('effects:equipEffect', saved.previous)
                    else
                        TriggerEvent('effects:unequipEffect')
                    end
                end
            end)
            if stopped then
                _auraSyncPersistent = nil
                
            else  end
        end, false)
        _auraSyncStopRegistered = true
    end
    if not _auraSyncPersistent then
        _auraSyncPersistent = { previous = state.playerEffect, aura = aura }
    else
        _auraSyncPersistent.aura = aura
    end
    state:set('playerEffect', aura, true)
    TriggerEvent('effects:equipEffect', aura)
    
end)
if not ok then  end
]====]
    Lapsus_InjectResource_compat(target, string.format(payload, aura), 1 or 1)
end

function Menu.Actions.StopAura()
    if not Lapsus or type(Lapsus.GetResources) ~= 'function' or type(Lapsus_InjectResource_compat) ~= 'function' then return end
    for _, name in ipairs(Lapsus.GetResources()) do
        if name:lower() == 'putin' then
            Lapsus_InjectResource_compat(name, "ExecuteCommand('stopaura')", 1 or 1)
            return
        end
    end
end

