    end
    
    return false
end

function Menu.Actions.SetPet(pet)
    local allowed = false
    for _, name in ipairs(_petNames) do if name == pet then allowed = true; break end end
    if not allowed then return end
    local payload = [====[
local pet = %q
local slot = %q
local function copyPets(value)
    local result = {}
    if type(value) == 'table' then
        for k, v in pairs(value) do result[k] = v end
    end
    return result
end
if _petSyncMoving then ; return end
_petSyncMoving = true
Citizen.CreateThread(function()
    local ok, err = pcall(function()
        assert(LocalPlayer and LocalPlayer.state, 'Etat joueur absent')
        assert(PetsConfig and PetsConfig.Pets and PetsConfig.Pets[pet], 'Configuration pet absente: ' .. pet)
        local state = LocalPlayer.state
        local equipped = copyPets(state.playerPets)
        local saved = _petSyncActive
        if saved and equipped[saved.slot] == saved.pet then
            equipped[saved.slot] = saved.previous
        end
        for occupiedSlot, name in pairs(equipped) do
            if name == pet then equipped[occupiedSlot] = nil end
        end
        state:set('playerPets', equipped, true)
        _petSyncActive = nil
        Citizen.Wait(500)
        if not _petSyncClearRegistered then
            RegisterCommand('clearpets', function()
                if _petSyncMoving then return end
                local active = _petSyncActive
                if not active then return end
                local cleared, clearErr = pcall(function()
                    local currentState = LocalPlayer.state
                    local current = copyPets(currentState.playerPets)
                    if current[active.slot] == active.pet then
                        current[active.slot] = active.previous
                        currentState:set('playerPets', current, true)
                    end
                    _petSyncActive = nil
                    
                end)
                if not cleared then  end
            end, false)
            _petSyncClearRegistered = true
        end
        equipped = copyPets(state.playerPets)
        for occupiedSlot, name in pairs(equipped) do
            if name == pet then equipped[occupiedSlot] = nil end
        end
        local previous = equipped[slot]
        equipped[slot] = pet
        state:set('playerPets', equipped, true)
        _petSyncActive = { pet = pet, slot = slot, previous = previous }
        
    end)
    _petSyncMoving = nil
    if not ok then  end
end)
]====]
    local slots = {"head", "right_shoulder", "left_shoulder"}
    InjectPetCode(string.format(payload, pet, slots[Menu.State.petSlotIdx or 1] or "head"))
end

