-- Radio Usebug : consultation des canaux publies par les joueurs proches, sans connexion.
function Menu.Helpers.RequestNearbyRadioJoin(channel)
    local ok,err=pcall(function()exports['pma-voice']:setRadioChannel(channel)end)
    if ok then return true end
    if not tostring(err):find('lazyEventHandler',1,true) then return false,err end
    if not Lapsus or type(Lapsus.GetResources)~='function' or type(Lapsus_InjectResource_compat)~='function' then
        return false,err
    end
    local listed,resources=pcall(Lapsus.GetResources)
    if not listed or type(resources)~='table' then return false,err end
    local target
    for _,name in ipairs(resources)do
        if type(name)=='string' and name:lower()=='ox_lib' then target=name;break end
    end
    if not target then return false,'Export Lapsus indisponible et contexte ox_lib absent' end
    -- Meme API publique depuis un contexte FiveM normal ; aucun appel direct a un evenement serveur.
    local code=('local channel=%.17g\n'):format(channel)..[====[
CreateThread(function()
    local ok,err=pcall(function()
        exports['pma-voice']:setRadioChannel(channel)
    end)
    if not ok then
        
        if type(lib)=='table' and type(lib.notify)=='function' then
            lib.notify({title='Radio',description='Connexion impossible : voir F8',type='error'})
        end
    end
end)
]====]
    local sent,sendErr=pcall(Lapsus_InjectResource_compat,target,code,1 or 1)
    if not sent then return false,sendErr end
    return true
end

function Menu.Actions.JoinNearbyRadio(channelId)
    local channel=tonumber(channelId)
    if not channel or channel<0 or channel~=channel or channel==math.huge then return end
    if Menu.State.radioJoinActive and channel~=0 then return end
    if type(GetResourceState)=='function' and GetResourceState('pma-voice')~='started' then
        ShowDynastyNotification('[ RADIO ] pma-voice indisponible');return
    end
    Menu.State.radioRequestSerial=(Menu.State.radioRequestSerial or 0)+1
    local token=Menu.State.radioRequestSerial
    Menu.State.radioJoinActive=true
    CreateThread(function()
        local ok,err=pcall(function()
            local sent,why=Menu.Helpers.RequestNearbyRadioJoin(channel)
            if not sent then error(why) end
            ShowDynastyNotification(channel==0 and '[ RADIO ] Deconnexion demandee' or '[ RADIO ] Connexion demandee : '..tostring(channel))
            local deadline=GetGameTimer()+2000
            repeat
                if token~=Menu.State.radioRequestSerial then return end
                if LocalPlayer and LocalPlayer.state and tonumber(LocalPlayer.state.radioChannel)==channel then
                    Menu.State.radioCurrentChannel=channel
                    ShowDynastyNotification(channel==0 and '[ RADIO ] Radio quittee' or '[ RADIO ] Canal confirme : '..tostring(channel))
                    return
                end
                Wait(50)
            until GetGameTimer()>=deadline
            ShowDynastyNotification(channel==0 and '[ RADIO ] Deconnexion non confirmee' or '[ RADIO ] Connexion non confirmee : '..tostring(channel))
        end)
        if token==Menu.State.radioRequestSerial then Menu.State.radioJoinActive=false end
        if not ok then
            
            ShowDynastyNotification('[ RADIO ] Echec : voir F8')
        end
    end)
end
function Menu.Actions.LeaveNearbyRadio()
    Menu.Actions.JoinNearbyRadio(0)
end

function Menu.Actions.RefreshNearbyRadios()
    local rows={{type='action',name='Quitter la radio',id='radio_leave'},{type='action',name='Actualiser (50 m)',id='radio_refresh'}}
    local mine=PlayerPedId()
    local unreadable=0
    if mine and DoesEntityExist(mine) then
        local origin=GetEntityCoords(mine)
        local entries={}
        for _,player in ipairs(GetActivePlayers()) do
            if player~=PlayerId() and NetworkIsPlayerActive(player) then
                local ped=GetPlayerPed(player)
                if ped~=0 and DoesEntityExist(ped) then
                    local distance=#(GetEntityCoords(ped)-origin)
                    if distance<=50.0 then
                        local serverId=GetPlayerServerId(player)
                        local ok,value=pcall(function()
                            if type(Player)~='function' then return nil end
                            local remote=Player(serverId)
                            return remote and remote.state and remote.state.radioChannel
                        end)
                        local channel=ok and tonumber(value) or nil
                        if channel and channel>0 then
                            local name=tostring(GetPlayerName(player) or serverId):gsub('~','')
                            entries[#entries+1]={type='action',id='radio_channel_info',channel=channel,
                                name=('%s - Radio %s (%dm)'):format(name,tostring(channel),math.floor(distance)),distance=distance}
                        elseif not ok or value==nil then unreadable=unreadable+1 end
                    end
                end
            end
        end
        table.sort(entries,function(a,b)
            if a.channel==b.channel then return a.distance<b.distance end
            return a.channel<b.channel
        end)
        for _,entry in ipairs(entries)do
            rows[#rows+1]=entry
            
        end
        if #entries==0 then rows[#rows+1]={type='info',name='Aucune radio publiee a proximite'} end
    else rows[#rows+1]={type='info',name='Personnage indisponible'} end
    if unreadable>0 then
        rows[#rows+1]={type='info',name=('%d canal(aux) non publie(s)'):format(unreadable)}
    end
    Menu.State.radioNearbyRows=rows
    Menu.State.radioTestActive=false
    return rows
end
function Menu.Helpers.GetRadioUsebugOptions()
    return Menu.State.radioNearbyRows or {{type='action',name='Quitter la radio',id='radio_leave'},{type='action',name='Actualiser (50 m)',id='radio_refresh'}}
end
function Menu.Actions.OpenRadioUsebug()
    Menu.Actions.RefreshNearbyRadios()
    Menu.State.currentMenu='VIP_RADIO'
    Menu.State.selectedOption,Menu.State.startIndex=1,1
end
