function Menu.Actions.ApplyRedsidePed(modelName)
    if Menu.State.redsideModelLoading then
        ShowDynastyNotification('[ REDSIDE ] Chargement deja en cours')
        return
    end
    Menu.State.redsideModelLoading = true
    CreateThread(function()
        local model
        local ok, message = pcall(function()
            model = GetHashKey(modelName)
            if not IsModelInCdimage(model) or not IsModelValid(model) or not IsModelAPed(model) then
                return 'Modele ped indisponible : ' .. modelName
            end
            RequestModel(model)
            local started = GetGameTimer()
            while not HasModelLoaded(model) do
                if GetGameTimer() - started >= 8000 then
                    return 'Chargement expire : ' .. modelName
                end
                Wait(0)
            end
            SetPlayerModel(PlayerId(), model)
            Wait(0)
            local ped = PlayerPedId()
            if not DoesEntityExist(ped) or GetEntityModel(ped) ~= model then
                return 'Changement non confirme : ' .. modelName
            end
            return 'Ped applique : ' .. modelName
        end)
        if model then pcall(SetModelAsNoLongerNeeded, model) end
        Menu.State.redsideModelLoading = false
        if not ok then
            print('[REDSIDE] ' .. tostring(message))
            message = 'Erreur de changement : detail dans F8'
        end
        ShowDynastyNotification('[ REDSIDE ] ' .. message)
    end)
end


function Menu.Helpers.IsExploitCategory(menu)
    return menu=="EXPLOIT_PUTIN" or menu=="EXPLOIT_SEED" or menu=="EXPLOIT_WAVESHIELD" or menu=="EXPLOIT_ELECTRON" or menu=="EXPLOIT_REDSIDE" or menu=="EXPLOIT_REDSIDE_WILD" or menu=="EXPLOIT_REDSIDE_PETS"
end
function Menu.Helpers.GetExploitCategoryOptions(menu)
    return Menu.Data.Options[menu] or {}
end
function Menu.Helpers.MigrateReorganizedBind(bind)
    if type(bind)~="table" then return end
    if type(bind.label)~="string" then return end
    if bind.label=="Copy Ped" and (bind.menu=="ONLINE" or bind.menu=="TROLL") then bind.label="Copy Outfit" end
    local name=bind.label
    local menu=bind.menu
    if menu=="ONLINE" or menu=="TROLL" then
        for index,item in ipairs(Menu.Data.Options.Troll.Categories[4] or {}) do
            if type(item)=="table" and item.name==name then bind.index=index;return end
        end
    end
    if name=="Anticheat Checker" and menu=="MISC" then menu="EXPLOIT"
    elseif menu=="EXPLOIT" or menu=="VIP" then
        if name=="Aura" or name=="Pets" or name=="Ped" or name=="Give" or name=="Crosse Abuse" then menu="EXPLOIT_PUTIN"
        elseif name=="Crash" or name=="Chat Abuse" then menu="EXPLOIT_SEED"
        elseif name=="Map Collision" or name=="Col Vitesse" or name=="Collision Speed" then menu="MISC" end
    end
    if name=="Col Vitesse" then name="Collision Speed" end
    if menu=="MISC" or menu=="EXPLOIT" or menu=="VIP" or Menu.Helpers.IsExploitCategory(menu) then
        local list=menu=="MISC" and Menu.Helpers.GetMiscOptions() or Menu.Helpers.IsExploitCategory(menu) and Menu.Helpers.GetExploitCategoryOptions(menu) or Menu.Helpers.GetVipOptions()
        for index,item in ipairs(list) do
            local label=type(item)=="table" and item.name or item
            if label==name then bind.menu=menu;bind.index=index;bind.label=name;return end
        end
    end
end

Menu.Helpers.SeedReviveLifecycle = [====[
-- User-tested revive code; NUI hiding removed in favor of the existing SEED presentation logic.
local function runTestedSeedRevive()
    -- Cosmetic notification APIs are optional and must never abort a revive.
    local function optionalNotification(name,...)
        local fn=_ENV[name]
        if type(fn)=='function' then pcall(fn,...) end
    end
    if timebeforerespawn then timebeforerespawn = 0 end
    if DeadTime then DeadTime = 0 end
    if deathTime then deathTime = 0 end
    if RespawnTimer then RespawnTimer = 0 end

    Citizen.CreateThread(function()
        for i = 1, 500 do
            RespawnButtonVisible = true
            isDead = false
            dead = false
            isPlayerDead = false
            Wait(10)
        end
    end)

    local playerPed = PlayerPedId()
    SetEntityHealth(playerPed, 200)
    ClearPedTasksImmediately(playerPed)


    -- Reset des states
    LocalPlayer.state.isDead = false
    LocalPlayer.state.dead = false
    LocalPlayer.state:set('isDead', false, true)

    -- Events de revive
    TriggerServerEvent("ambulance:removeItemsAfterRPDeath", true)
    TriggerEvent("ambulance:revive", 1, GetPlayerServerId(PlayerId()))
    TriggerEvent("esx_ambulancejob:revive")

    -- Forcer les inputs
    Citizen.CreateThread(function()
        for i = 1, 10 do
            SetControlNormal(0, 38, 1.0)
            Wait(100)
        end
    end)

    -- Supprimer toutes les notifications existantes
    optionalNotification('ClearAllHelpMessages')
    optionalNotification('ThefeedFlushQueue')
    optionalNotification('ThefeedPauseQueue',true)

    -- Bloquer les notifications serveur pendant 5 secondes après la revive
    Citizen.CreateThread(function()
        local endTime = GetGameTimer() + 5000
        while GetGameTimer() < endTime do
            optionalNotification('ThefeedFlushQueue')
            optionalNotification('ClearAllHelpMessages')
            optionalNotification('ClearPrints')
            Wait(100)
        end
        optionalNotification('ThefeedPauseQueue',false)
    end)
end

-- Keep the established SEED deathscreen cleanup; use the user-tested revival sequence.
local function resolveSeedRevive(module)
    local function upvalue(fn,wanted)
        if type(fn)~='function' or not debug or type(debug.getupvalue)~='function' then return nil end
        for i=1,80 do
            local name,value=debug.getupvalue(fn,i)
            if not name then break end
            if name==wanted then return value end
        end
    end
    local manager=upvalue(SEED.On,'eventManager')
    local listeners=manager and manager.listeners and manager.listeners.playerDied
    local hideDeathUI
    for _,listener in ipairs(listeners or {}) do
        local timer=upvalue(listener.fn,'startDeathTimer')
        local respawn=upvalue(timer,'manageRespawn')
        local hide=upvalue(respawn,'hideDeathUI')
        if type(hide)=='function' then hideDeathUI=hide;break end
    end
    if not hideDeathUI then error('Nettoyage interne du deathscreen introuvable : aucune modification appliquee') end
    return function()
        -- This resets deathUIActive, focus, HUD and blur together, as SEED expects.
        hideDeathUI()
        runTestedSeedRevive()
        hideDeathUI()
    end
end
]====]

function Menu.Actions.ReviveSeed(target)
    if not Lapsus or type(Lapsus.InjectResource)~='function' or type(Lapsus.GetResources)~='function' then
        ShowDynastyNotification("[ REVIVE SEED ] API Lapsus indisponible")
        return false
    end
    if not target then
        local ok,resources=pcall(Lapsus.GetResources)
        for _,name in ipairs(ok and type(resources)=='table' and resources or {}) do
            if type(name)=='string' and name:lower()=='seed' and GetResourceState(name)=='started' then
                target=name
                break
            end
        end
    end
    if not target or GetResourceState(target)~='started' then
        ShowDynastyNotification("[ REVIVE SEED ] Ressource seed indisponible")
        return false
    end
    if Menu.State.seedRevivePending then
        ShowDynastyNotification("[ REVIVE SEED ] Deja en cours")
        return false
    end
    local ack="mirage:seedRevive:"..tostring(GetGameTimer())..":"..tostring({})
    local handler
    handler=AddEventHandler(ack,function(success,message)
        if handler then RemoveEventHandler(handler);handler=nil end
        Menu.State.seedRevivePending=false
        print("[ REVIVE SEED ] "..tostring(message))
        ShowDynastyNotification(success and "[ REVIVE SEED ] Vivant / ecran de mort ferme" or "[ REVIVE SEED ] Echec : voir F8")
    end)
    local code=("local ack=%q\n"):format(ack) .. Menu.Helpers.SeedReviveLifecycle .. [====[
do
    if type(SEED)~="table" or type(SEED.Thread)~="function" then
        TriggerEvent(ack,false,"API SEED absente dans la ressource cible")
        return
    end
    SEED.Thread(function()
        local token="mirage_revive"
        local suppressed=false
        local success,message=pcall(function()
            if type(Modules)~="table" or type(Modules.Get)~="function" then error("Modules SEED indisponibles") end
            local ambulance=Modules.Get('jobsbuilder')
            if not ambulance or type(ambulance.EventFormatter)~="function" or not ambulance.frame then
                error("Module ambulance ou deathscreen non initialise")
            end
            local frame=ambulance.frame
            local revive=resolveSeedRevive(ambulance)
            if type(SEED.EmitSync)~="function" then error("Evenements locaux SEED indisponibles") end
            SEED.EmitSync('deathscreen:suppress',token,true)
            suppressed=true
            revive()
            local deadline=GetGameTimer()+8000
            while GetGameTimer()<deadline do
                local ped=PlayerPedId()
                local player=CPlayer()
                if DoesEntityExist(ped) and not IsEntityDead(ped) and not player.Dead and not frame.visible then
                    TriggerScreenblurFadeOut(0)
                    StopScreenEffect('DeathFailOut')
                    StopGameplayCamShaking(true)
                    return
                end
                Wait(50)
            end
            error("La fonction SEED n'a pas termine le revive ou ferme le deathscreen")
        end)
        if suppressed then
            pcall(SEED.EmitSync,'deathscreen:suppress',token,false)
        end
        TriggerEvent(ack,success,success and "Etat vivant et deathscreen ferme verifies cote client" or tostring(message))
    end)
end
]====]
    Menu.State.seedRevivePending=true
    local ok,sent,err=pcall(Lapsus.InjectResource,target,code)
    if not ok or sent==false then
        if handler then RemoveEventHandler(handler);handler=nil end
        Menu.State.seedRevivePending=false
        print("[ REVIVE SEED ] Injection refusee : "..tostring(ok and err or sent))
        ShowDynastyNotification("[ REVIVE SEED ] Envoi impossible : voir F8")
        return false
    end
    local timeout=(Citizen and Citizen.SetTimeout) or SetTimeout
    if type(timeout)=="function" then
        timeout(10000,function()
            if not handler then return end
            RemoveEventHandler(handler);handler=nil
            Menu.State.seedRevivePending=false
            ShowDynastyNotification("[ REVIVE SEED ] Aucune confirmation du client SEED")
        end)
    end
    ShowDynastyNotification("[ REVIVE SEED ] Demande envoyee")
    return true
end

