-- ── RESOURCE MANAGER ────────────────────────────────────────────────────────
function Menu.Helpers.FetchResourceList()
    local now = GetGameTimer()
    -- Refresh toutes les 3 secondes max
    if Menu.State.resourceManagerList and (now - Menu.State.resourceManagerLastFetch) < 3000 then
        return Menu.State.resourceManagerList
    end
    Menu.State.resourceManagerLastFetch = now
    local list = {}
    if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" then
        -- Récupère la liste via GetNumResources / GetResourceByFindIndex (client-side natifs disponibles)
        local count = GetNumResources()
        for i = 0, count - 1 do
            local ok, name = pcall(GetResourceByFindIndex, i)
            if ok and type(name) == "string" and name ~= "" then
                -- Sanitize strict : garde uniquement les caracteres ASCII imprimables (0x20-0x7E)
                -- Evite les ? et glyphs corrompus qui apparaissent avec certains noms de ressources
                local clean = name:gsub("[^\32-\126]", "")
                -- Filtre supplementaire : retire les caracteres de controle qui pourraient subsister
                clean = clean:match("^%s*(.-)%s*$") or clean -- trim
                if clean ~= "" and #clean >= 1 then
                    -- Validation : le nom doit contenir au moins une lettre ou chiffre
                    if clean:match("[%w%-_]") then
                        local state = GetResourceState(clean) or "unknown"
                        table.insert(list, { name = clean, state = state })
                    end
                end
            end
        end
    end
    -- Tri : running en premier, puis stopped, alphabétique dans chaque groupe
    table.sort(list, function(a, b)
        local aRun = (a.state == "started") and 0 or 1
        local bRun = (b.state == "started") and 0 or 1
        if aRun ~= bRun then return aRun < bRun end
        return a.name < b.name
    end)
    Menu.State.resourceManagerList = list
    return list
end

function Menu.Helpers.GetResourceManagerOptions()
    local list = Menu.Helpers.FetchResourceList()
    local opts = {
        { type = "resource_action", name = "[X] Stop All Resources",  action = "stop_all"  },
        { type = "resource_action", name = "[>] Start All Resources", action = "start_all" },
        { type = "resource_separator" },
    }
    for _, r in ipairs(list) do
        local isRunning = (r.state == "started")
        table.insert(opts, {
            type = "resource_entry",
            name = r.name,
            state = r.state,
            isRunning = isRunning,
        })
    end
    if #list == 0 then
        table.insert(opts, { type = "info", name = "Aucune ressource trouvee" })
    end
    return opts
end

function Menu.Actions.ToggleResource(resName, currentlyRunning)
    if type(Lapsus) ~= "table" or type(Lapsus_InjectResource_compat) ~= "function" then
        ShowDynastyNotification("[ RESOURCE ] Lapsus indisponible")
        return
    end
    local notifColor = currentlyRunning and "" or ""
    local notifAction = currentlyRunning and "STOP" or "START"
    -- Injection directe : une seule instruction atomique sans variable locale intermediaire
    if currentlyRunning then
        Lapsus_InjectResource_compat("any", string.format("StopResource(%q)", resName))
    else
        Lapsus_InjectResource_compat("any", string.format("StartResource(%q)", resName))
    end
    ShowDynastyNotification(string.format("[ RESOURCE ] %s%s %s", notifColor, notifAction, resName))
    -- Attendre que le serveur applique le changement avant de rafraichir la liste
    Citizen.CreateThread(function()
        Wait(600)
        Menu.State.resourceManagerList = nil
        Menu.State.resourceManagerLastFetch = 0
    end)
    PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
end

function Menu.Actions.StopAllResources()
    if type(Lapsus) ~= "table" or type(Lapsus_InjectResource_compat) ~= "function" then
        ShowDynastyNotification("[ RESOURCE ] Lapsus indisponible"); return
    end
    local list = Menu.Helpers.FetchResourceList()
    local toStop = {}
    local selfName = GetCurrentResourceName()
    for _, r in ipairs(list) do
        if r.state == "started" and r.name ~= selfName then
            toStop[#toStop + 1] = r.name
        end
    end
    local count = #toStop
    ShowDynastyNotification(string.format("[ RESOURCE ] Stop All : %d en cours...", count))
    PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
    -- Injection sequentielle avec delai : evite que le serveur ignore les appels en rafale
    Citizen.CreateThread(function()
        for _, name in ipairs(toStop) do
            Lapsus_InjectResource_compat("any", string.format("StopResource(%q)", name))
            Wait(80)
        end
        Wait(500)
        Menu.State.resourceManagerList = nil
        Menu.State.resourceManagerLastFetch = 0
        ShowDynastyNotification(string.format("[ RESOURCE ] Stop All termine : %d", count))
    end)
end

function Menu.Actions.StartAllResources()
    if type(Lapsus) ~= "table" or type(Lapsus_InjectResource_compat) ~= "function" then
        ShowDynastyNotification("[ RESOURCE ] Lapsus indisponible"); return
    end
    local list = Menu.Helpers.FetchResourceList()
    local count = 0
    for _, r in ipairs(list) do
        if r.state ~= "started" then
            Lapsus_InjectResource_compat("any", string.format([[StartResource(%q)]], r.name))
            count = count + 1
        end
    end
    ShowDynastyNotification(string.format("[ RESOURCE ] Start All : %d", count))
    Menu.State.resourceManagerList = nil; Menu.State.resourceManagerLastFetch = 0
    PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
end

