function Menu.Helpers.GetAllowedBanners()
    local allowed = {}
    local authedCode = (_G.AuthedCode or ""):lower()
    local myPrivate = _G.PrivateBannerMap[authedCode] -- nil si code sans banniÃ¨re privÃ©e

    for _, b in ipairs(Menu.AvailableBanners) do
