            type     = "bind_entry",
            id       = "active_bind_action",
            label    = label,
            name     = label,
            badge    = entry.bind.menu or "?",
            bindKey  = entry.key,
            bindData = entry.bind,
            options  = { "Modifier", "Supprimer" },
            valueIdx = savedIdx,
        })
    end
    if #list == 0 then
        table.insert(list, { type = "info", name = "Aucun bind actif" })
    end
    -- Hint footer
    table.insert(list, { type = "separator", label = "Gauche/Droite = choisir / Entree = confirmer" })
    return list
end

local cachedPlayerList = {}
local lastPlayerListUpdate = 0
local onlineFilterVehicles = false

function Menu.Helpers.GetCachedPlayerList()
    local currentTime = GetGameTimer()
    if currentTime - Menu.Cache.lastPlayerListUpdate < 1500 and #cachedPlayerList > 0 then
        return cachedPlayerList
    end
    Menu.Cache.lastPlayerListUpdate = currentTime

    local success, result = pcall(function()
        local list = {}
        local playerPed = PlayerPedId()
        local pCoords = GetEntityCoords(playerPed)

        for _, pid in ipairs(GetActivePlayers()) do
            local ped = GetPlayerPed(pid)
            if DoesEntityExist(ped) then
                local exists = DoesEntityExist(ped)
                local dist = 99999

                if exists then
                    local targetCoords = GetEntityCoords(ped)
                    dist = #(pCoords - targetCoords)
                end

                local pName = GetPlayerName(pid) or ("Player " .. pid)
                if not onlineFilterVehicles or (exists and IsPedInAnyVehicle(ped, false)) then
                    table.insert(list, {
                        name = pName,
                        id = pid,
                        serverId = GetPlayerServerId(pid),
                        dist = dist
                    })
                end
            end
        end
        -- Proximity Based Sorting (User Request)
        table.sort(list, function(a, b)
            if math.abs((a.dist or 0) - (b.dist or 0)) < 2.0 then -- 2m jitter threshold
                return (a.serverId or 0) < (b.serverId or 0)
            end
            return (a.dist or 0) < (b.dist or 0)
        end)
        table.insert(list, 1, { name = "[X] Unselect All", serverId = -1, dist = -1 })
        return list
    end)

    if success then
        cachedPlayerList = result
        return result
    else
        return cachedPlayerList
    end
end

Menu.State.onlineTypeFilter = Menu.State.onlineTypeFilter or "All"
Menu.State.onlineGlobalOptions = Menu.State.onlineGlobalOptions or {
    { name = "Teleport", type = "selector", options = {"To Player", "To Me", "All To Me"}, valueIdx = 1, id = "global_tp" },
    { name = "Select", type = "selector", options = {"Select All", "Unselect All", "Inverse", "None"}, valueIdx = 1, id = "global_select" },
    { name = "Type", type = "selector", options = {"All", "On Foot", "In Vehicle"}, valueIdx = 1, id = "global_type" },
}

local cachedOnlineList = {}

function Menu.Helpers.GetOnlineMenuList()
    local currentTime = GetGameTimer()
    if currentTime - (Menu.Cache.lastOnlineListUpdate or 0) < 2000 and #cachedOnlineList > 0 then
        return cachedOnlineList
    end

    local list = {}
    if Menu.State.onlineTab == 1 then
        local players = Menu.Helpers.GetCachedPlayerList()
        -- Insert persistent global options
        for i=1, #Menu.State.onlineGlobalOptions do
            table.insert(list, Menu.State.onlineGlobalOptions[i])
        end
        table.insert(list, { name = "--- Player List ---", type = "separator" } or { name = "--- Player List ---", isSeparator = true })

        -- Apply type filter
        local filter = Menu.State.onlineTypeFilter or "All"
        for i=1, #players do
            local p = players[i]
            if p.dist == -1 then -- Special buttons (Unselect All)
                table.insert(list, p)
            else
                if filter == "All" then
                    table.insert(list, p)
                elseif filter == "In Vehicle" then
                    if p.id then
                        local ped = GetPlayerPed(p.id)
                        if DoesEntityExist(ped) and IsPedInAnyVehicle(ped, false) then
                            table.insert(list, p)
                        end
                    end
                elseif filter == "On Foot" then
                    if p.id then
                        local ped = GetPlayerPed(p.id)
                        if DoesEntityExist(ped) and not IsPedInAnyVehicle(ped, false) then
                            table.insert(list, p)
                        end
                    end
                end
            end
        end
    else
        list = Menu.Data.Options.Troll.Categories[Menu.State.onlineTab] or {}
    end

    cachedOnlineList = list
    Menu.Cache.lastOnlineListUpdate = currentTime
    return list
end

