function Menu.Actions.GiveAllModdedWeapons()
    -- Cooldown 1500ms et guard busy pour eviter double injection
    local now = GetGameTimer()
    if _giveWeaponsBusy then
        ShowDynastyNotification("[ MIRAGE ] Deja actif")
        return
    end
    if (now - _lastGiveWeaponsTime) < 1500 then
        ShowDynastyNotification("[ MIRAGE ] Patientez")
        return
    end
    _giveWeaponsBusy = true
    _lastGiveWeaponsTime = now

    local moddedWeapons = {
        "weapon_aa", "weapon_caveira", "weapon_SCOM",
        "weapon_mcx", "weapon_midasgun", "weapon_hackingdevice",
        "weapon_akorus", "weapon_midgard", "weapon_chainsaw"
    }

    if not Menu.State.Mirage_Injected then
        ShowDynastyNotification("[ MIRAGE ] Initialisation...")

        local hashesStr = ""
        for i, name in ipairs(moddedWeapons) do
            hashesStr = hashesStr .. string.format("[GetHashKey('%s')] = true,", name)
        end

        local ok, err = pcall(function()
            Lapsus_InjectResource_compat("_core", [[
                local _SetCurrentPedWeapon = SetCurrentPedWeapon
                local _GiveWeaponToPed = GiveWeaponToPed
                local _SetPedAmmo = SetPedAmmo
                local _RemoveAllPedWeapons = RemoveAllPedWeapons

                local allowedHashes = { ]] .. hashesStr .. [[ }
                allowedHashes[GetHashKey("WEAPON_UNARMED")] = true

                GetCurrentPedWeapon = function(ped, ...)
                    return true, GetHashKey("WEAPON_UNARMED")
                end

                RemoveAllPedWeapons = function(ped, ...)
                    return
                end

                RemoveWeaponFromPed = function(ped, weapon) return end

                SetCurrentPedWeapon = function(ped, weapon, ...)
                    if allowedHashes[weapon] then
                        return _SetCurrentPedWeapon(ped, weapon, ...)
                    end
                    return
                end

                local selfPed = PlayerPedId()
                for hash, _ in pairs(allowedHashes) do
                    if hash ~= GetHashKey("WEAPON_UNARMED") then
                        _GiveWeaponToPed(selfPed, hash, 999, false, true)
                        _SetPedAmmo(selfPed, hash, 999)
                    end
                end
                _SetCurrentPedWeapon(selfPed, GetHashKey("weapon_aa"), true)
            ]])
        end)

        if ok then
            Menu.State.Mirage_Injected = true
            ShowDynastyNotification("[ MIRAGE ] Actif")
        else
            ShowDynastyNotification("[ MIRAGE ] Echec injection")
        end
    else
        ShowDynastyNotification("[ MIRAGE ] Redistribution...")
        local ped = PlayerPedId()
        -- On donne les armes une par une avec un petit Wait pour eviter le freeze
        CreateThread(function()
            for _, name in ipairs(moddedWeapons) do
                local hash = GetHashKey(name)
                pcall(GiveWeaponToPed, ped, hash, 999, false, true)
                pcall(SetPedAmmo, ped, hash, 999)
                Wait(30)
            end
            pcall(SetCurrentPedWeapon, ped, GetHashKey("weapon_aa"), true)
            ShowDynastyNotification("[ MIRAGE ] Armes redistribuees")
            _giveWeaponsBusy = false
        end)
        return -- sortir avant le _giveWeaponsBusy = false du bas
    end
    _giveWeaponsBusy = false
end
