_G.GiveInputState = {
    active      = false,  -- true = écran de saisie affiché
    inputBuffer = "",     -- ce que l'utilisateur tape
    errorMsg    = "",     -- message d'erreur
    errorTimer  = 0,      -- timestamp fin affichage erreur
