-- État de saisie pour le Ped personnalisé (VIP_PED)
_G.PedInputState = {
    active      = false,
    inputBuffer = "",
    errorMsg    = "",
    errorTimer  = 0,
}

-- Table VK -> char pour le give (lettres + chiffres + underscore)
local _giveVKtoChar = {
    [0x41]="a",[0x42]="b",[0x43]="c",[0x44]="d",[0x45]="e",
    [0x46]="f",[0x47]="g",[0x48]="h",[0x49]="i",[0x4A]="j",
    [0x4B]="k",[0x4C]="l",[0x4D]="m",[0x4E]="n",[0x4F]="o",
    [0x50]="p",[0x51]="q",[0x52]="r",[0x53]="s",[0x54]="t",
    [0x55]="u",[0x56]="v",[0x57]="w",[0x58]="x",[0x59]="y",
    [0x5A]="z",
    [0x30]="0",[0x31]="1",[0x32]="2",[0x33]="3",[0x34]="4",
    [0x35]="5",[0x36]="6",[0x37]="7",[0x38]="8",[0x39]="9",
    [0x60]="0",[0x61]="1",[0x62]="2",[0x63]="3",[0x64]="4",
    [0x65]="5",[0x66]="6",[0x67]="7",[0x68]="8",[0x69]="9",
    [0xBD]="_",
}
local _giveVKPrev = {}

-- ── THREAD BOUCLE CLAVIER GIVE INPUT ─────────────────────────────────
CreateThread(function()
    local _bsPrev    = false
    local _enterPrev = false
    local _escPrev   = false
    local _ctrlVPrev = false
    while true do
        Wait(0)
        if not (_G.GiveInputState and _G.GiveInputState.active) then
            _bsPrev    = false
            _enterPrev = false
            _escPrev   = false
            _ctrlVPrev = false
            Wait(50)
        else
            if not Lapsus or not Lapsus_GetAsyncKeyState_compat then Wait(50) end

            HideHelpTextThisFrame()
            DisableAllControlActions(0)
            DisableAllControlActions(1)
            DisableAllControlActions(2)
            SetNuiFocus(true, true)
            SetNuiFocusKeepInput(true)

            local now = GetGameTimer()

            -- Backspace : effacer dernier caractère
            local bsDown = Lapsus_GetAsyncKeyState_compat(0x08)
            if bsDown and not _bsPrev then
                local buf = _G.GiveInputState.inputBuffer
                if #buf > 0 then
                    _G.GiveInputState.inputBuffer = buf:sub(1, #buf - 1)
                end
                PlaySoundFrontend(-1, "NAV_UP_DOWN", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            end
            _bsPrev = bsDown

            -- ECHAP : annuler
            local escDown = Lapsus_GetAsyncKeyState_compat(0x1B)
            if escDown and not _escPrev then
                _G.GiveInputState.active      = false
                _G.GiveInputState.inputBuffer = ""
                SetNuiFocus(false, false)
                SetNuiFocusKeepInput(false)
                PlaySoundFrontend(-1, "BACK", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            end
            _escPrev = escDown

            -- CTRL+V : coller depuis le presse-papier
            local ctrlDown = Lapsus_GetAsyncKeyState_compat(0x11) or Lapsus_GetAsyncKeyState_compat(0xA2) or Lapsus_GetAsyncKeyState_compat(0xA3)
            local vDown    = Lapsus_GetAsyncKeyState_compat(0x56)
            local ctrlV    = ctrlDown and vDown
            if ctrlV and not _ctrlVPrev then
                local pasted = nil
                local ok1, clip1 = pcall(function()
                    if Lapsus.GetClipboard then return Lapsus.GetClipboard()
                    elseif Lapsus.GetClipboardText then return Lapsus.GetClipboardText() end
                end)
                if ok1 and clip1 and type(clip1) == "string" and #clip1 > 0 then
                    pasted = clip1
                end
                if not pasted or #pasted == 0 then
                    local ok2, clip2 = pcall(GetClipboardText)
                    if ok2 and clip2 and type(clip2) == "string" and #clip2 > 0 then
                        pasted = clip2
                    end
                end
                if pasted and #pasted > 0 then
                    -- Nettoyer : lettres, chiffres et underscore uniquement (suffixe d'arme)
                    local clean = pasted:gsub("[^%w_]", ""):lower()
                    local remaining = 40 - #_G.GiveInputState.inputBuffer
                    if remaining > 0 then
                        _G.GiveInputState.inputBuffer = _G.GiveInputState.inputBuffer .. clean:sub(1, remaining)
                    end
                    PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                else
                    _G.GiveInputState.errorMsg   = "Presse-papier vide ou inaccessible."
                    _G.GiveInputState.errorTimer = now + 2500
                    PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                end
            end
            _ctrlVPrev = ctrlV

            -- Lettres / chiffres / underscore
            for vk, ch in pairs(_giveVKtoChar) do
                local down = Lapsus_GetAsyncKeyState_compat(vk)
                if down and not _giveVKPrev[vk] then
                    if #_G.GiveInputState.inputBuffer < 40 then
                        _G.GiveInputState.inputBuffer = _G.GiveInputState.inputBuffer .. ch
                        PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                    end
                end
                _giveVKPrev[vk] = down
            end

            -- ENTREE : valider et donner l'arme
            local enterDown = Lapsus_GetAsyncKeyState_compat(0x0D)
            if enterDown and not _enterPrev then
                local input = _G.GiveInputState.inputBuffer
                if input == "" then
                    _G.GiveInputState.errorMsg   = "Nom vide ! Tapez le suffixe de l'arme."
                    _G.GiveInputState.errorTimer = now + 2500
                    PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                else
                    local weaponFull = "weapon_" .. input:upper()
                    local mode = _G.GiveInputState.mode or "give"
                    _G.GiveInputState.active      = false
                    _G.GiveInputState.inputBuffer = ""
                    _G._vkEnterState              = true
                    _G._lastSelectionTime         = GetGameTimer() + 350
                    SetNuiFocus(false, false)
                    SetNuiFocusKeepInput(false)
                    if mode == "vipgive" then
                        Menu.Actions.GiveVipWeaponPerm(weaponFull, input)
                    else
                        Menu.Actions.GiveDynaWeapon(weaponFull)
                    end
                    while Lapsus and Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x0D) do Wait(0) end
                    PlaySoundFrontend(-1, "LEADERBOARD_EXIT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                end
            end
            _enterPrev = enterDown
        end
    end
end)

