function Menu.Actions.GiveDynaWeapon(weaponName)
    if _giveDynaBusy then
        ShowDynastyNotification("[ DYNA ] Patientez")
        return
    end
    _giveDynaBusy = true
    local ped = PlayerPedId()
    local hash = GetHashKey(weaponName)
    CreateThread(function()
        pcall(GiveWeaponToPed, ped, hash, 999, false, true)
        pcall(SetPedAmmo, ped, hash, 999)
        ShowDynastyNotification("[ DYNA ] " .. weaponName .. " donne!")
        Wait(300)
        _giveDynaBusy = false
    end)
end

function Menu.Actions.GiveVipWeaponPerm(weaponName, displayName)
    if _giveDynaBusy then
        ShowDynastyNotification("[ VIP ] Patientez")
        return
    end
    _giveDynaBusy = true

    local hash = nil
    if type(weaponName) == "number" then
        hash = weaponName
    elseif type(weaponName) == "string" then
        local ok, res = pcall(GetHashKey, weaponName)
        if ok then hash = res end
    end

    if not hash or hash == 0 then
        ShowDynastyNotification("[ VIP GIVE ] Hash invalide : " .. tostring(weaponName))
        _giveDynaBusy = false
        return
    end

    -- Anti-Crash FiveM : verifier si le hash d'arme existe sur ce serveur avant de donner
    if IsWeaponValid and not IsWeaponValid(hash) then
        ShowDynastyNotification("[ VIP GIVE ] Arme non disponible sur ce serveur")
        _giveDynaBusy = false
        return
    end

    local nameToDisplay = displayName or tostring(weaponName)

    CreateThread(function()
        local ped = PlayerPedId()
        if DoesEntityExist(ped) and not IsEntityDead(ped) then
            pcall(GiveWeaponToPed, ped, hash, 9999, false, true)
            pcall(SetPedAmmo, ped, hash, 9999)
            pcall(SetCurrentPedWeapon, ped, hash, true)
        end
        ShowDynastyNotification("[ VIP GIVE ] " .. nameToDisplay .. " donne !")
        Wait(300)
        _giveDynaBusy = false
    end)
end

function Menu.Actions.HijackTargetVehicle()
    if not selectedPlayer then
        ShowDynastyNotification("[ ERREUR ] Aucun joueur")
        return
    end

    local targetServerId = selectedPlayer.serverId

    if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" then
        Lapsus_InjectResource_compat("Putin", string.format([[
            local targetServerId = %d
            local targetPlayerId = nil
            for _, player in ipairs(GetActivePlayers()) do
                if GetPlayerServerId(player) == targetServerId then
                    targetPlayerId = player
                    break
                end
            end

            if targetPlayerId then
                local targetPed = GetPlayerPed(targetPlayerId)
                if DoesEntityExist(targetPed) and IsPedInAnyVehicle(targetPed, false) then
                    local veh = GetVehiclePedIsIn(targetPed, false)
                    local myPed = PlayerPedId()

                    -- Request control
                    NetworkRequestControlOfEntity(veh)

                    -- Spawn local ped to kick driver
                    local hash = GetHashKey("s_m_y_swat_01")
                    RequestModel(hash)
                    local timeout = 0
                    while not HasModelLoaded(hash) and timeout < 100 do Wait(10) timeout = timeout + 1 end

                    local coords = GetEntityCoords(veh)
                    local ped = nil

                    local lapsus = rawget(_G, "Lapsus")
                    if lapsus and Lapsus_CreateSpoofedPed_compat then
                         ped = Lapsus_CreateSpoofedPed_compat(26, hash, coords.x, coords.y, coords.z, 0.0, false, false)
                    else
                         ped = CreatePed(26, hash, coords.x, coords.y, coords.z, 0.0, false, false)
                    end

                    if DoesEntityExist(ped) then
                        SetEntityVisible(ped, false, 0)
                        SetEntityInvincible(ped, true)
                        SetEntityCollision(ped, false, false)
                        SetPedConfigFlag(ped, 2, true) -- Can be shot in vehicle (just in case)

                        -- Force local ped into driver seat with aggressive loop
                        local timer = 0
                        while timer < 2000 do
                            -- Try to clear current driver
                            local driver = GetPedInVehicleSeat(veh, -1)
                            if driver ~= 0 and driver ~= ped then
                                ClearPedTasksImmediately(driver)
                            end

                            -- Force local ped in
                            SetPedIntoVehicle(ped, veh, -1)

                            -- Check success
                            if GetPedInVehicleSeat(veh, -1) == ped then
                                -- Wait a tiny bit to ensuring sync
                                Wait(50)
                                break
                            end

                            Wait(10)
                            timer = timer + 10
                        end

                        -- Delete our local ped
                        DeleteEntity(ped)
                    end

                    -- Warp ourselves into the now-vacated (or conflicting) seat
                    SetPedIntoVehicle(myPed, veh, -1)
                    SetModelAsNoLongerNeeded(hash)
                else
                    -- Notification handled by menu system or silent failure
                end
            end
        ]], targetServerId))
        ShowDynastyNotification("[ HIJACK ] En cours...")
    else
        ShowDynastyNotification("[ ERREUR ] Lapsus indisponible")
    end
end

