-- Anti-spam guards pour 360 et Flip
function Menu.Actions.Vehicle360()
    local ped = PlayerPedId()
    if not IsPedInAnyVehicle(ped, false) then
        ShowDynastyNotification("[ TRICK ] Hors vehicule")
        return
    end
    local veh = GetVehiclePedIsIn(ped, false)
    local vel = GetEntityVelocity(veh)
    SetEntityVelocity(veh, vel.x, vel.y, vel.z + 5.0)
    CreateThread(function()
        Wait(200)
        if not DoesEntityExist(veh) then return end
        local startRot = GetEntityRotation(veh, 2)
        local steps = 36
        for i = 1, steps do
            if not DoesEntityExist(veh) then break end
            local newYaw = (startRot.z + (i * (360.0 / steps))) % 360.0
            SetEntityRotation(veh, startRot.x, startRot.y, newYaw, 2, true)
            Wait(15)
        end
    end)
end

