-- Helper : retourne le handle veh correspondant a vehicleSelectedVehicle, ou nil
-- (netId prioritaire, handle local sinon ; verifie que c'est bien un vehicule)
function Menu.Helpers.GetSelectedVehicleHandle()
    local sel = Menu.State.vehicleSelectedVehicle
    if not sel or type(sel) ~= "number" or sel <= 0 then return nil end
    local function isVeh(e)
        return e and e ~= 0 and DoesEntityExist(e) and IsEntityAVehicle(e)
    end
    local okId, exists = pcall(NetworkDoesNetworkIdExist, sel)
    if okId and exists then
        local ok, e = pcall(NetworkGetEntityFromNetworkId, sel)
        if ok and isVeh(e) then return e end
    end
    if isVeh(sel) then return sel end
    return nil
end

-- Vehicule vise par la camera de jeu (raycast), ou nil
function Menu.Helpers.GetAimedVehicle(maxDist)
    local playerPed = PlayerPedId()
    local camPos = GetGameplayCamCoord()
    local camRot = GetGameplayCamRot(2)
    local pitch  = math.rad(camRot.x)
    local yaw    = math.rad(camRot.z)
    local dist   = maxDist or 400.0
    local dirX   = -math.sin(yaw) * math.cos(pitch)
    local dirY   =  math.cos(yaw) * math.cos(pitch)
    local dirZ   =  math.sin(pitch)
    local ray = StartExpensiveSynchronousShapeTestLosProbe(
        camPos.x, camPos.y, camPos.z,
        camPos.x + dirX * dist, camPos.y + dirY * dist, camPos.z + dirZ * dist,
        -1, playerPed, 7
    )
    local _, hit, hitCoords, _, entityHit = GetShapeTestResult(ray)
    local myVeh = GetVehiclePedIsIn(playerPed, false)
    local found = nil
    if hit == 1 or hit == true then
        if entityHit and entityHit ~= 0 and DoesEntityExist(entityHit) then
            local t = GetEntityType(entityHit)
            if t == 2 then
                found = entityHit
            elseif t == 1 then
                local v = GetVehiclePedIsIn(entityHit, false)
                if v and v ~= 0 and DoesEntityExist(v) then found = v end
            end
        end
        if not found and hitCoords then
            local near = GetClosestVehicle(hitCoords.x, hitCoords.y, hitCoords.z, 6.0, 0, 70)
            if near and near ~= 0 and DoesEntityExist(near) then found = near end
        end
    end
    if found and found == myVeh then return nil end
    return found
end

-- Cible des options Troll : vehicule selectionne dans List, sinon vise, sinon actuel, sinon plus proche
function Menu.Helpers.ResolveTrollVehicle(tag)
    local veh = Menu.Helpers.GetSelectedVehicleHandle()
    if veh and DoesEntityExist(veh) then return veh end
    veh = Menu.Helpers.GetAimedVehicle()
    if veh and DoesEntityExist(veh) then
        ShowDynastyNotification("[ " .. (tag or "VEHICLE") .. " ] Vehicule vise")
        return veh
    end
    local playerPed = PlayerPedId()
    if IsPedInAnyVehicle(playerPed, false) then
        local myVeh = GetVehiclePedIsIn(playerPed, false)
        if myVeh and myVeh ~= 0 and DoesEntityExist(myVeh) then
            return myVeh
        end
    end
    local myCoords = GetEntityCoords(playerPed)
    local nearVeh = GetClosestVehicle(myCoords.x, myCoords.y, myCoords.z, 50.0, 0, 70)
    if nearVeh and nearVeh ~= 0 and DoesEntityExist(nearVeh) then
        return nearVeh
    end
    ShowDynastyNotification("[ " .. (tag or "VEHICLE") .. " ] Aucun vehicule (selectionne-en un dans List ou vise-le)")
    return nil
end

-- Attend le controle reseau d'une entite
function Menu.Helpers.EnsureVehicleControl(veh, timeoutMs)
    if not veh or not DoesEntityExist(veh) then return false end
    local t0 = GetGameTimer()
    while not NetworkHasControlOfEntity(veh) do
        NetworkRequestControlOfEntity(veh)
        Wait(10)
        if not DoesEntityExist(veh) then return false end
        if GetGameTimer() - t0 > (timeoutMs or 1000) then return false end
    end
    return true
end

-- Helper interne : warp invisible dans le veh pour forcer le controle reseau, execute fn(), puis sort
-- Pipeline NPC hijack pour obtenir le controle reseau d'un vehicule
-- Utilise un NPC invisible pour prendre le siege conducteur si le vehicule est occupe,
-- ce qui force le transfert de controle reseau cote serveur (identique a NPCHijackDriver).
-- fn(veh) est execute une fois le controle acquis.
-- Pipeline universel pour executer fn(veh) avec le controle reseau garanti.
-- Copie exacte du pipeline physgun :
--   1. NetworkHasControlOfEntity → action directe, pas de warp.
--   2. Sinon : joueur warp invisible dans le veh, boucle takeover (ejecter driver, prendre volant),
--      puis sortir + spawner NPC conducteur pour remplacer le joueur, puis action.
local function WithNPCNetworkControl(veh, fn)
    if not veh or not DoesEntityExist(veh) then return end
    local playerPed = PlayerPedId()

    -- Controle deja acquis : executer l'action sans reprendre le siege.
    if NetworkHasControlOfEntity(veh) then
        SetEntityAsMissionEntity(veh, true, true)
        pcall(fn, veh)
        return
    end

    local ok = Menu.Helpers.HijackVehicleWithOptions(veh, { npcTask = "none" })
    if not ok then
        ShowDynastyNotification("[ CTRL ] Controle refuse")
        return
    end

    NetworkRequestControlOfEntity(veh)
    SetEntityAsMissionEntity(veh, true, true)

    local watch = seedBlocksInvisibility()
    if watch then
        _G._bypassWarpWatchRunning = true
        CreateThread(function()
            while _G._bypassWarpWatchRunning do
                local ped = PlayerPedId()
                if not IsEntityVisible(ped) then SetEntityVisible(ped, true, false) end
                if GetEntityAlpha(ped) < 255 then ResetEntityAlpha(ped) end
                Wait(0)
            end
            SetEntityVisible(PlayerPedId(), true, false)
            ResetEntityAlpha(PlayerPedId())
        end)
    end

    local _ok = pcall(fn, veh)
    _G._bypassWarpWatchRunning = false
    SetEntityVisible(playerPed, true, false)
    ResetEntityAlpha(playerPed)
    if not _ok then ShowDynastyNotification("[ CTRL ] Erreur interne") end
end

-- =============================================================================
--  PIPELINE UNIQUE DE HIJACK VEHICULE (base : NPC Hijack freecam)
--  Utilise par : NPC Hijack (freecam), NPC Drive, Delete Vehicle, Bug Vehicle,
--  Broke Wheel, Physgun, TP Passenger, Warp Vehicle (via WithNPCNetworkControl).
--  A appeler DANS un CreateThread (utilise Wait).
--  opts.npcTask : "wander" (V1) | "v2" (boost chaotique) | "none" (NPC immobile)
--  opts.freezeAfter : fige le ped local a la fin (comportement freecam)
--  Retourne : success (bool), npc (entity ou nil)
-- =============================================================================
function Menu.Helpers.NPCHijackV2Loop(veh, pnj)
    CreateThread(function()
        local startTime = GetGameTimer()
        while (GetGameTimer() - startTime) < 90000 do
            if not DoesEntityExist(veh) or not DoesEntityExist(pnj) then break end
            if not IsPedInVehicle(pnj, veh, false) then break end
            NetworkRequestControlOfEntity(veh)

            local boostType = math.random(1, 4)
            local speed = math.random(60, 100) + 0.0
            local fwd = GetEntityForwardVector(veh)

            if boostType == 1 then
                SetEntityVelocity(veh, fwd.x * speed, fwd.y * speed, math.random(3, 12) + 0.0)
                ApplyForceToEntity(veh, 1, fwd.x * 500.0, fwd.y * 500.0, 150.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
            elseif boostType == 2 then
                local sign = (math.random(0, 1) == 0) and -1.0 or 1.0
                local sideX, sideY = -fwd.y * sign, fwd.x * sign
                SetEntityVelocity(veh, (fwd.x * 0.3 + sideX * 0.9) * speed, (fwd.y * 0.3 + sideY * 0.9) * speed, math.random(4, 16) + 0.0)
                SetEntityAngularVelocity(veh, 0.0, 0.0, sign * math.random(6, 16))
                ApplyForceToEntity(veh, 1, sideX * 600.0, sideY * 600.0, 180.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
            elseif boostType == 3 then
                SetEntityVelocity(veh, fwd.x * (speed * 0.6), fwd.y * (speed * 0.6), math.random(25, 50) + 0.0)
                ApplyForceToEntity(veh, 1, fwd.x * 250.0, fwd.y * 250.0, 700.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
            else
                local angle = math.random() * math.pi * 2.0
                local dirX, dirY = math.cos(angle), math.sin(angle)
                SetEntityVelocity(veh, dirX * speed, dirY * speed, math.random(5, 22) + 0.0)
                SetEntityAngularVelocity(veh, (math.random() - 0.5) * 12.0, (math.random() - 0.5) * 12.0, (math.random() - 0.5) * 25.0)
                ApplyForceToEntity(veh, 1, dirX * 600.0, dirY * 600.0, 250.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
            end

            if math.random(1, 4) == 1 then StartVehicleHorn(veh, 300, "HELDDOWN", false) end
            TaskVehicleDriveWander(pnj, veh, 150.0, 1074528293)
            Wait(math.random(200, 380))
        end
    end)
end

function Menu.Helpers._HijackVehicleImpl(veh, opts)
    opts = opts or {}
    if not veh or veh == 0 or not DoesEntityExist(veh) then return false, nil end

    -- Toujours marquer comme mission entity d'emblee pour empecher GTA de le supprimer
    SetEntityAsMissionEntity(veh, true, true)

    local playerPed      = PlayerPedId()
    local initialCoords  = GetEntityCoords(playerPed)
    local initialHeading = GetEntityHeading(playerPed)
    local vPos           = GetEntityCoords(veh)
    local npcTask        = opts.npcTask or "wander"

    -- Si le joueur est dans son propre vehicule : on y retourne a la fin
    local prevVeh, prevSeat = nil, -2
    if IsPedInAnyVehicle(playerPed, false) then
        local pv = GetVehiclePedIsIn(playerPed, false)
        if pv and pv ~= 0 and pv ~= veh then
            prevVeh = pv
            for s = -1, GetVehicleMaxNumberOfPassengers(pv) - 1 do
                if GetPedInVehicleSeat(pv, s) == playerPed then prevSeat = s; break end
            end
        end
    end

    local function RequestControl(entity, timeoutMs)
        if not entity or not DoesEntityExist(entity) then return false end
        local start = GetGameTimer()
        NetworkRequestControlOfEntity(entity)
        while not NetworkHasControlOfEntity(entity) do
            Wait(10)
            if not DoesEntityExist(entity) then return false end
            if GetGameTimer() - start > (timeoutMs or 500) then return false end
            NetworkRequestControlOfEntity(entity)
        end
        return true
    end

    local warped = false

    local function restorePlayer()
        SetEntityCoordsNoOffset(playerPed, initialCoords.x, initialCoords.y, initialCoords.z, false, false, false, false)
        SetEntityHeading(playerPed, initialHeading)
        SetEntityVisible(playerPed, true, false)
        ResetEntityAlpha(playerPed)
        if warped then
            warped = false
            pcall(ClearFocus)
            pcall(NewLoadSceneStop)
        end
        if prevVeh and prevSeat ~= -2 and DoesEntityExist(prevVeh) and IsVehicleSeatFree(prevVeh, prevSeat) then
            SetPedIntoVehicle(playerPed, prevVeh, prevSeat)
        end
    end

    -- Garder le joueur visible pendant tout le pipeline si bypass seed actif
    if seedBlocksInvisibility() then
        _G._hijackVisWatch = true
        CreateThread(function()
            while _G._hijackVisWatch do
                local ped = PlayerPedId()
                if not IsEntityVisible(ped) then SetEntityVisible(ped, true, false) end
                if GetEntityAlpha(ped) < 255 then ResetEntityAlpha(ped) end
                Wait(0)
            end
        end)
    end

    -- Si le joueur n'est pas deja dans le vehicule cible : warp a proximite immediate
    if GetVehiclePedIsIn(playerPed, false) ~= veh then
        warped = true
        RequestCollisionAtCoord(vPos.x, vPos.y, vPos.z)
        SetEntityCoordsNoOffset(playerPed, vPos.x, vPos.y, vPos.z + 0.5, false, false, false)
        Wait(60)
        if not DoesEntityExist(veh) then
            _G._hijackVisWatch = false
            restorePlayer()
            return false, nil
        end
    end

    SetEntityVisible(playerPed, true, false)
    ResetEntityAlpha(playerPed)
    SetEntityAsMissionEntity(veh, true, true)
    RequestControl(veh, 600)
    SetVehicleDoorsLocked(veh, 1)
    SetVehicleDoorsLockedForAllPlayers(veh, false)
    ClearPedTasksImmediately(playerPed)

    -- Ejecter un eventuel PNJ deja au volant (pas un joueur)
    local existingDriver = GetPedInVehicleSeat(veh, -1)
    if existingDriver ~= 0 and existingDriver ~= playerPed and DoesEntityExist(existingDriver) and not IsPedAPlayer(existingDriver) then
        RequestControl(existingDriver, 300)
        ClearPedTasksImmediately(existingDriver)
        SetEntityAsMissionEntity(existingDriver, true, true)
        SetEntityCoords(existingDriver, 0.0, 0.0, -100.0, false, false, false, false)
        DeleteEntity(existingDriver)
        Wait(20)
    end

    -- Le siege conducteur peut rester occupe apres la premiere requete reseau.
    -- Tenter une sortie, puis attendre la confirmation du siege libre.
    if existingDriver ~= 0 and existingDriver ~= playerPed and DoesEntityExist(existingDriver) and IsPedAPlayer(existingDriver) then
        RequestControl(existingDriver, 500)
        TaskLeaveVehicle(existingDriver, veh, 16)
        local driverWait = GetGameTimer()
        while GetPedInVehicleSeat(veh, -1) == existingDriver and GetGameTimer() - driverWait < 1200 do Wait(20) end
        if GetPedInVehicleSeat(veh, -1) == existingDriver then
            _G._hijackVisWatch = false
            restorePlayer()
            ShowDynastyNotification("[ NPC HIJACK ] Conducteur joueur toujours au volant")
            return false, nil
        end
    end

    SetPedIntoVehicle(playerPed, veh, -1)
    local takeoverSuccess = false
    local tStart = GetGameTimer()
    while (GetGameTimer() - tStart) < 2000 do
        if not DoesEntityExist(veh) then break end
        RequestControl(veh, 200)
        if IsPedInVehicle(playerPed, veh, false) and GetPedInVehicleSeat(veh, -1) == playerPed then
            takeoverSuccess = true
            break
        end
        SetPedIntoVehicle(playerPed, veh, -1)
        Wait(30)
    end

    if not takeoverSuccess then
        _G._hijackVisWatch = false
        restorePlayer()
        if opts.freezeAfter then FreezeEntityPosition(playerPed, true) end
        return false, nil
    end

    -- Le joueur est au volant : controle reseau garanti, execution de onSeated
    if opts.onSeated then
        RequestControl(veh, 400)
        local okCb, errCb = pcall(opts.onSeated, veh)
        if not okCb then  end
    end

    -- Si le vehicule a ete supprime pendant onSeated
    if not DoesEntityExist(veh) then
        _G._hijackVisWatch = false
        restorePlayer()
        if opts.freezeAfter then FreezeEntityPosition(playerPed, true) end
        return true, nil
    end

    -- Remplacer le joueur par un NPC conducteur AVANT de restaurer la position du joueur
    local npc = nil
    if not opts.noNPC and DoesEntityExist(veh) then
        local model = GetHashKey("s_m_y_marine_01")
        RequestModel(model)
        local tModel = GetGameTimer()
        while not HasModelLoaded(model) and (GetGameTimer() - tModel) < 1500 do Wait(10) end

        -- Ejecter le joueur sur le cote du vehicule
        TaskLeaveVehicle(playerPed, veh, 16)
        SetEntityCoordsNoOffset(playerPed, vPos.x + 2.0, vPos.y, vPos.z + 0.5, false, false, false)
        Wait(40)

        if HasModelLoaded(model) and DoesEntityExist(veh) then
            npc = CreatePedInsideVehicle(veh, 4, model, -1, false, false)
            if not npc or not DoesEntityExist(npc) then
                npc = CreatePed(4, model, vPos.x, vPos.y, vPos.z, 0.0, false, false)
                if npc and DoesEntityExist(npc) then SetPedIntoVehicle(npc, veh, -1) end
            end
            if npc and DoesEntityExist(npc) then
                SetEntityAsMissionEntity(npc, true, true)
                SetEntityAsMissionEntity(veh, true, true)
                SetBlockingOfNonTemporaryEvents(npc, true)
                SetPedRandomComponentVariation(npc, 0)
                SetPedCanRagdoll(npc, false)
                SetPedCanBeDraggedOut(npc, false)
                SetPedKeepTask(npc, true)
                SetDriverAggressiveness(npc, 1.0)
                SetDriverAbility(npc, 1.0)
                SetVehicleEngineOn(veh, true, true, false)
                SetPedIntoVehicle(npc, veh, -1)

                if npcTask == "v2" then
                    SetEntityInvincible(veh, true)
                    SetEntityInvincible(npc, true)
                    pcall(SetVehicleEnginePowerMultiplier, veh, 50.0)
                    pcall(SetVehicleCheatPowerIncrease, veh, 5.0)
                    TaskVehicleDriveWander(npc, veh, 150.0, 1074528293)
                    Menu.Helpers.NPCHijackV2Loop(veh, npc)
                elseif npcTask == "none" then
                    SetEntityInvincible(npc, true)
                else
                    TaskVehicleDriveWander(npc, veh, 40.0, 786603)
                end
            end
            SetModelAsNoLongerNeeded(model)
        end
    else
        if IsPedInVehicle(playerPed, veh, false) then
            TaskLeaveVehicle(playerPed, veh, 16)
            Wait(40)
        end
    end

    -- Restaurer le joueur a sa position d'origine
    restorePlayer()
    if opts.freezeAfter then FreezeEntityPosition(playerPed, true) end

    _G._hijackVisWatch = false
    SetEntityVisible(playerPed, true, false)
    ResetEntityAlpha(playerPed)
    if not opts.noNPC and (not npc or not DoesEntityExist(npc) or GetPedInVehicleSeat(veh, -1) ~= npc) then
        return false, nil
    end
    return true, npc
end

-- Wrapper : anti-double-lancement + garantit le nettoyage meme en cas d'erreur
function Menu.Helpers.HijackVehicle(veh, opts)
    local now = GetGameTimer()
    if _G._hijackBusy and (now - (_G._hijackBusyAt or 0)) < 2500 then
        local waitStart = now
        while _G._hijackBusy and (GetGameTimer() - waitStart) < 2500 do
            Wait(50)
        end
        if _G._hijackBusy then
            _G._hijackBusy     = false
            _G._hijackVisWatch = false
            local ped = PlayerPedId()
            pcall(SetEntityVisible, ped, true, false)
            pcall(ResetEntityAlpha, ped)
            pcall(ClearFocus)
            pcall(NewLoadSceneStop)
        end
    else
        _G._hijackBusy = false
    end
    _G._hijackBusy   = true
    _G._hijackBusyAt = GetGameTimer()
    local ok, res, npc = pcall(Menu.Helpers._HijackVehicleImpl, veh, opts)
    _G._hijackBusy     = false
    _G._hijackVisWatch = false
    local ped = PlayerPedId()
    SetEntityVisible(ped, true, false)
    ResetEntityAlpha(ped)
    if not ok then
        pcall(ClearFocus)
        pcall(NewLoadSceneStop)
        ShowDynastyNotification("[ NPC HIJACK ] Erreur interne : " .. tostring(res))
        return false, nil
    end
    return res, npc
end

-- Reference stable du pipeline NPC avec options (une ancienne surcharge existe plus bas).
Menu.Helpers.HijackVehicleWithOptions=Menu.Helpers.HijackVehicle
function Menu.Helpers.HijackTrollVehicle(veh)
    if not veh or veh == 0 or not DoesEntityExist(veh) then return false end
    local ok = Menu.Helpers.HijackVehicleWithOptions(veh, { npcTask = "none", freezeAfter = false })
    if not ok then ShowDynastyNotification("[ VEHICULE ] NPC Hijack refuse") end
    return ok == true
end

-- Sequence originale du bouton NPC Hijack freecam, delais d'origine.
function Menu.Helpers.RunFreecamNpcHijackLegacy(vehicleToNPCDrive, opts)
    opts = opts or {}
    if not vehicleToNPCDrive or not DoesEntityExist(vehicleToNPCDrive) then return false end
    local resultNpc=nil
    local playerPed = PlayerPedId()
    local initialCoords = GetEntityCoords(playerPed)
    local initialHeading = GetEntityHeading(playerPed)

    local function RequestControl(entity, timeoutMs)
        if not entity or not DoesEntityExist(entity) then return false end
        local start = GetGameTimer()
        NetworkRequestControlOfEntity(entity)
        while not NetworkHasControlOfEntity(entity) do
            Wait(10)
            if not DoesEntityExist(entity) then return false end
            if GetGameTimer() - start > (timeoutMs or 500) then
                return false
            end
            NetworkRequestControlOfEntity(entity)
        end
        return true
    end

    -- Invisible pendant le warp
    SetEntityVisible(playerPed, true, false)
    ResetEntityAlpha(playerPed)

    RequestControl(vehicleToNPCDrive, 800)
    SetVehicleDoorsLocked(vehicleToNPCDrive, 1)
    SetVehicleDoorsLockedForAllPlayers(vehicleToNPCDrive, false)

    local function tryEnterSeat(seatIndex)
        SetPedIntoVehicle(playerPed, vehicleToNPCDrive, seatIndex)
        Wait(0)
        return IsPedInVehicle(playerPed, vehicleToNPCDrive, false) and GetPedInVehicleSeat(vehicleToNPCDrive, seatIndex) == playerPed
    end

    local function getFirstFreeSeat(v)
        local numSeats = GetVehicleModelNumberOfSeats(GetEntityModel(v))
        if not numSeats or numSeats <= 0 then return -1 end
        for seat = 0, (numSeats - 2) do
            if IsVehicleSeatFree(v, seat) then return seat end
        end
        return -1
    end

    ClearPedTasksImmediately(playerPed)
    SetVehicleDoorsLocked(vehicleToNPCDrive, 1)
    SetVehicleDoorsLockedForAllPlayers(vehicleToNPCDrive, false)

    local takeoverSuccess = false
    local tStart = GetGameTimer()

    while (GetGameTimer() - tStart) < 1000 do
        RequestControl(vehicleToNPCDrive, 400)
        -- La demande de siege doit etre envoyee au reseau avant le warp local.
        if NetworkHasControlOfEntity(vehicleToNPCDrive) then
            pcall(SetVehicleExclusiveDriver_2, vehicleToNPCDrive, playerPed, 0)
        end

        if IsVehicleSeatFree(vehicleToNPCDrive, -1) and tryEnterSeat(-1) then
            takeoverSuccess = true
            break
        end

        if not IsPedInVehicle(playerPed, vehicleToNPCDrive, false) then
            local fs = getFirstFreeSeat(vehicleToNPCDrive)
            if fs ~= -1 then
                tryEnterSeat(fs)
            end
        end

        local drv = GetPedInVehicleSeat(vehicleToNPCDrive, -1)
        if drv ~= 0 and drv ~= playerPed and DoesEntityExist(drv) then
            RequestControl(drv, 400)
            ClearPedTasksImmediately(drv)
            SetEntityAsMissionEntity(drv, true, true)
            SetEntityCoords(drv, 0.0, 0.0, -100.0, false, false, false, false)
            Wait(20)
            DeleteEntity(drv)
        end

        local t0 = GetGameTimer()
        while (GetGameTimer() - t0) < 400 do
            local occ = GetPedInVehicleSeat(vehicleToNPCDrive, -1)
            if occ == 0 or (occ ~= 0 and not DoesEntityExist(occ)) then break end
            Wait(0)
        end

        local t1 = GetGameTimer()
        while (GetGameTimer() - t1) < 500 do
            if NetworkHasControlOfEntity(vehicleToNPCDrive) then
                pcall(SetVehicleExclusiveDriver_2, vehicleToNPCDrive, playerPed, 0)
            end
            if IsVehicleSeatFree(vehicleToNPCDrive, -1) and tryEnterSeat(-1) then
                takeoverSuccess = true
                break
            end
            Wait(0)
        end
        if takeoverSuccess then break end
        Wait(0)
    end

    if takeoverSuccess then
        -- Le joueur doit quitter le siege conducteur AVANT la creation du NPC.
        FreezeEntityPosition(playerPed, false)
        if IsPedInVehicle(playerPed, vehicleToNPCDrive, false) then
            TaskLeaveVehicle(playerPed, vehicleToNPCDrive, 16)
            local exitStart = GetGameTimer()
            while IsPedInVehicle(playerPed, vehicleToNPCDrive, false) and GetGameTimer() - exitStart < 900 do
                Wait(20)
            end
        end
        if IsPedInVehicle(playerPed, vehicleToNPCDrive, false) then
            ClearPedTasksImmediately(playerPed)
            TaskLeaveVehicle(playerPed, vehicleToNPCDrive, 16)
            Wait(100)
        end
        if IsPedInVehicle(playerPed, vehicleToNPCDrive, false)
            or GetPedInVehicleSeat(vehicleToNPCDrive, -1) == playerPed then
            ShowDynastyNotification("[ NPC HIJACK ] Sortie conducteur refusee")
            return false, nil
        end
        SetEntityCoordsNoOffset(playerPed, initialCoords.x, initialCoords.y, initialCoords.z, false, false, false, false)
        SetEntityHeading(playerPed, initialHeading)
        SetEntityVisible(playerPed, true, false)
        ResetEntityAlpha(playerPed)
        if opts.freezeAfter ~= false then FreezeEntityPosition(playerPed, true) end

        if DoesEntityExist(vehicleToNPCDrive) and GetPedInVehicleSeat(vehicleToNPCDrive, -1) == 0 then
            RequestControl(vehicleToNPCDrive, 1000)
            local model = GetHashKey("s_m_y_marine_01")
            RequestModel(model)
            local tModel = GetGameTimer()
            while not HasModelLoaded(model) and (GetGameTimer() - tModel) < 2000 do Wait(0) end
            if HasModelLoaded(model) then
                local npc = CreatePedInsideVehicle(vehicleToNPCDrive, 4, model, -1, false, false)
                if not DoesEntityExist(npc) then
                    local vc = GetEntityCoords(vehicleToNPCDrive)
                    npc = CreatePed(4, model, vc.x, vc.y, vc.z + 2.0, 0.0, false, false)
                    if DoesEntityExist(npc) then SetPedIntoVehicle(npc, vehicleToNPCDrive, -1) end
                end
                if DoesEntityExist(npc) then
                    resultNpc=npc
                    SetEntityAsMissionEntity(npc, true, false)
                    SetBlockingOfNonTemporaryEvents(npc, true)
                    SetPedRandomComponentVariation(npc, 0)
                    local tSeat = GetGameTimer()
                    while not IsPedInVehicle(npc, vehicleToNPCDrive, false) and (GetGameTimer() - tSeat) < 1500 do
                        SetPedIntoVehicle(npc, vehicleToNPCDrive, -1)
                        Wait(50)
                    end
                    Wait(200)
                    local curMode = opts.npcTask or (_G.FreecamNPCHijackModes or { "V1", "V2" })[_G.FreecamNPCHijackModeIdx or 1]
                    if curMode == "V2" then
                        SetEntityInvincible(vehicleToNPCDrive, true)
                        SetEntityInvincible(npc, true)
                        SetPedCanRagdoll(npc, false)
                        SetPedCanBeDraggedOut(npc, false)
                        SetPedKeepTask(npc, true)
                        SetDriverAggressiveness(npc, 1.0)
                        SetDriverAbility(npc, 1.0)
                        SetVehicleEngineOn(vehicleToNPCDrive, true, true, false)
                        pcall(SetVehicleEnginePowerMultiplier, vehicleToNPCDrive, 50.0)
                        pcall(SetVehicleCheatPowerIncrease, vehicleToNPCDrive, 5.0)
                        TaskVehicleDriveWander(npc, vehicleToNPCDrive, 150.0, 1074528293)
                        ShowDynastyNotification("[ NPC HIJACK V2 ] Boost dans tous les sens actif !")

                        CreateThread(function()
                            local veh = vehicleToNPCDrive
                            local pnj = npc
                            local startTime = GetGameTimer()
                            while (GetGameTimer() - startTime) < 90000 do
                                if not DoesEntityExist(veh) or not DoesEntityExist(pnj) then break end
                                if not IsPedInVehicle(pnj, veh, false) then break end

                                NetworkRequestControlOfEntity(veh)

                                local boostType = math.random(1, 4)
                                local speed = math.random(60.0, 100.0)

                                if boostType == 1 then
                                    local fwd = GetEntityForwardVector(veh)
                                    SetEntityVelocity(veh, fwd.x * speed, fwd.y * speed, math.random(3.0, 12.0))
                                    ApplyForceToEntity(veh, 1, fwd.x * 500.0, fwd.y * 500.0, 150.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                                elseif boostType == 2 then
                                    local fwd = GetEntityForwardVector(veh)
                                    local sign = (math.random(0, 1) == 0) and -1.0 or 1.0
                                    local sideX, sideY = -fwd.y * sign, fwd.x * sign
                                    SetEntityVelocity(veh, (fwd.x * 0.3 + sideX * 0.9) * speed, (fwd.y * 0.3 + sideY * 0.9) * speed, math.random(4.0, 16.0))
                                    SetEntityAngularVelocity(veh, 0.0, 0.0, sign * math.random(6.0, 16.0))
                                    ApplyForceToEntity(veh, 1, sideX * 600.0, sideY * 600.0, 180.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                                elseif boostType == 3 then
                                    local fwd = GetEntityForwardVector(veh)
                                    SetEntityVelocity(veh, fwd.x * (speed * 0.6), fwd.y * (speed * 0.6), math.random(25.0, 50.0))
                                    ApplyForceToEntity(veh, 1, fwd.x * 250.0, fwd.y * 250.0, 700.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                                else
                                    local angle = math.random() * math.pi * 2.0
                                    local dirX, dirY = math.cos(angle), math.sin(angle)
                                    SetEntityVelocity(veh, dirX * speed, dirY * speed, math.random(5.0, 22.0))
                                    SetEntityAngularVelocity(veh, (math.random() - 0.5) * 12.0, (math.random() - 0.5) * 12.0, (math.random() - 0.5) * 25.0)
                                    ApplyForceToEntity(veh, 1, dirX * 600.0, dirY * 600.0, 250.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                                end

                                if math.random(1, 4) == 1 then
                                    StartVehicleHorn(veh, 300, "HELDDOWN", false)
                                end

                                TaskVehicleDriveWander(pnj, veh, 150.0, 1074528293)
                                Wait(math.random(200, 380))
                            end
                        end)
                    else
                        if curMode ~= "none" then
                            TaskVehicleDriveWander(npc, vehicleToNPCDrive, 30.0, 786603)
                            ShowDynastyNotification("[ NPC HIJACK ] NPC au volant")
                        end
                    end
                end
                SetModelAsNoLongerNeeded(model)
            end
        end
    else
        FreezeEntityPosition(playerPed, false)
        if IsPedInVehicle(playerPed, vehicleToNPCDrive, false) then
            TaskLeaveVehicle(playerPed, vehicleToNPCDrive, 16)
            Wait(100)
        end
        if not IsPedInVehicle(playerPed, vehicleToNPCDrive, false) then
            SetEntityCoordsNoOffset(playerPed, initialCoords.x, initialCoords.y, initialCoords.z, false, false, false, false)
        end
        SetEntityVisible(playerPed, true, false)
        ResetEntityAlpha(playerPed)
        if opts.freezeAfter ~= false then FreezeEntityPosition(playerPed, true) end
        ShowDynastyNotification("[ NPC HIJACK ] Failed to take control")
    end

    return resultNpc~=nil and DoesEntityExist(resultNpc) and IsPedInVehicle(resultNpc,vehicleToNPCDrive,false),resultNpc
end

function Menu.Helpers.RunFreecamNpcHijack(vehicleToNPCDrive, opts)
    opts = opts or {}
    local mode = opts.npcTask or (_G.FreecamNPCHijackModes or { "V1", "V2" })[_G.FreecamNPCHijackModeIdx or 1]
    local mapped = mode == "V2" and "v2" or (mode == "none" and "none" or "wander")
    return Menu.Helpers.HijackVehicleWithOptions(vehicleToNPCDrive, {
        npcTask = mapped,
        freezeAfter = opts.freezeAfter ~= false
    })
end

function Menu.Helpers.WaitConfirmedVehicleControl(vehicle,timeout)
    if not vehicle or vehicle==0 or not DoesEntityExist(vehicle) or not NetworkGetEntityIsNetworked(vehicle) then return false end
    local started,stable=GetGameTimer(),nil
    repeat
        if not DoesEntityExist(vehicle) or not NetworkGetEntityIsNetworked(vehicle) then return false end
        NetworkRequestControlOfEntity(vehicle)
        if NetworkHasControlOfEntity(vehicle) then
            stable=stable or GetGameTimer()
            if GetGameTimer()-stable>=100 then return true end
        else stable=nil end
        Wait(25)
    until GetGameTimer()-started>=(timeout or 1500)
    return false
end

function Menu.Helpers.PrepareNpcVehicleEntry(vehicle,freeDriverSeat)
    if not vehicle or not DoesEntityExist(vehicle) then return false end
    if _G._effectVehicleWarpBusy then
        ShowDynastyNotification('[ HIJACK ] Une prise de vehicule est deja en cours');return false
    end
    -- Laisser le NPC Hijack tenter la prise ; le controle est obligatoire APRES,
    -- avant Warp/TP Passenger, pas comme condition prealable a cette acquisition.
    ShowDynastyNotification('[ HIJACK ] Prise NPC prealable...')
    local ok,npc=Menu.Helpers.RunFreecamNpcHijack(vehicle)
    if not ok or not DoesEntityExist(vehicle) then
        ShowDynastyNotification('[ HIJACK ] Prise impossible');return false
    end
    -- Le PNJ reellement installe au volant est le signal de depart demande.
    if not npc or not DoesEntityExist(npc) or GetPedInVehicleSeat(vehicle,-1)~=npc then
        ShowDynastyNotification('[ HIJACK ] NPC pas encore au volant');return false
    end
    if NetworkGetEntityIsNetworked(vehicle) then NetworkRequestControlOfEntity(vehicle) end
    if freeDriverSeat and npc and DoesEntityExist(npc) and not IsPedAPlayer(npc) then
        TaskLeaveVehicle(npc,vehicle,16)
        local untilTime=GetGameTimer()+350
        while DoesEntityExist(npc) and IsPedInVehicle(npc,vehicle,false) and GetGameTimer()<untilTime do Wait(10) end
        -- Seul le PNJ cree par cette prise est nettoye.
        if DoesEntityExist(npc) then SetEntityAsMissionEntity(npc,true,true);DeleteEntity(npc) end
    end
    return DoesEntityExist(vehicle)
end

-- Force-reset manuel du lock hijack (appeler si bug persistant)
function Menu.Helpers.ResetHijackLock()
    _G._hijackBusy     = false
    _G._hijackBusyAt   = 0
    _G._hijackVisWatch = false
    local ped = PlayerPedId()
    pcall(SetEntityVisible, ped, true, false)
    pcall(ResetEntityAlpha, ped)
    pcall(ClearFocus)
    pcall(NewLoadSceneStop)
    ShowDynastyNotification("[ HIJACK ] Lock reset force")
end

-- Supprime un vehicule (+ occupants NPC) : a appeler quand on a deja le controle
function Menu.Helpers.ForceDeleteVehicle(v)
    if not v or not DoesEntityExist(v) then return true end
    local myPed = PlayerPedId()
    SetEntityAsMissionEntity(v, true, true)
    NetworkRequestControlOfEntity(v)
    local maxSeats = GetVehicleMaxNumberOfPassengers(v)
    for seat = -1, maxSeats - 1 do
        local occ = GetPedInVehicleSeat(v, seat)
        if occ ~= 0 and DoesEntityExist(occ) and occ ~= myPed and not IsPedAPlayer(occ) then
            NetworkRequestControlOfEntity(occ)
            SetEntityAsMissionEntity(occ, true, true)
            DeleteEntity(occ)
        end
    end
    for _ = 1, 5 do
        if not DoesEntityExist(v) then break end
        NetworkRequestControlOfEntity(v)
        SetEntityAsMissionEntity(v, true, true)
        DeleteVehicle(v)
        DeleteEntity(v)
        Wait(20)
    end
    if DoesEntityExist(v) then
        SetEntityCoords(v, 0.0, 0.0, -1000.0, false, false, false, false)
        DeleteVehicle(v)
        DeleteEntity(v)
    end
    if DoesEntityExist(v) and type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" then
        local netId = NetworkGetEntityIsNetworked(v) and NetworkGetNetworkIdFromEntity(v) or nil
        if netId then
            Lapsus_InjectResource_compat("any", string.format([[
                local veh = NetworkGetEntityFromNetworkId(%d)
                if veh and DoesEntityExist(veh) then
                    SetEntityAsMissionEntity(veh, true, true)
                    DeleteVehicle(veh)
                    DeleteEntity(veh)
                end
            ]], netId))
        end
    end
    return not DoesEntityExist(v)
end

-- Hijack + suppression : prend le controle (pipeline NPC Hijack) puis supprime le vehicule
function Menu.Helpers.HijackAndDelete(veh)
    if not veh or veh == 0 or not DoesEntityExist(veh) then
        ShowDynastyNotification("[ DELETE ] Aucun vehicule")
        return
    end
    local now = GetGameTimer()
    if _G._hijackBusy and (now - (_G._hijackBusyAt or 0)) >= 2500 then
        _G._hijackBusy     = false
        _G._hijackVisWatch = false
        pcall(ClearFocus); pcall(NewLoadSceneStop)
    end
    ShowDynastyNotification("[ DELETE ] Suppression...")
    CreateThread(function()
        if not Menu.Helpers.HijackTrollVehicle(veh) then return end
        SetEntityAsMissionEntity(veh, true, true)
        NetworkRequestControlOfEntity(veh)
        local deleted = Menu.Helpers.ForceDeleteVehicle(veh)

        if deleted or not DoesEntityExist(veh) then
            Menu.State.vehicleSelectedVehicle = nil
            lastVehicleListUpdate = 0
            ShowDynastyNotification("[ DELETE ] Vehicule supprime")
        else
            ShowDynastyNotification("[ DELETE ] Echec suppression")
        end
    end)
end

-- NPC Drive : meme pipeline que le NPC Hijack freecam
function Menu.Helpers.NPCDriveVehicle(veh, label)
    if not veh or veh == 0 or not DoesEntityExist(veh) then
        ShowDynastyNotification("[ NPC HIJACK ] Aucun vehicule")
        return
    end
    local now = GetGameTimer()
    if _G._hijackBusy and (now - (_G._hijackBusyAt or 0)) >= 2500 then
        _G._hijackBusy     = false
        _G._hijackVisWatch = false
        pcall(ClearFocus); pcall(NewLoadSceneStop)
    end
    local modes = _G.FreecamNPCHijackModes or { "V1", "V2" }
    local curMode = modes[_G.FreecamNPCHijackModeIdx or 1] or "V1"
    ShowDynastyNotification("[ NPC HIJACK " .. curMode .. " ] Prise de controle...")
    CreateThread(function()
        local ok = Menu.Helpers.RunFreecamNpcHijack(veh, { npcTask = curMode, freezeAfter = false })
        if ok then
            ShowDynastyNotification("[ NPC HIJACK " .. curMode .. " ] " .. (label or "Vehicule") .. " : NPC au volant")
        else
            ShowDynastyNotification("[ NPC HIJACK ] Echec controle")
        end
    end)
end

local function WithNetworkControl(veh, fn)
    if not DoesEntityExist(veh) then return end
    local playerPed   = PlayerPedId()
    local savedCoords = GetEntityCoords(playerPed)
    local savedHead   = GetEntityHeading(playerPed)
    local wasInVeh    = IsPedInAnyVehicle(playerPed, false)
    local prevVeh     = wasInVeh and GetVehiclePedIsIn(playerPed, false) or nil
    local prevSeat    = -2

    -- Trouver le siege conducteur libre, sinon n importe quel siege libre
    local function findFreeSeat()
        if IsVehicleSeatFree(veh, -1) then return -1 end
        local max = GetVehicleMaxNumberOfPassengers(veh)
        for s = 0, max - 1 do
            if IsVehicleSeatFree(veh, s) then return s end
        end
        return -1 -- forcer quand meme
    end

    -- Memoriser le siege actuel si on etait dans un veh
    if wasInVeh and prevVeh then
        local max = GetVehicleMaxNumberOfPassengers(prevVeh)
        for s = -1, max - 1 do
            if GetPedInVehicleSeat(prevVeh, s) == playerPed then
                prevSeat = s; break
            end
        end
    end

    -- Rendre completement invisible pendant tout le warp (sauf si bypass seed actif)
    SetEntityVisible(playerPed, true, false)
    ResetEntityAlpha(playerPed)
    SetEntityInvincible(playerPed, true)
    local seat = findFreeSeat()
    SetPedIntoVehicle(playerPed, veh, seat)
    -- Si bypass seed actif : forcer visibilite apres SetPedIntoVehicle
    if seedBlocksInvisibility() then
        SetEntityVisible(playerPed, true, false)
        ResetEntityAlpha(playerPed)
    end
    Wait(120)

    -- Demander le controle reseau maintenant qu on est dedans
    SetEntityAsMissionEntity(veh, true, true)
    if NetworkGetEntityIsNetworked(veh) then
        local netId = NetworkGetNetworkIdFromEntity(veh)
        NetworkRequestControlOfNetworkId(netId)
        local t = 0
        while not NetworkHasControlOfEntity(veh) and t < 60 do
            Wait(50); t = t + 1
            NetworkRequestControlOfNetworkId(netId)
            -- Pendant la boucle aussi, garder visible si bypass seed
            if seedBlocksInvisibility() then
                SetEntityVisible(playerPed, true, false)
                ResetEntityAlpha(playerPed)
            end
        end
    end

    -- Thread de surveillance bypass seed pendant fn()
    local bypassWatch2Active = seedBlocksInvisibility()
    if bypassWatch2Active then
        _G._bypassWarpWatch2Running = true
        CreateThread(function()
            while _G._bypassWarpWatch2Running do
                local ped = PlayerPedId()
                if not IsEntityVisible(ped) then SetEntityVisible(ped, true, false) end
                if GetEntityAlpha(ped) < 255 then ResetEntityAlpha(ped) end
                Wait(0)
            end
            SetEntityVisible(PlayerPedId(), true, false)
            ResetEntityAlpha(PlayerPedId())
        end)
    end

    -- Executer l action
    pcall(fn, veh)
    _G._bypassWarpWatch2Running = false
    Wait(80)

    -- Sortir du vehicule et retourner a la position initiale
    TaskLeaveVehicle(playerPed, veh, 16)
    Wait(300)

    -- Si on etait dans un autre veh avant, y retourner
    if wasInVeh and prevVeh and DoesEntityExist(prevVeh) then
        SetPedIntoVehicle(playerPed, prevVeh, prevSeat)
    else
        SetEntityCoords(playerPed, savedCoords.x, savedCoords.y, savedCoords.z, false, false, false, false)
        SetEntityHeading(playerPed, savedHead)
    end

    Wait(100)
    SetEntityVisible(playerPed, true, false)
    ResetEntityAlpha(playerPed)
    SetEntityInvincible(playerPed, false)
end

-- Bug le vehicule selectionne : NPC hijack puis Bug V1/V2 (meme mode que Bug Vehicle freecam)
function Menu.Actions.BugNearestVehicle()
    local veh = Menu.Helpers.ResolveTrollVehicle("BUG")
    if not veh then return end
    local modes = _G.FreecamBugVehicleModes or { "V1", "V2" }
    local mode = modes[_G.FreecamBugVehicleModeIdx or 1] or "V1"
    if mode == "V2" then
        Menu.Actions.BugVehicleV2(veh)
    else
        Menu.Actions.BugVehicleV1(veh)
    end
end

-- Casser les roues du vehicule selectionne dans le Tab List
function Menu.Actions.BrokeSelectedVehicleWheels()
    local veh = Menu.Helpers.ResolveTrollVehicle("BROKE")
    if not veh then return end
    local now = GetGameTimer()
    if _G._hijackBusy and (now - (_G._hijackBusyAt or 0)) >= 8000 then
        _G._hijackBusy     = false
        _G._hijackVisWatch = false
        pcall(ClearFocus); pcall(NewLoadSceneStop)
    end
    ShowDynastyNotification("[ BROKE ] En cours...")
    CreateThread(function()
        WithNPCNetworkControl(veh, function(v)
            SetVehicleWheelsCanBreak(v, true)
            local numWheels = GetVehicleNumberOfWheels(v)
            for i = 0, numWheels - 1 do
                SetVehicleTyreBurst(v, i, true, 1000.0)
                BreakOffVehicleWheel(v, i, true, true, true, false)
            end
            -- Restaurer la collision du vÃ©hicule pour Ã©viter qu'il passe sous la map
            SetEntityCollision(v, true, true)
            SetVehicleOnGroundProperly(v)
        end)
        ShowDynastyNotification("[ BROKE ] OK")
    end)
end

-- Supprimer le vehicule selectionne dans le Tab List : NPC hijack puis suppression
function Menu.Actions.DeleteSelectedVehicle()
    local veh = Menu.Helpers.ResolveTrollVehicle("DELETE")
    if not veh then return end
    Menu.Helpers.HijackAndDelete(veh)
end

-- Faire exploser le vehicule selectionne dans le Tab Troll / List
function Menu.Actions.ExplodeSelectedVehicle(targetVehicle)
    local veh = targetVehicle or Menu.Helpers.ResolveTrollVehicle("EXPLODE")
    if not veh or veh == 0 or not DoesEntityExist(veh) then return end

    ShowDynastyNotification("[ EXPLODE ] Explosion en cours...")
    CreateThread(function()
        SetEntityAsMissionEntity(veh, true, true)
        NetworkRequestControlOfEntity(veh)

        local vCoords = GetEntityCoords(veh)

        if not Menu.Helpers.HijackTrollVehicle(veh) then return end

        SetEntityAsMissionEntity(veh, true, true)
        NetworkRequestControlOfEntity(veh)
        SetVehicleEngineHealth(veh, -4000.0)
        SetVehicleBodyHealth(veh, -4000.0)
        SetVehiclePetrolTankHealth(veh, -4000.0)
        NetworkExplodeVehicle(veh, true, false, -1)
        AddExplosion(vCoords.x, vCoords.y, vCoords.z, 2, 10.0, true, false, 1.0)
        AddExplosion(vCoords.x, vCoords.y, vCoords.z, 7, 10.0, true, false, 1.0)

        local netId = NetworkGetEntityIsNetworked(veh) and NetworkGetNetworkIdFromEntity(veh) or nil
        if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" and netId then
            Lapsus_InjectResource_compat("any", string.format([[
                local v = NetworkGetEntityFromNetworkId(%d)
                if v and DoesEntityExist(v) then
                    SetVehicleEngineHealth(v, -4000.0)
                    NetworkExplodeVehicle(v, true, false, -1)
                    local c = GetEntityCoords(v)
                    AddExplosion(c.x, c.y, c.z, 2, 10.0, true, false, 1.0)
                end
            ]], netId))
        end

        ShowDynastyNotification("[ EXPLODE ] Boom !")
    end)
end

