-- Faire foncer un NPC dans le vehicule selectionne sur le joueur/vehicule le plus proche
function Menu.Actions.CrazyNPC()
    local veh = Menu.Helpers.GetSelectedVehicleHandle()
    if not veh then
        ShowDynastyNotification("[ CRAZY NPC ] Aucun vehicule")
        return
    end

    CreateThread(function()
        local playerPed      = PlayerPedId()
        local initialCoords  = GetEntityCoords(playerPed)
        local initialHeading = GetEntityHeading(playerPed)
        local vPos           = GetEntityCoords(veh)

        local function WaitNetControl(entity, timeoutMs)
            if not entity or not DoesEntityExist(entity) then return false end
            local t0 = GetGameTimer()
            while not NetworkHasControlOfEntity(entity) do
                NetworkRequestControlOfEntity(entity)
                Wait(10)
                if not DoesEntityExist(entity) then return false end
                if GetGameTimer() - t0 > (timeoutMs or 1000) then return false end
            end
            return true
        end

        local function GetClosestTarget(fromVeh)
            if not fromVeh or not DoesEntityExist(fromVeh) then return nil end
            local fromCoords = GetEntityCoords(fromVeh)
            local bestEnt    = nil
            local bestDist   = math.huge
            for i = 0, 31 do
                local p = GetPlayerPed(i)
                if p and p ~= playerPed and DoesEntityExist(p) then
                    local pv = GetVehiclePedIsIn(p, false)
                    local ent = (pv and pv ~= 0 and DoesEntityExist(pv)) and pv or p
                    local d = #(fromCoords - GetEntityCoords(ent))
                    if d < bestDist then
                        bestDist = d
                        bestEnt  = ent
                    end
                end
            end
            return bestEnt
        end

        -- Charger le monde + warp invisible
        RequestCollisionAtCoord(vPos.x, vPos.y, vPos.z)
        SetFocusPosAndVel(vPos.x, vPos.y, vPos.z, 0, 0, 0)
        NewLoadSceneStart(vPos.x, vPos.y, vPos.z, vPos.x, vPos.y, vPos.z, 500.0, 0)
        SetEntityVisible(playerPed, true, false)
        ResetEntityAlpha(playerPed)
        SetEntityCoordsNoOffset(playerPed, vPos.x, vPos.y, vPos.z + 2.0, false, false, false)
        Wait(100)

        -- Ejecter le conducteur NPC existant si present
        local drv = GetPedInVehicleSeat(veh, -1)
        if drv ~= 0 and drv ~= playerPed and DoesEntityExist(drv) and not IsPedAPlayer(drv) then
            if WaitNetControl(drv, 600) then
                ClearPedTasksImmediately(drv)
                SetEntityAsMissionEntity(drv, true, true)
                SetEntityCoords(drv, 0.0, 0.0, -100.0, false, false, false, false)
                Wait(30)
                DeleteEntity(drv)
            end
        end
        Wait(100)

        local controlled = WaitNetControl(veh, 1500)

        -- Retour joueur
        SetEntityCoordsNoOffset(playerPed, initialCoords.x, initialCoords.y, initialCoords.z, false, false, false, false)
        SetEntityHeading(playerPed, initialHeading)
        SetEntityVisible(playerPed, true, false)
        ResetEntityAlpha(playerPed)

        if not controlled then
            ShowDynastyNotification("[ CRAZY NPC ] Echec controle")
            return
        end
        if not DoesEntityExist(veh) then
            ShowDynastyNotification("[ CRAZY NPC ] Vehicule disparu")
            return
        end

        local model = GetHashKey("s_m_y_marine_01")
        RequestModel(model)
        local tModel = GetGameTimer()
        while not HasModelLoaded(model) and (GetGameTimer() - tModel) < 3000 do Wait(0) end
        if not HasModelLoaded(model) then
            ShowDynastyNotification("[ CRAZY NPC ] Modele invalide")
            return
        end

        local npc = CreatePedInsideVehicle(veh, 4, model, -1, true, false)
        if not DoesEntityExist(npc) then
            local vc = GetEntityCoords(veh)
            npc = CreatePed(4, model, vc.x, vc.y, vc.z + 1.5, 0.0, true, false)
            if DoesEntityExist(npc) then SetPedIntoVehicle(npc, veh, -1) end
        end
        SetModelAsNoLongerNeeded(model)

        if not DoesEntityExist(npc) then
            ShowDynastyNotification("[ CRAZY NPC ] Creation echouee")
            return
        end

        SetEntityAsMissionEntity(npc, true, true)
        SetBlockingOfNonTemporaryEvents(npc, true)
        SetPedFleeAttributes(npc, 0, false)
        SetPedCombatAttributes(npc, 2,  true)
        SetPedCombatAttributes(npc, 52, true)
        SetPedCombatAttributes(npc, 46, true)
        SetPedRandomComponentVariation(npc, 0)
        SetVehicleEngineOn(veh, true, true, false)

        local tSeat = GetGameTimer()
        while not IsPedInVehicleSeat(npc, veh, -1) and (GetGameTimer() - tSeat) < 2000 do
            SetPedIntoVehicle(npc, veh, -1)
            Wait(50)
        end

        if not IsPedInVehicleSeat(npc, veh, -1) then
            ShowDynastyNotification("[ CRAZY NPC ] NPC bloque")
            return
        end

        ShowDynastyNotification("[ CRAZY NPC ] Actif")
        CreateThread(function()
            local lastTarget = nil
            while DoesEntityExist(npc) and IsPedInVehicleSeat(npc, veh, -1) do
                local target = GetClosestTarget(veh)
                if target and DoesEntityExist(target) then
                    if target ~= lastTarget then
                        lastTarget = target
                        ClearPedTasksImmediately(npc)
                    end
                    local tCoords = GetEntityCoords(target)
                    TaskVehicleDriveToCoord(npc, veh,
                        tCoords.x, tCoords.y, tCoords.z,
                        120.0, 0, GetEntityModel(veh), 786603, 0.1, true
                    )
                    SetVehicleEngineOn(veh, true, true, false)
                end
                Wait(250)
            end
            if DoesEntityExist(npc) then
                SetEntityAsMissionEntity(npc, true, true)
                DeleteEntity(npc)
            end
            ShowDynastyNotification("[ CRAZY NPC ] Detruit")
        end)
    end)
end

