-- Utilisation partagee du Full Invisible : chaque fonction libere sa propre demande.
local fullInvisibleOwners = {}
local manualFullInvisible = false
local setFullInvisibleRaw = Menu.Actions.SetFullInvisible
function Menu.Actions.SetFullInvisible(enable)
    manualFullInvisible = not not enable
    if not enable and next(fullInvisibleOwners) then return true end
    return setFullInvisibleRaw(enable)
end
function Menu.Actions.AcquireFullInvisible(owner)
    if not _G._positionF7Running then return false end
    if fullInvisibleOwners[owner] then return Menu.State.soloSessionFullInvisActive end
    if not Menu.State.soloSessionFullInvisActive and not setFullInvisibleRaw(true) then return false end
    fullInvisibleOwners[owner] = true
    return true
end
function Menu.Actions.ReleaseFullInvisible(owner)
    if not fullInvisibleOwners[owner] then return end
    fullInvisibleOwners[owner] = nil
    if not next(fullInvisibleOwners) and not manualFullInvisible then
        return setFullInvisibleRaw(false)
    end
    return true
end
function Menu.Actions.ForceStopFullInvisible()
    fullInvisibleOwners = {}
    manualFullInvisible = false
    _G._noclipDesyncSoloActive = false
    return setFullInvisibleRaw(false)
end
