                    local enable=not Menu.State.soloSessionFullInvisActive
                    if enable then Menu.State.soloSessionIdx=2; _G.soloSessionIdx=2 end
                    Menu.Actions.SetFullInvisible(enable)
                    
                end
                -- Bypass Seed : on ne force plus l'arret de l'invisibilite
                if Menu.State.soloSessionFullInvisActive then
