                    if not Lapsus.SpoofPosition(true,pos.x,pos.y,-1500.0) then
                        error('Mise a jour de position refusee.')
                    end
                end
                Lapsus.Wait(0)
            end
        end)
        Menu.Actions.ForceStopFullInvisible()
        _G._positionF7Running=nil
        if not ok then  end
    end)
elseif not apiReady() then
    
end
end

-- Godmode Putin : chemin evenement fourni, avec restauration conditionnelle.
function Menu.Helpers.GetPutinResource()
    local now=GetGameTimer()
    if Menu.State.putinResourceChecked and now<(Menu.State.putinResourceNextCheck or 0) then
        return Menu.State.putinResourceName
    end
    Menu.State.putinResourceChecked=true
    Menu.State.putinResourceNextCheck=now+1000
    Menu.State.putinResourceName=nil
    local ok,names=false,nil
    if type(Lapsus)=='table' and type(Lapsus.GetResources)=='function' then ok,names=pcall(Lapsus.GetResources) end
    if ok and type(names)=='table' then
        for _,name in ipairs(names) do
            if type(name)=='string' and name:lower()=='putin' then
                local running=true
                if type(GetResourceState)=='function' then
                    local stateOk,state=pcall(GetResourceState,name)
                    running=stateOk and (state=='started' or state=='starting')
                end
                if running then Menu.State.putinResourceName=name;return name end
            end
        end
    end
    return nil
end
function Menu.Helpers.HasPutinResource()
    return Menu.Helpers.GetPutinResource()~=nil
end

function Menu.Actions.SetPutinGodmode(enable)
    if not Lapsus or type(Lapsus.GetResources)~="function" or type(Lapsus_InjectResource_compat)~="function" then
        ;return false
    end
    local ok,resources=pcall(Lapsus.GetResources)
    if not ok or type(resources)~="table" then ;return false end
    local target
    for _,name in ipairs(resources) do
        if type(name)=="string" and name:lower()=="putin" then target=name;break end
    end
    if not target then ;return false end
    local code
    if enable then
        code=[====[
do
    local key='_putinMenuGodmodeController'
    local previous=_G[key]
    if previous and type(previous.dispose)=='function' then previous.dispose() end
    if type(_FRL)~='table' or type(_FRL.PlayerData)~='table' then
        ;return
    end
    local framework=_FRL
    local data=framework.PlayerData
    local ped=PlayerPedId()
    if not data.PassJoin or not data.cache or data.cache.playerped~=ped or not DoesEntityExist(ped) then
        ;return
    end
    if IsEntityDead(ped) then ;return end
    local marker='mirage_godmode:'..tostring(GetGameTimer())
    local beforeServer,beforeType=data.invincibleServer,data.invincibleType
    local ownsMarker=not (beforeServer==true or beforeServer==1)
    local running=true
    local stopHandler
    local function truth(value)return value==true or value==1 end
    local function optional(fn,...)
        if type(fn)~='function' then return false end
        local ok,value=pcall(fn,...)
        return ok and truth(value)
    end
    local function protectedElsewhere()
        local drop=EventsModule and EventsModule.functions and EventsModule.functions.IsPlayerNearADrop
        return truth(data.invincibleServer) or truth(data.safezone)
            or optional(framework.GetGameInstanceDefaultDataByKey,'safe')
            or (data.jail and (tonumber(data.jail.time) or 0)>0)
            or truth(data.AFK) or truth(_jbEv) or truth(_MOJQlj)
            or optional(_ZkZz1Up) or optional(drop)
    end
    local controller={}
    function controller.dispose()
        if not running then return end
        running=false
        if ownsMarker and framework.PlayerData==data and data.invincibleType==marker then
            local ok,err=pcall(function()
                TriggerEvent('gamemode:setInvincible',truth(beforeServer),beforeType)
                data.invincibleServer=beforeServer
                data.invincibleType=beforeType
                local protected=protectedElsewhere() and true or false
                data.invincible=protected
                local current=PlayerPedId()
                if DoesEntityExist(current) then
                    SetEntityInvincible(current,protected)
                    SetEntityCanBeDamaged(current,not protected)
                end
            end)
            if not ok then  end
        end
        if stopHandler and type(RemoveEventHandler)=='function' then RemoveEventHandler(stopHandler) end
        if _G[key]==controller then _G[key]=nil end
    end
    local function maintain()
        if framework.PlayerData~=data or not data.PassJoin then controller.dispose();return end
        if not ownsMarker and not truth(data.invincibleServer) then
            -- An inherited protection has ended; acquire our own instead of silently losing God Mode.
            beforeServer,beforeType=data.invincibleServer,data.invincibleType
            ownsMarker=true
            TriggerEvent('gamemode:setInvincible',true,marker)
        end
        if ownsMarker and (data.invincibleType~=marker or not truth(data.invincibleServer)) then
            
            controller.dispose();return
        end
        local current=PlayerPedId()
        if not DoesEntityExist(current) or not data.cache or data.cache.playerped~=current or IsEntityDead(current) then return end
        -- Putin's native loop reads these flags; avoid a competing per-frame native loop.
        -- Its health synchronizer clamps increases to PlayerData.health, so update it first.
        local maximum=GetEntityMaxHealth(current)
        if maximum>0 and GetEntityHealth(current)<maximum then
            data.health=maximum
            SetEntityHealth(current,maximum)
        end
    end
    local ok,err=pcall(function()
        if ownsMarker then
            TriggerEvent('gamemode:setInvincible',true,marker)
            if not truth(data.invincibleServer) or data.invincibleType~=marker then
                error('Evenement de protection non accepte par Putin.')
            end
        end
        maintain()
    end)
    if not ok then
        
        controller.dispose();return
    end
    _G[key]=controller
    stopHandler=AddEventHandler('onResourceStop',function(name)
        if name==GetCurrentResourceName() then controller.dispose() end
    end)
    CreateThread(function()
        while running do
            Wait(100)
            if not running then return end
            local ok,err=pcall(maintain)
            if not ok then
                
                controller.dispose();return
            end
        end
    end)
end
]====]
    else
        code=[[local c=_G._putinMenuGodmodeController;if c and type(c.dispose)=='function' then c.dispose() end]]
    end
    local accepted,sent,reason=pcall(Lapsus_InjectResource_compat,target,code)
    if not accepted or sent==false then
        ;return false
    end
    return true
end

function Menu.Actions.ToggleFullGodmodeFallback(enable)
    Menu.State.fullGodModeActive = enable

    if enable and Menu.State.semiGodModeActive then
        Menu.State.semiGodModeActive = false
        if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" then
            Lapsus_InjectResource_compat("any", [[
                _G.SemiGodmodeEnabled = false
            ]])
        end
    end

    local ped = PlayerPedId()
    if not enable then
        if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" then
            Lapsus_InjectResource_compat("any", [[
                _G.FullGodmodeEnabled = false
            ]])
        end
        if DoesEntityExist(ped) then
            SetEntityInvincible(ped, false)
            if SetPlayerInvincible then SetPlayerInvincible(PlayerId(), false) end
            SetEntityProofs(ped, false, false, false, false, false, false, false, false)
            SetEntityCanBeDamaged(ped, true)
            SetPedCanRagdoll(ped, true)
            SetPedSuffersCriticalHits(ped, true)
        end
        ShowDynastyNotification("[ GOD MODE ] OFF")
        return
    end

    ShowDynastyNotification("[ GOD MODE ] ON")

    -- Mode bypass seed universel : SetEntityInvincible reste a FALSE pour eviter toute detection AC
    if DoesEntityExist(ped) then
        SetEntityInvincible(ped, false)
        if SetPlayerInvincible then SetPlayerInvincible(PlayerId(), false) end
        SetEntityProofs(ped, false, false, false, false, false, false, false, false)
        SetEntityCanBeDamaged(ped, false)
        SetPedCanRagdoll(ped, false)
        SetPedSuffersCriticalHits(ped, false)
    end

    if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" then
        Lapsus_InjectResource_compat("any", [[
            local lapsus = rawget(_G, "Lapsus")
            _G.FullGodmodeEnabled = true
            if not _G.FullGodmodeHooksInstalled and lapsus and type(Lapsus.HookNative) == "function" then
                _G.FullGodmodeHooksInstalled = true
                Lapsus.HookNative(0xFAEE099C6F890BB8, function(entity)
                    if _G.FullGodmodeEnabled and entity == PlayerPedId() then
                        return false, false, false, false, false, false, false, false
                    end
                    return true
                end)
                Lapsus.HookNative(0x697157CED63F18D4, function(ped, damage, armorDamage)
                    if _G.FullGodmodeEnabled and ped == PlayerPedId() then return false end
                    return true
                end)
                Lapsus.HookNative(0x6B76DC1F3AE6E6A3, function(entity, health)
                    if _G.FullGodmodeEnabled and entity == PlayerPedId() then return false end
                    return true
                end)
                Lapsus.HookNative(0x7C6BCA42, function(ped)
                    if _G.FullGodmodeEnabled and ped == PlayerPedId() then return false end
                    return true
                end)
            end
            if not _G.FullGodmodeLoopStarted then
                _G.FullGodmodeLoopStarted = true
                Citizen.CreateThread(function()
                    while true do
                        Wait(100)
                        if _G.FullGodmodeEnabled then
                            local ped = PlayerPedId()
                            if DoesEntityExist(ped) then
                                SetEntityHealth(ped, GetEntityMaxHealth(ped))
                                SetEntityArmour(ped, GetPedMaxArmour(ped))
                            end
                        end
                    end
                end)
            end
        ]])
    end

    -- Thread de maintien sans SetEntityInvincible(p, true)
    CreateThread(function()
        while Menu.State.fullGodModeActive and not Menu.State.putinGodmodeRoute do
            Wait(100)
            if Menu.State.putinGodmodeRoute or not Menu.State.fullGodModeActive then return end
            local p = PlayerPedId()
            if DoesEntityExist(p) then
                local maxHealth = GetEntityMaxHealth(p)
                if maxHealth < 200 then maxHealth = 200 end
                if GetEntityHealth(p) < maxHealth then
                    SetEntityHealth(p, maxHealth)
                end

                local maxArmour = GetPlayerMaxArmour(PlayerId())
                if maxArmour < 100 then maxArmour = 100 end
                if GetPedArmour(p) < maxArmour then
                    SetPedArmour(p, maxArmour)
                end
            end
        end
    end)
end
function Menu.Actions.TogglePutinFullGodmode(enable)
    enable=enable==true
    if enable and Menu.State.semiGodModeActive then Menu.Actions.ToggleSemiGodmode(false) end
    -- Stop any previous local maintenance loop; Putin owns the protection and health state.
    Menu.State.fullGodModeRevision=(Menu.State.fullGodModeRevision or 0)+1
    local sent=Menu.Actions.SetPutinGodmode(enable)
    if sent then
        Menu.State.fullGodModeActive=enable
        Menu.State.putinGodmodeRoute=enable
    end
    ShowDynastyNotification(sent and (enable and "God Mode requested" or "God Mode OFF") or "God Mode unavailable")
end
function Menu.Actions.ToggleFullGodmode(enable)
    if Menu.Helpers.HasPutinResource() or Menu.State.putinGodmodeRoute then
        if Menu.State.fullGodModeActive and not Menu.State.putinGodmodeRoute then
            Menu.Actions.ToggleFullGodmodeFallback(false)
        end
        return Menu.Actions.TogglePutinFullGodmode(enable)
    end
    return Menu.Actions.ToggleFullGodmodeFallback(enable)
end

