function Menu.Actions.ToggleSemiGodmode(enable)
    if enable and Menu.State.putinGodmodeRoute then Menu.Actions.ToggleFullGodmode(false) end
    if type(Lapsus) ~= "table" or type(Lapsus_InjectResource_compat) ~= "function" then
        ShowDynastyNotification("[ ERREUR ] Lapsus indisponible")
        return
    end

    Menu.State.semiGodModeActive = enable

    if enable and Menu.State.fullGodModeActive then
        Menu.State.fullGodModeActive = false
        if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" then
            Lapsus_InjectResource_compat("any", [[
                _G.FullGodmodeEnabled = false
            ]])
        end
        local ped = PlayerPedId()
        SetEntityInvincible(ped, false)
        if SetPlayerInvincible then SetPlayerInvincible(PlayerId(), false) end
    end

    local code = string.format([[
        local lapsus = rawget(_G, "Lapsus")
        _G.SemiGodmodeEnabled = %s
        if _G.SemiGodmodeEnabled then _G.FullGodmodeEnabled = false end

        if not _G.SemiGodmodeHooksInstalled and lapsus and type(Lapsus.HookNative) == "function" then
            _G.SemiGodmodeHooksInstalled = true

            Lapsus.HookNative(0xFAEE099C6F890BB8, function(entity, b0, b1, b2, b3, b4, b5, b6, b7)
                if _G.SemiGodmodeEnabled and entity == PlayerPedId() then
                    return true, entity, b0, b1, b2, b3, b4, b5, b6, false
                end
                return true
            end)

            Lapsus.HookNative(0x697157CED63F18D4, function(ped, damage, armorDamage)
                if _G.SemiGodmodeEnabled and ped == PlayerPedId() then
                    local reducedDamage = damage * 0.1
                    local reducedArmor = armorDamage * 0.1
                    return true, ped, reducedDamage, reducedArmor
                end
                return true
            end)

            Lapsus.HookNative(0x7C6BCA42, function(ped)
                if _G.SemiGodmodeEnabled and ped == PlayerPedId() then
                    local health = GetEntityHealth(ped)
                    if health < 110 then
                        return false
                    end
                end
                return true
            end)
        end

        if not _G.SemiGodmodeLoopStarted then
            _G.SemiGodmodeLoopStarted = true
            _G.LastHealth = nil

            Citizen.CreateThread(function()
                while true do
                    Wait(200)
                    if _G.SemiGodmodeEnabled then
                        local ped = PlayerPedId()
                        if DoesEntityExist(ped) then
                            local currentHealth = GetEntityHealth(ped)
                            local maxHealth = GetEntityMaxHealth(ped)

                            if currentHealth < maxHealth then
                                local regenAmount = math.min(3, maxHealth - currentHealth)
                                SetEntityHealth(ped, currentHealth + regenAmount)
                            end

                            if math.random(1, 10) == 1 then
                                ClearPedBloodDamage(ped)
                                ResetPedVisibleDamage(ped)
                            end

                            _G.LastHealth = currentHealth
                        end
                    end
                end
            end)

            Citizen.CreateThread(function()
                while true do
                    Wait(10)
                    if _G.SemiGodmodeEnabled then
                        local ped = PlayerPedId()
                        if DoesEntityExist(ped) then
                            local currentHealth = GetEntityHealth(ped)
                            local maxHealth = GetEntityMaxHealth(ped)

                            if _G.LastHealth and currentHealth < _G.LastHealth then
                                local damageTaken = _G.LastHealth - currentHealth
                                if damageTaken > 5 then
                                    local regenAmount = math.min(30, maxHealth - currentHealth)
                                    SetEntityHealth(ped, currentHealth + regenAmount)
                                end
                            end

                            if currentHealth < (maxHealth * 0.8) then
                                local regenAmount = math.min(15, maxHealth - currentHealth)
                                SetEntityHealth(ped, currentHealth + regenAmount)
                            end

                            _G.LastHealth = currentHealth
                        end
                    end
                end
            end)
        end
    ]], tostring(enable))

    Lapsus_InjectResource_compat("any", code)

    if enable then
        local ped = PlayerPedId()
        if DoesEntityExist(ped) then
            SetEntityHealth(ped, GetEntityMaxHealth(ped))
        end
        ShowDynastyNotification("[ SEMI GOD ] ON")
    else
        ShowDynastyNotification("[ SEMI GOD ] OFF")
    end
end

