function Menu.Actions.ToggleAntiTeleportFallback(enable)
    Menu.State.antiTpActive = enable

    if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" then
        if enable then
            ShowDynastyNotification("[ ANTI-TP ] Actif")
        else
            ShowDynastyNotification("[ ANTI-TP ] Desactive")
        end

        Citizen.CreateThread(function()
            -- LAYER 1: Native Hooks (Inject into AntiTeleportHook)
            local nativeCode = string.format([[
                local lapsus = rawget(_G, "Lapsus")
                _G.AntiTeleportEnabled = %s

                if not _G.AntiTeleportHookInstalled and lapsus and type(Lapsus.HookNative) == "function" then
                    _G.AntiTeleportHookInstalled = true

                    -- Intercepte SetEntityCoords
                    Lapsus.HookNative(0x06840DA4F9E24E4D, function(entity, x, y, z, xAxis, yAxis, zAxis, clearArea)
                        if _G.AntiTeleportEnabled and entity == PlayerPedId() then
                            return false -- Blocage du TP forc
                        end
                        return true
                    end)

                    -- Intercepte SetEntityCoordsNoOffset
                    Lapsus.HookNative(0x239A3351C7284A45, function(entity, x, y, z, xAxis, yAxis, zAxis)
                        if _G.AntiTeleportEnabled and entity == PlayerPedId() then
                            return false
                        end
                        return true
                    end)
                end
            ]], tostring(enable))
            Lapsus_InjectResource_compat("AntiTeleportHook", nativeCode)

            Citizen.Wait(50)

            -- LAYER 2: Event Interception (Inject into Putin resource)
            local eventCode = string.format([[
            if _G.AntiTeleportEnabled == nil then _G.AntiTeleportEnabled = false end
            _G.AntiTeleportEnabled = %s

            if not _G.AntiTeleportEventHooksInstalled then
                _G.AntiTeleportEventHooksInstalled = true

                -- Bloque les vnements de TP classiques (Admin menus)
                AddEventHandler("admin:TeleportPlayer", function(target, coords)
                    if _G.AntiTeleportEnabled then
                        CancelEvent()
                    end
                end)

                AddEventHandler("admin:TpToPlayer", function(coords)
                    if _G.AntiTeleportEnabled then
                        CancelEvent()
                    end
                end)
            end
            ]], tostring(enable))
            Lapsus_InjectResource_compat("Putin", eventCode)
        end)
    else
        ShowDynastyNotification("[ ERREUR ] Lapsus indisponible")
    end

    -- LAYER 3: Robust Distance Detection (Local fallback)
    if enable then
        CreateThread(function()
            local lastPos = GetEntityCoords(PlayerPedId())
            while Menu.State.antiTpActive and not Menu.State.antiTpUsingPutin do
                local playerPed = PlayerPedId()
                if not playerPed or playerPed == 0 then Wait(100)
                else
                local currentPos = GetEntityCoords(playerPed)

                SetPedCanRagdoll(playerPed, false)
                SetPedConfigFlag(playerPed, 128, true)
                SetPedConfigFlag(playerPed, 401, true)

                if not Menu.State.noclipActive and not _G.Menu.State.Freecam.active then
                    local dist = #(currentPos - lastPos)
                    if dist > 50.0 and not IsPedFalling(playerPed) and not IsPedInParachuteFreeFall(playerPed) then
                        SetEntityCoordsNoOffset(playerPed, lastPos.x, lastPos.y, lastPos.z, false, false, false)
                        currentPos = lastPos
                    end
                end

                lastPos = currentPos
                Wait(0)
                end -- ped guard
            end

            local ped = PlayerPedId()
            if DoesEntityExist(ped) then
                SetPedCanRagdoll(ped, true)
                SetPedConfigFlag(ped, 128, false)
                SetPedConfigFlag(ped, 401, false)
            end
        end)
    end
end

function Menu.Helpers.SetPutinAntiTeleport(enable,suspended)
    if not L or type(L.GetResources)~="function" or type(Lapsus_InjectResource_compat)~="function" then
        ;return false
    end
    local ok,resources=pcall(L.GetResources)
    if not ok or type(resources)~="table" then ;return false end
    local target
    for _,name in ipairs(resources) do if type(name)=="string" and name:lower()=="putin" then target=name;break end end
    if not target then ;return false end
    local code=("local enabled=%s\nlocal suspended=%s\n"):format(tostring(enable==true),tostring(suspended==true)) .. [====[
do
    local key='_mirageAntiTeleportController'
    local previous=_G[key]
    if not enabled then
        if previous and type(previous.dispose)=='function' then previous.dispose() end
        return
    end
    if type(_FRL)~='table' or type(_FRL.Game)~='table' then
        ;return
    end
    if previous and previous.version==2 and previous.framework==_FRL then
        previous.suspended=suspended
        return
    end
    if previous and type(previous.dispose)=='function' then previous.dispose() end
    local controller={version=2,framework=_FRL,suspended=suspended,active=true,blocked=0}
    local restorations={}
    local function truth(v)return v==true or v==1 or v=='1' end
    local function blocks(entity)
        if not controller.active or controller.suspended then return false end
        local ped=PlayerPedId()
        if entity==ped then return true end
        if truth(IsPedInAnyVehicle(ped,false)) then
            local vehicle=GetVehiclePedIsIn(ped,false)
            if vehicle and vehicle~=0 and entity==vehicle then return true end
        end
        return false
    end
    local function wrap(container,name)
        local original=container[name]
        if type(original)~='function' then return end
        local wrapper=function(entity,...)
            if blocks(entity) then controller.blocked=controller.blocked+1;return end
            return original(entity,...)
        end
        restorations[#restorations+1]={container=container,name=name,original=original,wrapper=wrapper}
        container[name]=wrapper
    end
    -- Intercept before Putin's collision/loading routine, plus its coordinate entry points.
    wrap(_FRL.Game,'Teleport')
    for _,name in ipairs({'SetEntityCoords','SetEntityCoordsNoOffset','SetEntityCoordsWithoutPlantsReset','SetPedCoordsKeepVehicle','SetPedCoordsNoGang'}) do
        wrap(_G,name)
    end
    function controller.dispose()
        controller.active=false
        for _,entry in ipairs(restorations) do
            if entry.container[entry.name]==entry.wrapper then entry.container[entry.name]=entry.original end
        end
        if _G[key]==controller then _G[key]=nil end
    end
    if #restorations==0 then ;return end
    _G[key]=controller
end
]====]
    local accepted,sent,err=pcall(Lapsus_InjectResource_compat,target,code)
    if not accepted or sent==false then
        ;return false
    end
    Menu.State.antiTpResourceSuspended=suspended==true
    return true
end

function Menu.Helpers.AntiTeleportBool(value)
    return value==true or value==1 or value=="1"
end

function Menu.Helpers.AntiTeleportSuspended()
    return Menu.State.noclipActive==true or _G.freecam_active==true
        or (Menu.State.Freecam and Menu.State.Freecam.active==true)
end

function Menu.Helpers.ShouldBlockTeleport(entity)
    if not Menu.State.antiTpActive or Menu.State.antiTpCorrecting or Menu.Helpers.AntiTeleportSuspended() then return false end
    local ped=PlayerPedId()
    if not ped or ped==0 or not DoesEntityExist(ped) then return false end
    if entity==ped then return true end
    if Menu.Helpers.AntiTeleportBool(IsPedInAnyVehicle(ped,false)) then
        local vehicle=GetVehiclePedIsIn(ped,false)
        return vehicle and vehicle~=0 and entity==vehicle
    end
    return false
end

function Menu.Helpers.UpdateAntiTeleport()
    if not Menu.State.antiTpActive then Menu.State.antiTpAnchor=nil;return end
    local suspended=Menu.Helpers.AntiTeleportSuspended() and true or false
    if suspended~=Menu.State.antiTpResourceSuspended then Menu.Helpers.SetPutinAntiTeleport(true,suspended) end
    local ped=PlayerPedId()
    if not ped or ped==0 or not Menu.Helpers.AntiTeleportBool(DoesEntityExist(ped)) then Menu.State.antiTpAnchor=nil;return end
    local vehicle=Menu.Helpers.AntiTeleportBool(IsPedInAnyVehicle(ped,false)) and GetVehiclePedIsIn(ped,false) or 0
    local entity=vehicle and vehicle~=0 and vehicle or ped
    local position=GetEntityCoords(entity)
    local now=GetGameTimer()
    local anchor=Menu.State.antiTpAnchor
    local function remember()
        Menu.State.antiTpAnchor={ped=ped,entity=entity,x=position.x,y=position.y,z=position.z,time=now,speed=tonumber(GetEntitySpeed(entity)) or 0}
    end
    if suspended or Menu.Helpers.AntiTeleportBool(IsEntityDead(ped)) or not anchor or anchor.ped~=ped or anchor.entity~=entity then remember();return end
    local dt=math.max(0.001,math.min(0.25,(now-anchor.time)/1000.0))
    local dx,dy,dz=position.x-anchor.x,position.y-anchor.y,position.z-anchor.z
    -- Use the previous speed: a forced displacement must not enlarge its own allowance.
    local threshold=math.max(10.0,(anchor.speed or 0)*dt*2.0+5.0)
    if dx*dx+dy*dy+dz*dz>threshold*threshold then
        Menu.State.antiTpCorrecting=true
        local ok,err=pcall(SetEntityCoordsNoOffset,entity,anchor.x,anchor.y,anchor.z,false,false,false)
        Menu.State.antiTpCorrecting=false
        if not ok then error(err) end
        local actual=GetEntityCoords(entity)
        local rx,ry,rz=actual.x-anchor.x,actual.y-anchor.y,actual.z-anchor.z
        if rx*rx+ry*ry+rz*rz>4.0 and not Menu.State.antiTpReturnErrorReported then
            Menu.State.antiTpReturnErrorReported=true
            
        end
        anchor.time=now
    else remember() end
end

function Menu.Actions.TogglePutinAntiTeleport(enable)
    enable=enable==true
    if not enable then
        Menu.State.antiTpActive=false
        Menu.State.antiTpAnchor=nil
        Menu.State.antiTpCorrecting=false
        Menu.Helpers.SetPutinAntiTeleport(false,false)
        if L and type(L.RemoveBlockedEvent)=="function" then
            local ok,removed,err=pcall(L.RemoveBlockedEvent,"gamemode:teleport","incoming")
            if not ok or removed==false then  end
        end
        ShowDynastyNotification("[ ANTI-TP ] OFF")
        return true
    end
    if not L or type(L.HookNative)~="function" then
        Menu.State.antiTpActive=false
        ShowDynastyNotification("Anti-Teleport API unavailable")
        
        return false
    end
    if not Menu.State.antiTpHooksInstalled then
        local hashes={0x06843DA7060A026B,0x239A3351AC1DA385,0x621873ECE1178967,0x9AFEFF481A85AB2E,0x87052FE446E07247}
        for _,hash in ipairs(hashes) do
            local ok,registered,err=pcall(L.HookNative,hash,function(entity)
                if Menu.Helpers.ShouldBlockTeleport(entity) then return false end
                return true
            end)
            if not ok or registered~=true then
                Menu.State.antiTpActive=false
                
                ShowDynastyNotification("Anti-Teleport unavailable")
                return false
            end
        end
        Menu.State.antiTpHooksInstalled=true
    end
    -- Putin actually receives gamemode:teleport, rather than the old guessed admin events.
    if type(L.AddBlockedEvent)=="function" then
        local ok,added,err=pcall(L.AddBlockedEvent,"gamemode:teleport","incoming")
        if not ok or added~=true then  end
    end
    local suspended=Menu.Helpers.AntiTeleportSuspended() and true or false
    if not Menu.Helpers.SetPutinAntiTeleport(true,suspended) then
        Menu.State.antiTpActive=false
        ShowDynastyNotification("Anti-Teleport unavailable")
        return false
    end
    Menu.State.antiTpActive=true
    Menu.State.antiTpAnchor=nil
    Menu.State.antiTpErrorReported=false
    Menu.State.antiTpReturnErrorReported=false
    Menu.Helpers.UpdateAntiTeleport()
    ShowDynastyNotification("[ ANTI-TP ] ON")
    return true
end

function Menu.Actions.ToggleAntiTeleport(enable)
    if Menu.Helpers.HasPutinResource() or Menu.State.antiTpUsingPutin then
        if enable and Menu.State.antiTpActive and not Menu.State.antiTpUsingPutin then
            Menu.Actions.ToggleAntiTeleportFallback(false)
        end
        local accepted=Menu.Actions.TogglePutinAntiTeleport(enable)
        if accepted then Menu.State.antiTpUsingPutin=enable==true end
        return accepted
    end
    return Menu.Actions.ToggleAntiTeleportFallback(enable)
end
CreateThread(function()
    while true do
        if Menu.State.antiTpUsingPutin and Menu.State.antiTpActive then
            pcall(Menu.Helpers.UpdateAntiTeleport)
            Wait(0)
        else Wait(100) end
    end
end)

