function Menu.Actions.ResetPed()
    local myPed   = PlayerPedId()
    local isFemale = GetEntityModel(myPed) == GetHashKey("mp_f_freemode_01")
    local baseModel = isFemale and "mp_f_freemode_01" or "mp_m_freemode_01"
    local modelHash = GetHashKey(baseModel)
    RequestModel(modelHash)
    local timeout = 0
    while not HasModelLoaded(modelHash) and timeout < 60 do
        Wait(50); timeout = timeout + 1
    end
    if not HasModelLoaded(modelHash) then
        ShowDynastyNotification("[ PED ] Impossible de charger le modele de base")
        return
    end
    SetPlayerModel(PlayerId(), modelHash)
    Wait(100)
    SetModelAsNoLongerNeeded(modelHash)
    myPed = PlayerPedId()
    SetPedDefaultComponentVariation(myPed)
    ShowDynastyNotification("[ PED ] Modele reinitialise !")
end

