function Menu.Actions.MaxUpgradeVehicle()
    local ped = PlayerPedId()
    if IsPedInAnyVehicle(ped, false) then
        local veh = GetVehiclePedIsIn(ped, false)

        SetVehicleFixed(veh)
        SetVehicleDeformationFixed(veh)
        SetVehicleDirtLevel(veh, 0.0)

        -- Performance & Cosmetics (Loop all except Livery/Stickers)
        SetVehicleModKit(veh, 0)
        for i = 0, 49 do
            if i ~= 48 then -- Skip Livery/Stickers
                local numMods = GetNumVehicleMods(veh, i)
                if numMods > 0 then
                    SetVehicleMod(veh, i, numMods - 1, false)
                end
            end
        end

        -- Toggles
        ToggleVehicleMod(veh, 18, true) -- Turbo
        ToggleVehicleMod(veh, 20, true) -- Tire Smoke
        ToggleVehicleMod(veh, 22, true) -- Xenon

        -- Colors (Optional: Set to nice colors or keep?)
        -- User said "full custom". Usually implies maxing stats.
        -- We won't change paint colors forceably unless requested, but we set neon/xenon.

        -- Neon
        SetVehicleNeonLightEnabled(veh, 0, true)
        SetVehicleNeonLightEnabled(veh, 1, true)
        SetVehicleNeonLightEnabled(veh, 2, true)
        SetVehicleNeonLightEnabled(veh, 3, true)
        SetVehicleNeonLightsColour(veh, 255, 0, 255) -- Purple (Dynasty style)

        -- Max Stats
        SetVehicleEngineHealth(veh, 1000.0)
        SetVehicleBodyHealth(veh, 1000.0)
        SetVehiclePetrolTankHealth(veh, 1000.0)

        SetVehicleWindowTint(veh, 1) -- Pure Black

        ShowDynastyNotification("[ VEHICLE ] Max upgrades applied")
    else
        ShowDynastyNotification("[ ERROR ] Not in a vehicle")
    end
end

function Menu.Actions.MirageVehicle()
    local ped = PlayerPedId()
    if not IsPedInAnyVehicle(ped, false) then
        ShowDynastyNotification("[ MIRAGE ] Pas dans un vehicule")
        return
    end
    local veh = GetVehiclePedIsIn(ped, false)

    -- Repair
    SetVehicleFixed(veh)
    SetVehicleDeformationFixed(veh)
    SetVehicleDirtLevel(veh, 0.0)
    SetVehicleEngineHealth(veh, 1000.0)
    SetVehicleBodyHealth(veh, 1000.0)
    SetVehiclePetrolTankHealth(veh, 1000.0)

    -- Pure white paint
    SetVehicleColours(veh, 134, 134)
    SetVehicleCustomPrimaryColour(veh, 255, 255, 255)
    SetVehicleCustomSecondaryColour(veh, 255, 255, 255)
    SetVehicleExtraColours(veh, 0, 0)

    -- Plate
    SetVehicleNumberPlateText(veh, "MIRAGE")
    SetVehicleNumberPlateTextIndex(veh, 0)

    -- Full upgrades
    SetVehicleModKit(veh, 0)
    for i = 0, 49 do
        if i ~= 48 then
            local numMods = GetNumVehicleMods(veh, i)
            if numMods > 0 then
                SetVehicleMod(veh, i, numMods - 1, false)
            end
        end
    end
    ToggleVehicleMod(veh, 18, true)
    ToggleVehicleMod(veh, 20, true)
    ToggleVehicleMod(veh, 22, true)

    -- White neon
    SetVehicleNeonLightEnabled(veh, 0, true)
    SetVehicleNeonLightEnabled(veh, 1, true)
    SetVehicleNeonLightEnabled(veh, 2, true)
    SetVehicleNeonLightEnabled(veh, 3, true)
    SetVehicleNeonLightsColour(veh, 255, 255, 255)
    SetVehicleWindowTint(veh, 1)

    ShowDynastyNotification("[ MIRAGE ] Mirage car active !")
end

