function Menu.Actions.BreakAllNearbyWheels()
    local playerPed = PlayerPedId()
    local playerVeh = GetVehiclePedIsIn(playerPed, false)
    local coords = GetEntityCoords(playerPed)
    local vehicles = GetGamePool('CVehicle')
    local count = 0

    for _, vehicle in ipairs(vehicles) do
        if vehicle == playerVeh then goto continue_bw end
        if not DoesEntityExist(vehicle) then goto continue_bw end

        local vehicleCoords = GetEntityCoords(vehicle)
        if #(coords - vehicleCoords) <= 150.0 then
            -- Pre-check control
            if NetworkGetEntityIsNetworked(vehicle) and not NetworkHasControlOfEntity(vehicle) then
                NetworkRequestControlOfEntity(vehicle)
            end

            if NetworkHasControlOfEntity(vehicle) or not NetworkGetEntityIsNetworked(vehicle) then
                SetVehicleWheelsCanBreak(vehicle, true)
                local numWheels = GetVehicleNumberOfWheels(vehicle)
                for i = 0, numWheels - 1 do
                    -- Burst first (more reliable for sync) then Break Off
                    SetVehicleTyreBurst(vehicle, i, true, 1000.0)
                    BreakOffVehicleWheel(vehicle, i, true, true, true, false)
                end
                -- Restaurer la collision pour Ã©viter que le vÃ©hicule passe sous la map
                SetEntityCollision(vehicle, true, true)
                SetVehicleOnGroundProperly(vehicle)
                count = count + 1
            end
        end

        ::continue_bw::
    end

    if count > 0 then
        ShowDynastyNotification("[ BROKE ] " .. count .. " vehicle(s) damaged")
    else
        ShowDynastyNotification("[ ERROR ] No vehicle in range")
    end
end

Menu.State.fovWarpActive = false

function Menu.Actions.ToggleFOVWarp()
    Menu.State.fovWarpActive = not Menu.State.fovWarpActive

    if Menu.State.fovWarpActive then
        ShowDynastyNotification("[ FOV WARP ] Active  -  [X] to warp")

        CreateThread(function()
            -- Optimize: Load textures once outside the loop
            if not HasStreamedTextureDictLoaded("commonmenu") then
                RequestStreamedTextureDict("commonmenu", true)
            end
            if not HasStreamedTextureDictLoaded("mp_inventory") then
                RequestStreamedTextureDict("mp_inventory", true)
            end

            while Menu.State.fovWarpActive do
                Wait(0)

                local aspect = GetAspectRatio(false)
                local scale = 0.42

                if HasStreamedTextureDictLoaded("mp_inventory") then
                    -- Draw the ring (contour only)
                    -- Black, semi-transparent (120 alpha)
                    DrawSprite("mp_inventory", "tab_selector", 0.5, 0.5, scale / aspect, scale, 0.0, 0, 0, 0, 120)
                end

                if IsControlJustPressed(0, 73) then -- X key (INPUT_VEH_DUCK)
                    local playerPed = PlayerPedId()
                    local camCoords = GetGameplayCamCoord()

                    if not HasStreamedTextureDictLoaded("commonmenu") then
                        RequestStreamedTextureDict("commonmenu", true)
                    end

                    -- Find closest vehicle/entity within FOV circle
                    local screenW, screenH = GetActiveScreenResolution()
                    local centerX, centerY = 0.5, 0.5
                    local aspect = GetAspectRatio(false)
                    local scale = 0.45 -- Circle Scale

                    local vehicles = (type(GetGamePool) == "function" and GetGamePool("CVehicle")) or {}
                    local bestTarget = nil
                    local minDistanceToCenter = scale / 2.0
                    local maxWarpDistance = 500.0 -- FOV Warp Distance: 500m

                    if type(vehicles) == "table" then
                        for _, veh in ipairs(vehicles) do
                            if DoesEntityExist(veh) then
                                local vCoords = GetEntityCoords(veh)
                                local distToVeh = #(vCoords - camCoords)

                                if distToVeh < maxWarpDistance then
                                    local onScreen, screenX, screenY = GetScreenCoordFromWorldCoord(vCoords.x, vCoords.y, vCoords.z)

                                    if onScreen then
                                        local dx = (screenX - centerX) * aspect
                                        local dy = screenY - centerY
                                        local dist = math.sqrt(dx*dx + dy*dy)

                                        if dist < minDistanceToCenter then
                                            minDistanceToCenter = dist
                                            bestTarget = veh
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bestTarget then
                         -- Use the shared robust hijack logic
                        Menu.Helpers.HijackVehicleLegacy(bestTarget, playerPed)
                        ShowDynastyNotification("[ FOV WARP ] Vehicle grabbed!")
                    end
                end
            end
        end)
    else
        ShowDynastyNotification("[ FOV WARP ] Disabled")
    end
end

function Menu.Helpers.HijackVehicleLegacy(targetVehicle, playerPed)
    if not DoesEntityExist(targetVehicle) then return false end

    -- Force ownership/mission status for sync
    SetEntityAsMissionEntity(targetVehicle, true, true)
    if NetworkGetEntityIsNetworked(targetVehicle) then
        local netId = NetworkGetNetworkIdFromEntity(targetVehicle)
        if netId and netId ~= 0 then
            SetNetworkIdCanMigrate(netId, true)
            SetNetworkIdExistsOnAllMachines(netId, true)
        end
    end

    -- Internal helper function for control (timeout Ã©tendu pour vÃ©hicules avec conducteur joueur)
    local function RequestControl(entity, timeoutMs)
        if not entity or not DoesEntityExist(entity) then return false end
        if NetworkHasControlOfEntity(entity) then return true end
        local start = GetGameTimer()
        NetworkRequestControlOfEntity(entity)
        while not NetworkHasControlOfEntity(entity) do
            Wait(10)
            if not DoesEntityExist(entity) then return false end
            NetworkRequestControlOfEntity(entity)
            if GetGameTimer() - start > (timeoutMs or 1500) then return false end
        end
        return true
    end

    local function tryEnter(v, s)
        SetPedIntoVehicle(playerPed, v, s)
        Wait(50)
        local inVeh = IsPedInVehicle(playerPed, v, false)
        local curSeat = -2
        if inVeh then
            for seat = -1, 4 do
                if GetPedInVehicleSeat(v, seat) == playerPed then
                    curSeat = seat
                    break
                end
            end
        end
        return inVeh, curSeat
    end

    -- Teleportation
    local vehCoords = GetEntityCoords(targetVehicle)
    SetEntityCoords(playerPed, vehCoords.x, vehCoords.y, vehCoords.z - 0.5, false, false, false, false)
    Wait(10)

    -- HIJACK LOGIC
    RequestControl(targetVehicle, 1500)
    SetVehicleDoorsLocked(targetVehicle, 1)
    SetVehicleDoorsLockedForAllPlayers(targetVehicle, false)

    local success = false
    local tStart = GetGameTimer()

    while (GetGameTimer() - tStart) < 2000 do
        RequestControl(targetVehicle, 800)

        local inVeh, seat = tryEnter(targetVehicle, -1)
        if not inVeh then
            for s = 0, 4 do
                if IsVehicleSeatFree(targetVehicle, s) then
                    inVeh, seat = tryEnter(targetVehicle, s)
                    if inVeh then break end
                end
            end
        end

        if inVeh then
            local drv = GetPedInVehicleSeat(targetVehicle, -1)
            if drv ~= 0 and drv ~= playerPed and DoesEntityExist(drv) then
                if IsPedAPlayer(drv) then
                    -- Conducteur joueur : Ã©jection forcÃ©e sans suppression
                    TaskLeaveVehicle(drv, targetVehicle, 4160)
                    ClearPedTasksImmediately(drv)
                else
                    -- NPC : suppression directe
                    if NetworkGetEntityIsNetworked(drv) then RequestControl(drv, 800) end
                    SetEntityAsMissionEntity(drv, true, true)
                    ClearPedTasksImmediately(drv)
                    SetEntityCoords(drv, 0.0, 0.0, -100.0, false, false, false, false)
                    DeleteEntity(drv)
                end
            end

            if seat ~= -1 then
                SetPedIntoVehicle(playerPed, targetVehicle, -1)
                Wait(50)
                if GetPedInVehicleSeat(targetVehicle, -1) == playerPed then
                    success = true
                    break
                end
            else
                success = true
                break
            end
        else
            local drv = GetPedInVehicleSeat(targetVehicle, -1)
            if drv ~= 0 and drv ~= playerPed and DoesEntityExist(drv) then
                if IsPedAPlayer(drv) then
                    -- Joueur conducteur : Ã©jection forcÃ©e
                    TaskLeaveVehicle(drv, targetVehicle, 4160)
                    ClearPedTasksImmediately(drv)
                else
                    -- NPC : suppression directe
                    RequestControl(drv, 800)
                    DeleteEntity(drv)
                end
            end
        end
        Wait(10)
    end

    return success or IsPedInVehicle(playerPed, targetVehicle, false)
end

function Menu.Helpers.BrokeVehicleDirect(veh)
    if not DoesEntityExist(veh) then return false end
    NetworkRequestControlOfEntity(veh)
    local t = GetGameTimer()
    while not NetworkHasControlOfEntity(veh) and GetGameTimer() - t < 2000 do
        NetworkRequestControlOfEntity(veh)
        Wait(100)
    end
    if not NetworkHasControlOfEntity(veh) then return false end
    SetVehicleWheelsCanBreak(veh, true)
    SetVehicleHasBeenOwnedByPlayer(veh, true)
    SetEntityAsMissionEntity(veh, true, true)
    local n = GetVehicleNumberOfWheels(veh)
    for i = 0, n - 1 do
        SetVehicleWheelHealth(veh, i, 0.0)
        BreakOffVehicleWheel(veh, i, true, true, true, false)
    end
    -- Restaurer la collision pour Ã©viter que le vÃ©hicule passe sous la map
    SetEntityCollision(veh, true, true)
    SetVehicleOnGroundProperly(veh)
    return true
end

-- ── CRASH ───────────────────────────────────────────────────────────────────
-- Priorité 1 : le véhicule dans lequel le joueur local est déjà assis.
-- Priorité 2 : le véhicule le plus proche (100 m).
-- Prise de contrôle réseau via pipeline NPC complet (identique WithNPCNetworkControl) :
--   le joueur s'assoit au volant pour forcer la migration réseau, éjecte l'occupant,
--   un NPC driver autonome est spawné, puis le joueur retourne à sa position initiale.
-- Le véhicule cible + tous ses occupants deviennent invisibles ; le joueur local reste visible.
_G.CrashThread = nil

function Menu.Actions.ToggleCrash()
    if not _G.AuthDone then return end

    Menu.State.crashActive = not Menu.State.crashActive

    if not Menu.State.crashActive then
        _G.CrashThread = nil
        ShowDynastyNotification("[ CRASH ] Désactivé")
        return
    end

    ShowDynastyNotification("[ CRASH ] Recherche du véhicule...")

    CreateThread(function()
        pcall(function()
            local myPed          = PlayerPedId()
            local myCoords       = GetEntityCoords(myPed)
            local initialCoords  = myCoords
            local initialHeading = GetEntityHeading(myPed)

            local veh = nil
            if IsPedInAnyVehicle(myPed, false) then
                veh = GetVehiclePedIsIn(myPed, false)
                if not veh or veh == 0 or not DoesEntityExist(veh) then veh = nil end
            end

            if not veh then
                veh = GetClosestVehicle(myCoords.x, myCoords.y, myCoords.z, 100.0, 0, 70)
                if not veh or veh == 0 or not DoesEntityExist(veh) then
                    ShowDynastyNotification("[ CRASH ] Aucun véhicule à portée (100m)")
                    Menu.State.crashActive = false
                    return
                end
            end

            local driverSeat = GetPedInVehicleSeat(veh, -1)
            if driverSeat ~= myPed then
                ShowDynastyNotification("[ CRASH ] Tu dois etre conducteur du vehicule")
                Menu.State.crashActive = false
                return
            end

            local function RequestControl(entity, ms)
                if not DoesEntityExist(entity) then return false end
                if NetworkHasControlOfEntity(entity) then return true end
                local t = GetGameTimer()
                repeat
                    NetworkRequestControlOfEntity(entity)
                    Wait(10)
                    if not DoesEntityExist(entity) then return false end
                until NetworkHasControlOfEntity(entity) or (GetGameTimer() - t) > (ms or 600)
                return NetworkHasControlOfEntity(entity)
            end

            local hasControl = NetworkHasControlOfEntity(veh)
            if not hasControl then
                local tCheck = GetGameTimer()
                while not hasControl and (GetGameTimer() - tCheck) < 1000 do
                    NetworkRequestControlOfEntity(veh)
                    Wait(50)
                    hasControl = NetworkHasControlOfEntity(veh)
                end
            end

            ShowDynastyNotification("[ CRASH ] Contrôle obtenu — invisibilité active")

            local threadKey = {}
            _G.CrashThread = threadKey

            CreateThread(function()
                while Menu.State.crashActive and _G.CrashThread == threadKey do
                    Wait(300)
                    if not DoesEntityExist(veh) then break end

                    pcall(function() SetEntityVisible(veh, false, false) end)
                    pcall(function() SetEntityAlpha(veh, 0, false) end)

                    local myPedNow = PlayerPedId()
                    local ns = GetVehicleModelNumberOfSeats(GetEntityModel(veh))
                    if ns and ns > 0 then
                        for seat = -1, (ns - 2) do
                            local occ = GetPedInVehicleSeat(veh, seat)
                            if occ ~= 0 and DoesEntityExist(occ) and occ ~= myPedNow then
                                pcall(function() SetEntityVisible(occ, false, false) end)
                                pcall(function() SetEntityAlpha(occ, 0, false) end)
                            end
                        end
                    end

                    pcall(function() SetEntityVisible(myPedNow, true, false) end)
                    pcall(function() ResetEntityAlpha(myPedNow) end)
                    pcall(function() FreezeEntityPosition(myPedNow, false) end)
                end

                if DoesEntityExist(veh) then
                    pcall(function() SetEntityVisible(veh, true, false) end)
                    pcall(function() ResetEntityAlpha(veh) end)
                    local ns2 = GetVehicleModelNumberOfSeats(GetEntityModel(veh))
                    if ns2 and ns2 > 0 then
                        for seat = -1, (ns2 - 2) do
                            local occ = GetPedInVehicleSeat(veh, seat)
                            if occ ~= 0 and DoesEntityExist(occ) then
                                pcall(function() SetEntityVisible(occ, true, false) end)
                                pcall(function() ResetEntityAlpha(occ) end)
                            end
                        end
                    end
                end

                local pedFinal = PlayerPedId()
                pcall(function() SetEntityVisible(pedFinal, true, false) end)
                pcall(function() ResetEntityAlpha(pedFinal) end)
                pcall(function() FreezeEntityPosition(pedFinal, false) end)
                ShowDynastyNotification("[ CRASH ] Desactive")
            end)
        end)
    end)
end
-- ── WARP VEHICULE (Camera Normale) ─────────────────────
-- Raycast depuis la camera normale (gameplay cam), pas la freecam.
-- Meme pipeline que le Warp freecam : NPC prend le siege, joueur warp, NPC supprime.
-- Si bypassSeedActive : le joueur ne devient JAMAIS invisible, meme 1 ms.
function Menu.Actions.WarpVehiculeNormalCam()
    if not _G.AuthDone then return end

    CreateThread(function()
        local playerPed = PlayerPedId()
        local camPos    = GetGameplayCamCoord()
        local camRot    = GetGameplayCamRot(2)

        -- Direction depuis la camera normale
        local pitch = math.rad(camRot.x)
        local yaw   = math.rad(camRot.z)
        local dirX  = -math.sin(yaw) * math.cos(pitch)
        local dirY  =  math.cos(yaw) * math.cos(pitch)
        local dirZ  =  math.sin(pitch)
        local endX  = camPos.x + dirX * 10000.0
        local endY  = camPos.y + dirY * 10000.0
        local endZ  = camPos.z + dirZ * 10000.0

        local ray = StartExpensiveSynchronousShapeTestLosProbe(
            camPos.x, camPos.y, camPos.z,
            endX, endY, endZ,
            -1, playerPed, 7
        )
        local _, hit, _, _, entityHit = GetShapeTestResult(ray)

        local targetVehicle = nil
        if hit and entityHit and entityHit ~= 0 and DoesEntityExist(entityHit) then
            if GetEntityType(entityHit) == 2 then
                targetVehicle = entityHit
            elseif GetEntityType(entityHit) == 1 then
                local v = GetVehiclePedIsIn(entityHit, false)
                if v and v ~= 0 and DoesEntityExist(v) then targetVehicle = v end
            end
        end

        if not targetVehicle then
            ShowDynastyNotification("[ WARP VEH ] Aucun vehicule vise")
            return
        end

        ShowDynastyNotification("[ WARP VEH ] Prise de controle en cours...")

        WithNPCNetworkControl(targetVehicle, function(v)
            -- Supprimer le NPC conducteur spawne par le pipeline
            local npcDrv = GetPedInVehicleSeat(v, -1)
            if npcDrv and npcDrv ~= 0 and DoesEntityExist(npcDrv) and not IsPedAPlayer(npcDrv) then
                ClearPedTasksImmediately(npcDrv)
                SetEntityAsMissionEntity(npcDrv, true, true)
                SetEntityCoords(npcDrv, 0.0, 0.0, -100.0, false, false, false, false)
                Wait(20)
                DeleteEntity(npcDrv)
                local tw = GetGameTimer()
                while (GetGameTimer() - tw) < 400 do
                    local occ = GetPedInVehicleSeat(v, -1)
                    if occ == 0 or not DoesEntityExist(occ) then break end
                    Wait(0)
                end
            end

            -- Warp : invisible seulement si bypass seed inactif
            SetEntityVisible(playerPed, true, false)
            ResetEntityAlpha(playerPed)
            SetVehicleDoorsLocked(v, 1)
            SetVehicleDoorsLockedForAllPlayers(v, false)
            SetPedIntoVehicle(playerPed, v, -1)
            Wait(100)

            -- Restaurer visibilite
            SetEntityVisible(playerPed, true, false)
            ResetEntityAlpha(playerPed)
            FreezeEntityPosition(playerPed, false)
            SetEntityAsMissionEntity(v, true, true)

            ShowDynastyNotification("[ WARP VEH ] Tu es au volant !")
        end)
    end)
end
-- ── FIN WARP VEHICULE ─────────────────────────

-- ── BUG VEHICULE V1 (Propulsion et glitch chaotique dans tous les sens) ─────────────────────────
function Menu.Helpers._BugV1Core(targetVehicle)
    if not targetVehicle or targetVehicle == 0 or not DoesEntityExist(targetVehicle) then
        ShowDynastyNotification("[ BUG VEH ] Aucun vehicule valide")
        return
    end

    ShowDynastyNotification("[ BUG VEH ] Bug V1 applique !")

    CreateThread(function()
        local targetCoords = GetEntityCoords(targetVehicle)

        SetEntityAsMissionEntity(targetVehicle, true, true)
        if not NetworkGetEntityIsNetworked(targetVehicle) then
            NetworkRegisterEntityAsNetworked(targetVehicle)
        end
        NetworkRequestControlOfEntity(targetVehicle)

        local netId = NetworkGetEntityIsNetworked(targetVehicle) and NetworkGetNetworkIdFromEntity(targetVehicle) or nil

        -- 1. Injection Lapsus si active
        if type(Lapsus) == "table" and type(Lapsus_InjectResource_compat) == "function" and netId then
            local code = string.format([[
                CreateThread(function()
                    local veh = NetworkGetEntityFromNetworkId(%d)
                    if not veh or not DoesEntityExist(veh) then return end
                    SetEntityAsMissionEntity(veh, true, true)
                    NetworkRequestControlOfEntity(veh)
                    local tc = GetEntityCoords(veh)
                    local m = GetHashKey("faggio")
                    RequestModel(m)
                    local t0 = GetGameTimer()
                    while not HasModelLoaded(m) and (GetGameTimer() - t0) < 500 do Wait(10) end
                    local ram = CreateVehicle(m, tc.x, tc.y, tc.z + 1.0, 0.0, true, false)
                    SetModelAsNoLongerNeeded(m)
                    if ram and DoesEntityExist(ram) then
                        SetEntityVisible(ram, false, false)
                        SetEntityAlpha(ram, 0, false)
                        for i = 1, 35 do
                            if not DoesEntityExist(ram) or not DoesEntityExist(veh) then break end
                            DetachEntity(ram, true, true)
                            Wait(5)
                            AttachEntityToEntityPhysically(ram, veh, 0, 0, 0, 2000.0, 1460.0, 1000.0, 10.0, 88.0, 600.0, true, true, true, false, 0)
                            ApplyForceToEntity(veh, 1, (math.random() - 0.5) * 500.0, (math.random() - 0.5) * 500.0, math.random(100.0, 400.0), 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                            SetEntityVelocity(veh, (math.random() - 0.5) * 80.0, (math.random() - 0.5) * 80.0, math.random(30.0, 80.0))
                            SetEntityAngularVelocity(veh, (math.random() - 0.5) * 40.0, (math.random() - 0.5) * 40.0, (math.random() - 0.5) * 40.0)
                            Wait(5)
                        end
                        Wait(50)
                        if DoesEntityExist(ram) then
                            DetachEntity(ram, true, true)
                            DeleteEntity(ram)
                        end
                    end
                end)
            ]], netId)
            pcall(Lapsus_InjectResource_compat, "any", code)
        end

        -- 2. Execution client locale directe sur le vehicule cible uniquement
        local m = GetHashKey("faggio")
        RequestModel(m)
        local t0 = GetGameTimer()
        while not HasModelLoaded(m) and (GetGameTimer() - t0) < 1500 do Wait(10) end
        local ramVeh = nil
        if HasModelLoaded(m) then
            ramVeh = CreateVehicle(m, targetCoords.x, targetCoords.y, targetCoords.z + 1.0, 0.0, true, false)
            SetModelAsNoLongerNeeded(m)
        end

        if ramVeh and DoesEntityExist(ramVeh) then
            SetEntityVisible(ramVeh, false, false)
            SetEntityAlpha(ramVeh, 0, false)
            SetEntityAsMissionEntity(ramVeh, true, true)

            for i = 1, 35 do
                if not DoesEntityExist(ramVeh) or not DoesEntityExist(targetVehicle) then break end
                DetachEntity(ramVeh, true, true)
                Wait(5)
                AttachEntityToEntityPhysically(ramVeh, targetVehicle, 0, 0, 0, 2000.0, 1460.0, 1000.0, 10.0, 88.0, 600.0, true, true, true, false, 0)
                ApplyForceToEntity(targetVehicle, 1, (math.random() - 0.5) * 500.0, (math.random() - 0.5) * 500.0, math.random(100.0, 400.0), 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                SetEntityVelocity(targetVehicle, (math.random() - 0.5) * 80.0, (math.random() - 0.5) * 80.0, math.random(30.0, 80.0))
                SetEntityAngularVelocity(targetVehicle, (math.random() - 0.5) * 40.0, (math.random() - 0.5) * 40.0, (math.random() - 0.5) * 40.0)
                Wait(5)
            end

            Wait(50)
            if DoesEntityExist(ramVeh) then
                DetachEntity(ramVeh, true, true)
                DeleteEntity(ramVeh)
            end
        else
            -- Si impossible de spawn le bélier, appliquer les forces et impulsions directement sur targetVehicle
            for i = 1, 35 do
                if not DoesEntityExist(targetVehicle) then break end
                ApplyForceToEntity(targetVehicle, 1, (math.random() - 0.5) * 800.0, (math.random() - 0.5) * 800.0, math.random(150.0, 500.0), 0.0, 0.0, 0.0, 0, false, true, true, false, true)
                SetEntityVelocity(targetVehicle, (math.random() - 0.5) * 100.0, (math.random() - 0.5) * 100.0, math.random(40.0, 90.0))
                SetEntityAngularVelocity(targetVehicle, (math.random() - 0.5) * 50.0, (math.random() - 0.5) * 50.0, (math.random() - 0.5) * 50.0)
                Wait(15)
            end
        end
    end)
end

