        Wait(100)

        for i = 1, 30 do
            DetachEntity(closestVeh, true, true)
            Wait(5)
            AttachEntityToEntityPhysically(closestVeh, targetVehicle, 0, 0, 0, 2000.0, 1460.0, 1000.0, 10.0, 88.0, 600.0, true, true, true, false, 0)
            Wait(5)
        end
    end)
end

-- Bug Vehicle : prise de controle reseau garantie, puis application du bug
function Menu.Helpers.BugWithHijack(veh, core)
    if not veh or veh == 0 or not DoesEntityExist(veh) then
        ShowDynastyNotification("[ BUG VEH ] Aucun vehicule valide")
        return
    end
    local now = GetGameTimer()
    if _G._hijackBusy and (now - (_G._hijackBusyAt or 0)) >= 2500 then
        _G._hijackBusy     = false
        _G._hijackVisWatch = false
        pcall(ClearFocus); pcall(NewLoadSceneStop)
    end
    ShowDynastyNotification("[ BUG VEH ] Application du bug...")
    CreateThread(function()
        if not Menu.Helpers.HijackTrollVehicle(veh) then return end
        SetEntityAsMissionEntity(veh, true, true)
        pcall(core, veh)
    end)
end

function Menu.Actions.BugVehicleV1(targetVehicle)
    Menu.Helpers.BugWithHijack(targetVehicle, Menu.Helpers._BugV1Core)
end

function Menu.Actions.BugVehicleV2(targetVehicle)
    Menu.Helpers.BugWithHijack(targetVehicle, Menu.Helpers._BugV2Core)
end

function Menu.Actions.BugVehicleFromCameraOrTarget(mode)
    local playerPed = PlayerPedId()
    local camPos    = GetGameplayCamCoord()
    local camRot    = GetGameplayCamRot(2)

    local pitch = math.rad(camRot.x)
    local yaw   = math.rad(camRot.z)
    local dirX  = -math.sin(yaw) * math.cos(pitch)
    local dirY  =  math.cos(yaw) * math.cos(pitch)
    local dirZ  =  math.sin(pitch)
    local endX  = camPos.x + dirX * 10000.0
    local endY  = camPos.y + dirY * 10000.0
    local endZ  = camPos.z + dirZ * 10000.0

    local ray = StartExpensiveSynchronousShapeTestLosProbe(
        camPos.x, camPos.y, camPos.z,
        endX, endY, endZ,
        -1, playerPed, 7
    )
    local _, hit, hitCoords, _, entityHit = GetShapeTestResult(ray)

    local targetVehicle = nil
    if hit and entityHit and entityHit ~= 0 and DoesEntityExist(entityHit) then
        if GetEntityType(entityHit) == 2 then
            targetVehicle = entityHit
        elseif GetEntityType(entityHit) == 1 then
            local v = GetVehiclePedIsIn(entityHit, false)
            if v and v ~= 0 and DoesEntityExist(v) then targetVehicle = v end
        end
    end

    if not targetVehicle and hit and hitCoords then
        local nearVeh = GetClosestVehicle(hitCoords.x, hitCoords.y, hitCoords.z, 6.0, 0, 70)
        if nearVeh and nearVeh ~= 0 and DoesEntityExist(nearVeh) then
            targetVehicle = nearVeh
        end
    end

    -- Fallback si aucun vehicule vise directement mais qu'un joueur cible est en vehicule
    if not targetVehicle and selectedPlayer and selectedPlayer.id then
        local tPed = GetPlayerPed(selectedPlayer.id)
        if DoesEntityExist(tPed) and IsPedInAnyVehicle(tPed, false) then
            targetVehicle = GetVehiclePedIsIn(tPed, false)
        end
    end

    if not targetVehicle then
        ShowDynastyNotification("[ BUG VEH ] Visez un vehicule ou ciblez un joueur en vehicule")
        return
    end

    local chosenMode = mode or (_G.FreecamBugVehicleModes and _G.FreecamBugVehicleModes[_G.FreecamBugVehicleModeIdx or 1]) or "V1"
    if chosenMode == "V2" then
        Menu.Actions.BugVehicleV2(targetVehicle)
    else
        Menu.Actions.BugVehicleV1(targetVehicle)
    end
end
