-- ── TELEPORT PASSAGER (FREECAM & NORMAL) ─────────────────────────
function Menu.Helpers.GetTargetVehicleFromRaycastOrSelf()
    local playerPed = PlayerPedId()
    local targetVeh = nil

    if freecam_active and cam_pos and cam_rot then
        local pitch = math.rad(cam_rot.x)
        local yaw   = math.rad(cam_rot.z)
        local dirX  = -math.sin(yaw) * math.cos(pitch)
        local dirY  =  math.cos(yaw) * math.cos(pitch)
        local dirZ  =  math.sin(pitch)
        local ray = StartExpensiveSynchronousShapeTestLosProbe(
            cam_pos.x, cam_pos.y, cam_pos.z,
            cam_pos.x + dirX * 1000.0,
            cam_pos.y + dirY * 1000.0,
            cam_pos.z + dirZ * 1000.0,
            -1, playerPed, 10
        )
        local _, hit, endCoords, _, entityHit = GetShapeTestResult(ray)
        if hit and entityHit and DoesEntityExist(entityHit) then
            if GetEntityType(entityHit) == 2 then
                targetVeh = entityHit
            elseif GetEntityType(entityHit) == 1 then
                local v = GetVehiclePedIsIn(entityHit, false)
                if v and v ~= 0 and DoesEntityExist(v) then targetVeh = v end
            end
        end
        if not targetVeh and hit and endCoords then
            local nearVeh = GetClosestVehicle(endCoords.x, endCoords.y, endCoords.z, 6.0, 0, 70)
            if nearVeh and nearVeh ~= 0 and DoesEntityExist(nearVeh) then
                targetVeh = nearVeh
            end
        end
    else
        local camPos = GetGameplayCamCoord()
        local camRot = GetGameplayCamRot(2)
        local pitch  = math.rad(camRot.x)
        local yaw    = math.rad(camRot.z)
        local dirX   = -math.sin(yaw) * math.cos(pitch)
        local dirY   =  math.cos(yaw) * math.cos(pitch)
        local dirZ   =  math.sin(pitch)
        local ray = StartExpensiveSynchronousShapeTestLosProbe(
            camPos.x, camPos.y, camPos.z,
            camPos.x + dirX * 1000.0,
            camPos.y + dirY * 1000.0,
            camPos.z + dirZ * 1000.0,
            -1, playerPed, 10
        )
        local _, hit, endCoords, _, entityHit = GetShapeTestResult(ray)
        if hit and entityHit and DoesEntityExist(entityHit) then
            if GetEntityType(entityHit) == 2 then
                targetVeh = entityHit
            elseif GetEntityType(entityHit) == 1 then
                local v = GetVehiclePedIsIn(entityHit, false)
                if v and v ~= 0 and DoesEntityExist(v) then targetVeh = v end
            end
        end
        if not targetVeh and hit and endCoords then
            local nearVeh = GetClosestVehicle(endCoords.x, endCoords.y, endCoords.z, 6.0, 0, 70)
            if nearVeh and nearVeh ~= 0 and DoesEntityExist(nearVeh) then
                targetVeh = nearVeh
            end
        end
    end

    if not targetVeh or targetVeh == 0 then
        targetVeh = GetVehiclePedIsIn(playerPed, false)
    end
    if (not targetVeh or targetVeh == 0) and selectedPlayer and selectedPlayer.id then
        local tPed = GetPlayerPed(selectedPlayer.id)
        if DoesEntityExist(tPed) and IsPedInAnyVehicle(tPed, false) then
            targetVeh = GetVehiclePedIsIn(tPed, false)
        end
    end

    if targetVeh and targetVeh ~= 0 and DoesEntityExist(targetVeh) then
        return targetVeh
    end
    return nil
end

function Menu.Actions.TPPassengerToDestination(targetVeh,destCoords,destName)
    if not targetVeh or targetVeh==0 or not DoesEntityExist(targetVeh) or not destCoords then
        ShowDynastyNotification('[ TP PASSAGER ] Vehicule ou destination invalide');return
    end
    if _G._tpPassengerBusy then ShowDynastyNotification('[ TP PASSAGER ] Operation en cours');return end
    _G._tpPassengerBusy=true
    local origin=Menu.Helpers.CaptureShootCarOrigin()
    CreateThread(function()
        local ok,err=pcall(function()
            if not Menu.Helpers.PrepareNpcVehicleEntry(targetVeh,false) then return end
            if not DoesEntityExist(targetVeh) then return end
            if NetworkGetEntityIsNetworked(targetVeh) then NetworkRequestControlOfEntity(targetVeh) end
            RequestCollisionAtCoord(destCoords.x,destCoords.y,destCoords.z)
            -- Declenchement immediat apres confirmation du PNJ au volant.
            if not DoesEntityExist(targetVeh) then return end
            SetEntityCoordsNoOffset(targetVeh,destCoords.x,destCoords.y,destCoords.z,false,false,false)
            ShowDynastyNotification('[ TP PASSAGER ] Vehicule TP vers '..(destName or 'Destination'))
        end)
        local safe,returned=pcall(Menu.Helpers.RestoreShootCarOrigin,origin)
        _G._tpPassengerBusy=false
        if not safe or not returned then ShowDynastyNotification('[ TP PASSAGER ] Retour joueur non confirme') end
        if not ok then ;ShowDynastyNotification('[ TP PASSAGER ] Erreur : voir F8') end
    end)
end

