_G.attachAnimActive = false

function Menu.Actions.ToggleInteractEmote(emoteType)
    if not selectedPlayer then return end
    local targetServerId = selectedPlayer.serverId

    local function stopCurrentAnim()
        _G.attachAnimActive = false
        Wait(50)
        local playerPed = PlayerPedId()
        if DoesEntityExist(playerPed) then
            if IsEntityAttached(playerPed) then DetachEntity(playerPed, true, false) end
            ClearPedTasksImmediately(playerPed)
        end
    end

    -- Toggle OFF si mÃªme emote
    if interactEmoteType == emoteType then
        stopCurrentAnim()
        interactEmoteType = nil
        return
    end

    -- ArrÃªter l'emote prÃ©cÃ©dente
    if interactEmoteType then
        stopCurrentAnim()
    end

    interactEmoteType = emoteType
    _G.attachAnimActive = true

    local emoteConfigs = {
        twerk     = { dict="switch@trevor@mocks_lapdance",           anim="001443_01_trvs_28_idle_stripper", bone=4103, ox=0.05, oy=0.38,  oz=0.0,  rx=0,   ry=0,   rz=0,   flags=33 },
        fuck      = { dict="rcmpaparazzo_2",                          anim="shag_loop_a",                     bone=4103, ox=0.04, oy=-0.4,  oz=0.1,  rx=0,   ry=0,   rz=0,   flags=33 },
        sex       = { dict="rcmpaparazzo_2",                          anim="shag_loop_a",                     bone=4103, ox=0.04, oy=-0.4,  oz=0.1,  rx=0,   ry=0,   rz=0,   flags=33 },
        sucer     = { dict="mp_ped_interaction",                      anim="blowjob_e",                       bone=4103, ox=0.0,  oy=0.45,  oz=-0.4, rx=0,   ry=0,   rz=180, flags=33 },
        wank      = { dict="mp_player_int_upperwank",                 anim="mp_player_int_wank_01",           bone=4103, ox=0.0,  oy=-0.3,  oz=0.0,  rx=0,   ry=0,   rz=0,   flags=51 },
        piggyback = { dict="anim@arena@celeb@flat@paired@no_props@", anim="piggyback_c_player_b",            bone=0,    ox=0.0,  oy=-0.25, oz=0.45, rx=0.5, ry=0.5, rz=180, flags=33 },
        shoulder  = { dict="creatures@cat@amb@world_cat_sleeping_ledge@idle_a", anim="idle_a", flags=67108874, sticky=true, boneId=0, ox=0.20, oy=-0.03, oz=0.58, rx=0, ry=0, rz=0 } -- Chat assis, rapproche du cou et abaisse sur l'epaule ; ajuster ox/oy/oz selon le ped.
    }

    local cfg = emoteConfigs[emoteType]
    if not cfg then _G.attachAnimActive = false; interactEmoteType = nil; return end

    Citizen.CreateThread(function()
        local playerPed = PlayerPedId()

        if not cfg.noAnim and not HasAnimDictLoaded(cfg.dict) then
            RequestAnimDict(cfg.dict)
            local t = GetGameTimer()
            while not HasAnimDictLoaded(cfg.dict) and GetGameTimer() - t < 3000 do Wait(0) end
        end
        if not cfg.noAnim and not HasAnimDictLoaded(cfg.dict) then
            _G.attachAnimActive = false; interactEmoteType = nil; return
        end

        local targetPed = nil
        for _, player in ipairs(GetActivePlayers()) do
            if GetPlayerServerId(player) == targetServerId then
                targetPed = GetPlayerPed(player); break
            end
        end
        if not targetPed or not DoesEntityExist(targetPed) then
            _G.attachAnimActive = false; interactEmoteType = nil; return
        end

        if IsEntityDead(targetPed) or IsEntityDead(playerPed) then
            _G.attachAnimActive = false; interactEmoteType = nil; return
        end
        local ok = pcall(AttachEntityToEntity, playerPed, targetPed, (cfg.boneId and GetPedBoneIndex(targetPed, cfg.boneId) or cfg.bone), cfg.ox, cfg.oy, cfg.oz, cfg.rx, cfg.ry, cfg.rz, false, false, false, cfg.sticky == true, 2, true)
        if not ok then _G.attachAnimActive = false; interactEmoteType = nil; return end
        if cfg.noAnim then
            ClearPedTasksImmediately(playerPed)
        else
            pcall(TaskPlayAnim, playerPed, cfg.dict, cfg.anim, 8.0, -8.0, 100000, cfg.flags, 0, false, false, false)
        end

        while _G.attachAnimActive and interactEmoteType == emoteType do
            Wait(50)
            if not DoesEntityExist(playerPed) or IsEntityDead(playerPed) then break end
            local curTargetPed = nil
            for _, player in ipairs(GetActivePlayers()) do
                if GetPlayerServerId(player) == targetServerId then
                    curTargetPed = GetPlayerPed(player); break
                end
            end
            if not curTargetPed or not DoesEntityExist(curTargetPed) or IsEntityDead(curTargetPed) then break end
            if not IsEntityAttachedToEntity(playerPed, curTargetPed) then
                pcall(AttachEntityToEntity, playerPed, curTargetPed, (cfg.boneId and GetPedBoneIndex(curTargetPed, cfg.boneId) or cfg.bone), cfg.ox, cfg.oy, cfg.oz, cfg.rx, cfg.ry, cfg.rz, false, false, false, cfg.sticky == true, 2, true)
            end
            if cfg.sticky then
                -- Suivi a chaque image ; empeche les commandes locales de casser la pose.
                DisableControlAction(0, 30, true)
                DisableControlAction(0, 31, true)
                DisableControlAction(0, 21, true)
                DisableControlAction(0, 22, true)
                DisableControlAction(0, 24, true)
                DisableControlAction(0, 25, true)
                DisableControlAction(0, 23, true)
                ProcessEntityAttachments(playerPed)
            end
            if not cfg.noAnim and not IsEntityPlayingAnim(playerPed, cfg.dict, cfg.anim, 3) then
                pcall(TaskPlayAnim, playerPed, cfg.dict, cfg.anim, 8.0, -8.0, 100000, cfg.flags, 0, false, false, false)
            end
        end

        if DoesEntityExist(playerPed) then
            if IsEntityAttached(playerPed) then DetachEntity(playerPed, true, false) end
            ClearPedTasksImmediately(playerPed)
        end
        if interactEmoteType == emoteType then interactEmoteType = nil end
        _G.attachAnimActive = false
    end)
end

