-- =====================================================================
CreateThread(function()
    while true do
        if not Menu.State.colSpammerActive then
            Wait(300)
        else
            if not _G.crashBugNearbyPlayersActive then
                _G.crashBugNearbyPlayersActive = true
                Citizen.CreateThread(function()
                    while _G.crashBugNearbyPlayersActive do
                        local ped = PlayerPedId()
                        if not ped or ped == 0 then Citizen.Wait(100)
                        else
                        -- Recupere le scenario selectionne dynamiquement
                        local scenarios = Menu.Helpers.GetColScenarios()
                        local idx = Menu.State.colSpamScenarioIdx or 1
                        local entry = scenarios[idx]

                        if entry and entry.propModel then
                            -- Mode prop exploit (lib:progressProps)
                            local model = entry.propModel
                            pcall(function() LocalPlayer.state:set('lib:progressProps', {model = model}, true) end)
                            Citizen.Wait(Menu.State.colSpamSpeed or 10)
                            pcall(function() LocalPlayer.state:set('lib:progressProps', nil, true) end)
                            Citizen.Wait(Menu.State.colSpamSpeed or 10)
                        else
                            -- Mode scénario classique
                            local scenName = (entry and entry.scenario) or "WORLD_HUMAN_WELDING"
                            FreezeEntityPosition(ped, true)
                            TaskStartScenarioInPlace(ped, scenName, 0, false)
                            Citizen.Wait(Menu.State.colSpamSpeed or 10)
                            ClearPedTasks(ped)
                            TaskStartScenarioInPlace(ped, scenName, 0, true)
                        end
                        end -- ped guard
                    end
                    local ped = PlayerPedId()
                    FreezeEntityPosition(ped, false)
                    ClearPedTasks(ped)
                    ClearPedTasksImmediately(ped)
                end)
            end
            -- Surveille la désactivation du toggle pour couper l'inner thread
            while Menu.State.colSpammerActive do
                Wait(200)
            end
            _G.crashBugNearbyPlayersActive = false
        end
    end
end)


