            local ped = PlayerPedId()
            local inVeh = IsPedInAnyVehicle(ped, false)

            -- Lire la vitesse actuelle (protÃ©gÃ©)
            local speed = 0.0
            if inVeh then
                local veh = GetVehiclePedIsIn(ped, false)
                if veh and veh ~= 0 and DoesEntityExist(veh) then
                    local ok, vel = pcall(GetEntityVelocity, veh)
                    if ok and vel then
                        speed = math.sqrt(vel.x*vel.x + vel.y*vel.y + vel.z*vel.z)
                    end
                end
            end
            local maxSpeed = SHIFT_BOOST_MAX_SPEED  -- synchronisÃ© avec la constante du boost
            local progress = math.min(speed / maxSpeed, 1.0)

            -- DÃ©tecter si SHIFT est maintenu
            local shiftHeld = false
            if Lapsus and Lapsus_GetAsyncKeyState_compat then
                shiftHeld = Lapsus_GetAsyncKeyState_compat(0x10)
            end
            if not shiftHeld then
                shiftHeld = IsControlPressed(0, 21) or IsDisabledControlPressed(0, 21)
            end

            local sw, sh = GetActiveScreenResolution()
            local barW = 280.0
            local barH = 6.0
            local barX = sw / 2 - barW / 2
            local barY = sh * 0.88

            -- MÃªme palette couleur que Easy Handling : bleu â†’ cyan â†’ vert
            local r, g, b
            if progress < 0.5 then
                r = 0.0; g = progress * 2.0; b = 1.0 - progress * 1.4
            else
                r = 0.0; g = 1.0; b = 0.0
            end

            -- Fond
            Lapsus_DrawRect_Filled(barX, barY, barW, barH, 0.1, 0.1, 0.1, 0.7, 3.0)

            -- Remplissage
            local fillW = barW * progress
            if fillW > 0 then
                Lapsus_DrawRect_Filled(barX, barY, fillW, barH, r, g, b, 0.9, 3.0)
            end

            -- Knob
            local knobW = 4.0
            local knobH = 14.0
            local knobX = barX + math.max(0, fillW) - knobW / 2
            local knobY = barY - (knobH - barH) / 2
            Lapsus_DrawRect_Filled(knobX, knobY, knobW, knobH, 1.0, 1.0, 1.0, 1.0, 2.0)

            -- Label : vert actif si SHIFT tenu, blanc sinon
            local labelTxt = shiftHeld and "SHIFT BOOST â–¶" or "SHIFT BOOST"
            local fontSize = 13
            local lw = Lapsus_GetTextWidth_compat(labelTxt, fontSize)
            local lR, lG, lB = shiftHeld and 0.2 or 1.0, shiftHeld and 1.0 or 1.0, shiftHeld and 0.2 or 1.0
            Lapsus_DrawText_compat(sw / 2 - lw / 2, barY - 22, labelTxt, fontSize, lR, lG, lB, 0.85)

            -- Vitesse km/h Ã  droite
            local kmh = math.floor(speed * 3.6)
            local speedTxt = kmh .. " km/h"
            local sw2 = Lapsus_GetTextWidth_compat(speedTxt, fontSize)
            Lapsus_DrawText_compat(barX + barW - sw2, barY + barH + 5, speedTxt, fontSize, r, g, b, 0.9)
        end
    end
end)


