-- Cache uniquement le cercle de cette progression ; chaque nouveau spawn remplace l'ancien.
local function progressWithoutCircle(data)
    local token={}
    _oxAttachProgressToken=token
    local original=SendNUIMessage
    local filtered
    filtered=function(message)
        if type(message)=='table' and message.action=='circleProgress' then
            if SendNUIMessage==filtered then SendNUIMessage=original end
            return
        end
        return original(message)
    end
    SendNUIMessage=filtered
    Citizen.CreateThread(function()
        Wait(data.duration)
        if _oxAttachProgressToken==token and lib.progressActive() then lib.cancelProgress() end
