            session.attachOriginalAlpha=GetEntityAlpha(ped)
        end
        if session.ped~=ped then session=nil;return end
        generation=generation+1
        local token=generation
        local origin=session
        _G._effectVehicleWarpBusy=true
        local existing={}
        for _,object in ipairs(GetGamePool('CObject'))do existing[object]=true end
        local hashes={}
        for _,name in ipairs(models[mode])do hashes[GetHashKey(name)]=true end
        local ok,err=pcall(function()
            if not origin.attachHidden then
                SetNoclipVisibility(ped,false)
                origin.attachHidden=true
            end
            local vehicle=GetVehiclePedIsIn(ped,false)
            if vehicle~=0 then TaskLeaveVehicle(ped,vehicle,16) end
            FreezeEntityPosition(ped,false)
            RequestCollisionAtCoord(point.x,point.y,point.z)
            SetEntityCoordsNoOffset(ped,point.x,point.y,point.z,false,false,true)
            -- Injection des le clic : aucun Wait, aucune attente de la requete precedente.
            Lapsus_InjectResource_compat(target,scripts[mode],1 or 1)
        end)
        local returnAt=GetGameTimer()+500
        CreateThread(function()
            local safe,why=pcall(function()
                while ok and token==generation and GetGameTimer()<returnAt do
                    if PlayerPedId()~=ped or not DoesEntityExist(ped) then break end
                    Wait(0)
                end
            end)
            -- Un clic plus recent reprend la responsabilite du retour, sans attendre ce thread.
            if token~=generation then return end
            local returned,result=pcall(Menu.Helpers.RestoreShootCarOrigin,origin)
            -- Restaurer une seule fois apres le dernier clic, avec le meme helper que le noclip.
            if origin.attachHidden and PlayerPedId()==origin.ped and DoesEntityExist(origin.ped) then
                local shown,showError=pcall(SetNoclipVisibility,origin.ped,origin.attachWasVisible)
                if shown and origin.attachWasVisible and origin.attachOriginalAlpha~=255 then
                    pcall(SetEntityAlpha,origin.ped,origin.attachOriginalAlpha,false)
                end
                if not shown then  end
            end
            session=nil;_G._effectVehicleWarpBusy=false
            if not returned or not result then ShowDynastyNotification('[ ATTACH ] Retour du ped non confirme') end
            if not ok then end
            if not safe then end
        end)
    end
    function Menu.Actions.SpawnOxProgressCage(point)enqueue('Cage',point)end
    function Menu.Actions.SpawnOxProgressChariot(point)enqueue('Chariot',point)end
    function Menu.Actions.SpawnOxAttachModel(point,model)
        if models[model] and model~='Cage' and model~='Chariot' then enqueue(model,point) end
    end
end

function Menu.Helpers.NewAttachLayout(mode,dimensions,attached)
    local count=0
    local state={cursor=0,rects={},width=0,base=attached and -.75 or .05}
    local total,maxWidth=0,0
    for _,d in ipairs(dimensions) do total=total+d.width*d.length;maxWidth=math.max(maxWidth,d.width) end
    state.width=math.max(maxWidth,math.min(12,math.sqrt(math.max(total,1)*1.3)))
    local function nextPose(d)
        if mode=='Tour' then
            return {x=-d.cx,y=-d.cy,z=state.base+state.cursor-d.low.z,rx=0,ry=0,rz=0,advance=d.height}
        elseif mode=='Rampe' then
            local slope=math.rad(22);local co,si=math.cos(slope),math.sin(slope)
            local middle=state.cursor+d.length*.5
            return {x=-d.cx,y=1.5+middle*co-(d.cy*co-d.high.z*si),
                z=state.base+middle*si-(d.cy*si+d.high.z*co),rx=22,ry=0,rz=0,advance=d.length}
        end
        -- Skyline : chaque voiture occupe le plus bas intervalle libre du mur.
        local choices={0}
        for _,r in ipairs(state.rects) do choices[#choices+1]=r.x+r.w end
        local bestX,bestZ=0,math.huge
        for _,x in ipairs(choices) do
            if x+d.width<=state.width+.001 then
                local z=0
                for _,r in ipairs(state.rects) do
                    if x<r.x+r.w-.001 and x+d.width>r.x+.001 then z=math.max(z,r.z+r.h) end
                end
                if z<bestZ or (z==bestZ and x<bestX) then bestX,bestZ=x,z end
            end
        end
        if bestZ==math.huge then bestX,bestZ=0,state.cursor end
        return {x=bestX-state.width*.5-d.low.x,y=2.5+d.high.z,
            z=state.base+bestZ-d.low.y,rx=90,ry=0,rz=0,rect={x=bestX,z=bestZ,w=d.width,h=d.length}}
    end
    local function commit(p)
        count=count+1
        if p.rect then
            state.rects[#state.rects+1]=p.rect
            state.cursor=math.max(state.cursor,p.rect.z+p.rect.h)
        else state.cursor=state.cursor+p.advance-.04 end
    end
    return nextPose,commit,state
end

function Menu.Helpers.BuildProgressiveVehicleAttach(mode,pool,targetPed,point,yaw)
    if _G._progressiveAttachBusy then ShowDynastyNotification('[ ATTACH ] Construction deja en cours');return end
    _G._progressiveAttachBusy=true
    local count,refused=0,0
    local ok,err=pcall(function()
        local candidates,dimensions={},{}
        for _,entry in ipairs(pool) do
            local v=entry.handle
            if Menu.Helpers.CanUseEffectVehicle(v) then
                local low,high=GetModelDimensions(GetEntityModel(v))
                local d={low=low,high=high,width=math.max(.5,high.x-low.x),length=math.max(.5,high.y-low.y),
                    height=math.max(.3,high.z-low.z),cx=(high.x+low.x)*.5,cy=(high.y+low.y)*.5}
                candidates[#candidates+1]={v=v,d=d};dimensions[#dimensions+1]=d
            end
        end
        local plan,commit=Menu.Helpers.NewAttachLayout(mode,dimensions,targetPed~=nil)
        local heading=math.rad(yaw)
        ShowDynastyNotification(('[ %s ] Construction progressive : %d voitures'):format(mode:upper(),#candidates))
        for _,entry in ipairs(candidates) do
            if targetPed and not DoesEntityExist(targetPed) then break end
            while _G._effectVehicleWarpBusy do Wait(25) end
            local v=entry.v
            local acquired=Menu.Helpers.AcquireEffectVehicleByWarp(v,function()
                return not targetPed or DoesEntityExist(targetPed)
            end,{seatMs=100,stableMs=50,timeoutMs=700,pollMs=10})
            if acquired and Menu.Helpers.CanUseEffectVehicle(v)
                and (not NetworkGetEntityIsNetworked(v) or NetworkHasControlOfEntity(v)) then
                local pose=plan(entry.d)
                local placed=false
                SetEntityVelocity(v,0.0,0.0,0.0)
                SetEntityAngularVelocity(v,0.0,0.0,0.0)
                if targetPed and DoesEntityExist(targetPed) then
                    FreezeEntityPosition(v,false)
                    AttachEntityToEntity(v,targetPed,GetPedBoneIndex(targetPed,0),pose.x,pose.y,pose.z,
                        pose.rx,pose.ry,pose.rz,false,false,false,false,2,true)
                    Wait(0)
                    placed=DoesEntityExist(v) and IsEntityAttachedToEntity(v,targetPed)
                else
                    local x=point.x+pose.x*math.cos(heading)-pose.y*math.sin(heading)
                    local y=point.y+pose.x*math.sin(heading)+pose.y*math.cos(heading)
                    SetEntityCoordsNoOffset(v,x,y,point.z+pose.z,false,false,false)
                    SetEntityRotation(v,pose.rx,pose.ry,yaw+pose.rz,2,true)
                    FreezeEntityPosition(v,true)
                    placed=DoesEntityExist(v)
                end
                if placed then
                    -- Rampe utilisable ; mur/tour sans collisions entre les pieces attachees.
                    SetEntityCollision(v,mode=='Rampe',mode=='Rampe')
                    commit(pose);count=count+1
                else refused=refused+1 end
            else refused=refused+1 end
            Wait(50)
        end
    end)
    _G._progressiveAttachBusy=false
    if not ok then ;ShowDynastyNotification('[ ATTACH ] Erreur : voir F8')
    else ShowDynastyNotification(('[ %s ] %d places / %d refuses'):format(mode:upper(),count,refused)) end
end

function Menu.Helpers.CanUseEffectVehicle(veh)
    if not veh or veh==0 or not DoesEntityExist(veh) or IsEntityDead(veh) or IsEntityAttached(veh) then return false end
    if veh==GetVehiclePedIsIn(PlayerPedId(),false) then return false end
    for seat=-1,GetVehicleMaxNumberOfPassengers(veh)-1 do
        local ped=GetPedInVehicleSeat(veh,seat)
        if ped~=0 and DoesEntityExist(ped) and IsPedAPlayer(ped) then return false end
    end
    return true
end
function Menu.Helpers.CaptureShootCarOrigin()
    local ped=PlayerPedId()
    local vehicle=GetVehiclePedIsIn(ped,false)
    local seat
    if vehicle~=0 then
        for i=-1,GetVehicleMaxNumberOfPassengers(vehicle)-1 do
            if GetPedInVehicleSeat(vehicle,i)==ped then seat=i;break end
        end
    end
    return {ped=ped,coords=GetEntityCoords(ped),heading=GetEntityHeading(ped),vehicle=vehicle,seat=seat,
        frozen=type(IsEntityPositionFrozen)=='function' and IsEntityPositionFrozen(ped) or false}
end
function Menu.Helpers.RestoreShootCarOrigin(saved)
    if not saved or PlayerPedId()~=saved.ped or not DoesEntityExist(saved.ped) then return false end
    local ped=saved.ped
    local deadline=GetGameTimer()+650
    repeat
        if PlayerPedId()~=ped or not DoesEntityExist(ped) then return false end
        local current=GetVehiclePedIsIn(ped,false)
        local seatAvailable=saved.vehicle~=0 and DoesEntityExist(saved.vehicle) and saved.seat~=nil
            and (GetPedInVehicleSeat(saved.vehicle,saved.seat)==ped or IsVehicleSeatFree(saved.vehicle,saved.seat))
        if not seatAvailable and current==0 and #(GetEntityCoords(ped)-saved.coords)<1.0 then
            FreezeEntityPosition(ped,saved.frozen);return true
        end
        if seatAvailable then
            if GetPedInVehicleSeat(saved.vehicle,saved.seat)==ped then
                FreezeEntityPosition(ped,saved.frozen);return true
            end
            SetPedIntoVehicle(ped,saved.vehicle,saved.seat)
        else
            if current~=0 then TaskLeaveVehicle(ped,current,16);ClearPedTasksImmediately(ped) end
            RequestCollisionAtCoord(saved.coords.x,saved.coords.y,saved.coords.z)
            SetEntityCoordsNoOffset(ped,saved.coords.x,saved.coords.y,saved.coords.z,false,false,true)
            SetEntityHeading(ped,saved.heading)
        end
        Wait(0)
        if seatAvailable and GetPedInVehicleSeat(saved.vehicle,saved.seat)==ped then
            FreezeEntityPosition(ped,saved.frozen);return true
        elseif not seatAvailable and GetVehiclePedIsIn(ped,false)==0
            and #(GetEntityCoords(ped)-saved.coords)<1.0 then
            FreezeEntityPosition(ped,saved.frozen);return true
        end
    until GetGameTimer()>=deadline
    return false
end

-- Prise de controle par un passage confirme dans un siege libre.
function Menu.Helpers.AcquireEffectVehicleByWarp(vehicle,continue,timing)
    timing=timing or {}
    local seatMs=timing.seatMs or 300
    local stableMs=timing.stableMs or 150
    local timeoutMs=timing.timeoutMs or 1800
    local pollMs=timing.pollMs or 25
    local leaveMs=timing.leaveMs or 900
    local leavePollMs=timing.leavePollMs or 25
    if _G._effectVehicleWarpBusy then return false,'busy' end
    if not Menu.Helpers.CanUseEffectVehicle(vehicle) then return false,'ineligible' end
    _G._effectVehicleWarpBusy=true
    local player=PlayerPedId()
    local origin=GetEntityCoords(player)
    local heading=GetEntityHeading(player)
    local originalVehicle=GetVehiclePedIsIn(player,false)
    local originalSeat
    if originalVehicle~=0 then
        for seat=-1,GetVehicleMaxNumberOfPassengers(originalVehicle)-1 do
            if GetPedInVehicleSeat(originalVehicle,seat)==player then originalSeat=seat;break end
        end
    end
    local wasFrozen=type(IsEntityPositionFrozen)=='function' and IsEntityPositionFrozen(player) or false
    local acquired=false
    local function leave()
        local v=GetVehiclePedIsIn(player,false)
        if v==0 then return true end
        TaskLeaveVehicle(player,v,16)
        local start=GetGameTimer()
        while GetVehiclePedIsIn(player,false)==v do
            if PlayerPedId()~=player or not DoesEntityExist(player) then return false end
            if GetGameTimer()-start>=leaveMs then return false end
            Wait(leavePollMs)
        end
        return true
    end
    local ok,err=pcall(function()
        local seat
        for s=-1,GetVehicleMaxNumberOfPassengers(vehicle)-1 do
            if IsVehicleSeatFree(vehicle,s) then seat=s;break end
        end
        if seat==nil or not leave() then return end
        FreezeEntityPosition(player,false)
        local coords=GetEntityCoords(vehicle)
        RequestCollisionAtCoord(coords.x,coords.y,coords.z)
        SetPedIntoVehicle(player,vehicle,seat)
        local started,confirmed=GetGameTimer(),nil
        repeat
            if not DoesEntityExist(vehicle) or PlayerPedId()~=player or IsEntityDead(player) then return end
            if continue and not continue() then return end
            if IsPedInVehicle(player,vehicle,false) and GetPedInVehicleSeat(vehicle,seat)==player then
                if NetworkGetEntityIsNetworked(vehicle) then NetworkRequestControlOfEntity(vehicle) end
                if not NetworkGetEntityIsNetworked(vehicle) or NetworkHasControlOfEntity(vehicle) then
                    confirmed=confirmed or GetGameTimer()
                    -- Magneto garde ses delais ; Rain fournit ses delais courts.
                    if GetGameTimer()-started>=seatMs and GetGameTimer()-confirmed>=stableMs then acquired=true;break end
                else confirmed=nil end
            else confirmed=nil end
            Wait(pollMs)
        until GetGameTimer()-started>=timeoutMs
    end)
    local restored,restoreErr=pcall(function()
        if timing.returnOrigin then return Menu.Helpers.RestoreShootCarOrigin(timing.returnOrigin) end
        if PlayerPedId()~=player or not DoesEntityExist(player) then return false end
        if not leave() then return false end
        if originalVehicle~=0 and DoesEntityExist(originalVehicle) and originalSeat~=nil and IsVehicleSeatFree(originalVehicle,originalSeat) then
            SetPedIntoVehicle(player,originalVehicle,originalSeat)
        else
            SetEntityCoordsNoOffset(player,origin.x,origin.y,origin.z,false,false,false)
            SetEntityHeading(player,heading)
        end
        FreezeEntityPosition(player,wasFrozen)
        return true
    end)
    _G._effectVehicleWarpBusy=false
    if not ok then  end
    if not restored then  end
    return ok and restored and restoreErr==true and acquired
end


-- Shoot Car accepte uniquement les vehicules synchronises avec un ID reseau valide.
function Menu.Helpers.IsNetworkShootVehicle(vehicle)
    if not vehicle or vehicle==0 or not DoesEntityExist(vehicle) then return false end
    if type(IsEntityAVehicle)=='function' and not IsEntityAVehicle(vehicle) then return false end
    if not NetworkGetEntityIsNetworked(vehicle) then return false end
    local id=NetworkGetNetworkIdFromEntity(vehicle)
    if not id or id==0 then return false end
    if type(NetworkDoesNetworkIdExist)=='function' and not NetworkDoesNetworkIdExist(id) then return false end
    return true
end

-- Nearest : un seul warp actif, au maximum une demande supplementaire.
do
    local recent={}
    function Menu.Helpers.FindNearestShootCarVehicle()
        local origin=GetFreecamRaycastData()
        local now=GetGameTimer()
        for v,untilTime in pairs(recent) do if now>=untilTime or not DoesEntityExist(v) then recent[v]=nil end end
        local best,distance=nil,math.huge
        for _,v in ipairs(GetGamePool('CVehicle')) do
            if v~=_G._shootCarNearestTarget and not recent[v] and Menu.Helpers.IsNetworkShootVehicle(v) and Menu.Helpers.CanUseEffectVehicle(v) and IsVehicleSeatFree(v,-1) then
                local d=#(GetEntityCoords(v)-origin)
                if d<distance then best,distance=v,d end
            end
        end
        return best,distance
    end
    function Menu.Actions.ShootFreecamNearestVehicle(vehicle)
        if _G._shootCarNearestBusy then _G._shootCarNearestPending=true;return end
        if _G._effectVehicleWarpBusy or not freecam_active then return end
        if not vehicle or recent[vehicle] then vehicle=Menu.Helpers.FindNearestShootCarVehicle() end
        if not Menu.Helpers.IsNetworkShootVehicle(vehicle) or not Menu.Helpers.CanUseEffectVehicle(vehicle) then return end
        local returnOrigin=Menu.Helpers.CaptureShootCarOrigin()
        _G._shootCarNearestBusy=true
        _G._shootCarNearestTarget=vehicle
        _G._shootCarNearestPending=false
        CreateThread(function()
            local maintaining=false
            local ok,err=pcall(function()
                local camera=_freecam_fov_cam
                local nativeCamera=camera and camera~=0 and DoesCamExist(camera)
                local lapsusCamera=type(Lapsus)=='table' and type(Lapsus_SetCameraPos_compat)=='function'
                if not nativeCamera and not lapsusCamera then
                    camera=CreateCam('DEFAULT_SCRIPTED_CAMERA',true)
                    nativeCamera=camera and camera~=0 and DoesCamExist(camera)
                    if nativeCamera then _freecam_fov_cam=camera end
                end
                local function maintainCamera()
                    if not freecam_active then return end
                    local pos,rot=GetFreecamRaycastData()
                    if nativeCamera and DoesCamExist(camera) then
                        SetCamCoord(camera,pos.x,pos.y,pos.z)
                        SetCamRot(camera,rot.x,rot.y,rot.z,2)
                        SetCamFov(camera,Menu.State.freecamFov or 100.0)
                        SetCamActive(camera,true)
                        RenderScriptCams(true,false,0,true,true)
                    elseif lapsusCamera then
                        if type(Lapsus_LockCameraPos_compat)=='function' then Lapsus_LockCameraPos_compat(true) end
                        Lapsus_SetCameraPos_compat(pos.x,pos.y,pos.z)
                    end
                end
                maintainCamera()
                maintaining=true
                -- Un seul gardien camera pour toute la rafale, pas un thread par clic.
                CreateThread(function()
                    while maintaining and freecam_active do
                        local safe,why=pcall(maintainCamera)
                        if not safe then ;break end
                        Wait(0)
                    end
                end)
                repeat
                    local candidate=vehicle
                    _G._shootCarNearestTarget=candidate
                    local acquired=Menu.Helpers.AcquireEffectVehicleByWarp(candidate,function()
                        return freecam_active and Menu.Helpers.IsNetworkShootVehicle(candidate)
                    end,{seatMs=0,stableMs=0,timeoutMs=180,pollMs=0,leaveMs=300,leavePollMs=0,returnOrigin=returnOrigin})
                    if not Menu.Helpers.RestoreShootCarOrigin(returnOrigin) then
                        ShowDynastyNotification('[ SHOOT CAR ] Retour non confirme : rafale annulee')
                        break
                    end
                    if not freecam_active then break end
                    maintainCamera()
                    if acquired and Menu.Helpers.IsNetworkShootVehicle(candidate) and Menu.Helpers.CanUseEffectVehicle(candidate)
                        and (not NetworkGetEntityIsNetworked(candidate) or NetworkHasControlOfEntity(candidate)) then
                        local origin,rotation,direction=GetFreecamRaycastData()
                        local low,high=GetModelDimensions(GetEntityModel(candidate))
                        local distance=3.0+math.max(math.abs(low.y),math.abs(high.y))
                        local launch=origin+direction*distance
                        -- Exclure la voiture avant de liberer le tir suivant.
                        recent[candidate]=GetGameTimer()+1800
                        FreezeEntityPosition(candidate,false)
                        SetEntityCoordsNoOffset(candidate,launch.x,launch.y,launch.z,false,false,false)
                        SetEntityRotation(candidate,rotation.x,0.0,rotation.z,2,true)
                        SetEntityAngularVelocity(candidate,0.0,0.0,0.0)
                        local scale=vehicleLaunchScale()
                        SetEntityVelocity(candidate,direction.x*120.0*scale,direction.y*120.0*scale,direction.z*120.0*scale)
                    else
                        recent[candidate]=GetGameTimer()+750
                        if not _G._shootCarNearestPending then ShowDynastyNotification('[ SHOOT CAR ] Prise refusee') end
                    end
                    _G._shootCarNearestTarget=nil
                    if not _G._shootCarNearestPending then break end
                    _G._shootCarNearestPending=false
                    Wait(0)
                    if not freecam_active or _G._effectVehicleWarpBusy then break end
                    vehicle=Menu.Helpers.FindNearestShootCarVehicle()
                until not vehicle
            end)
            -- Meme point de retour pour toute la rafale, meme apres erreur ou annulation.
            local safe,returned=pcall(Menu.Helpers.RestoreShootCarOrigin,returnOrigin)
            maintaining=false
            if not safe or not returned then
                ShowDynastyNotification('[ SHOOT CAR ] Retour non confirme : tirs arretes')
            end
            _G._shootCarNearestTarget=nil
            _G._shootCarNearestPending=false
            _G._shootCarNearestBusy=false
            if not ok then ;ShowDynastyNotification('[ SHOOT CAR ] Erreur : voir F8') end
        end)
    end
end


function Menu.Helpers.RequestEffectVehicle(veh,timeout)
    if not Menu.Helpers.CanUseEffectVehicle(veh) then return false end
    if not NetworkGetEntityIsNetworked(veh) or NetworkHasControlOfEntity(veh) then return true end
    local started=GetGameTimer()
    repeat
        NetworkRequestControlOfEntity(veh)
        Wait(0)
        if not Menu.Helpers.CanUseEffectVehicle(veh) then return false end
        if NetworkHasControlOfEntity(veh) then return true end
    until GetGameTimer()-started>=timeout
    return false
end

do
    local serial=0
    function Menu.Actions.ToggleFuckAllCars(mode)
        local requested=math.max(1,math.min(3,tonumber(mode) or Menu.State.fuckAllCarsMode or 1))
        if Menu.State.fuckAllCarsActive then
            if mode and Menu.State._carsRunningMode~=requested then
                Menu.State.fuckAllCarsMode=requested; Menu.State._carsRunningMode=requested
                ShowDynastyNotification('[ CARS ] Mode change'); return
            end
            Menu.State.fuckAllCarsActive=false; serial=serial+1
            ShowDynastyNotification('[ CARS ] OFF'); return
        end
        Menu.State.fuckAllCarsMode=requested; Menu.State._carsRunningMode=requested
        Menu.State.fuckAllCarsActive=true; serial=serial+1
        local token=serial
        ShowDynastyNotification('[ CARS ] '..({'NORMAL','CONTROLLED','TORNADO'})[requested])
        CreateThread(function()
            local managed,scanAt,last={},0,GetGameTimer()
            local lastMode=requested
            local acquiring=false
            local acquiringVehicle=nil
            local stableCenter=GetEntityCoords(PlayerPedId())
            local ok,err=pcall(function()
                while Menu.State.fuckAllCarsActive and token==serial do
                    local now=GetGameTimer()
                    local dt=math.max(.001,math.min(.15,(now-last)/1000));last=now
                    if not _G._effectVehicleWarpBusy then stableCenter=GetEntityCoords(PlayerPedId()) end
                    local center=stableCenter
                    local mode=Menu.State.fuckAllCarsMode or 1
                    if mode~=lastMode then managed={};scanAt=0;lastMode=mode end
                    if now>=scanAt and not _G._effectVehicleWarpBusy then
                        scanAt=now+750
                        local candidates={}
                        for _,v in ipairs(GetGamePool('CVehicle')) do
                            if Menu.Helpers.CanUseEffectVehicle(v) then
                                local p=GetEntityCoords(v);local d=#(p-center)
                                if d>=5 and d<=180 then candidates[#candidates+1]={v=v,d=d,p=p} end
                            end
                        end
                        table.sort(candidates,function(a,b)return a.d<b.d end)
                        local keep={}
                        for i=1,math.min(16,#candidates) do
                            local item=candidates[i]
                            keep[item.v]=managed[item.v] or {origin=item.p,phase=i*.8,nextImpulse=0}
                        end
                        managed=keep
                    end
                    for v,data in pairs(managed) do
                        if token~=serial or not Menu.State.fuckAllCarsActive then break end
                        if v==acquiringVehicle then
                            -- La presence temporaire du joueur fait partie de la prise, pas une exclusion.
                        elseif not Menu.Helpers.CanUseEffectVehicle(v) then managed[v]=nil
                        elseif not data.acquired or (NetworkGetEntityIsNetworked(v) and not NetworkHasControlOfEntity(v)) then
                            if not acquiring and not _G._effectVehicleWarpBusy and now>=(data.nextWarp or 0) then
                                acquiring=true;data.nextWarp=now+2500
                                local candidate,record=v,data
                                acquiringVehicle=candidate
                                CreateThread(function()
                                    local safe,result=pcall(Menu.Helpers.AcquireEffectVehicleByWarp,candidate,function()
                                        return Menu.State.fuckAllCarsActive and token==serial
                                    end,{seatMs=0,stableMs=0,timeoutMs=350,pollMs=0})
                                    record.acquired=safe and result==true
                                    acquiringVehicle=nil
                                    acquiring=false
                                    if not safe then  end
                                end)
                            end
                        else
                            local p=GetEntityCoords(v);local velocity=GetEntityVelocity(v)
                            if mode==1 then
                                if now>=data.nextImpulse then
                                    data.nextImpulse=now+650+math.random(0,350)
                                    local angle=math.random()*math.pi*2;local speed=math.random(20,34)
                                    SetEntityVelocity(v,math.cos(angle)*speed,math.sin(angle)*speed,math.random(4,10)+0.0)
                                    SetEntityAngularVelocity(v,(math.random()-.5)*2,(math.random()-.5)*2,(math.random()-.5)*4)
                                    StartVehicleHorn(v,180,'HELDDOWN',false)
                                end
                            else
                                local origin=mode==3 and center or data.origin
                                local dx,dy=origin.x-p.x,origin.y-p.y
                                local radius=math.sqrt(dx*dx+dy*dy)
                                local nx,ny=0.0,1.0
                                if radius>.1 then nx,ny=dx/radius,dy/radius end
                                local tx,ty,tz
                                if mode==3 then
                                    local pull=math.max(-12,math.min(18,(radius-22)*1.4))
                                    tx=-ny*22+nx*pull;ty=nx*22+ny*pull
                                    local altitude=origin.z+7+math.sin(now*.001+data.phase)*2
                                    tz=math.max(-6,math.min(10,(altitude-p.z)*2.5))
                                else
                                    local a=now*.00065+data.phase
                                    local goalX=origin.x+math.cos(a)*18
                                    local goalY=origin.y+math.sin(a*2)*12
                                    local gx,gy=goalX-p.x,goalY-p.y
                                    local len=math.sqrt(gx*gx+gy*gy)
                                    local speed=math.min(14,len*1.3)
                                    tx=len>.1 and gx/len*speed or 0;ty=len>.1 and gy/len*speed or 0
                                    tz=velocity.z
                                end
                                local blend=1-math.exp(-(mode==3 and 3.5 or 2.0)*dt)
                                SetEntityVelocity(v,velocity.x+(tx-velocity.x)*blend,velocity.y+(ty-velocity.y)*blend,
                                    mode==3 and velocity.z+(tz-velocity.z)*blend or tz)
                                SetEntityAngularVelocity(v,0.0,0.0,mode==3 and .8 or 0.0)
                            end
                        end
                    end
                    Wait(50)
                end
            end)
            -- Ne supprimer aucun PNJ existant et ne couper aucun moteur lors de l'arret.
            if token==serial then Menu.State.fuckAllCarsActive=false end
            if not ok then ;ShowDynastyNotification('[ CARS ] Erreur : voir F8') end
        end)
    end
end

function Menu.Helpers.isPlayerAttached(id)
    if not id then return false end
    if attachedPlayers[id] and DoesEntityExist(attachedPlayers[id]) then
        return true
    else
        if attachedPlayers[id] then
            attachedPlayers[id] = nil
            originalCoords[id] = nil
        end
        return false
    end
end

function Menu.Actions.DetachPlayer(id)
    if not id then return end

    if attachedPlayers[id] then
        local ped = attachedPlayers[id]
        if DoesEntityExist(ped) then
            SetEntityCollision(ped, true, true)
        end

        if originalCoords[id] then
            local success = pcall(function()
                SetEntityCoords(ped, originalCoords[id].x, originalCoords[id].y, originalCoords[id].z, false, false, false, true)
            end)
            if not success then
                local myCoords = GetEntityCoords(PlayerPedId())
                SetEntityCoords(ped, myCoords.x, myCoords.y, myCoords.z + 2.0, false, false, false, true)
            end
        end
    end

    attachedPlayers[id] = nil
    originalCoords[id] = nil
    -- Notification removed
end

Menu.State.spectateActive = false

function Menu.Actions.AttachPlayerToMe(id)
    if not id then return end

    local ped = GetPlayerPed(id)
    if DoesEntityExist(ped) then
        if attachedPlayers[id] then
            Menu.Actions.DetachPlayer(id)
        else
            attachedPlayers[id] = ped
            originalCoords[id] = GetEntityCoords(ped)

            SetEntityCollision(ped, false, false)

            -- Note: position updates are handled by the global attachment thread (see CreateThread near line 7880).
            -- Creating a second thread here caused double SetEntityCoordsNoOffset calls every frame.

            -- Notification removed
        end
    end
end

function Menu.Actions.ToggleAttachPlayer()
    if not selectedPlayer then return end

    if Menu.Helpers.isPlayerAttached(selectedPlayer.id) then
        Menu.Actions.DetachPlayer(selectedPlayer.id)
    else
        Menu.Actions.AttachPlayerToMe(selectedPlayer.id)
    end
end

Menu.State.punchAllRadiusIdx=2
Menu.State.punchAllBusy=false
function Menu.Actions.CleanupPunchAll(run)
    run=run or Menu.State.punchAllRun
    if not run then return end
    run.cancelled=true
    for _,target in ipairs(run.targets or {}) do
        if attachedPlayers[target.id]==target.ped then
            attachedPlayers[target.id]=nil;originalCoords[target.id]=nil
            if DoesEntityExist(target.ped) then
                pcall(SetEntityCollision,target.ped,not target.collisionDisabled,true)
            end
        end
    end
    if Menu.State.punchAllRun==run then
        Menu.State.punchAllRun=nil;Menu.State.punchAllBusy=false
    end
end
function Menu.Actions.PunchAll()
    if Menu.State.soloSessionActive or Menu.State.soloSessionFullInvisActive then
        ShowDynastyNotification('Punch All: desactive en Solo Session')
        return false
    end
    if Menu.State.punchAllBusy then ShowDynastyNotification('Punch All busy');return false end
    local me=PlayerPedId()
    if not DoesEntityExist(me) or IsPedDeadOrDying(me,true) or IsPedInAnyVehicle(me,false) then
        ShowDynastyNotification('Punch All unavailable');return false
    end
    local radii={10,25,50,100,200}
    local radius=radii[Menu.State.punchAllRadiusIdx or 2] or 25
    local origin=GetEntityCoords(me)
    local candidates={}
    for _,id in ipairs(GetActivePlayers()) do
        if id~=PlayerId() and NetworkIsPlayerActive(id) then
            local ped=GetPlayerPed(id)
            if ped and ped~=0 and DoesEntityExist(ped) and not attachedPlayers[id]
                and not IsPedDeadOrDying(ped,true) and not IsPedInAnyVehicle(ped,false) then
                local position=GetEntityCoords(ped)
                local dx,dy,dz=position.x-origin.x,position.y-origin.y,position.z-origin.z
                if dx*dx+dy*dy+dz*dz<=radius*radius then
                    candidates[#candidates+1]={id=id,ped=ped,position=position}
                end
            end
        end
    end
    if #candidates==0 then ShowDynastyNotification('Punch All: no players');return false end
    local run={targets={},owned={},ped=me,cancelled=false}
    Menu.State.punchAllRun=run;Menu.State.punchAllBusy=true
    CreateThread(function()
        local ok=pcall(function()
            if run.cancelled then return end
            local dict='melee@unarmed@streamed_core'
            RequestAnimDict(dict)
            local deadline=GetGameTimer()+3000
            while not HasAnimDictLoaded(dict) do
                if run.cancelled then return end
                if GetGameTimer()>=deadline then error('Animation unavailable') end
                Wait(0)
            end
            if run.cancelled or PlayerPedId()~=me or not DoesEntityExist(me) or IsPedDeadOrDying(me,true) or IsPedInAnyVehicle(me,false) then return end
            for i,target in ipairs(candidates) do
                if run.cancelled then return end
                if NetworkIsPlayerActive(target.id) and GetPlayerPed(target.id)==target.ped
                    and DoesEntityExist(target.ped) and not IsPedDeadOrDying(target.ped,true)
                    and not IsPedInAnyVehicle(target.ped,false) and not attachedPlayers[target.id] then
                    if type(GetEntityCollisionDisabled)=='function' then target.collisionDisabled=GetEntityCollisionDisabled(target.ped)==true end
                    -- Register ownership before modifying the entity so failures are cleaned up.
                    run.targets[#run.targets+1]=target
                    run.owned[target.id]=target.ped
                    attachedPlayers[target.id]=target.ped;originalCoords[target.id]=target.position
                    SetEntityCollision(target.ped,false,false)
                end
                if i%16==0 then Wait(0) end
            end
            if #run.targets==0 then return end
            Wait(750)
            if run.cancelled or PlayerPedId()~=me or not DoesEntityExist(me) or IsPedDeadOrDying(me,true) or IsPedInAnyVehicle(me,false) then return end
            local first=run.targets[1]
            if DoesEntityExist(first.ped) then TaskTurnPedToFaceEntity(me,first.ped,300) end
            Wait(300)
            if run.cancelled or PlayerPedId()~=me or not DoesEntityExist(me) or IsPedDeadOrDying(me,true) or IsPedInAnyVehicle(me,false) then return end
            ClearPedTasks(me)
            SetCurrentPedWeapon(me,GetHashKey('WEAPON_UNARMED'),true)
            TaskPlayAnim(me,dict,'heavy_hit_1',8.0,-8.0,900,0,0,false,false,false)
            Wait(400)
            if run.cancelled or PlayerPedId()~=me or not DoesEntityExist(me) or IsPedDeadOrDying(me,true) or IsPedInAnyVehicle(me,false) then return end
            local forward=GetEntityForwardVector(me)
            local processed=0
            for i,target in ipairs(run.targets) do
                if run.cancelled then return end
                if NetworkIsPlayerActive(target.id) and GetPlayerPed(target.id)==target.ped
                    and DoesEntityExist(target.ped) and attachedPlayers[target.id]==target.ped then
                    SetEntityCollision(target.ped,not target.collisionDisabled,true)
                    ApplyForceToEntity(target.ped,1,forward.x*20.0,forward.y*20.0,8.0,0.0,0.0,0.0,0,false,true,true,false,true)
                    SetPedToRagdoll(target.ped,3000,3000,0,false,false,false)
                    ApplyDamageToPed(target.ped,80,false)
                    processed=processed+1
                end
                if i%16==0 then Wait(0) end
            end
            ShowDynastyNotification('Punch All: '..processed)
            Wait(500)
        end)
        Menu.Actions.CleanupPunchAll(run)
        if not ok then ShowDynastyNotification(run.failure or 'Punch All failed') end
    end)
    return true
end

function Menu.Actions.AttachAndPunch(id)
    if not id then return end
    local ped = GetPlayerPed(id)
    if not DoesEntityExist(ped) then return end
    if attachedPlayers[id] then
        Menu.Actions.DetachPlayer(id)
        return
    end

    local myPed = PlayerPedId()

    attachedPlayers[id] = ped
    originalCoords[id] = GetEntityCoords(ped)
    SetEntityCollision(ped, false, false)

    CreateThread(function()
        -- Le thread global d'attachement ramÃ¨ne la cible devant nous (AK_DIST)
        Wait(250)

        local dict = "melee@unarmed@streamed_core"
        RequestAnimDict(dict)
        local timeout = GetGameTimer() + 3000
        while not HasAnimDictLoaded(dict) and GetGameTimer() < timeout do
            Wait(0)
        end

        TaskTurnPedToFaceEntity(myPed, ped, 300)
        Wait(300)

        ClearPedTasks(myPed)
        SetCurrentPedWeapon(myPed, GetHashKey("WEAPON_UNARMED"), true)
        TaskPlayAnim(myPed, dict, "heavy_hit_1", 8.0, -8.0, 900, 0, 0, false, false, false)
        Wait(400)

        SetEntityCollision(ped, true, true)
        local forward = GetEntityForwardVector(myPed)
        ApplyForceToEntity(ped, 1, forward.x * 20.0, forward.y * 20.0, 8.0, 0.0, 0.0, 0.0, 0, false, true, true, false, true)
        SetPedToRagdoll(ped, 3000, 3000, 0, false, false, false)
        ApplyDamageToPed(ped, 80, false)
        Wait(500)

        if DoesEntityExist(ped) then SetEntityCollision(ped, true, true) end
        attachedPlayers[id] = nil
        originalCoords[id] = nil
    end)
end

