-- ── SILENT KILL : attach + punch (basé sur AttachAndPunch) ────────────────
function Menu.Actions.SilentKillAttach(id)
    if not id then return end
    local ped = GetPlayerPed(id)
    if not DoesEntityExist(ped) then return end
    if attachedPlayers[id] then
        Menu.Actions.DetachPlayer(id)
    end

    local myPed = PlayerPedId()
    attachedPlayers[id] = ped
    originalCoords[id] = GetEntityCoords(ped)
    SetEntityCollision(ped, false, false)

    -- Watcher : clear sur mort, touche R, ou timeout 2s
    CreateThread(function()
        local deadline = GetGameTimer() + 2000
        repeat
            Wait(0)
        until IsEntityDead(ped)
            or not DoesEntityExist(ped)
            or IsDisabledControlJustPressed(0, 45) or IsControlJustPressed(0, 45)  -- R (reload)
            or GetGameTimer() > deadline

        -- Délai de 500ms après la mort avant de clear les tasks (évite l'animation instanée)
        Wait(500)
        ClearPedTasksImmediately(myPed)
        SetEntityCollision(ped, true, true)
        attachedPlayers[id] = nil
        originalCoords[id] = nil
    end)
end

