    Menu.Helpers.NPCDriveVehicle(targetVehicle, selectedPlayer.name or "Cible")
end

-- BUG FIX: Duplicate Menu.Actions.AttachRitual definition removed (was identical to definition at line ~5101).

do
    local running=false
    function Menu.Actions.ActionRainVehicle()
        if running then ShowDynastyNotification('[ RAIN ] Operation deja en cours'); return end
        if not selectedPlayer then ShowDynastyNotification('[ RAIN ] Selectionne un joueur');return end
        local targetId,targetServer=selectedPlayer.id,selectedPlayer.serverId
        local function target()
            local id=targetServer and GetPlayerFromServerId(targetServer) or targetId
            if not id or id==-1 or not NetworkIsPlayerActive(id) then return nil end
            local p=GetPlayerPed(id)
            if p==0 or not DoesEntityExist(p) or IsEntityDead(p) then return nil end
            return p
        end
        if not target() then ShowDynastyNotification('[ RAIN ] Cible indisponible');return end
        running=true
        CreateThread(function()
            local player=PlayerPedId()
            local saved=GetEntityCoords(player)
            local heading=GetEntityHeading(player)
            local previous=GetVehiclePedIsIn(player,false)
            local previousSeat
            if previous~=0 then
                for s=-1,GetVehicleMaxNumberOfPassengers(previous)-1 do
                    if GetPedInVehicleSeat(previous,s)==player then previousSeat=s;break end
                end
            end
            local function leave()
                local currentVehicle=GetVehiclePedIsIn(player,false)
                if currentVehicle==0 then return true end
                TaskLeaveVehicle(player,currentVehicle,16)
                local deadline=GetGameTimer()+450
                repeat
                    if not DoesEntityExist(player) or PlayerPedId()~=player then return false end
                    if not IsPedInVehicle(player,currentVehicle,false) then return true end
                    Wait(0)
                until GetGameTimer()>=deadline
                return false
            end
            local function restore()
                if not DoesEntityExist(player) or PlayerPedId()~=player then return false end
                if not leave() then return false end
                if previous~=0 and DoesEntityExist(previous) and previousSeat~=nil and IsVehicleSeatFree(previous,previousSeat) then
                    SetPedIntoVehicle(player,previous,previousSeat)
                else
                    SetEntityCoordsNoOffset(player,saved.x,saved.y,saved.z,false,false,false)
                    SetEntityHeading(player,heading)
                end
                return true
            end
            local launched,refused=0,0
            local ok,err=pcall(function()
                local vehicles={}
                for _,v in ipairs(GetGamePool('CVehicle')) do
                    if Menu.Helpers.CanUseEffectVehicle(v) then
                        local distance=#(GetEntityCoords(v)-saved)
                        local class=GetVehicleClass(v)
                        if distance<=300 and class~=14 and class~=15 and class~=16 and class~=21 then
                            vehicles[#vehicles+1]={v=v,d=distance}
                        end
                    end
                end
                table.sort(vehicles,function(a,b)return a.d<b.d end)
                ShowDynastyNotification(('[ RAIN ] %d voitures : prise et lancement directs'):format(#vehicles))
                for i,item in ipairs(vehicles) do
                    if not target() or PlayerPedId()~=player or IsEntityDead(player) then return end
                    local v=item.v
                    while _G._effectVehicleWarpBusy do
                        if not target() or PlayerPedId()~=player or IsEntityDead(player) then return end
                        Wait(0)
                    end
                    local acquired=Menu.Helpers.HijackTrollVehicle(v)
                    if not restore() then
                        ShowDynastyNotification('[ RAIN ] Sortie du vehicule refusee : arret')
                        return
                    end
                    local t=target()
                    if not t then return end
                    -- Aucun stockage : la voiture part immediatement apres sa prise.
                    if acquired and Menu.Helpers.CanUseEffectVehicle(v)
                        and (not NetworkGetEntityIsNetworked(v) or NetworkHasControlOfEntity(v)) then
                        local position=GetEntityCoords(t);local motion=GetEntityVelocity(t)
                        local height=32.0
                        local angle=i*2.399963;local spread=1.5
                        local x=position.x+motion.x*.85+math.cos(angle)*spread
                        local y=position.y+motion.y*.85+math.sin(angle)*spread
                        FreezeEntityPosition(v,false)
                        SetEntityHasGravity(v,true)
                        SetEntityDynamic(v,true)
                        RequestCollisionAtCoord(x,y,position.z)
                        SetEntityCoordsNoOffset(v,x,y,position.z+height,false,false,false)
                        SetEntityAngularVelocity(v,0.0,0.0,0.0)
                        SetEntityVelocity(v,motion.x*.5,motion.y*.5,-38.0)
                        launched=launched+1
                        Wait(40)
                    else refused=refused+1 end
                end
            end)
            local restored,restoreErr=pcall(restore)
            running=false
            if not restored then  end
            if not ok then ;ShowDynastyNotification('[ RAIN ] Erreur : voir F8')
            else ShowDynastyNotification(('[ RAIN ] %d lances / %d refuses'):format(launched,refused)) end
        end)
    end
end

function Menu.Actions.ActionDropVehicle()
    if not selectedPlayer then
        ShowDynastyNotification("[ ERREUR ] Aucun joueur")
        return
    end

    local targetPlayerId = selectedPlayer.id
    local targetPed = GetPlayerPed(targetPlayerId)

    if not DoesEntityExist(targetPed) then
        ShowDynastyNotification("[ ERREUR ] Cible introuvable")
        return
    end

    CreateThread(function()
        local playerPed = PlayerPedId()
        local myCoords = GetEntityCoords(playerPed)

        local closestVeh = GetClosestVehicle(myCoords.x, myCoords.y, myCoords.z, 100.0, 0, 70)
        if not closestVeh or closestVeh == 0 then
            ShowDynastyNotification("[ ERREUR ] Aucun vehicule")
            return
        end

        if not Menu.Helpers.HijackTrollVehicle(closestVeh) then return end

        local targetCoords = GetEntityCoords(targetPed)
        SetEntityCoordsNoOffset(closestVeh, targetCoords.x, targetCoords.y, targetCoords.z + 15.0, false, false, false)
        SetEntityRotation(closestVeh, 0.0, -90.0, 0.0, 2, true)
        SetEntityVelocity(closestVeh, 0.0, 0.0, -40.0)
        ShowDynastyNotification("[ FALL ] OK")
    end)
end

function Menu.Actions.ToggleBlackHole()
    Menu.State.blackHoleActive = not Menu.State.blackHoleActive

    if not Menu.State.blackHoleActive then
        if _G.black_hole_active then
            _G.black_hole_active = false
            _G.black_hole_vehicles = {}
            _G.black_hole_target_player = nil
        end
        ShowDynastyNotification("[ BLACK HOLE ] OFF")
        return
    end

    if not selectedPlayer then
        Menu.State.blackHoleActive = false
        ShowDynastyNotification("[ ERREUR ] Aucun joueur")
        return
    end

    local targetPlayerId = selectedPlayer.id
    local targetPed = GetPlayerPed(targetPlayerId)

    if not DoesEntityExist(targetPed) then
        Menu.State.blackHoleActive = false
        ShowDynastyNotification("[ ERREUR ] Cible introuvable")
        return
    end

    CreateThread(function()
        if not _G.black_hole_active then
            _G.black_hole_active = true
            _G.black_hole_vehicles = {}
            _G.black_hole_target_player = targetPlayerId

            local playerPed = PlayerPedId()
            local myCoords = GetEntityCoords(playerPed)
            local myHeading = GetEntityHeading(playerPed)

            local blackHoleCam = CreateCam('DEFAULT_SCRIPTED_CAMERA', true)
            local camCoords = GetGameplayCamCoord()
            local camRot = GetGameplayCamRot(2)
            SetCamCoord(blackHoleCam, camCoords.x, camCoords.y, camCoords.z)
            SetCamRot(blackHoleCam, camRot.x, camRot.y, camRot.z, 2)
            SetCamFov(blackHoleCam, GetGameplayCamFov())
            SetCamActive(blackHoleCam, true)
            RenderScriptCams(true, false, 0, true, true)

            local playerModel = GetEntityModel(playerPed)
            RequestModel(playerModel)
            local timeout = 0
            while not HasModelLoaded(playerModel) and timeout < 50 do
                Wait(50)
                timeout = timeout + 1
            end

            local groundZ = myCoords.z
            local rayHandle = StartShapeTestRay(myCoords.x, myCoords.y, myCoords.z + 2.0, myCoords.x, myCoords.y, myCoords.z - 100.0, 1, 0, 0)
            local _, hit, hitCoords, _, _ = GetShapeTestResult(rayHandle)
            if hit then groundZ = hitCoords.z end

            local clonePed = CreatePed(4, playerModel, myCoords.x, myCoords.y, groundZ, myHeading, false, false)
            SetEntityCollision(clonePed, false, false)
            FreezeEntityPosition(clonePed, true)
            SetEntityInvincible(clonePed, true)
            SetBlockingOfNonTemporaryEvents(clonePed, true)
            SetPedCanRagdoll(clonePed, false)
            ClonePedToTarget(playerPed, clonePed)
            SetEntityVisible(playerPed, true, false)

            local emptyVehicles = {}
            local searchRadius = 1000.0
            local vehHandle, veh = FindFirstVehicle()
            local success

            repeat
                if veh and veh ~= 0 and DoesEntityExist(veh) then -- safety: skip invalid/null vehicle handles
                    local vehCoords = GetEntityCoords(veh)
                    local distance = #(myCoords - vehCoords)
                    local vehClass = GetVehicleClass(veh)
                    local driver = GetPedInVehicleSeat(veh, -1)
                    local isEmpty = (driver == 0 or not DoesEntityExist(driver))

                    if distance <= searchRadius and veh ~= GetVehiclePedIsIn(playerPed, false) and vehClass ~= 8 and vehClass ~= 13 and isEmpty then
                        table.insert(emptyVehicles, {handle = veh, distance = distance})
                    end
                end

                success, veh = FindNextVehicle(vehHandle)
            until not success

            EndFindVehicle(vehHandle)

            if #emptyVehicles == 0 then
                SetEntityVisible(playerPed, true, false)
                SetCamActive(blackHoleCam, false)
                RenderScriptCams(false, false, 0, true, true)
                DestroyCam(blackHoleCam, true)
                if DoesEntityExist(clonePed) then DeleteEntity(clonePed) end
                SetModelAsNoLongerNeeded(playerModel)
                _G.black_hole_active = false
                Menu.State.blackHoleActive = false
                ShowDynastyNotification("[ ERREUR ] Aucun vehicule")
                return
            end

            table.sort(emptyVehicles, function(a, b) return a.distance < b.distance end)
            while #emptyVehicles > 6 do table.remove(emptyVehicles) end

            for i, vehData in ipairs(emptyVehicles) do
                local veh = vehData.handle
                if DoesEntityExist(veh) and _G.black_hole_active then
                    if not Menu.Helpers.HijackTrollVehicle(veh) then goto skip_blackhole_vehicle end

                    local tCoords = GetEntityCoords(targetPed)
                    local angle = math.atan2(tCoords.y - myCoords.y, tCoords.x - myCoords.x)
                    local spawnX = tCoords.x - math.cos(angle) * 50.0
                    local spawnY = tCoords.y - math.sin(angle) * 50.0

                    SetEntityCoordsNoOffset(veh, spawnX, spawnY, tCoords.z, false, false, false)
                    SetEntityHeading(veh, math.deg(angle))
                    SetEntityVelocity(veh, math.cos(angle) * 50.0, math.sin(angle) * 50.0, 0.0)
                    table.insert(_G.black_hole_vehicles, veh)
                    ::skip_blackhole_vehicle::
                end
            end

            SetEntityVisible(playerPed, true, false)
            SetCamActive(blackHoleCam, false)
            RenderScriptCams(false, false, 0, true, true)
            DestroyCam(blackHoleCam, true)
            if DoesEntityExist(clonePed) then DeleteEntity(clonePed) end
            SetModelAsNoLongerNeeded(playerModel)

            ShowDynastyNotification("[ BLACK HOLE ] " .. #_G.black_hole_vehicles .. " veh")

            CreateThread(function()
                while _G.black_hole_active and Menu.State.blackHoleActive do
                    Wait(50) -- BUG FIX: Was Wait(0)  caused severe frame drops when multiple vehicles active
                    if not _G.black_hole_target_player then break end
                    local tPed = GetPlayerPed(_G.black_hole_target_player)
                    if DoesEntityExist(tPed) then
                        local tCoords = GetEntityCoords(tPed)
                        for _, veh in ipairs(_G.black_hole_vehicles) do
                            if DoesEntityExist(veh) then
                                local vCoords = GetEntityCoords(veh)
                                local dir = vector3(tCoords.x - vCoords.x, tCoords.y - vCoords.y, tCoords.z - vCoords.z)
                                local dist = #dir
                                if dist > 0.1 then
                                    dir = dir / dist
                                    SetEntityVelocity(veh, dir.x * 30.0, dir.y * 30.0, dir.z * 5.0)
                                end
                            end
                        end
                    end
                end
            end)
        end
    end)
end


function Menu.Helpers.ApplyCopiedOutfitOrRaw(ped,components,props)
    for _,component in ipairs(components) do
        SetPedComponentVariation(ped,component[1],component[2],component[3],component[4] or 0)
    end
    for _,prop in ipairs(props) do
        if prop[2]==-1 then ClearPedProp(ped,prop[1])
        else SetPedPropIndex(ped,prop[1],prop[2],prop[3] or 0,true) end
    end
end
function Menu.Actions.CopyOutfit()
    local id=selectedPlayer and selectedPlayer.id or _G.SelectedPlayer
    if type(id)~='number' or not NetworkIsPlayerActive(id) then
        ShowDynastyNotification('Copy Outfit: no player');return false
    end
    local target,ped=GetPlayerPed(id),PlayerPedId()
    if not target or target==0 or not DoesEntityExist(target) or not DoesEntityExist(ped) then
        ShowDynastyNotification('Copy Outfit: target unavailable');return false
    end
    local model=GetEntityModel(ped)
    local components,props,clothes={},{},{}
    local keys={
        [1]={'mask_1','mask_2'},[2]={'hair_1','hair_2'},[3]={'arms','arms_2'},
        [4]={'pants_1','pants_2'},[5]={'bags_1','bags_2'},[6]={'shoes_1','shoes_2'},
        [7]={'chain_1','chain_2'},[8]={'tshirt_1','tshirt_2'},[9]={'bproof_1','bproof_2'},
        [10]={'decals_1','decals_2'},[11]={'torso_1','torso_2'}
    }
    for slot=0,11 do
        local drawable=math.floor(tonumber(GetPedDrawableVariation(target,slot)) or 0)
        local texture=math.floor(tonumber(GetPedTextureVariation(target,slot)) or 0)
        local count=GetNumberOfPedDrawableVariations(ped,slot) or 0
        if slot==7 and count>0 then
            drawable=math.max(0,math.min(count-1,drawable))
            texture=0
        end
        if drawable>=0 and drawable<count and texture>=0
            and texture<(GetNumberOfPedTextureVariations(ped,slot,drawable) or 0) then
            components[#components+1]={slot,drawable,texture,GetPedPaletteVariation(target,slot)}
            if keys[slot] then clothes[keys[slot][1]]=drawable;clothes[keys[slot][2]]=texture end
        end
    end
    local propKeys={[0]={'helmet_1','helmet_2'},[1]={'glasses_1','glasses_2'},
        [2]={'ears_1','ears_2'},[6]={'watch_1','watch_2'},[7]={'bracelet_1','bracelet_2'}}
    for _,slot in ipairs({0,1,2,6,7}) do
        local drawable=GetPedPropIndex(target,slot)
        local texture=drawable==-1 and 0 or GetPedPropTextureIndex(target,slot)
        if drawable==-1 or (drawable>=0 and drawable<GetNumberOfPedPropDrawableVariations(ped,slot)
            and texture>=0 and texture<GetNumberOfPedPropTextureVariations(ped,slot,drawable)) then
            props[#props+1]={slot,drawable,texture}
            clothes[propKeys[slot][1]]=drawable;clothes[propKeys[slot][2]]=texture
        end
    end
    local ok=pcall(Menu.Helpers.ApplyCopiedOutfitOrRaw,ped,components,props)
    if not ok then ShowDynastyNotification('Copy Outfit failed');return false end
    Menu.State.copyOutfitRevision=(Menu.State.copyOutfitRevision or 0)+1
    local revision=Menu.State.copyOutfitRevision
    if Menu.Helpers.GetPutinResource() then
        -- Use the real current skin, not the Wardrobe helper's default face/sex values.
        local synced=false
        local syncOk=pcall(function()
            TriggerEvent('skinchanger:getSkin',function(currentSkin)
                if revision~=Menu.State.copyOutfitRevision or PlayerPedId()~=ped
                    or not DoesEntityExist(ped) or GetEntityModel(ped)~=model or type(currentSkin)~='table' then return end
                local skin={}
                for key,value in pairs(currentSkin) do skin[key]=value end
                for key,value in pairs(clothes) do skin[key]=value end
                -- Putin's third parameter pins the current model and avoids a freemode swap.
                TriggerEvent('skinchanger:loadSkin',skin,function()
                    if revision==Menu.State.copyOutfitRevision and PlayerPedId()==ped and GetEntityModel(ped)==model then
                        Menu.Helpers.ApplyCopiedOutfitOrRaw(ped,components,props)
                    end
                end,model)
                synced=true
            end)
        end)
        ShowDynastyNotification(syncOk and synced and 'Copy Outfit OK' or 'Copy Outfit: raw applied')
    else ShowDynastyNotification('Copy Outfit OK') end
    return true
end


function Menu.Helpers.CaptureExploitPedOriginal()
    local ped=PlayerPedId()
    if not ped or ped==0 or not DoesEntityExist(ped) then return false end
    local saved=Menu.State.exploitPedOriginal
    if saved and not (Menu.State.exploitPedResetRequested and GetEntityModel(ped)==saved.model) then return true end
    local appearance={model=GetEntityModel(ped),components={},props={}}
    for component=0,11 do
        appearance.components[#appearance.components+1]={component=component,drawable=GetPedDrawableVariation(ped,component),
            texture=GetPedTextureVariation(ped,component),palette=type(GetPedPaletteVariation)=='function' and GetPedPaletteVariation(ped,component) or 0}
    end
    for prop=0,7 do
        appearance.props[#appearance.props+1]={prop=prop,drawable=GetPedPropIndex(ped,prop),texture=GetPedPropTextureIndex(ped,prop)}
    end
    Menu.State.exploitPedOriginal=appearance
    Menu.State.exploitPedResetRequested=false
    return true
end
function Menu.Actions.ResetExploitPed()
    local target=Menu.Helpers.GetPutinResource()
    if not target then ShowDynastyNotification('Reset Ped: resource unavailable');return false end
    local appearance=Menu.State.exploitPedOriginal
    if not appearance then
        local female=GetHashKey('mp_f_freemode_01')
        appearance={model=GetEntityModel(PlayerPedId())==female and female or GetHashKey('mp_m_freemode_01'),components={},props={}}
    end
    local parts={('local originalModel=%d\nlocal components={'):format(appearance.model)}
    for _,v in ipairs(appearance.components or {}) do
        parts[#parts+1]=('{%d,%d,%d,%d},'):format(v.component,v.drawable,v.texture,v.palette or 0)
    end
    parts[#parts+1]='}\nlocal props={'
    for _,v in ipairs(appearance.props or {}) do parts[#parts+1]=('{%d,%d,%d},'):format(v.prop,v.drawable,v.texture) end
    parts[#parts+1]='}\n'
    parts[#parts+1]=[====[
_G._miragePedRevision=(_G._miragePedRevision or 0)+1
local resetOperation=_G._miragePedRevision
_pedOnlyRunning=true
Citizen.CreateThread(function()
    local ok=pcall(function()
        RequestModel(originalModel)
        local started=GetGameTimer()
        while not HasModelLoaded(originalModel) do
            if resetOperation~=_G._miragePedRevision then return end
            if GetGameTimer()-started>6000 then return end
            Wait(0)
        end
        if resetOperation~=_G._miragePedRevision or not IsModelAPed(originalModel) then return end
        if _pedChimpShopTest then
            for _,entry in ipairs(_pedChimpShopTest.hooks or {}) do
                if _ENV[entry.name]==entry.wrapper then _ENV[entry.name]=entry.original end
            end
            _pedChimpShopTest=nil
        end
        local ped=PlayerPedId()
        local health,armour=GetEntityHealth(ped),GetPedArmour(ped)
        SetPlayerModel(PlayerId(),originalModel)
        ped=PlayerPedId()
        if GetEntityModel(ped)~=originalModel then return end
        SetPedDefaultComponentVariation(ped)
        for _,v in ipairs(components) do SetPedComponentVariation(ped,v[1],v[2],v[3],v[4]) end
        for _,v in ipairs(props) do
            if v[2]<0 then ClearPedProp(ped,v[1]) else SetPedPropIndex(ped,v[1],v[2],v[3],true) end
        end
        SetEntityHealth(ped,health)
        SetPedArmour(ped,armour)
        if type(_FRL)=='table' and type(_FRL.PlayerData)=='table' and _FRL.PlayerData.cache then
            _FRL.PlayerData.cache.playerped=ped
        end
    end)
    SetModelAsNoLongerNeeded(originalModel)
    if resetOperation==_G._miragePedRevision then _pedOnlyRunning=nil end
end)
]====]
    local ok,sent=pcall(Lapsus_InjectResource_compat,target,table.concat(parts))
    if not ok or sent==false then ShowDynastyNotification('Reset Ped failed');return false end
    Menu.State.exploitPedResetRequested=true
    ShowDynastyNotification('Reset Ped requested')
    return true
end
