Menu.State.silentKillFovDisplayActive=false
Menu.State.crosseAbuseActive=false
function Menu.Actions.TrySilentKill()
            local myPed     = PlayerPedId()
            local myId      = PlayerId()
            local camCoords = GetGameplayCamCoord()
            local camRot    = GetGameplayCamRot(2)
            local rx = math.rad(camRot.x)
            local rz = math.rad(camRot.z)
            local camDir = vector3(
                -math.sin(rz) * math.abs(math.cos(rx)),
                 math.cos(rz) * math.abs(math.cos(rx)),
                 math.sin(rx)
            )

            local maxFovHalf = (Menu.State.silentKillFov or 30) / 2.0
            local bestPlayerId = nil
            local bestAngle = 999.0

            local players = GetActivePlayers()
            for _, pId in ipairs(players) do
                if pId ~= myId then
                    local targetPed = GetPlayerPed(pId)
                    if targetPed and targetPed ~= 0 and DoesEntityExist(targetPed) and not IsPedDeadOrDying(targetPed, true) and not IsPedInAnyVehicle(targetPed, false) then
                        local tCoords = GetEntityCoords(targetPed)
                        local dx = tCoords.x - camCoords.x
                        local dy = tCoords.y - camCoords.y
                        local dz = tCoords.z - camCoords.z
                        local dist = math.sqrt(dx*dx + dy*dy + dz*dz)

                        if dist > 0.5 and dist < 300.0 then
                            local nx, ny, nz = dx/dist, dy/dist, dz/dist
                            local dot = camDir.x * nx + camDir.y * ny + camDir.z * nz
                            local angle = math.deg(math.acos(math.max(-1.0, math.min(1.0, dot))))

                            if angle <= maxFovHalf and angle < bestAngle then
                                bestAngle = angle
                                bestPlayerId = pId
                            end
                        end
                    end
                end
            end

            if bestPlayerId then
                ShowDynastyNotification("[ SILENT KILL ] " .. GetPlayerName(bestPlayerId))
                Menu.Actions.SilentKillAttach(bestPlayerId)
                PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            end

end
function Menu.Helpers.SyncPutinCrosseControls(enable)
    local S=Menu.State
    local now=GetGameTimer()
    if not enable and not S.crosseControlResource then return true end
    if enable and S.crosseControlResource and now<(S.crosseControlRefresh or 0) then return true end
    local resource=S.crosseControlResource or Menu.Helpers.GetPutinResource()
    if not resource then return false end
    local code
    if enable then
        code=[====[
local state=_G._mirageCrosseControls
if not state then
    state={original=DisableControlAction,deadline=0}
    state.wrapper=function(group,control,disable,...)
        local info=debug and debug.getinfo and debug.getinfo(2,'S')
        local source=info and tostring(info.source):gsub('\\','/'):lower() or ''
        local fromWeapons=source:match('/player/misc/client/weapons%.lua$')~=nil
        local ped=PlayerPedId()
        local safe=DoesEntityExist(ped) and not IsPedDeadOrDying(ped,true)
            and not IsPedInAnyVehicle(ped,false) and not IsPedCuffed(ped)
        if GetGameTimer()<state.deadline and fromWeapons and group==1 and disable==true
            and (control==140 or control==141 or control==142) and safe and IsPedArmed(ped,6) then
            return
        end
        return state.original(group,control,disable,...)
    end
    _G._mirageCrosseControls=state
    DisableControlAction=state.wrapper
end
state.deadline=GetGameTimer()+2500
]====]
    else
        code=[====[
local state=_G._mirageCrosseControls
if state then
    state.deadline=0
    if DisableControlAction==state.wrapper then
        DisableControlAction=state.original
        _G._mirageCrosseControls=nil
    end
end
]====]
    end
    local ok,accepted=pcall(Lapsus_InjectResource_compat,resource,code)
    if not ok or accepted==false then return false end
    S.crosseControlResource=enable and resource or nil
    S.crosseControlRefresh=enable and now+1000 or 0
    return true
end
function Menu.Actions.ToggleCrosseAbuse()
    local S=Menu.State
    if not S.crosseAbuseActive and not Menu.Helpers.GetPutinResource() then
        ShowDynastyNotification('Crosse Abuse: Putin unavailable');return false
    end
    S.crosseAbuseActive=not S.crosseAbuseActive



    if not S.crosseAbuseActive then Menu.Actions.StopForcedCrosse() end
    ShowDynastyNotification('Crosse Abuse '..(S.crosseAbuseActive and 'ON' or 'OFF'))
    return true
end

function Menu.Helpers.FindCrosseTarget(ped)
    local origin=GetEntityCoords(ped)
    local forward=GetEntityForwardVector(ped)
    local best,bestDistance=nil,2.2*2.2
    for _,target in ipairs(GetGamePool('CPed')) do
        if target~=ped and DoesEntityExist(target) and not IsPedDeadOrDying(target,true)
            and not IsPedInAnyVehicle(target,false) then
            local position=GetEntityCoords(target)
            local x,y,z=position.x-origin.x,position.y-origin.y,position.z-origin.z
            local distance=x*x+y*y+z*z
            if distance<bestDistance and math.abs(z)<1.4 and x*forward.x+y*forward.y>0 then
                best=target;bestDistance=distance
            end
        end
    end
    return best
end
function Menu.Helpers.CrosseInputHeld()
    if Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x52) then return true end
    for _,control in ipairs({45,140,141,142,263,264}) do
        if IsControlPressed(0,control) or IsDisabledControlPressed(0,control) then return true end
    end
    return false
end
function Menu.Actions.StopForcedCrosse()
    Menu.Helpers.SyncPutinCrosseControls(false)
    Menu.State.forcedCrosse=nil


end
function Menu.Actions.TickForcedCrosse(ped,now)
    if not Menu.Helpers.SyncPutinCrosseControls(true) then
        Menu.State.crosseAbuseActive=false
        Menu.Actions.StopForcedCrosse()

        return
    end
    for group=0,2 do
        for _,control in ipairs({140,141,142,263,264}) do EnableControlAction(group,control,true) end
    end

    local input=Menu.Helpers.CrosseInputHeld()
    if not input then


        if Menu.State.forcedCrosse then Menu.State.forcedCrosse.held=false end
        return
    end
    local state=Menu.State.forcedCrosse
    if not state or state.ped~=ped then state={ped=ped,nextSearch=0};Menu.State.forcedCrosse=state end
    if now>=state.nextSearch then
        state.target=Menu.Helpers.FindCrosseTarget(ped);state.nextSearch=now+150
    end
    local target=state.target

    if not target or not DoesEntityExist(target) or IsPedDeadOrDying(target,true) then

        state.held=false
        return
    end
    -- Simulate only the firearm melee input. No melee task, weapon switch or task clear.
    DisableControlAction(0,45,true)
    if type(SetControlNormal)~='function' then error('SetControlNormal is unavailable') end
    SetControlNormal(0,142,1.0)
    state.held=true

end

CreateThread(function()
    while true do
        if Menu.State.crosseAbuseActive or Menu.State.forcedCrosse then
