            else Menu.Actions.StopForcedCrosse() end
            Wait(0)
        else Wait(200) end
    end
end)

Menu.State.staffAbuseActive=false
function Menu.Actions.SetStaffAbuse(enable)
    enable=enable==true
    local ok,result=pcall(function()
        if not Lapsus or type(Lapsus.GetResources)~="function" or type(Lapsus.InjectResource)~="function" then error("API Lapsus indisponible.") end
        local target
        for _,name in ipairs(Lapsus.GetResources()) do
            if type(name)=="string" and name:lower()=="putin" then target=name;break end
        end
        if not target then error("Ressource Putin introuvable.") end
        local code=("local enabled=%s\n"):format(tostring(enable)) .. [====[
do
    local key='_mirageStaffWeaponsController'
    local previous=_G[key]
    if previous and type(previous.dispose)=='function' then previous.dispose() end
    if not enabled then return end
    if type(_FRL)~='table' or type(_FRL.ShowNotification)~='function'
        or type(SetCurrentPedWeapon)~='function' or type(GetSelectedPedWeapon)~='function' then
        ;return
    end
    local framework=_FRL
    local originalSet,originalNotify=SetCurrentPedWeapon,framework.ShowNotification
    local controller={active=true}
    local unarmed=GetHashKey('WEAPON_UNARMED')
    local function same(a,b)return type(a)=='number' and type(b)=='number' and a%4294967296==b%4294967296 end
    local function inRestrictedService()
        local data=framework.PlayerData
        local service=AdminSystem and AdminSystem.Service
        return data and service and service.enabled==true and data.group
            and data.group~='admin' and data.group~='elite' and data.group~='owner'
    end
    local setWrapper=function(ped,weapon,...)
        if controller.active and inRestrictedService() and ped==PlayerPedId() and same(weapon,unarmed) then
            local info=debug and type(debug.getinfo)=='function' and debug.getinfo(2,'f')
            local caller=info and info.func
            -- Once identified by its real notification, stop this specific routine before holstering.
            if caller and caller==controller.staffRoutine then
                controller.pending=nil
                return
            end
            local selected=GetSelectedPedWeapon(ped)
            if not same(selected,unarmed) and not same(selected,-2009644972) then
                controller.pending={ped=ped,weapon=selected,time=GetGameTimer(),caller=caller}
            end
        end
        return originalSet(ped,weapon,...)
    end
    local notifyWrapper=function(message,...)
        if controller.active and inRestrictedService() and message=="Vous ne pouvez pas sortir d'arme en étant en service" then
            local info=debug and type(debug.getinfo)=='function' and debug.getinfo(2,'f')
            local caller=info and info.func
            if caller and caller==controller.staffRoutine and not same(GetSelectedPedWeapon(PlayerPedId()),unarmed) then return end
            local pending=controller.pending
            controller.pending=nil
            if pending and pending.ped==PlayerPedId() and (GetGameTimer()-pending.time)%4294967296<=100 then
                if caller and caller==pending.caller then
                    controller.staffRoutine=caller
                elseif not controller.identificationErrorReported then
                    controller.identificationErrorReported=true
                    
                end
                -- Restore at most the first identification pass; later passes never switch weapons.
                if same(GetSelectedPedWeapon(pending.ped),unarmed) then
                    local ok,err=pcall(originalSet,pending.ped,pending.weapon,true)
                    if not ok and not controller.errorReported then
                        controller.errorReported=true
                        
                    end
                end
                if same(GetSelectedPedWeapon(pending.ped),pending.weapon) then return end
            end
        end
        return originalNotify(message,...)
    end
    function controller.dispose()
        controller.active=false;controller.pending=nil
        if SetCurrentPedWeapon==setWrapper then SetCurrentPedWeapon=originalSet end
        if framework.ShowNotification==notifyWrapper then framework.ShowNotification=originalNotify end
        if _G[key]==controller then _G[key]=nil end
    end
    SetCurrentPedWeapon=setWrapper
    framework.ShowNotification=notifyWrapper
    _G[key]=controller
end
]====]
        local sent,err=Lapsus.InjectResource(target,code)
        if sent==false then error(err or "Execution refusee par Lapsus.") end
        return true
    end)
    if not ok then
        ShowDynastyNotification('Staff Abuse failed')
        return false
    end
    Menu.State.staffAbuseActive=enable
    ShowDynastyNotification('Staff Abuse '..(enable and 'ON' or 'OFF'))
    return true
end


function ExecuteMenuAction(menu, index, listOverride)
    local menu = menu or Menu.State.currentMenu
    local index = index or Menu.State.selectedOption
    local fullList = listOverride

    if not fullList then
        fullList = Menu.Helpers.GetFullListForMenu(menu)
    end

    if (menu=='ONLINE' and Menu.State.onlineTab==4) or (menu=='TROLL' and Menu.State.trollTab==4) then
        local item=fullList and fullList[index]
        if type(item)=='table' and item.id=='punch_all' then Menu.Actions.PunchAll();return end
    end
    if menu=='SETTINGS_UTILITY' then
        local item=fullList and fullList[index]
        if type(item)=='table' and item.id=='move_ui' then
            Menu.Actions.SetUILayoutEditing(not Menu.State.nuiLayoutEditing)
            return
        elseif type(item)=='table' and item.id=='reset_ui_positions' then
            Menu.State.nuiLayoutReset=(Menu.State.nuiLayoutReset or 0)+1
            ShowDynastyNotification('UI positions reset')
            return
        end
    end
    if menu == "MAIN" then
        local choice = Menu.Data.Options.Main[index]
        Menu.State.menuLastSwitchTime = GetGameTimer() -- Sync lock on switch

        if choice == "Player" then
            Menu.State.mainRestoreOption = index
            Menu.State.currentMenu = "PLAYER"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
        elseif choice == "Online Menu" then
            Menu.State.mainRestoreOption = index
            Menu.State.currentMenu = "ONLINE"
            -- Restore persistent state if it exists
            if Menu.State.onlineRestoreOption then
                Menu.State.selectedOption = Menu.State.onlineRestoreOption
                Menu.State.startIndex = Menu.State.onlineRestoreStart or 1
            else
                Menu.State.selectedOption, Menu.State.startIndex = 1, 1
            end
        elseif choice == "Combat" then
            Menu.State.mainRestoreOption = index
            Menu.State.currentMenu = "COMBAT"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
        elseif choice == "Vehicle" then
            Menu.State.mainRestoreOption = index
            Menu.State.currentMenu = "VEHICLE"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
        elseif choice == "Weapon" then
            Menu.State.mainRestoreOption = index
            Menu.State.currentMenu = "WEAPON"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
        elseif choice == "Misc" then
            Menu.State.mainRestoreOption = index
            Menu.State.currentMenu = "MISC"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
        elseif choice == "Settings" then
            Menu.State.mainRestoreOption = index
            Menu.State.currentMenu = "SETTINGS"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
        end

    elseif menu == "ONLINE" then
        if Menu.State.onlineTab == 1 then
            local target = (listOverride or fullList)[index]
            if target then
                if target.id == "global_tp" then
                    local mode = target.options[target.valueIdx]
                    if mode == "To Player" then
                        Menu.Actions.TeleportToPlayer()
                    elseif mode == "To Me" then
                        if selectedPlayer then
                            -- Basic exploit attempt (usually needs entity control)
                            local ped = GetPlayerPed(selectedPlayer.id)
                            if DoesEntityExist(ped) then
                                local myCoords = GetEntityCoords(PlayerPedId())
                                SetEntityCoords(ped, myCoords.x, myCoords.y, myCoords.z, false, false, false, false)
                            end
                        end
                    elseif mode == "All To Me" then
                        local myCoords = GetEntityCoords(PlayerPedId())
                        local players = GetActivePlayers()
                        for i=1, #players do
                            local ped = GetPlayerPed(players[i])
                            if DoesEntityExist(ped) and players[i] ~= PlayerId() then
                                SetEntityCoords(ped, myCoords.x, myCoords.y, myCoords.z, false, false, false, false)
                            end
                        end
                        ShowDynastyNotification("[ MASSE ] TP en cours...")
                    end
                elseif target.id == "global_select" then
                    local mode = target.options[target.valueIdx]
                    if mode == "Select All" then
                        Menu.State.massActionActive = true
                        ShowDynastyNotification("[ MASSE ] ON")
                    elseif mode == "Unselect All" then
                        Menu.State.massActionActive = false
                        selectedPlayer = nil
                        ShowDynastyNotification("[ MASSE ] Deselectionnes")
                    elseif mode == "None" then
                        Menu.State.massActionActive = false
                        selectedPlayer = nil
                        ShowDynastyNotification("[ SELECTION ] Reset")
                    elseif mode == "Inverse" then
                        Menu.State.massActionActive = not Menu.State.massActionActive
                        ShowDynastyNotification("Mass Action: " .. (Menu.State.massActionActive and "ON" or "OFF"))
                    end
                elseif target.id == "global_type" then
                    local mode = target.options[target.valueIdx]
                    Menu.State.onlineTypeFilter = mode
                    Menu.State.selectedOption, Menu.State.startIndex = 1, 1
                    ShowDynastyNotification("Filter: " .. mode)
                elseif target.type == "separator" then
                    -- Ignore
                else
                    if selectedPlayer and target and selectedPlayer.serverId == target.serverId then
                        selectedPlayer = nil
                        ShowDynastyNotification("[ SELECTION ] Deselectionne")
                    else
                        selectedPlayer = target
                        ShowDynastyNotification("Target: " .. (target and target.name or "Unknown"))
                    end
                end
            end
        else
            local data = fullList[index]
            if not data or data.type == "separator" then return end

            -- Onglet 4 (All) : actions de masse sans joueur requis
            if Menu.State.onlineTab == 4 then
                if data.type == "action" or data.type == "toggle" then
                    if data.id == "broke_all" or data.state == "brokeAllActive" then
                        Menu.Actions.BrokeAllVehicles(150.0)
                    elseif data.state == "fuckAllCarsActive" or data.id == "fuck_all_cars" then
                        Menu.Actions.ToggleFuckAllCars()
                    elseif data.state == "launchAllSoloActive" then
                        Menu.Actions.LaunchAll(true)
                    elseif data.id == "launch_all" or data.state == "launchAllActive" then
                        Menu.Actions.LaunchAll()
                    elseif data.id == "kill_all" or data.state == "killAllActive" then
                        Menu.Actions.ToggleKillAll()
                    elseif data.state == "hardKillAllActive" then
                        Menu.Actions.ToggleHardKillAll()
                    elseif data.state == "killAllPnjActive" or data.id == "kill_all_pnj" then
                        Menu.Actions.ToggleKillAllPnj()
                    elseif data.state == "unlockAllVehicleActive" then
                        Menu.State.unlockAllVehicleActive = not Menu.State.unlockAllVehicleActive
                        ShowDynastyNotification("[ UNLOCK ] " .. (Menu.State.unlockAllVehicleActive and "ON" or "OFF"))
                    end
                elseif data.type == "selector" then
                    if data.id == "kill_all_selector" then
                        local idx = data.valueIdx or 1
                        if idx == 1 then Menu.Actions.ToggleKillAll()
                        elseif idx == 2 then Menu.Actions.ToggleHardKillAll()
                        elseif idx == 3 then Menu.Actions.ToggleKillAllPnj()
                        elseif idx == 4 then Menu.Actions.ToggleKillAllAura()
                        end
                    elseif data.id == "launch_all_selector" then
                        local idx = data.valueIdx or 1
                        if idx == 1 then Menu.Actions.LaunchAll(false)
                        elseif idx == 2 then Menu.Actions.LaunchAll(true)
                        end
                    elseif data.id == "fuck_all_cars_selector" then
                        local idx = data.valueIdx or 1
                        Menu.State.fuckAllCarsMode = idx
                        Menu.Actions.ToggleFuckAllCars(idx)
                    end
                end
                return
            end

            -- Onglets 2 et 3 : nÃ©cessitent un joueur sÃ©lectionnÃ©
            -- Exception: toggle-off de Attach Car ne nÃ©cessite pas de joueur sÃ©lectionnÃ©
            local canRunWithoutPlayer = (data.type == "toggle" and data.state == "attachCarActive" and Menu.State.attachCarActive) or (data.id == "reset_ped") or (data.id == "warp_veh_cam") or (data.id == "bug_vehicule_online")
            if not selectedPlayer and not canRunWithoutPlayer then
                ShowDynastyNotification("[ ERREUR ] Aucun joueur")
                PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                return
            end
            local data = fullList[index]
            if not data or data.type == "separator" then return end

            local function runAction(target)
                local oldSelected = selectedPlayer
                selectedPlayer = target

                local ok, err = pcall(function()
                    if data.type == "action" then
                        if data.id == "launch1" then Menu.Actions.LaunchPlayer()
                        elseif data.id == "launch2" then Menu.Actions.LunchPlayer2()
                        elseif data.id == "hard_launch" then Menu.Actions.HardLaunchPlayer()
                        elseif data.id == "tp_player" then Menu.Actions.TeleportToPlayer()
                        elseif data.id == "steal_outfit" then Menu.Actions.StealOutfit()
                        elseif data.id == "copy_outfit" then Menu.Actions.CopyOutfit()
                        elseif data.id == "reset_ped" then Menu.Actions.ResetPed()
                        elseif data.id == "npc_drive" then Menu.Actions.ActionNPCDrive()
                        elseif data.id == "broke_veh" then Menu.Actions.TrollBrokeAll()
                        elseif data.id == "bug_player" then Menu.Actions.BugPlayer()
                        elseif data.id == "fullbox" then Menu.Actions.AttachRitual()
                        elseif data.id == "ritual" then Menu.Actions.AttachRitual()
