        if type(wdata)=="table" and wdata.id=="spoof_weapon" then
            Menu.Actions.ToggleSpoofWeapon()
            return
        elseif type(wdata) == "table" and wdata.type == "give_weapon" then
            if not wdata.weapon then return end
            local hash = GetHashKey(wdata.weapon)
            local name = wdata.name
            -- Double-ENTREE : premier appui = alerte notif, deuxieme = give
            local now = GetGameTimer()
            if _giveWeaponPending and _giveWeaponPending.hash == hash and (now - _giveWeaponPending.time) < _giveWeaponPendingDelay then
                _giveWeaponPending = nil
                local ped = PlayerPedId()
                pcall(GiveWeaponToPed, ped, hash, 9999, false, true)
                ShowDynastyNotification("[ GIVE ] " .. name)
            else
                _giveWeaponPending = { hash = hash, name = name, time = now }
                ShowDynastyNotification("[ GIVE ] " .. name .. " Confirmer ?")
            end
            return
        elseif type(wdata) == "table" and wdata.type == "selector" and wdata.weapons then
            local idx = wdata.valueIdx or 1
            local weapHash = wdata.weapons[idx]
            local weapName = wdata.options[idx] or wdata.name
            if not weapHash then return end
            local hash = GetHashKey(weapHash)
            -- Double-ENTREE : premier appui = alerte notif, deuxieme = give
            local now = GetGameTimer()
            if _giveWeaponPending and _giveWeaponPending.hash == hash and (now - _giveWeaponPending.time) < _giveWeaponPendingDelay then
                _giveWeaponPending = nil
                local ped = PlayerPedId()
                pcall(GiveWeaponToPed, ped, hash, 9999, false, true)
                ShowDynastyNotification("[ GIVE ] " .. weapName)
            else
                _giveWeaponPending = { hash = hash, name = weapName, time = now }
                ShowDynastyNotification("[ GIVE ] " .. weapName .. " Confirmer ?")
            end
            return
        elseif type(wdata) == "table" and wdata.type == "attach" then
            if wdata.id == "none" or not wdata.weapHash or wdata.weapHash == 0 then return end
            local ped = PlayerPedId()
            local weapHash = wdata.weapHash
            local compHash = GetHashKey(wdata.id)
            local ok, has = pcall(HasPedGotWeaponComponent, ped, weapHash, compHash)
            if ok and has then
                pcall(RemoveWeaponComponentFromPed, ped, weapHash, compHash)
                ShowDynastyNotification("[ ARME ] " .. wdata.name .. ": Retire")
            else
                pcall(GiveWeaponComponentToPed, ped, weapHash, compHash)
                ShowDynastyNotification("[ ARME ] " .. wdata.name .. ": Equipe")
            end
            return
        elseif type(wdata) == "table" and wdata.type == "weapon_size" then
