                    "WEAPON_MICROSMG","WEAPON_SHOTGUN","WEAPON_PUMPSHOTGUN","WEAPON_RPG",
                    "WEAPON_GRENADELAUNCHER","WEAPON_MINIGUN","WEAPON_HEAVYSNIPER_MK2"
                }
                for _, wname in ipairs(allWeapons) do
                    local hash = GetHashKey(wname)
                    if HasPedGotWeapon(ped, hash, false) then
                        SetPedAmmo(ped, hash, 9999)
                    end
                end
            end)
            ShowDynastyNotification("[ WEAPON ] Munitions max")
        elseif type(wdata) == "table" and wdata.type == "toggle" then
            local st = wdata.state
            Menu.State[st] = not Menu.State[st]
            local on = Menu.State[st]
            ShowDynastyNotification("[ WEAPON ] " .. wdata.name .. ": " .. (on and "ON" or "OFF"))
            -- Menu.Helpers.SaveConfig()
            if st == "noReloadActive" and on then
                Citizen.CreateThread(function()
                    while Menu.State.noReloadActive do
