                -- Nettoyer le cache pour cette touche
                if _G.KeybindSelectorState then _G.KeybindSelectorState[item.bindKey] = nil end
                ShowDynastyNotification("[ BIND ] " .. removedLabel .. " supprime")
                PlaySoundFrontend(-1, "BACK", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                Menu.State.selectedOption = math.max(1, index - 1)
            end
        end

    elseif menu == "CONFIGS" then
        local configsList = Menu.Helpers.GetConfigsOptions()
        local choice = configsList[index]
        if choice == "Create new config..." then
            Citizen.CreateThread(function()
                local name = Menu.Helpers.PromptKeyboardInput("Nom de la config", "", 20)
                if name and name ~= "" then
                    name = name:gsub("[^a-zA-Z0-9_%-%s]", "")
                    if name ~= "" then
                        -- Verifier si le nom existe deja
                        local alreadyExists = Menu.CloudConfigs and Menu.CloudConfigs.profiles and Menu.CloudConfigs.profiles[name]
                        if alreadyExists then
                            local overwrite = Menu.Helpers.PromptConfirm("Config \"" .. name .. "\" existe deja ! Remplacer ?")
                            if not overwrite then
                                ShowDynastyNotification("[ CONFIG ] Annule")
                                return
                            end
                        end
                        Menu.Helpers.SaveConfigProfile(name)
                        Menu.State.selectedOption = 1
                        Menu.State.startIndex = 1
                    else
                        ShowDynastyNotification("[ CONFIG ] Nom invalide")
                    end
                else
                    ShowDynastyNotification("[ CONFIG ] Annule")
                end
            end)
        elseif type(choice) == "string" then
            Menu.State.selectedProfileName = choice
            Menu.State.currentMenu = "CONFIG_OPTIONS"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end

    elseif menu == "CONFIG_OPTIONS" then
        local name = Menu.State.selectedProfileName
        if index == 1 then
            if name then
                Menu.Helpers.LoadConfigProfile(name)
            end
            Menu.State.currentMenu = "CONFIGS"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif index == 2 then
            if name then
                Menu.Helpers.DeleteConfigProfile(name)
            end
            Menu.State.currentMenu = "CONFIGS"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
            PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif index == 3 then
            Menu.State.currentMenu = "CONFIGS"
            Menu.State.selectedOption, Menu.State.startIndex = 1, 1
            PlaySoundFrontend(-1, "BACK", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end
    end
end

_G.ExecuteMenuAction = ExecuteMenuAction
Menu.Actions.ExecuteMenuAction = ExecuteMenuAction

function Menu.Actions.HandleHorizontalNavigation(dir)
    if (Menu.State.currentMenu=='ONLINE' and Menu.State.onlineTab==4) or (Menu.State.currentMenu=='TROLL' and Menu.State.trollTab==4) then
        local list=Menu.Helpers.GetFullListForMenu(Menu.State.currentMenu)
        local item=list and list[Menu.State.selectedOption or 1]
        if type(item)=='table' and item.id=='punch_all' then
            local index=((Menu.State.punchAllRadiusIdx or 2)-1+dir)%5+1
            Menu.State.punchAllRadiusIdx=index
            item.valueIdx=index
            return
        end
    end
    local menu = Menu.State.currentMenu
    local isSlider = false
    local opt = Menu.State.selectedOption

    -- 1. Identify context
    if Menu.State.currentMenu == "PLAYER" and opt == 3 then
        -- SOLO SESSION : ←/→ cycle entre Normal et Full Invisible
        local current = Menu.State.soloSessionIdx or 1
        local newIdx = current + dir
        if newIdx > 2 then newIdx = 1
        elseif newIdx < 1 then newIdx = 2 end
        if Menu.State.soloSessionActive then Menu.Actions.SoloSession() end
        Menu.State.soloSessionIdx = newIdx
        _G.soloSessionIdx = newIdx
        local names = {"Normal", "Full Invisible"}
        ShowDynastyNotification("[ SESSION ] Mode : " .. names[newIdx])
        PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        return
    elseif Menu.State.currentMenu == "PLAYER" and opt == 5 then
        -- MIRAGE PEWPEW : ←/→ cycle
        local current = Menu.State.miragePewPewIdx or 1
        local newIdx = current + dir
        if newIdx > 4 then newIdx = 1
        elseif newIdx < 1 then newIdx = 4 end
        
        Menu.State.miragePewPewIdx = newIdx
        Menu.State.miragePewPewPreviewIdx = newIdx
        Menu.State.pistolStaffActive = (newIdx == 2 or newIdx == 4)
        Menu.State.carPistolActive   = (newIdx == 3 or newIdx == 4)
        
        -- Sync the old selectedIdx variable too just in case
        miragePewPewSelectedIdx = newIdx
        
        local names = {"OFF", "Pistol Staff", "Car Pistol", "Both"}
        ShowDynastyNotification("[ MIRAGE PEWPEW ] " .. names[newIdx])
        PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        return
    elseif Menu.State.currentMenu == "VEHICLE" then
        local vlist
        if Menu.State.vehicleTab == 1 then
            vlist = Menu.Helpers.GetVehicleMenuList()
        else
            vlist = Menu.Data.Options.Vehicle.Categories[Menu.State.vehicleTab]
        end
        local vitem = vlist and vlist[opt]
        if vitem and vitem.type == "selector" then isSlider = true
        elseif type(vitem) == "string" and (vitem == "Easy Handling") then isSlider = true end
    elseif Menu.State.currentMenu == "VIP_PED" then
        local item=Menu.Helpers.GetPedOptions()[Menu.State.selectedOption]
        if item and item.id=="ped_component_texture" then Menu.Actions.ChangePedTexture(item,dir)
        elseif item and item.id=="chimp_variant" then Menu.Actions.ChangeChimpTexture(dir) end

    elseif Menu.State.currentMenu == "VIP_PETS" then isSlider = (opt == 1)
    elseif Menu.State.currentMenu == "MOVEMENT" and (opt == 1 or opt == 2 or opt == 5 or opt == 6) then isSlider = true
    elseif Menu.State.currentMenu == "VIP_GIVE" then
        local glist = Menu.Helpers.GetDynaGiveOptions()
        local item = glist and glist[opt]
        if item and item.type == "vipgive_selector" then isSlider = true end
    elseif Menu.State.currentMenu == "WARDROBE" and (opt == 2 or opt >= 4) then isSlider = true
    elseif Menu.State.currentMenu == "SETTINGS_RENDER" then
        isSlider = (opt == 1 or opt == 3 or opt == 4 or opt == 6 or opt == 7 or opt == 8 or opt == 9 or opt == 10)
    elseif Menu.State.currentMenu == "SETTINGS_UTILITY" then
        isSlider = false
    elseif Menu.State.currentMenu == "KEYBINDS" or Menu.State.currentMenu == "ACTIVE_BINDS" then
        local opts = (Menu.State.currentMenu == "KEYBINDS") and Menu.Helpers.GetKeybindOptions() or Menu.Helpers.GetActiveBindsOptions()
        local item = opts and opts[opt]
        if item and (item.id == "bind_action" or item.id == "active_bind_action") then isSlider = true end
    elseif Menu.State.currentMenu == "TROLL" then
        local cat = Menu.Data.Options.Troll.Categories[Menu.State.trollTab]
        local item = cat and cat[opt]
        if item and item.type == "selector" then isSlider = true end
    elseif Menu.State.currentMenu == "ONLINE" then
        local list = Menu.Helpers.GetOnlineMenuList()
        local item = list and list[opt]
        if item and item.type == "selector" then isSlider = true end
    elseif Menu.State.currentMenu == "WEAPON" and Menu.State.weaponTab == 2 then
        local wlist = Menu.Helpers.GetWeaponGiveOptions()
        local item = wlist and wlist[opt]
        if item and item.type == "selector" and item.weapons then isSlider = true end
    elseif Menu.State.currentMenu == "DYNA" and Menu.State.dynaTab == 2 then
        local dlist = Menu.Helpers.GetDynaGiveOptions()
        local item = dlist and dlist[opt]
        if item and item.type == "selector" and item.weapons then isSlider = true end
    elseif Menu.State.currentMenu == "MOVEMENT" and (opt == 2 or opt == 5 or opt == 6) then isSlider = true
    elseif Menu.State.currentMenu == "MISC" then
        local miscList = Menu.Helpers.GetMiscOptions()
        local item = miscList and miscList[opt]
        if item and type(item) == "table" and (item.id == "misc_spam_speed" or item.id == "vip_spam_speed" or item.id == "vip_mapcollision") then isSlider = true
        elseif item and type(item) == "table" and item.id == "misc_tp_passager" then isSlider = true end
    elseif Menu.State.currentMenu == "EXPLOIT" or Menu.State.currentMenu == "VIP" then
        local vipList = Menu.Helpers.GetVipOptions()
        local item = vipList and vipList[opt]
        if item and type(item) == "table" and (item.id == "vip_mapcollision" or item.id == "vip_spam_speed") then isSlider = true end
    elseif Menu.State.currentMenu == "COMBAT" then
        local combatList = Menu.Data.Options.Combat.Categories[Menu.State.combatTab or 1] or {}
        local item = combatList[opt]
        if type(item) == "table" then
            if item.type == "selector" then
                isSlider = true
                item.valueIdx = (item.valueIdx + dir - 1) % #item.options + 1
                if item.id == "super_punch_mode" then
                    Menu.State.superPunchModeIdx = item.valueIdx
                    ShowDynastyNotification("[ SUPER PUNCH ] Mode: " .. item.options[item.valueIdx])
                end
                PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            elseif item.type == "slider" and (item.id == "silentKillFov" or item.id == "carryFov") then
                isSlider = true
            end
        end
    elseif Menu.State.currentMenu == "WEAPON" and Menu.State.weaponTab == 1 then
        local wlist = Menu.Data.Options.Weapon.Categories[1] or {}
        local item = wlist[opt]
        if type(item) == "table" and item.type == "selector" then
            isSlider = true
            item.valueIdx = (item.valueIdx + dir - 1) % #item.options + 1
            if item.id == "shoot_car_mode" then
                Menu.State.shootCarModeIdx = item.valueIdx
                ShowDynastyNotification("[ SHOOT CAR ] Mode: " .. item.options[item.valueIdx])
            end
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end
    elseif Menu.State.currentMenu == "WEAPON" and Menu.State.weaponTab == 3 then
        local wlist = Menu.Helpers.GetWeaponAttachOptions()
        local item = wlist and wlist[opt]
        if item and item.type == "weapon_size" then isSlider = true end
    end

    if not isSlider then return end

    -- 2. Handle Logic
    if Menu.State.currentMenu == "MOVEMENT" and Menu.State.selectedOption == 1 then
          -- Noclip Speed (0-100 scale, same as Easy Handling)
          local current = Menu.State.noclipSpeed or 5.0
          Menu.State.noclipSpeed = math.max(0.0, math.min(100.0, current + (dir * 1.0)))

    elseif Menu.State.currentMenu == "MOVEMENT" and Menu.State.selectedOption == 2 then
          local current = Menu.State.noclipPose or 1
          local pose = (current + dir - 1) % 6 + 1
          Menu.State.noclipPose = pose
          local _poseNamesScroll2 = {"Invisible", "Visible", "Aladin", "OmniMove", "Desync", "Chair"}
          local ped = PlayerPedId()
          local isInvisible = (pose == 1) and not seedBlocksInvisibility()
          Menu.State.noclipInvisible = isInvisible
          if Menu.State.noclipActive then
              SetNoclipVisibility(ped, not isInvisible)
              local veh = GetVehiclePedIsIn(ped, false)
              if veh and veh ~= 0 then SetNoclipVisibility(veh, not isInvisible) end
              ClearPedTasks(ped)
              if pose == 3 then
                  local dict = "rcmcollect_paperleadinout@"
                  RequestAnimDict(dict)
                  local t = GetGameTimer()
                  while not HasAnimDictLoaded(dict) and (GetGameTimer() - t) < 3000 do Wait(10) end
                  if HasAnimDictLoaded(dict) then
                      TaskPlayAnim(ped, dict, "meditiate_idle", 8.0, -8.0, -1, 1, 0.0, false, false, false)
                      SetEntityAnimSpeed(ped, dict, "meditiate_idle", 0.0)
                      SetEntityAnimCurrentTime(ped, dict, "meditiate_idle", 0.0)
                  end
                  EnsureAladinCarpet(ped)
              else
                  CleanupAladinCarpet()
              end
              if pose == 5 then
                  InitDesyncState(ped)
              else
                  CleanupDesyncState()
              end
              if pose == 6 then
                  local dictC = "amb@prop_human_seat_chair@male@generic@base"
                  RequestAnimDict(dictC)
                  local tC = GetGameTimer()
                  while not HasAnimDictLoaded(dictC) and (GetGameTimer() - tC) < 3000 do Wait(10) end
                  if HasAnimDictLoaded(dictC) then
                      TaskPlayAnim(ped, dictC, "base", 8.0, -8.0, -1, 1, 0.0, false, false, false)
                      SetEntityAnimSpeed(ped, dictC, "base", 1.0)
                  end
                  EnsureChairProp(ped)
              else
                  CleanupChairProp()
              end
          end
          local poseName = _poseNamesScroll2[pose] or "?"
          local activeStr = Menu.State.noclipActive and "" or " (actif au prochain noclip)"
          ShowDynastyNotification("[ NOCLIP ] Pose: " .. poseName .. activeStr)
          PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

    elseif Menu.State.currentMenu == "MOVEMENT" and Menu.State.selectedOption == 5 then
          -- Freecam Speed : toujours ajustable
          local _fcSpeeds = {0.1, 0.25, 0.5, 1.0, 2.0, 5.0}
          freeCamSpeedIdx = math.max(1, math.min(#_fcSpeeds, (freeCamSpeedIdx or 3) + dir))
          freeCamSpeed = _fcSpeeds[freeCamSpeedIdx]
          local _fcNames = {"0.1", "0.25", "0.5", "1.0", "2.0", "5.0"}
          ShowDynastyNotification("Vitesse Freecam: " .. (_fcNames[freeCamSpeedIdx] or "1.0"))
          PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

    elseif Menu.State.currentMenu == "MOVEMENT" and Menu.State.selectedOption == 6 then
          -- Freecam Layout : gauche/droite cycle
          local count = #FREECAM_LAYOUTS
          _G.freecam_layout = ((_G.freecam_layout or 1) - 1 + dir + count) % count + 1
          local layoutName = FREECAM_LAYOUTS[_G.freecam_layout].name
          ShowDynastyNotification("Layout: " .. layoutName)
          PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

    elseif Menu.State.currentMenu == "VEHICLE" then
        if Menu.State.vehicleTab == 1 then
            -- Tab List : navigation horizontale sur les selecteurs
            local vlist = Menu.Helpers.GetVehicleMenuList()
            local item = vlist and vlist[Menu.State.selectedOption]
            if item and item.type == "selector" then
                item.valueIdx = (item.valueIdx + dir - 1) % #item.options + 1
                if item.id == "veh_action_mode" then
                    Menu.State.vehicleActionMode = item.valueIdx
                    local modes = {"Bring", "TP To", "Warp"}
                    ShowDynastyNotification("[ VEHICLE ] Action: " .. modes[item.valueIdx])
                end
                PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            end
        else
            local vcat = Menu.Data.Options.Vehicle.Categories[Menu.State.vehicleTab]
            local item = vcat and vcat[Menu.State.selectedOption]
            if item and item.type == "selector" then
                if item.id == "builder_veh" then
                    item.valueIdx = (item.valueIdx + dir - 1) % #item.options + 1
                    Menu.State.builderMode = item.valueIdx
                    local names = {"Ramp", "Tour", "Cross"}
                    ShowDynastyNotification("[ BUILDER ] Mode : " .. (names[item.valueIdx] or ""))
                elseif item.id == "sit_on_vehicle" then
                    item.valueIdx = (item.valueIdx + dir - 1) % #item.options + 1
                    Menu.State.sitPoseIdx = item.valueIdx
                    if Menu.State.sitOnVehicleActive then
                        Menu.Actions.UpdateSitPose()
                    end
                    ShowDynastyNotification("[ SIT ] Pose : " .. (item.options[item.valueIdx] or ""))
                else
                    item.valueIdx = (item.valueIdx + dir - 1) % #item.options + 1
                end
                PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            elseif type(item) == "string" and item == "Easy Handling" then
                local current = Menu.State.easyHandlingStrength or 0.0
                Menu.State.easyHandlingStrength = math.max(0.0, math.min(100.0, current + (dir * 2.0)))
            end
        end

    elseif Menu.State.currentMenu == "SETTINGS_RENDER" then
        if opt == 1 then -- Menu Scale
            _G.menuScale = math.max(0.5, math.min(1.3, (_G.menuScale or 1.0) + (dir * 0.05)))
            Menu.Cache.lastResCheck = 0
            PlaySoundFrontend(-1, "NAV_UP_DOWN", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif opt == 3 then -- Menu Position
            Menu.State.menuPosIdx = ((Menu.State.menuPosIdx or 1) + dir - 1) % 3 + 1
            local posNames = {"Gauche", "Centre", "Droite"}
            ShowDynastyNotification("[ POSITION ] " .. (posNames[Menu.State.menuPosIdx] or "Gauche"))
            Menu.Cache.lastResCheck = 0
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif opt == 4 then -- Banner Style
            local allowed = Menu.Helpers.GetAllowedBanners()
            if #allowed > 0 then
                local currentName = Menu.AvailableBanners[Menu.BannerIndex] and Menu.AvailableBanners[Menu.BannerIndex].name
                local currentAllowedIdx = 1
                for i, b in ipairs(allowed) do
                    if b.name == currentName then currentAllowedIdx = i; break end
                end
                local newAllowedIdx = (currentAllowedIdx + dir - 1) % #allowed + 1
                local newBanner = allowed[newAllowedIdx]
                for gi, b in ipairs(Menu.AvailableBanners) do
                    if b.name == newBanner.name then Menu.BannerIndex = gi; break end
                end
                if Menu.LoadBannerTexture then Menu.LoadBannerTexture(newBanner.url, true) end
                if type(Menu.LoadNotifIconForBanner) == "function" then Menu.LoadNotifIconForBanner(newBanner.name) end
                Menu.ApplyBannerTheme(newBanner.name)
            end
            PlaySoundFrontend(-1, "NAV_UP_DOWN", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif opt == 6 then -- Selection Style
            Menu.State.selectionStyle = (Menu.State.selectionStyle == 1) and 2 or 1
            local styleName = Menu.State.selectionStyle == 1 and "Old (gradient)" or "New (arrondi + blink)"
            ShowDynastyNotification("[ SELECTION ] Style: " .. styleName)
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif opt == 7 then -- Sidebar
            Menu.State.sidebarSide = (Menu.State.sidebarSide == "right") and "left" or "right"
            ShowDynastyNotification("Sidebar: " .. (Menu.State.sidebarSide == "right" and "Droite" or "Gauche"))
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif opt == 8 then -- Highlighter
            local isOff = (Menu.State.selectionHighlighterActive == false)
            Menu.State.selectionHighlighterActive = isOff
            ShowDynastyNotification(isOff and "Highlighter: ON" or "Highlighter: OFF")
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif opt == 9 then -- Menu Border (Simple, Glow, Anim, OFF)
            local curVal = (Menu.State.menuBorderActive == false) and 4 or (Menu.State.menuBorderStyle or 3)
            local newVal = (curVal + dir - 1) % 4 + 1
            if newVal == 4 then
                Menu.State.menuBorderActive = false
                ShowDynastyNotification("[ BORDURE ] OFF")
            else
                Menu.State.menuBorderActive = true
                Menu.State.menuBorderStyle = newVal
                local styleNames = {"Simple (Fixe)", "Glow (Brillance)", "Anim (Respiration)"}
                ShowDynastyNotification("[ BORDURE ] " .. (styleNames[newVal] or "Anim"))
            end
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif opt == 10 then -- Freecam Crosshair type
            Menu.State.freecamCrosshairType = ((Menu.State.freecamCrosshairType or 1) + dir - 1) % 3 + 1
            local names = {"German", "Cross", "Carre"}
            ShowDynastyNotification("Freecam Crosshair: " .. (names[Menu.State.freecamCrosshairType] or "N/A"))
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end

    elseif Menu.State.currentMenu == "SETTINGS_UTILITY" then
        -- no action

    elseif Menu.State.currentMenu == "COMBAT" then
        local combatList = Menu.Data.Options.Combat.Categories[Menu.State.combatTab] or {}
        local item = combatList[opt]
        if type(item) == "table" and item.type == "slider" and (item.id == "silentKillFov" or item.id == "carryFov") then
            local step = item.step or 5
            local cur  = Menu.State.silentKillFov or 30
            local next = cur + (dir * step)
            if next < (item.min or 5)   then next = item.min or 5   end
            if next > (item.max or 180) then next = item.max or 180 end
            Menu.State.silentKillFov = next
            ShowDynastyNotification("[ SILENT KILL ] FOV : " .. next .. "°")
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end

    elseif Menu.State.currentMenu == "MISC" then
        local miscList = Menu.Helpers.GetMiscOptions()
        local item = miscList and miscList[opt]
        if item and type(item) == "table" and item.id == "misc_spam_speed" then
            local cur = Menu.State.colSpamSpeed or 10
            local next = cur + (-dir * 10) -- droite = moins de ms = plus rapide = barre pleine
            if next < 10  then next = 10  end
            if next > 500 then next = 500 end
            Menu.State.colSpamSpeed = next
            ShowDynastyNotification("[ MAP COL ] Vitesse Spam : " .. next .. "ms")
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif item and type(item) == "table" and item.id == "misc_tp_passager" then
            local count = item.options and #item.options or 3
            local cur = Menu.State.tpPassagerIdx or 1
            cur = ((cur - 1 + dir + count) % count) + 1
            Menu.State.tpPassagerIdx = cur
            item.valueIdx = cur
            local destName = item.options and item.options[cur] or "?"
            ShowDynastyNotification("[ TP PASSAGER ] Destination : " .. destName)
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        elseif item and type(item) == "table" and item.id == "vip_mapcollision" then
            -- Left/Right cycle le scenario, Enter toggle ON/OFF
            local scenarios = Menu.Helpers.GetColScenarios()
            local count = #scenarios
            local cur = Menu.State.colSpamScenarioIdx or 1
            cur = ((cur - 1 + dir + count) % count) + 1
            Menu.State.colSpamScenarioIdx = cur
            local scenName = (scenarios[cur] and scenarios[cur].short) or "?"
            ShowDynastyNotification("[ MAP COL ] Scenario : " .. scenName)
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
            -- Redemarrer le spammer si actif avec le nouveau scenario
            if Menu.State.colSpammerActive then
                _G.crashBugNearbyPlayersActive = false
            end
        elseif item and type(item) == "table" and item.id == "vip_spam_speed" then
            local cur = Menu.State.colSpamSpeed or 10
            local next = cur + (-dir * 10) -- droite (dir=1) = moins de ms = plus rapide
            if next < 10  then next = 10  end
            if next > 500 then next = 500 end
            Menu.State.colSpamSpeed = next
            ShowDynastyNotification("[ MAP COL ] Vitesse Spam : " .. next .. "ms")
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end


    elseif Menu.State.currentMenu == "WEAPON" and Menu.State.weaponTab == 3 then
        local wlist = Menu.Helpers.GetWeaponAttachOptions()
        local item = wlist and wlist[opt]
        if item and item.type == "weapon_size" then
            local value=math.max(1,math.min(100,(Menu.State.weaponSizeValue or 10)+dir))
            local accepted=true
            if Menu.State.weaponSizeActive then
                accepted=Menu.Actions.SetWeaponSize(true,value)
            else
                Menu.State.weaponSizeValue=value
            end
            if accepted then ShowDynastyNotification('Weapon Size '..tostring(value)) end
            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
        end

    elseif menu == "KEYBINDS" then
        local opts = Menu.Helpers.GetKeybindOptions()
        local item = opts and opts[opt]
        if item and item.id == "bind_action" then
