function Menu.OnRender()
    if RenderShootVisionVisuals then pcall(RenderShootVisionVisuals) end
    if RenderESPVisuals then pcall(RenderESPVisuals) end
    if DrawSilentKillFOVCircle then pcall(DrawSilentKillFOVCircle) end
