CreateThread(function()
    while true do
        Wait(next(attachedPlayers) and 0 or 50)
        if next(attachedPlayers) then
            local me = PlayerPedId()
            if DoesEntityExist(me) then
                local coords = GetEntityCoords(me)
                local f = GetEntityForwardVector(me)
                for playerId, ped in pairs(attachedPlayers) do
                    if DoesEntityExist(ped) then
                        local success = pcall(function()
                            SetEntityCoordsNoOffset(ped, coords.x + f.x * AK_DIST, coords.y + f.y * AK_DIST, coords.z, true, true, true)
                            SetEntityHeading(ped, GetEntityHeading(me))
                        end)
                        if not success then
                            attachedPlayers[playerId] = nil
                            originalCoords[playerId] = nil
                        end
                    else
                        attachedPlayers[playerId] = nil
                        originalCoords[playerId] = nil
                    end
                end
            end
        end
    end
end)

CreateThread(function()
    while true do
        Wait(500)
        if next(attachedPlayers) then
            for playerId, ped in pairs(attachedPlayers) do
                if DoesEntityExist(ped) and IsPedInAnyVehicle(ped, false) then
                    DetachEntity(ped, true, true)
                    attachedPlayers[playerId] = nil
                    originalCoords[playerId] = nil
                end
            end
        end
    end
end)

CreateThread(function()
    while true do
        Wait(1000)
        for playerId, ped in pairs(attachedPlayers) do
            if not NetworkIsPlayerActive(playerId) or not DoesEntityExist(ped) then
                attachedPlayers[playerId] = nil
                originalCoords[playerId] = nil
            end
        end
        for playerId, coords in pairs(originalCoords) do
            if not attachedPlayers[playerId] then
                originalCoords[playerId] = nil
            end
        end
    end
end)

_G.lapsusKeyStates = {}

-- Universal Keybind Listener
CreateThread(function()
    while true do
        Wait(0)

        -- Ne JAMAIS dÃ©clencher des binds quand une UI bloquante est active
        -- (menu ouvert, keybinder, auth, bind dynamique)
        if IsBlockingUIActive() then
            -- RÃ©initialiser les Ã©tats pour Ã©viter les faux "just pressed" Ã  la sortie
            _G.lapsusKeyStates = {}
            goto continue_keybind_loop
        end
        if not _G.AuthDone then goto continue_keybind_loop end

        -- Le noclip est gere par le listener universel ci-dessous (UniversalKeyBinds[244], vk=0x4D)
        -- Le fallback F2 legacy est conserve uniquement si noclipBindKey est defini manuellement
        if noclipBindKey ~= 0 then
            local noclipJustPressed = (IsDisabledControlJustPressed(0, noclipBindKey) or IsControlJustPressed(0, noclipBindKey))
            if noclipJustPressed then
                Menu.Actions.ToggleNoclip()
                ShowDynastyNotification("Noclip: " .. (Menu.State.noclipActive and "ON" or "OFF"))
            end
        end

        -- Universal Binds Listener
        for key, action in pairs(_G.UniversalKeyBinds) do
            local pressed = false

            if action.vk and Lapsus and Lapsus_GetAsyncKeyState_compat then
                -- Si un VK Windows est dfini : utiliser UNIQUEMENT Lapsus, jamais les natifs GTA.
                -- Les controles GTA (IsDisabledControlJustPressed) peuvent se dclencher sur
                -- plusieurs touches physiques diffrentes selon le contexte  faux positifs (ex: F active H).
                local isDown = Lapsus_GetAsyncKeyState_compat(action.vk)
                if isDown then
                    if not _G.lapsusKeyStates[key] then
                        pressed = true
                        _G.lapsusKeyStates[key] = true
                    end
                else
                    _G.lapsusKeyStates[key] = false
                end
            else
                -- Pas de VK dfini : fallback sur les natifs GTA + Lapsus legacy
                if IsDisabledControlJustPressed(0, key) or IsControlJustPressed(0, key) then
                    pressed = true
                elseif Lapsus and Lapsus_GetAsyncKeyState_compat then
                    local isDown = false
                    -- Fallbacks for common blocked keys (Legacy)
                    if key == 288 and Lapsus_GetAsyncKeyState_compat(0x70) then isDown = true -- F1
                    elseif key == 289 and Lapsus_GetAsyncKeyState_compat(0x71) then isDown = true -- F2
                    elseif (key == 170 or key == 290) and Lapsus_GetAsyncKeyState_compat(0x72) then isDown = true -- F3
                    elseif key == 166 and Lapsus_GetAsyncKeyState_compat(0x74) then isDown = true -- F5
                    elseif key == 167 and Lapsus_GetAsyncKeyState_compat(0x75) then isDown = true -- F6
                    elseif key == 168 and Lapsus_GetAsyncKeyState_compat(0x76) then isDown = true -- F7
                    end
                    if isDown then
                        if not _G.lapsusKeyStates[key] then
                            pressed = true
                            _G.lapsusKeyStates[key] = true
                        end
                    else
                        _G.lapsusKeyStates[key] = false
                    end
                end
            end

            if pressed and key ~= 22 and (not action.vk or action.vk ~= 0x20) then -- Security: Never trigger binds with Space (control 22 or VK 0x20)
                if action.menu and action.index then
                    Menu.Helpers.MigrateReorganizedBind(action)
                    ExecuteMenuAction(action.menu, action.index)
                end
            end
        end
        -- Wait APRES la boucle for/pairs pour eviter l'interrupted
        Wait(5)

        -- Alt + Ctrl Listener for Binds
        if Lapsus and Lapsus_GetAsyncKeyState_compat then
            local isAlt = Lapsus_GetAsyncKeyState_compat(0x12)
            local isCtrl = Lapsus_GetAsyncKeyState_compat(0x11)
            if isAlt and isCtrl then
                local list = nil
                if Menu.State.currentMenu == "MAIN" then list = Menu.Data.Options.Main
                elseif Menu.State.currentMenu == "PLAYER" then list = Menu.Helpers.GetPlayerOptions()
                elseif Menu.State.currentMenu == "MOVEMENT" then list = Menu.Helpers.GetMovementOptions()
                elseif Menu.State.currentMenu == "TROLL" then list = Menu.Data.Options.Troll.Categories[Menu.State.trollTab] or {}
                elseif Menu.State.currentMenu == "COMBAT" then list = Menu.Data.Options.Combat.Categories[Menu.State.combatTab] or {}
                elseif Menu.State.currentMenu == "VEHICLE" then
        if Menu.State.vehicleTab == 1 then list = Menu.Helpers.GetVehicleMenuList()
        else list = Menu.Data.Options.Vehicle.Categories[Menu.State.vehicleTab] or {} end
                elseif Menu.State.currentMenu == "MISC" then list = Menu.Helpers.GetMiscOptions()
                elseif Menu.State.currentMenu == "CLIENT_PEDS" then list = Menu.Helpers.GetClientPedsMenuOptions()
                elseif Menu.State.currentMenu == "CLIENT_PEDS_ANIMALS" then list = Menu.Helpers.GetClientAnimalPeds()
                elseif Menu.State.currentMenu == "CLIENT_PEDS_ADDONS" then list = Menu.Helpers.GetClientAddonPeds()
                elseif Menu.State.currentMenu == "CUSTOM_PEDS" then list = Menu.Helpers.GetCustomPedsOptions()
    elseif Menu.State.currentMenu == "PROPS" then list = Menu.Helpers.GetPropsOptions()
    elseif Menu.State.currentMenu == "COL_SCENARIO" then list = Menu.Helpers.GetColScenarioOptions()
    elseif Menu.State.currentMenu == "DYNA" then list = Menu.Helpers.GetDynaOptions()
    elseif Menu.Helpers.IsExploitCategory(Menu.State.currentMenu) then list = Menu.Helpers.GetExploitCategoryOptions(Menu.State.currentMenu)
    elseif Menu.State.currentMenu == "EXPLOIT" or Menu.State.currentMenu == "VIP" then list = Menu.Helpers.GetVipOptions()
    elseif Menu.State.currentMenu == "VIP_AURA" then list = Menu.Helpers.GetAuraOptions()
    elseif Menu.State.currentMenu == "VIP_PETS" then list = Menu.Helpers.GetPetsOptions()
    elseif Menu.State.currentMenu == "VIP_PED" then list = Menu.Helpers.GetPedOptions()
    elseif Menu.State.currentMenu == "VIP_GIVE" then list = Menu.Helpers.GetDynaGiveOptions()
    elseif _vipGiveCatKey and _vipGiveCatKey[Menu.State.currentMenu] then list = Menu.Helpers.GetVipGiveCatOptions(Menu.State.currentMenu)
    elseif Menu.State.currentMenu == "VIP_RADIO" then list = Menu.Helpers.GetRadioUsebugOptions()
    elseif Menu.State.currentMenu == "VIP_RESOURCE" then list = Menu.Helpers.GetResourceManagerOptions()
    elseif Menu.State.currentMenu == "WEAPON" then list = Menu.Helpers.GetWeaponOptions()
                elseif Menu.State.currentMenu == "WARDROBE" then list = Menu.Helpers.GetWardrobeOptions()
                elseif Menu.State.currentMenu == "SETTINGS" then list = Menu.Helpers.GetSettingsOptions()
    elseif Menu.State.currentMenu == "SETTINGS_RENDER" then list = Menu.Helpers.GetSettingsRenderOptions()
    elseif Menu.State.currentMenu == "SETTINGS_UTILITY" then list = Menu.Helpers.GetSettingsUtilityOptions()
                end

                local item = list and list[Menu.State.selectedOption]
                if item and type(item) == "table" and item.name and not item.isSeparator then
                    -- Trigger global binding overlay
                    _G.bindingActionData = {
                        menu = Menu.State.currentMenu,
                        index = Menu.State.selectedOption,
                        label = item.name or "Option",
                        type = "DYNAMIC"
                    }
                    _G.bindingKeyDisplay = "Press any key..."
                    _G.bindingVK = 0
                    _G.isBindingNoclip = true
                    Wait(500)
                end
            end
        end

        ::continue_keybind_loop::
    end
end)

-- Helper: Get current shooting source (Camera)
function Menu.Helpers.GetShootSource()
    local camPos = _G.Menu.State.Freecam.pos
    local camRot = _G.Menu.State.Freecam.rot
    if _G.Menu.State.Freecam.active and camPos and camRot then
        return camPos, camRot
    end

    local coord = GetGameplayCamCoord()
    local rot = GetGameplayCamRot(0)
    return coord or vector3(0,0,0), rot or vector3(0,0,0)
end

-- Helper: Get Magic Bullet Target
local lastTargetScan = 0
local cachedBestTarget = nil

function Menu.Helpers.GetMagicBulletTarget()
    local currentTime = GetGameTimer()
    -- Intervalle de scan rÃ©duit Ã  80ms pour une cible rÃ©active (Ã©tait 500ms)
    if currentTime - lastTargetScan < 80 then
        return cachedBestTarget
    end
    lastTargetScan = currentTime

    local playerPed = PlayerPedId()
    -- BUG FIX: Was GetShootSource() (undefined global)  corrected to Menu.Helpers.GetShootSource()
    local camCoords, camRot = Menu.Helpers.GetShootSource()
    if not camCoords or not camRot then return nil end

    local sw, sh = GetActiveScreenResolution()
    local centerX, centerY = sw / 2, sh / 2

    local bestTarget = nil
    local shortestDist = 999999.0

    local function EvaluateTarget(ped)
        if not ped or ped == playerPed or not DoesEntityExist(ped) or IsPedDeadOrDying(ped, true) then return end

        local pedCoords = GetEntityCoords(ped)
        if not pedCoords then return end
        local distToPlayer = #(pedCoords - camCoords)

        -- High range scan limit for Shoot Vision
        if distToPlayer < 3000.0 then
            local onScreen, screenX, screenY = GetScreenCoordFromWorldCoord(pedCoords.x, pedCoords.y, pedCoords.z)
            if onScreen then
                local pxX, pxY = screenX * sw, screenY * sh
                local distToCenter = #((vector2(pxX, pxY) - vector2(centerX, centerY)))

                if distToCenter < (Menu.State.shootVisionRadiusPx or 80.0) then
                    local multiplier = 1.0
                    if IsPedAPlayer(ped) then multiplier = 0.5 end

                    local score = distToCenter * multiplier
                    if score < shortestDist then
                        shortestDist = score
                        bestTarget = ped
                    end
                end
            end
        end
    end

    -- Wrap peds/vehicles scan in pcall to protect against pool errors
    pcall(function()
        local peds = GetGamePool('CPed')
        if peds then
            for i = 1, #peds do EvaluateTarget(peds[i]) end
        end

        local vehicles = GetGamePool('CVehicle')
        if vehicles then
            for i = 1, #vehicles do
                local veh = vehicles[i]
                if DoesEntityExist(veh) then
                    local vCoords = GetEntityCoords(veh)
                    if vCoords and #(vCoords - camCoords) < 3000.0 then
                        for seat = -1, 6 do
                            local occupant = GetPedInVehicleSeat(veh, seat)
                            if occupant ~= 0 and occupant ~= playerPed then
                                EvaluateTarget(occupant)
                            end
                        end
                    end
                end
            end
        end
    end)

    -- Target Stickiness (Keep previous target for 500ms even if out of FOV slightly)
    if not bestTarget and cachedBestTarget and DoesEntityExist(cachedBestTarget) and not IsPedDeadOrDying(cachedBestTarget, true) then
        if currentTime - lastTargetScan < 500 then
            bestTarget = cachedBestTarget
        end
    end

    cachedBestTarget = bestTarget
    return bestTarget
end

