local function DrawChamsHighlighter(entity, r, g, b, alpha)
    if not entity or entity == 0 or not DoesEntityExist(entity) then return end
    local isPed = IsEntityAPed(entity)
    local isVeh = IsEntityAVehicle(entity)
    local aInt = math.floor(alpha)
    local thick = Menu.State.highlighterThickness or 1.0

    -- Recupere la couleur dynamique du theme si disponible, sinon vert par defaut
    local vr, vg, vb = r, g, b

    -- 1. Native Outline Glow (chams) — wallhack visible à travers les murs
    pcall(SetEntityDrawOutline, entity, true)
    pcall(SetEntityDrawOutlineColor, vr, vg, vb, 255)
    pcall(SetEntityDrawOutlineShader, 1)  -- shader 1 = visible à travers la géométrie

    -- Purge _freecamHighlightTarget si l'entité a été supprimée entre deux frames
    if _G._freecamHighlightTarget and not DoesEntityExist(_G._freecamHighlightTarget) then
        _G._freecamHighlightTarget = nil
    end
    -- Pour les véhicules : en freecam on dessine aussi la boite wireframe (feedback visuel Crash)
    -- Hors freecam : on continue comme avant (outline glow seul pour les véhicules)
    if isVeh and not _G._freecamHighlightTarget then return end
    if isVeh and _G._freecamHighlightTarget ~= entity then return end

    -- 2. Fleche 3D pointee au-dessus de la tete (peds uniquement)
    local coords = GetEntityCoords(entity)
    local okDim, minDim, maxDim = pcall(GetModelDimensions, GetEntityModel(entity))
    local hOffset = (okDim and maxDim and minDim) and ((maxDim.z - minDim.z) + 0.55) or 2.15
    local markerSize = 0.25 + (thick - 1.0) * 0.1
    DrawMarker(2, coords.x, coords.y, coords.z + hOffset, 0.0, 0.0, 0.0, 180.0, 0.0, 0.0, markerSize, markerSize, markerSize, vr, vg, vb, 230, true, true, 2, false, nil, nil, false)

    -- 3. Boite 3D fil de fer encadrant l'entite
    if okDim and minDim and maxDim then
        local pad = 0.02 + (thick - 1.0) * 0.03
        local minX, minY, minZ, maxX, maxY, maxZ

        if isPed then
            -- Pour les peds la bounding box du modele est souvent trop large.
            -- On utilise les bones cles pour recalculer une boite fidele a la silhouette.
            local boneIds = {
                31086,  -- Head
                39317,  -- Neck
                24818,  -- Spine3 (epaules)
                23553,  -- Spine0 (bassin)
                45509,  -- L_UpperArm
                40269,  -- R_UpperArm
                18905,  -- L_Hand
                57005,  -- R_Hand
                58271,  -- L_Thigh
                63931,  -- L_Calf
                28252,  -- R_Calf
                14201,  -- L_Foot
                26610,  -- R_Foot
            }
            local bMinX, bMinY, bMinZ =  9999,  9999,  9999
            local bMaxX, bMaxY, bMaxZ = -9999, -9999, -9999
            local gotAny = false
            local entityCoords = GetEntityCoords(entity)
            for _, boneId in ipairs(boneIds) do
                local ok2, bx, by, bz = pcall(GetPedBoneCoords, entity, boneId, 0.0, 0.0, 0.0)
                if ok2 and bx then
                    -- Convertir en local entity space pour les comparaisons
                    local lx = bx - entityCoords.x
                    local ly = by - entityCoords.y
                    local lz = bz - entityCoords.z
                    if lx < bMinX then bMinX = lx end
                    if ly < bMinY then bMinY = ly end
                    if lz < bMinZ then bMinZ = lz end
                    if lx > bMaxX then bMaxX = lx end
                    if ly > bMaxY then bMaxY = ly end
                    if lz > bMaxZ then bMaxZ = lz end
                    gotAny = true
                end
            end
            if gotAny then
                -- Marge fine laterale (largeur epaules ~0.25), plus proche du corps que la bbox modele
                local lateralPad = 0.18 + pad
                local depthPad   = 0.15 + pad
                minX = bMinX - lateralPad
                maxX = bMaxX + lateralPad
                minY = bMinY - depthPad
                maxY = bMaxY + depthPad
                minZ = bMinZ - 0.08        -- juste sous les pieds
                maxZ = bMaxZ + 0.08 + pad  -- juste au-dessus de la tete
            else
                -- Fallback : silhouette humaine fixe serree (~0.45m large, 1.8m haut)
                minX = -0.28; maxX = 0.28
                minY = -0.18; maxY = 0.18
                minZ = minDim.z; maxZ = maxDim.z
            end
            -- Convertir en world-space via offset depuis l'entite
            local c1 = vector3(GetEntityCoords(entity).x + minX, GetEntityCoords(entity).y + minY, GetEntityCoords(entity).z + minZ)
            -- On utilise GetOffsetFromEntityInWorldCoords pour tenir compte de la rotation du ped
            local ec = GetEntityCoords(entity)
            c1 = GetOffsetFromEntityInWorldCoords(entity, minX, minY, minZ)
            local c2 = GetOffsetFromEntityInWorldCoords(entity, maxX, minY, minZ)
            local c3 = GetOffsetFromEntityInWorldCoords(entity, maxX, maxY, minZ)
            local c4 = GetOffsetFromEntityInWorldCoords(entity, minX, maxY, minZ)
            local c5 = GetOffsetFromEntityInWorldCoords(entity, minX, minY, maxZ)
            local c6 = GetOffsetFromEntityInWorldCoords(entity, maxX, minY, maxZ)
            local c7 = GetOffsetFromEntityInWorldCoords(entity, maxX, maxY, maxZ)
            local c8 = GetOffsetFromEntityInWorldCoords(entity, minX, maxY, maxZ)

            DrawLine(c1.x, c1.y, c1.z, c2.x, c2.y, c2.z, vr, vg, vb, aInt)
            DrawLine(c2.x, c2.y, c2.z, c3.x, c3.y, c3.z, vr, vg, vb, aInt)
            DrawLine(c3.x, c3.y, c3.z, c4.x, c4.y, c4.z, vr, vg, vb, aInt)
            DrawLine(c4.x, c4.y, c4.z, c1.x, c1.y, c1.z, vr, vg, vb, aInt)
            DrawLine(c5.x, c5.y, c5.z, c6.x, c6.y, c6.z, vr, vg, vb, aInt)
            DrawLine(c6.x, c6.y, c6.z, c7.x, c7.y, c7.z, vr, vg, vb, aInt)
            DrawLine(c7.x, c7.y, c7.z, c8.x, c8.y, c8.z, vr, vg, vb, aInt)
            DrawLine(c8.x, c8.y, c8.z, c5.x, c5.y, c5.z, vr, vg, vb, aInt)
            DrawLine(c1.x, c1.y, c1.z, c5.x, c5.y, c5.z, vr, vg, vb, aInt)
            DrawLine(c2.x, c2.y, c2.z, c6.x, c6.y, c6.z, vr, vg, vb, aInt)
            DrawLine(c3.x, c3.y, c3.z, c7.x, c7.y, c7.z, vr, vg, vb, aInt)
            DrawLine(c4.x, c4.y, c4.z, c8.x, c8.y, c8.z, vr, vg, vb, aInt)
        else
            -- Vehicules : bounding box modele standard
            minX = minDim.x - pad; maxX = maxDim.x + pad
            minY = minDim.y - pad; maxY = maxDim.y + pad
            minZ = minDim.z - pad; maxZ = maxDim.z + pad

            local c1 = GetOffsetFromEntityInWorldCoords(entity, minX, minY, minZ)
            local c2 = GetOffsetFromEntityInWorldCoords(entity, maxX, minY, minZ)
            local c3 = GetOffsetFromEntityInWorldCoords(entity, maxX, maxY, minZ)
            local c4 = GetOffsetFromEntityInWorldCoords(entity, minX, maxY, minZ)
            local c5 = GetOffsetFromEntityInWorldCoords(entity, minX, minY, maxZ)
            local c6 = GetOffsetFromEntityInWorldCoords(entity, maxX, minY, maxZ)
            local c7 = GetOffsetFromEntityInWorldCoords(entity, maxX, maxY, maxZ)
            local c8 = GetOffsetFromEntityInWorldCoords(entity, minX, maxY, maxZ)

            DrawLine(c1.x, c1.y, c1.z, c2.x, c2.y, c2.z, vr, vg, vb, aInt)
            DrawLine(c2.x, c2.y, c2.z, c3.x, c3.y, c3.z, vr, vg, vb, aInt)
            DrawLine(c3.x, c3.y, c3.z, c4.x, c4.y, c4.z, vr, vg, vb, aInt)
            DrawLine(c4.x, c4.y, c4.z, c1.x, c1.y, c1.z, vr, vg, vb, aInt)
            DrawLine(c5.x, c5.y, c5.z, c6.x, c6.y, c6.z, vr, vg, vb, aInt)
            DrawLine(c6.x, c6.y, c6.z, c7.x, c7.y, c7.z, vr, vg, vb, aInt)
            DrawLine(c7.x, c7.y, c7.z, c8.x, c8.y, c8.z, vr, vg, vb, aInt)
            DrawLine(c8.x, c8.y, c8.z, c5.x, c5.y, c5.z, vr, vg, vb, aInt)
            DrawLine(c1.x, c1.y, c1.z, c5.x, c5.y, c5.z, vr, vg, vb, aInt)
            DrawLine(c2.x, c2.y, c2.z, c6.x, c6.y, c6.z, vr, vg, vb, aInt)
            DrawLine(c3.x, c3.y, c3.z, c7.x, c7.y, c7.z, vr, vg, vb, aInt)
            DrawLine(c4.x, c4.y, c4.z, c8.x, c8.y, c8.z, vr, vg, vb, aInt)
        end
    end
end

function Menu.Helpers.ProcessSelectionHighlighter()
    if Menu.State.selectionHighlighterActive == false then
        if _lastHighlightedEntity and DoesEntityExist(_lastHighlightedEntity) then
            pcall(SetEntityDrawOutline, _lastHighlightedEntity, false)
            _lastHighlightedEntity = nil
        end
        return
    end

    local targetEntity = nil

    -- 0. Freecam : si active et highlighter ON, on cherche le véhicule visé par la caméra
    --    Utilise cam_rot (rotation freecam réelle) au lieu de GetGameplayCameraRot,
    --    portée maximale GTA (10 000 m), perce les murs via le flag de penetration.
    if freecam_active and Menu.State.selectionHighlighterActive ~= false then
        local camCoord = cam_pos
        if camCoord and cam_rot then
            local pitch = math.rad(cam_rot.x)
            local yaw   = math.rad(cam_rot.z)
            local dirX  = -math.sin(yaw) * math.cos(pitch)
            local dirY  =  math.cos(yaw) * math.cos(pitch)
            local dirZ  =  math.sin(pitch)
            local endX  = camCoord.x + dirX * 10000.0
            local endY  = camCoord.y + dirY * 10000.0
            local endZ  = camCoord.z + dirZ * 10000.0
            -- flag -1 = toutes entités, options 4 = perce les murs (wallhack)
            local ray = StartExpensiveSynchronousShapeTestLosProbe(
                camCoord.x, camCoord.y, camCoord.z,
                endX, endY, endZ,
                -1, PlayerPedId(), 4)
            local _, hit, _, _, hitEntity = GetShapeTestResult(ray)
            if hit and hitEntity and hitEntity ~= 0 and DoesEntityExist(hitEntity) then
                if IsEntityAVehicle(hitEntity) then
                    targetEntity = hitEntity
                elseif IsEntityAPed(hitEntity) then
                    -- Si on vise un occupant, cibler son véhicule
                    local pedVeh = GetVehiclePedIsIn(hitEntity, false)
                    if pedVeh and pedVeh ~= 0 and DoesEntityExist(pedVeh) then
                        targetEntity = pedVeh
                    end
                end
            end
            -- Mémoriser la cible freecam pour le rendu wireframe wallhack
            _G._freecamHighlightTarget = targetEntity
        end
    else
        _G._freecamHighlightTarget = nil
    end

    -- Si pas en freecam : logique selection explicite (joueur / vehicule selectionne)
    if not freecam_active then
        if selectedPlayer and selectedPlayer.id then
            local ped = GetPlayerPed(selectedPlayer.id)
            if DoesEntityExist(ped) and ped ~= PlayerPedId() then
                if IsPedInAnyVehicle(ped, false) then
                    targetEntity = GetVehiclePedIsIn(ped, false)
                else
                    targetEntity = ped
                end
            end
        -- 2. Vehicule EXPLICITEMENT selectionne (via la touche Entree dans le Vehicle Menu)
        elseif Menu.State.vehicleSelectedVehicle then
            local key = Menu.State.vehicleSelectedVehicle
            local veh = nil
            if type(key) == "number" then
                if NetworkDoesEntityExistWithNetworkId(key) then
                    veh = NetworkGetEntityFromNetworkId(key)
                elseif DoesEntityExist(key) then
                    veh = key
                end
            end
            if veh and DoesEntityExist(veh) then
                targetEntity = veh
            end
        end
    end

    -- Nettoyage si l'entite selectionnee a change ou a ete deselectionnee
    if _lastHighlightedEntity and _lastHighlightedEntity ~= targetEntity and DoesEntityExist(_lastHighlightedEntity) then
        pcall(SetEntityDrawOutline, _lastHighlightedEntity, false)
        _lastHighlightedEntity = nil
    end

    -- Surlignage continu (RESTE ACTIF MEME SI LE MENU EST FERME tant qu'il n'est pas deselectionne !)
    if targetEntity and DoesEntityExist(targetEntity) then
        _lastHighlightedEntity = targetEntity

        local themeColor = (Menu.Colors and (Menu.Colors.HeaderPink or Menu.Colors.SelectedBg)) or { r = 40, g = 220, b = 90 }
        local r, g, b = themeColor.r or 40, themeColor.g or 220, themeColor.b or 90
        local pulseAlpha = math.floor(180 + math.sin(GetGameTimer() * 0.007) * 75)

        DrawChamsHighlighter(targetEntity, r, g, b, pulseAlpha)
    end
end


