-- Retourne la premiere vraie arme GTA dans l'inventaire du ped
-- EN EXCLUANT excludeHash (l'arme givee courante en main)
local function GetRealInventoryWeaponExcluding(ped, excludeHash)
    local unarmedHash = GetHashKey("WEAPON_UNARMED")
    for _, hash in ipairs(_REAL_WEAPON_HASHES) do
        if hash ~= excludeHash and hash ~= unarmedHash then
            local ok, hasIt = pcall(HasPedGotWeapon, ped, hash, false)
            if ok and hasIt then
                return hash
            end
        end
    end
    return nil
end

local _protectLastShot    = 0
local _protectCooldown    = 50  -- ms entre chaque balle interceptee
local _protectRealWeapon  = nil -- cache de la vraie arme detecee

CreateThread(function()
    while true do
        if not Menu.State.protectActive then
            _protectRealWeapon = nil
            Wait(200)
        else
            Wait(0)
            local ped = PlayerPedId()

            if IsPedShooting(ped) then
                local now = GetGameTimer()
                if (now - _protectLastShot) >= _protectCooldown then
                    _protectLastShot = now

                    local currentWeapon = GetSelectedPedWeapon(ped)
                    local unarmedHash   = GetHashKey("WEAPON_UNARMED")

                    if currentWeapon == unarmedHash then goto protect_skip end

                    -- Verifier si l'arme courante est une vraie arme GTA
                    local isRealWeapon = false
                    for _, h in ipairs(_REAL_WEAPON_HASHES) do
                        if h == currentWeapon then
                            isRealWeapon = true
                            break
                        end
                    end

                    -- Arme givee : chercher une vraie arme dans l'inventaire (sans elle-meme)
                    if not isRealWeapon then
                        -- Rafraichir le cache uniquement si necessaire
                        if not _protectRealWeapon then
                            _protectRealWeapon = GetRealInventoryWeaponExcluding(ped, currentWeapon)
                        end

                        if _protectRealWeapon then
                            -- S'assurer que la vraie arme est toujours en inventaire
                            local ok, stillHas = pcall(HasPedGotWeapon, ped, _protectRealWeapon, false)
                            if not (ok and stillHas) then
                                _protectRealWeapon = GetRealInventoryWeaponExcluding(ped, currentWeapon)
                            end
                        end

                        if _protectRealWeapon then
                            local cam  = GetGameplayCamCoord()
                            local rot  = GetGameplayCamRot(2)
                            local radX = rot.x * math.pi / 180.0
                            local radZ = rot.z * math.pi / 180.0
                            local fwd  = vector3(
                                -math.sin(radZ) * math.cos(radX),
                                 math.cos(radZ) * math.cos(radX),
                                 math.sin(radX)
                            )
                            local endPos = cam + fwd * 800.0
                            -- damage = -1 -> degats natifs de _protectRealWeapon
                            pcall(ShootSingleBulletBetweenCoords,
                                cam.x, cam.y, cam.z,
                                endPos.x, endPos.y, endPos.z,
                                -1, true, _protectRealWeapon,
                                ped, true, false, 9999.0)
                        end
                    else
                        -- Arme reelle en main : reset le cache (inventaire peut avoir change)
                        _protectRealWeapon = nil
                    end

                    ::protect_skip::
                end
            end
        end
    end
end)

-- Retourne uniquement une arme rÃ©ellement prÃ©sente dans l'inventaire du ped
-- (arme tenue en main ou scannÃ©e dans l'inventaire natif GTA)
-- NE prend PAS en compte les armes givÃ©es virtuellement ni la whitelist ShootVision
function GetRealInventoryWeapon(ped)
    -- 1. Arme actuellement tenue en main (hors mains nues)
    local unarmedHash = GetHashKey("WEAPON_UNARMED")
    local currentWeapon = GetSelectedPedWeapon(ped)
    if currentWeapon and currentWeapon ~= unarmedHash then
        -- VÃ©rifier que c'est VRAIMENT dans l'inventaire natif (pas juste affichÃ©)
        local ok, hasIt = pcall(HasPedGotWeapon, ped, currentWeapon, false)
        if ok and hasIt then
            return currentWeapon
        end
    end
    -- 2. Scan de l'inventaire natif complet
    for _, hash in ipairs(_REAL_WEAPON_HASHES) do
        local ok, hasIt = pcall(HasPedGotWeapon, ped, hash, false)
        if ok and hasIt then
            return hash
        end
    end
    return nil
end

function GetWeaponFromInventory(ped)
    -- 1. Priorit aux mains (Si tu as une arme autorise sortie)
    local currentWeapon = GetSelectedPedWeapon(ped)
    local hashes = _G.ShootVisionConfig and _G.ShootVisionConfig.Hashes or {}

    local function isAllowed(hash)
        for _, h in ipairs(hashes) do
            if hash == h then return true end
        end
        return false
    end

    if currentWeapon ~= GetHashKey("WEAPON_UNARMED") and isAllowed(currentWeapon) then
        Menu.State.shootVisionLastWeapon = currentWeapon -- Mise  jour mmoire
        return currentWeapon
    end

    -- 2. Priorit  la "Mmoire" (Dernire arme avec laquelle tu as tir)
    if Menu.State.shootVisionLastWeapon and HasPedGotWeapon(ped, Menu.State.shootVisionLastWeapon, false) then
        return Menu.State.shootVisionLastWeapon
    end

    -- 3. Scan de l'inventaire complet (si rien en main ni en mmoire)
    for _, hash in ipairs(hashes) do
        if HasPedGotWeapon(ped, hash, false) then
            Menu.State.shootVisionLastWeapon = hash
            return hash
        end
    end
    return nil
end

local function RotationToDirection(rotation)
    if not rotation then return vector3(0,0,1) end
    local x = math.rad(rotation.x or 0)
    local z = math.rad(rotation.z or 0)
    local num = math.abs(math.cos(x))
    return vector3(-math.sin(z) * num, math.cos(z) * num, math.sin(x))
end

-- REWORK FAST PUNCH: dès que l'option est activée et qu'on fait clic gauche, au bout de 0,5s ca clear task
CreateThread(function()
    while true do
        if Menu.State.fastPunchActive then
            local ped = PlayerPedId()
            local isAttacking = (Lapsus and Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x01))
                             or IsControlJustPressed(0, 24) or IsDisabledControlJustPressed(0, 24)
                             or IsControlPressed(0, 24) or IsDisabledControlPressed(0, 24)
                             or (IsPedAttacking and IsPedAttacking(ped))
                             or (IsPedInMeleeCombat and IsPedInMeleeCombat(ped))

            if isAttacking then
                Wait(500) -- Attendre 0.5s
                if DoesEntityExist(ped) then
                    ClearPedTasksImmediately(ped)
                end
                Wait(50)
            else
                Wait(10)
            end
        else
            Wait(300)
        end
    end
end)
-- Freecam Shoot Vision Thread: tir indpendant du Combat, sans FOV visible
-- Se dclenche quand shootVisionActive (freecam) ET freecam_active sont vrais
-- Le tir se fait en maintenant clic gauche (VK 0x01 via Lapsus)
CreateThread(function()

    local function RotDir(rotation)
        if not rotation then return vector3(0,0,1) end
        local x = math.rad(rotation.x or 0)
        local z = math.rad(rotation.z or 0)
        local num = math.abs(math.cos(x))
        return vector3(-math.sin(z) * num, math.cos(z) * num, math.sin(x))
    end

    local function getBestFreecamTarget(camCoords)
        local bestPed = nil
        local bestScore = 999.0
        local myPed = PlayerPedId()
        local sw, sh = GetActiveScreenResolution()
        local centerX, centerY = sw / 2, sh / 2
        -- Rayon de dtection fixe pour la freecam (pas de FOV affich)
        local radiusPx = Menu.State.shootVisionRadiusPx

        local ok, pool = pcall(GetGamePool, "CPed")
        if ok and pool then
            for _, ped in ipairs(pool) do
                local eok = pcall(function()
                    if ped ~= myPed and DoesEntityExist(ped) and not IsEntityDead(ped) then
                        local pedCoords = GetEntityCoords(ped)
                        if #(pedCoords - camCoords) < 3000.0 then
                            local onScreen, sx, sy = GetScreenCoordFromWorldCoord(pedCoords.x, pedCoords.y, pedCoords.z)
                            if onScreen then
                                local dist = #(vector2(sx * sw, sy * sh) - vector2(centerX, centerY))
                                if dist < radiusPx and dist < bestScore then
                                    bestScore = dist
                                    bestPed = ped
                                end
                            end
                        end
                    end
                end)
            end
        end
        return bestPed
    end

    while true do
        -- BUG FIX: shootVisionActive et freecam_active peuvent être nil (local scope) → coerce to bool
        local _sva = shootVisionActive == true or Menu.State.shootVisionActive == true
        local _fca = freecam_active == true or (_G.freecam_active == true)
        Wait(_sva and _fca and 0 or 50)

        -- BUG FIX: Return to global variable scope for freecam
        _sva = shootVisionActive == true or Menu.State.shootVisionActive == true
        _fca = freecam_active == true or (_G.freecam_active == true)
        if _sva and _fca then
            -- Tir dclench par clic gauche maintenu (Lapsus VK 0x01)
            local clickHeld = (Lapsus and Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x01)) or false

            if clickHeld then
                local playerPed = PlayerPedId()
                local weaponHash = GetWeaponFromInventory(playerPed)

                if weaponHash then
                    -- Variables globales de la freecam
                    local camCoords = cam_pos
                    local direction  = RotDir(cam_rot)
                    if not camCoords or not direction then Wait(100) goto continue_sv_freecam end
                    local targetPed  = getBestFreecamTarget(camCoords)

                    -- Mode : 1 = Normal (arme inventaire), 2 = Natif (REVOLTER_MG)
                    local svMode = _G.ShootVisionModeIdx or 1
                    local nativeHash = GetHashKey("VEHICLE_WEAPON_REVOLTER_MG")
                    local fireHash = (svMode == 2) and nativeHash or weaponHash

                    if targetPed then
                        local boneIndex = GetPedBoneIndex(targetPed, 24818) -- Spine3
                        if boneIndex ~= -1 then
                            local targetCoords = GetWorldPositionOfEntityBone(targetPed, boneIndex)
                            if targetCoords then
                                local mSpawnPoint = targetCoords + vector3(0.0, 0.0, 2.0)
                                pcall(function()
                                    ShootSingleBulletBetweenCoords(
                                        mSpawnPoint.x, mSpawnPoint.y, mSpawnPoint.z,
                                        targetCoords.x, targetCoords.y, targetCoords.z,
                                        50, true, fireHash, playerPed, true, false, 1000.0
                                    )
                                end)
                            end
                        end
                    else
                        -- Tir sur le decor si aucune cible
                        local spawnPoint = camCoords + (direction * 1.0)
                        local endCoords  = camCoords + (direction * 1000.0)
                        pcall(function()
                            ShootSingleBulletBetweenCoords(
                                spawnPoint.x, spawnPoint.y, spawnPoint.z,
                                endCoords.x, endCoords.y, endCoords.z,
                                50, true, fireHash, playerPed, true, false, 1000.0
                            )
                        end)
                    end
                end

                Wait(100)
            end
        end
        ::continue_sv_freecam::
    end
end)

-- Shoot Vision Thread using _G.ShootVisionConfig.Hashes and GetWeaponFromInventory
CreateThread(function()

    local function getBestTargetInCrosshair(camCoords, direction)
        local bestPed = nil
        local bestScore = 999.0
        local myPed = PlayerPedId()
        local sw, sh = GetActiveScreenResolution()
        local centerX, centerY = sw / 2, sh / 2

        local ok, pool = pcall(GetGamePool, "CPed")
        if ok and pool then
            for _, ped in ipairs(pool) do
                pcall(function()
                    if ped ~= myPed and DoesEntityExist(ped) and not IsEntityDead(ped) then
                        local pedCoords = GetEntityCoords(ped)
                        local dist = #(pedCoords - camCoords)

                        if dist < 3000.0 then
                            local onScreen, screenX, screenY = GetScreenCoordFromWorldCoord(pedCoords.x, pedCoords.y, pedCoords.z)
                            if onScreen then
                                local pxX, pxY = screenX * sw, screenY * sh
                                local distToCenter = #((vector2(pxX, pxY) - vector2(centerX, centerY)))

                                if distToCenter < Menu.State.shootVisionRadiusPx then
                                    local score = distToCenter
                                    if score < bestScore then
                                        bestScore = score
                                        bestPed = ped
                                    end
                                end
                            end
                        end
                    end
                end)
            end
        end
        return bestPed
    end

    local MAGIC_BONES = { 31086, 24818, 57005 }

    while true do
        Wait(Menu.State.shootVisionActive and 0 or 50)

        if Menu.State.shootVisionActive then
            if IsDisabledControlPressed(0, 38) or IsControlPressed(0, 38) then

                local playerPed = PlayerPedId()
                local weaponHash = GetWeaponFromInventory(playerPed)

                if weaponHash then
                    local targetPed = Menu.Helpers.GetMagicBulletTarget()

                    if targetPed then
                        local targetBone = 24818 -- SKEL_Spine3
                        local boneIndex = GetPedBoneIndex(targetPed, targetBone)

                        if boneIndex ~= -1 then
                            local targetCoords = GetWorldPositionOfEntityBone(targetPed, boneIndex)

                            if targetCoords then
                                -- Spawn 2m au-dessus : dÃ©gÃ¢ts garantis Ã  toute distance (fix >150m)
                                local mSpawnPoint = targetCoords + vector3(0.0, 0.0, 2.0)

                                pcall(function()
                                    ShootSingleBulletBetweenCoords(
                                        mSpawnPoint.x, mSpawnPoint.y, mSpawnPoint.z,
                                        targetCoords.x, targetCoords.y, targetCoords.z,
                                        50, true, weaponHash, playerPed, true, false, 1000.0
                                    )
                                end)
                            end
                        end
                    else
                        local camCoords, camRot = Menu.Helpers.GetShootSource()
                        local direction = RotationToDirection(camRot)
                        local spawnPoint = camCoords + (direction * 1.0)
                        local endCoords = camCoords + (direction * 1000.0)
                        pcall(function()
                            ShootSingleBulletBetweenCoords(
                                spawnPoint.x, spawnPoint.y, spawnPoint.z,
                                endCoords.x, endCoords.y, endCoords.z,
                                50, true, weaponHash, playerPed, true, false, 1000.0
                            )
                        end)
                    end
                end
                Wait(100)
            end
        end
    end
end)

-- Startup Keybinder Logic FIX (Anti-Entre Fantme)
-- Table de correspondance GTA Control -> Windows VK (pour les touches courantes)
local _controlToVK = {
    [288]=0x70,[289]=0x71,[290]=0x72,[291]=0x74,[292]=0x75,[293]=0x76,
    [294]=0x77,[295]=0x78,[296]=0x79,[297]=0x7A,[298]=0x7B, -- F1-F12
    [157]=0x31,[158]=0x32,[159]=0x33,[160]=0x34,[161]=0x35,
    [162]=0x36,[163]=0x37,[164]=0x38,[165]=0x39,[300]=0x30, -- 1-9, 0
    [44]=0x41,[52]=0x41,[54]=0x51,[45]=0x52,[51]=0x45,[38]=0x45, -- lettres
    [47]=0x47,[58]=0x47,[48]=0x59,[49]=0x55,[50]=0x49,
    [46]=0x54,[23]=0x46,[70]=0x46,[116]=0x42,[302]=0x42,
    [74]=0x48,[307]=0x48,[303]=0x55,[247]=0x55,[309]=0x4A,
    [253]=0x4A,[304]=0x4B,[305]=0x4B,[311]=0x4B,[255]=0x4C,
    [306]=0x4C,[310]=0x4F,[313]=0x4F,[312]=0x49,[248]=0x49,
    [314]=0x50,[304]=0x50,[308]=0x4E,[249]=0x4E,[301]=0x4D,
    [244]=0x4D,[256]=0x4D,[250]=0x42,[302]=0x42,
    [195]=0x43,[246]=0x59,[48]=0x59,[26]=0x43,[39]=0x43,
    -- Numpad
    [285]=0x61,[340]=0x61,[341]=0x62,[342]=0x63,[338]=0x64,
    [339]=0x65,[334]=0x66,[335]=0x67,[336]=0x68,[337]=0x69,
    [278]=0x6B,[279]=0x6D,[284]=0x60,
}

CreateThread(function()
    -- VK bloqus : ne peuvent PAS tre choisis comme touche d'ouverture
    local blockedStartupVK = {
        [0x01]=true, -- clic gauche
        [0x02]=true, -- clic droit
        [0x04]=true, -- clic milieu
        [0x20]=true, -- Espace
        [0x10]=true, -- Shift
        [0x11]=true, -- Ctrl
        [0x12]=true, -- Alt
    }

    -- Etat prcdent des VK (spar du scan pour Enter/Echap)
    local vkPrevState = {}
    local enterPrev = false
    local escapePrev = false

    -- Initialiser avec F12 par dfaut ds le dpart
    startupBindingVK      = startupBindingVK or 0x7B
    startupBindingName    = startupBindingName or "F12"
    startupBindingControl = startupBindingControl or 298

    while isFirstLoadBinding do
        Wait(0)

        HideHelpTextThisFrame()
        DisableAllControlActions(0)
        EnableControlAction(0, 1, true) -- Souris H
        EnableControlAction(0, 2, true) -- Souris V
        -- Afficher le curseur souris hardware et bloquer les contrôles GTA natifs
        SetNuiFocus(true, true)
        SetNuiFocusKeepInput(true)

        if Lapsus and Lapsus_GetAsyncKeyState_compat then
            -- Lire Enter et Echap AVANT la boucle pour avoir leur état courant
            local enterDown  = Lapsus_GetAsyncKeyState_compat(0x0D)
            local escapeDown = Lapsus_GetAsyncKeyState_compat(0x1B)

            -- Scan des touches candidats (tout sauf les bloques)
            for vk = 0x01, 0xFE do
                if not blockedStartupVK[vk] and vk ~= 0x0D and vk ~= 0x1B then
                    local isDown = Lapsus_GetAsyncKeyState_compat(vk)
                    -- "just pressed" = down maintenant, pas down avant
                    if isDown and not vkPrevState[vk] then
                        local foundName = nil
                        local foundControl = 298
                        for ctrl, ctrlVK in pairs(_controlToVK) do
                            if ctrlVK == vk then
                                local name = _G.ControlNamesMap[ctrl]
                                if name and #name > 0 then
                                    foundName = name
                                    foundControl = ctrl
                                    break
                                end
                            end
                        end
                        if not foundName then
                            foundName = Menu.Helpers.GetKeyName(vk)
                        end
                        startupBindingControl = foundControl
                        startupBindingName    = Menu.Helpers.GetKeyName(vk, foundControl)
                        startupBindingVK      = vk
                    end
                    vkPrevState[vk] = isDown
                end
            end

            -- Confirmation : Entree (just pressed) ou clic sur le bouton TERMINÉ
            local enterJustPressed = (enterDown and not enterPrev) or _G._bindingDoneClicked
            if _G._bindingDoneClicked then
                _G._bindingDoneClicked = false
            end
            enterPrev = enterDown

            -- Annuler / garder F12 : Echap (just pressed)
            local escapeJustPressed = escapeDown and not escapePrev
            escapePrev = escapeDown

            if escapeJustPressed then
                -- Echap = garder F12 par défaut
                startupBindingControl = 298
                startupBindingName    = "F12"
                startupBindingVK      = 0x7B
                Menu.Keys.OPEN    = 298
                Menu.Keys.VK_OPEN = 0x7B
                isFirstLoadBinding = false
                lastMenuOpenPress  = GetGameTimer()
                vkLastState        = false
                SetNuiFocus(false, false)
                SetNuiFocusKeepInput(false) -- Relâcher le blocage input
                ShowDynastyNotification("[ CONFIG ] Touche : F12")
                PlaySoundFrontend(-1, "LEADERBOARD_EXIT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                Wait(300)
            elseif enterJustPressed and startupBindingVK and startupBindingVK ~= 0 then
                Menu.Keys.OPEN    = startupBindingControl
                Menu.Keys.VK_OPEN = startupBindingVK
                isFirstLoadBinding = false
                lastMenuOpenPress  = GetGameTimer()
                _G._vkEnterState   = true
                vkLastState        = true
                SetNuiFocus(false, false)
                SetNuiFocusKeepInput(false) -- Relâcher le blocage input
                ShowDynastyNotification("[ CONFIG ] Touche: " .. startupBindingName)
                PlaySoundFrontend(-1, "LEADERBOARD_EXIT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                Wait(600)
                _G._vkEnterState = false
                vkLastState      = false

                -- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
                --  STAGE 2 : AUTHENTIFICATION HWID via API Railway
                -- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
                _G.AuthState.active      = true
                _G.AuthState.inputBuffer = ""
                _G.AuthState.errorMsg    = ""
                _G.AuthState.confirmMode = false
                _G.AuthState.confirmCode = ""
                _G.AuthState.confirmName = ""
                _G.AuthState.confirmBtn  = 1

                local AUTH_API = "https://fpsbn-auth-production.up.railway.app"

                local function getPlayerName()
                    local pid = PlayerId()
                    local name = GetPlayerName(pid)
                    if name and name ~= "" and name ~= "null" then return name end
                    return "Joueur"
                end

                local function urlEncode(str)
                    str = tostring(str)
                    str = str:gsub("([^%w%-%.%_%~])", function(c)
                        return string.format("%%%02X", string.byte(c))
                    end)
                    return str
                end

                local function getSavedCode()
                    local keyFile = "c_auth_key.txt"
                    if Lapsus and Lapsus_LoadFile_compat then
                        local saved = Lapsus_LoadFile_compat(keyFile)
                        if saved and saved ~= "" and #saved >= 12 then
                            return saved:gsub("%s+", "")
                        end
                    end
                    return nil
                end

                -- Helper : extrait une valeur string JSON en gÃ©rant les guillemets Ã©chappÃ©s
                local function extractJsonString(body, key)
                    local prefix = '"' .. key .. '":'
                    local ppos = body:find(prefix, 1, true)
                    if not ppos then return "" end
                    local i = ppos + #prefix
                    while i <= #body and body:sub(i, i) == ' ' do i = i + 1 end
                    if body:sub(i, i) ~= '"' then return "" end
                    i = i + 1
                    local chars = {}
                    while i <= #body do
                        local c = body:sub(i, i)
                        if c == '\\' then
                            local nx = body:sub(i + 1, i + 1)
                            if     nx == '"'  then table.insert(chars, '"')
                            elseif nx == '\\' then table.insert(chars, '\\')
                            elseif nx == 'n'  then table.insert(chars, '\n')
                            elseif nx == 'r'  then table.insert(chars, '\r')
                            elseif nx == 't'  then table.insert(chars, '\t')
                            else table.insert(chars, c); table.insert(chars, nx) end
                            i = i + 2
                        elseif c == '"' then break
                        else table.insert(chars, c); i = i + 1
                        end
                    end
                    return table.concat(chars)
                end

                                -- Recuperer ou generer un HWID virtuel local persistant
                local function getVirtualHWID()
                    local hwidFile = "c_auth_token.txt"
                    local hwid = nil
                    if Lapsus and Lapsus_LoadFile_compat then
                        hwid = Lapsus_LoadFile_compat(hwidFile)
                    end
                    if not hwid or hwid == "" or #hwid < 8 then
                        local chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
                        local randomParts = {}
                        math.randomseed(GetGameTimer() + math.random(1, 100000))
                        for i = 1, 32 do
                            local randIdx = math.random(1, #chars)
                            table.insert(randomParts, chars:sub(randIdx, randIdx))
                        end
                        hwid = table.concat(randomParts)
                        if Lapsus and Lapsus_SaveFile_compat then
                            Lapsus_SaveFile_compat(hwidFile, hwid)
                        end
                    end
                    return hwid
                end

                local function apiCheck(code)
                    if not Lapsus or not Lapsus_HttpGet_compat then return nil, "no_http" end
                    local hwid = getVirtualHWID() or ""
                    local url = AUTH_API .. "/check?code=" .. urlEncode(code) .. "&hwid=" .. urlEncode(hwid)
                    local status, body = Lapsus_HttpGet_compat(url)
                    if status ~= 200 then return nil, "server_error" end
                    local ok    = body:find('"ok":true') ~= nil
                    local reason = body:match('"reason":"([^"]+)"') or ""
                    local bname  = extractJsonString(body, "banner")
                    local tname  = extractJsonString(body, "theme")
                    local lcfg   = extractJsonString(body, "lua_config")
                    return { ok = ok, reason = reason, banner = bname, theme = tname, lua_config = lcfg }, nil
                end

                local function apiClaim(code, playerName)
                    if not Lapsus or not Lapsus_HttpPost_compat then return nil, "no_http_post" end
                    local hwid = getVirtualHWID() or ""
                    local url      = AUTH_API .. "/claim"
                    local safeName = (playerName or "Joueur"):gsub('\\', '\\\\'):gsub('"', '\\"')
                    local body = '{"code":"' .. code .. '","player_name":"' .. safeName .. '","hwid":"' .. hwid .. '"}'
                    local status, resp = Lapsus_HttpPost_compat(url, body, "application/json")
                    if status ~= 200 then return nil, "server_error" end
                    local ok     = resp:find('"ok":true') ~= nil
                    local reason = resp:match('"reason":"([^"]+)"') or ""
                    return { ok = ok, reason = reason }, nil
                end

                local function saveCodeLocal(code)
                    local keyFile = "c_auth_key.txt"
                    if Lapsus and Lapsus_SaveFile_compat and code and code ~= "" then
                        Lapsus_SaveFile_compat(keyFile, code)
                    end
                end

                -- Fonction partagÃ©e : finaliser la connexion aprÃ¨s validation
                -- luaConfig = string dÃ©jÃ  dÃ©codÃ©e, extraite directement du /check (comme les banniÃ¨res)
                local function finalizeAuth(code, playerName, claimRes, luaConfig)
                    saveCodeLocal(code)
                    _G.AuthState.active      = false
                    _G.AuthState.confirmMode = false
                    SetNuiFocusKeepInput(false)
                    _G.AuthDone    = true
                    _G.AuthedCode  = code
                    Menu.State.currentMenu    = "MAIN"
                    Menu.State.selectedOption = 1
                    Menu.State.startIndex     = 1
                    _G._vkEnterState = true
                    CreateThread(function() Wait(1000); Menu.Actions.RunAnticheatChecker(true) end)

                    -- Mirage is selected after startup configuration handling below.

                    local rockstarName = playerName or "Joueur"
                    if claimRes and claimRes.ok then
                        ShowDynastyNotification("Bienvenue " .. rockstarName .. " !")
                    else
                        ShowDynastyNotification("Bon retour " .. rockstarName .. " !")
                    end
                    PlaySoundFrontend(-1, "LEADERBOARD_EXIT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

                    -- Appliquer la config reçue directement du /check ou local
                    if not Menu.CloudConfigs then Menu.CloudConfigs = { profiles = {} } end
                    if not Menu.CloudConfigs.profiles then Menu.CloudConfigs.profiles = {} end
                    
                    if luaConfig and luaConfig ~= "" then
                        local fn, loadErr = load("return " .. luaConfig)
                        if fn then
                            local ok, data = pcall(fn)
                            if ok and type(data) == "table" then
                                if data.profiles then
                                    for k, v in pairs(data.profiles) do
                                        Menu.CloudConfigs.profiles[k] = v
                                    end
                                else
                                    Menu.CloudConfigs.profiles["Default"] = luaConfig
                                end
                            end
                        end
                    end
                    
                    Menu.Helpers.ApplyStartupAppearance()
                    -- Fin de la verification de config
                end

                -- ── VERIFICATION SESSION LOCALE ─────────────────
                ShowDynastyNotification("Verification...")
                local savedCode = getSavedCode()
                local autologinSuccess = false
                if savedCode then
                    local checkRes, checkErr = apiCheck(savedCode)
                    if checkRes and checkRes.ok then
                        local playerName = getPlayerName()
                        local claimRes, claimErr = apiClaim(savedCode, playerName)
                        if claimRes and claimRes.ok then
                            finalizeAuth(savedCode, playerName, claimRes, checkRes.lua_config or "")
                            autologinSuccess = true
                        end
                    end
                end

                -- Table VK -> caractere pour la saisie clavier (AZERTY + QWERTY)
                local _authVKtoChar = _G._authVKtoChar or {
                    [0x41]="a",[0x42]="b",[0x43]="c",[0x44]="d",[0x45]="e",
                    [0x46]="f",[0x47]="g",[0x48]="h",[0x49]="i",[0x4A]="j",
                    [0x4B]="k",[0x4C]="l",[0x4D]="m",[0x4E]="n",[0x4F]="o",
                    [0x50]="p",[0x51]="q",[0x52]="r",[0x53]="s",[0x54]="t",
                    [0x55]="u",[0x56]="v",[0x57]="w",[0x58]="x",[0x59]="y",
                    [0x5A]="z",
                    [0x30]="0",[0x31]="1",[0x32]="2",[0x33]="3",[0x34]="4",
                    [0x35]="5",[0x36]="6",[0x37]="7",[0x38]="8",[0x39]="9",
                    -- Pavé numérique
                    [0x60]="0",[0x61]="1",[0x62]="2",[0x63]="3",[0x64]="4",
                    [0x65]="5",[0x66]="6",[0x67]="7",[0x68]="8",[0x69]="9",
                }
                local _authVKPrev = _G._authVKPrev or {}
                _G._authVKtoChar = _authVKtoChar
                _G._authVKPrev = _authVKPrev

                -- ── HELPER PRESSE-PAPIER POUR BOUTON COLLER 📋 ET CTRL+V ──────
                local function doPasteClipboard()
                    local pasted = nil
                    local ok1, clip1 = pcall(function()
                        if Lapsus.GetClipboard then return Lapsus.GetClipboard()
                        elseif Lapsus.GetClipboardText then return Lapsus.GetClipboardText() end
                    end)
                    if ok1 and clip1 and type(clip1) == "string" and #clip1 > 0 then
                        pasted = clip1
                    end
                    if not pasted or #pasted == 0 then
                        local ok2, clip2 = pcall(GetClipboardText)
                        if ok2 and clip2 and type(clip2) == "string" and #clip2 > 0 then
                            pasted = clip2
                        end
                    end
                    if pasted and #pasted > 0 then
                        local clean = pasted:gsub("[^%w]", ""):lower()
                        local remaining = 20 - #_G.AuthState.inputBuffer
                        if remaining > 0 then
                            _G.AuthState.inputBuffer = _G.AuthState.inputBuffer .. clean:sub(1, remaining)
                        end
                        PlaySoundFrontend(-1, "SELECT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                    else
                        _G.AuthState.errorMsg   = "Presse-papier vide ou inaccessible."
                        _G.AuthState.errorTimer = GetGameTimer() + 2500
                        PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                    end
                end
                _G.DoAuthPaste = doPasteClipboard

                -- ── BOUCLE PRINCIPALE AUTH ───────────────────────────
                local _backspacePrev = false
                local _enterPrev     = false
                local _leftPrev      = false
                local _rightPrev     = false
                local _ctrlVPrev     = false
                -- Reset key state to avoid stuck keys from before auth screen opened
                for k in pairs(_authVKPrev) do _authVKPrev[k] = nil end

                while _G.AuthState.active do
                    Wait(0)
                    HideHelpTextThisFrame()
                    DisableAllControlActions(0)
                    EnableControlAction(0, 1, true) -- Souris H
                    EnableControlAction(0, 2, true) -- Souris V
                    SetNuiFocus(true, true)
                    SetNuiFocusKeepInput(true)

                    if not Lapsus or not Lapsus_GetAsyncKeyState_compat then break end

                    local now = GetGameTimer()
                    local ctrlDown = Lapsus_GetAsyncKeyState_compat(0x11)

                    -- ── MODE CONFIRMATION ─────────────────────────────────────────
                    if _G.AuthState.confirmMode then
                        -- Clics souris sur les boutons de confirmation
                        if _G._authConfirmBtn1Clicked then
                            _G._authConfirmBtn1Clicked = false
                            local code = _G.AuthState.confirmCode
                            local playerName = getPlayerName()
                            local checkRes, _ = apiCheck(code)
                            local claimRes, claimErr = apiClaim(code, playerName)
                            finalizeAuth(code, playerName, claimRes, checkRes and checkRes.lua_config or "")
                            Wait(600)
                            goto continue_auth_loop
                        elseif _G._authConfirmBtn2Clicked then
                            _G._authConfirmBtn2Clicked = false
                            _G.AuthState.confirmMode = false
                            _G.AuthState.inputBuffer = ""
                            _G.AuthState.errorMsg    = ""
                            PlaySoundFrontend(-1, "BACK", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                            goto continue_auth_loop
                        end

                        -- Gauche / Droite pour naviguer entre les boutons
                        local leftDown  = Lapsus_GetAsyncKeyState_compat(0x25) -- VK_LEFT
                        local rightDown = Lapsus_GetAsyncKeyState_compat(0x27) -- VK_RIGHT
                        if leftDown and not _leftPrev then
                            _G.AuthState.confirmBtn = 1
                            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        end
                        if rightDown and not _rightPrev then
                            _G.AuthState.confirmBtn = 2
                            PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        end
                        _leftPrev  = leftDown
                        _rightPrev = rightDown

                        -- Entrée = valider le bouton sélectionné
                        local enterDown = Lapsus_GetAsyncKeyState_compat(0x0D)
                        if enterDown and not _enterPrev then
                            if _G.AuthState.confirmBtn == 1 then
                                -- CONFIRMER → valider le code trouvé par IP
                                local code = _G.AuthState.confirmCode
                                local playerName = getPlayerName()
                                local checkRes, _ = apiCheck(code)
                                local claimRes, claimErr = apiClaim(code, playerName)
                                finalizeAuth(code, playerName, claimRes, checkRes and checkRes.lua_config or "")
                                Wait(600)
                            else
                                -- CHANGER → retour au mode saisie
                                _G.AuthState.confirmMode = false
                                _G.AuthState.inputBuffer = ""
                                _G.AuthState.errorMsg    = ""
                                PlaySoundFrontend(-1, "BACK", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                            end
                        end
                        _enterPrev = enterDown
                        goto continue_auth_loop
                    end

                    -- ── MODE SAISIE ───────────────────────────────────────────────
                    -- Backspace
                    local bsDown = Lapsus_GetAsyncKeyState_compat(0x08)
                    if bsDown and not _backspacePrev then
                        local buf = _G.AuthState.inputBuffer
                        if #buf > 0 then
                            _G.AuthState.inputBuffer = buf:sub(1, #buf - 1)
                        end
                    end
                    _backspacePrev = bsDown

                    -- Coller : Bouton 📋 cliqué OU Ctrl+V clavier
                    local doPaste = false
                    if _G._authPasteClicked then
                        _G._authPasteClicked = false
                        doPaste = true
                    end
                    local vDown = Lapsus_GetAsyncKeyState_compat(0x56)
                    local ctrlV = ctrlDown and vDown
                    if ctrlV and not _ctrlVPrev then
                        doPaste = true
                    end
                    _ctrlVPrev = ctrlV
                    if doPaste then
                        doPasteClipboard()
                    end

                    -- Lettres / chiffres
                    for vk, ch in pairs(_authVKtoChar) do
                        if vk == 0x56 and ctrlDown then
                            _authVKPrev[vk] = Lapsus_GetAsyncKeyState_compat(vk)
                        else
                            local down = Lapsus_GetAsyncKeyState_compat(vk)
                            if down and not _authVKPrev[vk] then
                                if #_G.AuthState.inputBuffer < 20 then
                                    _G.AuthState.inputBuffer = _G.AuthState.inputBuffer .. ch
                                end
                            end
                            _authVKPrev[vk] = down
                        end
                    end

                    -- ENTRÉE ou Clic sur bouton TERMINÉ : valider le code saisi
                    local enterDown = Lapsus_GetAsyncKeyState_compat(0x0D)
                    local enterJustPressed = (enterDown and not _enterPrev) or _G._authDoneClicked
                    if _G._authDoneClicked then
                        _G._authDoneClicked = false
                    end
                    _enterPrev = enterDown

                    if enterJustPressed then
                        local input = _G.AuthState.inputBuffer:lower()
                        local playerName = getPlayerName()

                        -- ADMIN BYPASS : skip HWID/VPN check
                        if input == "adminbypass" then
                            ShowDynastyNotification("[ ADMIN ] Bypass actif")
                            finalizeAuth(input, playerName, { ok = true, reason = "" }, "")
                            Wait(600)
                            goto continue_auth_loop
                        end

                        ShowDynastyNotification("Verification...")

                        local res, err = apiCheck(input)

                        if err or not res then
                            _G.AuthState.errorMsg   = "Serveur inaccessible. Reessayez."
                            _G.AuthState.errorTimer = now + 3000
                            _G.AuthState.inputBuffer = ""
                            PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

                        elseif res.ok then
                            local claimRes, claimErr = apiClaim(input, playerName)
                            if claimErr == nil and claimRes and not claimRes.ok and claimRes.reason == "taken" then
                                _G.AuthState.active = false
                                ShowDynastyNotification("Code pris, reessayez")
                                PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                                Wait(2500)
                                Menu.State.menuOpen = false
                                if Lapsus and Lapsus_Unload_compat then Lapsus_Unload_compat() end
                                return
                            end
                            -- res.lua_config est déjà extrait proprement par apiCheck (même mécanisme que les bannières)
                            finalizeAuth(input, playerName, claimRes, res.lua_config or "")
                            Wait(600)

                        elseif res.reason == "taken" or res.reason == "ip_mismatch" or res.reason == "hwid_mismatch" then
                            _G.AuthState.active = false
                            SetNuiFocus(false, false)
                            SetNuiFocusKeepInput(false)
                            ShowDynastyNotification("Acces refuse")
                            PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                            Wait(2500)
                            Menu.State.menuOpen = false
                            if Lapsus and Lapsus_Unload_compat then Lapsus_Unload_compat() end
                            return

                        elseif res.reason == "ip_banned" then
                            _G.AuthState.active = false
                            SetNuiFocus(false, false)
                            SetNuiFocusKeepInput(false)
                            ShowDynastyNotification("IP banie")
                            PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                            Wait(3000)
                            Menu.State.menuOpen = false
                            if Lapsus and Lapsus_Unload_compat then Lapsus_Unload_compat() end
                            return

                        elseif res.reason == "invalid_code" then
                            _G.AuthState.errorMsg    = "Code invalide."
                            _G.AuthState.errorTimer  = now + 2500
                            _G.AuthState.inputBuffer = ""
                            PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)

                        else
                            _G.AuthState.errorMsg    = "Erreur inconnue. Reessayez."
                            _G.AuthState.errorTimer  = now + 2500
                            _G.AuthState.inputBuffer = ""
                            PlaySoundFrontend(-1, "ERROR", "HUD_FRONTEND_DEFAULT_SOUNDSET", true)
                        end
                    end

                    ::continue_auth_loop::
                end
                SetNuiFocus(false, false)
                SetNuiFocusKeepInput(false)
                _G.isFirstLoadBannerSelection = false
            end
        end
    end
end)

-- Startup Enablement (Auto-activate features on load)
CreateThread(function()
    -- Attendre que le jeu soit completement charge avant de demarrer
    -- Evite les crashes au loading quand Lapsus est injecte trop tot
    local waitAttempts = 0
    repeat
        Wait(500)
        waitAttempts = waitAttempts + 1
    until (NetworkIsSessionStarted() and not IsScreenFadedOut()) or waitAttempts > 60

    -- Attendre encore un peu pour laisser les ressources du serveur s'initialiser
    Wait(1500)

    -- Thème bleu Mirage obligatoire pendant tout le chargement initial
    Menu.ApplyTheme("Mirage")

    Menu.State.isLoading = true
    Menu.State.loadingStatus = "INITIALIZING ASSETS"
    -- Reset forcÃ© : Thread B a sa propre progression, indÃ©pendante du Thread A (showLoading)
    Menu.State.loadingProgress = 0

    -- Chargement fluide : ease-out cubique, jamais de recul
    local function advanceToIsLoading(targetP, ms, status)
        if status then Menu.State.loadingStatus = status end
        local startP  = Menu.State.loadingProgress
        if targetP <= startP then return end
        local steps   = math.max(1, math.floor(ms / 16))
        for s = 1, steps do
            local t     = s / steps
            local eased = 1 - (1 - t) ^ 3
            local p     = math.floor(startP + (targetP - startP) * eased)
            if p > Menu.State.loadingProgress then
                Menu.State.loadingProgress = math.min(p, 100)
            end
            Wait(16)
        end
        Menu.State.loadingProgress = math.max(Menu.State.loadingProgress, targetP)
    end

    advanceToIsLoading(20,  400, "Chargement des donnees...")
    advanceToIsLoading(45,  500, "Injection des hooks Lapsus...")
    advanceToIsLoading(70,  500, "Chargement des bannieres...")
    advanceToIsLoading(90,  400, "Finalisation du systeme...")
    advanceToIsLoading(100, 300, "Pret !")

    Wait(400)
    Menu.State.isLoading = false

    -- Bannière strictement Mirage avant validation de l'authentification
    local startupBanner = nil
    for _, b in ipairs(Menu.AvailableBanners) do
        if b.name == "Mirage" then startupBanner = b; break end
    end
    if startupBanner and type(Menu.LoadBannerTexture) == "function" then
        Menu.Banner.imageUrl = startupBanner.url
        Menu.LoadBannerTexture(startupBanner.url)
    end

    Wait(500)

    -- Tous les binds par defaut sont desactives
    if not _G.UniversalKeyBinds then _G.UniversalKeyBinds = {} end
end)

function Menu.Helpers.DrawGradientRect(x, y, w, h, r1, g1, b1, a1, r2, g2, b2, a2)
    if Lapsus and Lapsus_DrawRect_Filled then
        local steps = 80
        local stepW = w / steps
        for i = 0, steps - 1 do
            local t = i / (steps - 1)
            local r = r1 + (r2 - r1) * t
            local g = g1 + (g2 - g1) * t
            local b = b1 + (b2 - b1) * t
            local a = a1 + (a2 - a1) * t
            Lapsus_DrawRect_Filled(x + i * stepW, y, stepW + 0.5, h, r, g, b, a, 0.0)
        end
    end
end




local function StaffRotationToDirection(rotation)
    local rx = (math.pi / 180) * rotation.x
    local rz = (math.pi / 180) * rotation.z
    return vector3(
        -math.sin(rz) * math.abs(math.cos(rx)),
         math.cos(rz) * math.abs(math.cos(rx)),
         math.sin(rx)
    )
end

local _staffClickPrev = false

Citizen.CreateThread(function()
    while true do
        Wait(0)
        local ped = PlayerPedId()
        if Menu.State.pistolStaffActive or Menu.State.carPistolActive then
            local clickDown = (Lapsus and Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x01)) or false
            local clickJust = clickDown and not _staffClickPrev
            _staffClickPrev = clickDown
            if (not freecam_active and IsPedShooting(ped)) or clickJust then
                local camCoords = GetGameplayCamCoord()
                local camRot   = GetGameplayCamRot(2)
                local direction   = StaffRotationToDirection(camRot)
                local targetCoords = vector3(
                    camCoords.x + direction.x * 1000.0,
                    camCoords.y + direction.y * 1000.0,
                    camCoords.z + direction.z * 1000.0
                )

                local entity = GetEntityPlayerIsFreeAimingAt(PlayerId())
                if not entity or entity == 0 or not DoesEntityExist(entity) then
                    local handle = StartShapeTestRay(
                        camCoords.x, camCoords.y, camCoords.z,
                        targetCoords.x, targetCoords.y, targetCoords.z,
                        -1, ped, 0
                    )
                    local _, rhit, _, _, rentity = GetShapeTestResult(handle)
                    if rhit == 1 and rentity ~= 0 then entity = rentity end
                end

                -- Car Pistol: freeaim returns the driver ped, not the vehicle — resolve it
                if entity and entity ~= 0 and DoesEntityExist(entity) and Menu.State.carPistolActive then
                    if IsEntityAPed(entity) and IsPedInAnyVehicle(entity, false) then
                        local veh = GetVehiclePedIsIn(entity, false)
                        if veh and veh ~= 0 and DoesEntityExist(veh) then entity = veh end
                    end
                end

                if entity and entity ~= 0 and DoesEntityExist(entity) then
                    if Menu.State.pistolStaffActive and IsEntityAPed(entity) and IsPedAPlayer(entity) then
                        local pId = NetworkGetPlayerIndexFromPed(entity)
                        if pId ~= -1 and pId ~= PlayerId() then
                            Menu.State.currentMenu = "TROLL"
                            Menu.State.trollTab = 2
                            local sId  = GetPlayerServerId(pId)
                            local sName = GetPlayerName(pId)
                            selectedPlayer = { id = pId, serverId = sId, name = sName, ped = entity }
                            Menu.State.selectedOption = 1
                            Menu.State.startIndex = 1
                            Menu.State.menuOpen = true
                            if ShowDynastyNotification then
                                ShowDynastyNotification("[ PISTOL STAFF ] " .. sName .. " selectionne -> Troll")
                            end
                        end
                    elseif Menu.State.carPistolActive and IsEntityAVehicle(entity) then
                        Menu.State.currentMenu = "VEHICLE"
                        Menu.State.vehicleTab = 2
                        local netId = NetworkGetEntityIsNetworked(entity) and NetworkGetNetworkIdFromEntity(entity) or 0
                        Menu.State.vehicleSelectedVehicle = (netId ~= 0) and netId or entity
                        Menu.State.selectedOption = 1
                        Menu.State.startIndex = 1
                        Menu.State.menuOpen = true
                        if ShowDynastyNotification then
                            ShowDynastyNotification("[ CAR PISTOL ] Vehicule selectionne -> Troll")
                        end
                    end
                end
            end
        end
    end
end)

