do
Menu.State.displayStaffActive = false

--[[
    FIVEM RGB ESP
    Client-side Lua
    Features:
    - Invisible player detection
    - RGB rainbow tracers
    - Skeleton ESP
    - Player names
    - Distance ESP
    - Toggle command
]]

local ESP = {
    enabled = false,
    skeleton = true,
    tracers = true,
    names = true,
    distance = true,
    invisibleOnly = false,
    maxDistance = 500.0,
    rainbowSpeed = 1.8
}

local bones = {
    {31086, 39317}, -- Head -> Neck
    {39317, 24816}, -- Neck -> Spine
    {24816, 23553},
    {23553, 11816},

    -- Left arm
    {39317, 45509},
    {45509, 61163},
    {61163, 18905},

    -- Right arm
    {39317, 40269},
    {40269, 28252},
    {28252, 57005},

    -- Left leg
    {11816, 58271},
    {58271, 63931},
    {63931, 14201},

    -- Right leg
    {11816, 51826},
    {51826, 36864},
    {36864, 52301}
}

local function rainbow(offset)
    local t = GetGameTimer() / 1000.0
    t = t * ESP.rainbowSpeed + (offset or 0)

    local r = math.floor(
        (math.sin(t) + 1.0) * 127.5
    )
    local g = math.floor(
        (math.sin(t + 2.094) + 1.0) * 127.5
    )
    local b = math.floor(
        (math.sin(t + 4.188) + 1.0) * 127.5
    )

    return r, g, b
end

local function isInvisible(ped)
    if not DoesEntityExist(ped) then
        return false
    end

    return not IsEntityVisible(ped)
        or GetEntityAlpha(ped) < 255
end

local function staffThickLine(x1, y1, z1, x2, y2, z2, r, g, b, a)
    local width = 0.008
    DrawLine(x1,y1,z1,x2,y2,z2,r,g,b,a)
    for _, d in ipairs({-width, width}) do
        DrawLine(x1+d,y1,z1,x2+d,y2,z2,r,g,b,a)
        DrawLine(x1,y1+d,z1,x2,y2+d,z2,r,g,b,a)
        DrawLine(x1,y1,z1+d,x2,y2,z2+d,r,g,b,a)
    end
end

local function drawBone(ped, boneA, boneB, r, g, b)
    local a = GetPedBoneCoords(
        ped, boneA, 0.0, 0.0, 0.0
    )
    local c = GetPedBoneCoords(
        ped, boneB, 0.0, 0.0, 0.0
    )

    staffThickLine(
        a.x, a.y, a.z,
        c.x, c.y, c.z,
        r, g, b, 255
    )
end

local function drawSkeleton(ped, r, g, b)
    for _, pair in ipairs(bones) do
        drawBone(
            ped, pair[1], pair[2],
            r, g, b
        )
    end
end

local function drawText3D(x, y, z, message, r, g, b)
    local visible, sx, sy =
        World3dToScreen2d(x, y, z)

    if not visible then return end

    SetTextScale(0.0, 0.32)
    SetTextFont(4)
    SetTextProportional(1)
    SetTextColour(r, g, b, 255)
    SetTextCentre(true)
    SetTextOutline()

    BeginTextCommandDisplayText("STRING")
    AddTextComponentSubstringPlayerName(message)
    EndTextCommandDisplayText(sx, sy)
end

local airborneSince = {}
local function suspectedNoclip(player, ped)
    local suspicious = not IsPedInAnyVehicle(ped, false)
        and not IsEntityAttached(ped) and not IsPedFalling(ped)
        and not IsPedJumping(ped) and not IsPedRagdoll(ped)
        and not IsPedInParachuteFreeFall(ped) and not IsPedSwimming(ped)
        and GetEntityHeightAboveGround(ped) > 1.5
    if not suspicious then airborneSince[player] = nil; return false end
    local now = GetGameTimer()
    local sample = airborneSince[player]
    if not sample or sample.ped ~= ped or now - sample.last > 500 then
        sample = {ped=ped, since=now, last=now}
        airborneSince[player] = sample
    end
    sample.last = now
    return now - sample.since >= 1200
end
local function staffFeet(ped)
    local left = GetPedBoneCoords(ped, 14201, 0.0, 0.0, 0.0)
    local right = GetPedBoneCoords(ped, 52301, 0.0, 0.0, 0.0)
    return {x=(left.x + right.x) * 0.5, y=(left.y + right.y) * 0.5, z=math.min(left.z, right.z)}
end

local function renderESP()
    local me = PlayerPedId()
    if not DoesEntityExist(me) then return end

    local myCoords = GetEntityCoords(me)
    local myFeet = staffFeet(me)
    local players = GetActivePlayers()

    for _, player in ipairs(players) do
        if player ~= PlayerId()
            and NetworkIsPlayerActive(player) then

            local ped = GetPlayerPed(player)

            if ped ~= 0
                and DoesEntityExist(ped)
                and not IsEntityDead(ped) then

                local coords = GetEntityCoords(ped)
                local dist = #(myCoords - coords)
                local invisible = isInvisible(ped)
                local noclip = suspectedNoclip(player, ped)

                if dist <= ESP.maxDistance
                    and (invisible or noclip) then

                    local r, g, b = rainbow(player * 0.35)
                    local feet = staffFeet(ped)

                    if ESP.tracers then
                        staffThickLine(
                            myFeet.x,
                            myFeet.y,
                            myFeet.z,
                            feet.x,
                            feet.y,
                            feet.z,
                            r, g, b, 255
                        )
                    end

                    if ESP.skeleton then
                        drawSkeleton(ped, r, g, b)
                    end

                    if ESP.names then
                        local name = GetPlayerName(player)
                            or "Unknown"

                        local label = name

                        if invisible then
                            label = "[INVISIBLE] " .. label
                        elseif noclip then
                            label = "[NOCLIP ?] " .. label
                        end

                        if ESP.distance then
                            label = label ..
                                string.format(
                                    " [%.0fm]", dist
                                )
                        end

                        drawText3D(
                            feet.x,
                            feet.y,
                            feet.z - 0.20,
                            label,
                            r, g, b
                        )
                    end
                end
            end
        end
    end
end

-- Main ESP loop
CreateThread(function()
    while true do
        if Menu.State.displayStaffActive then
            renderESP()
            Wait(0)
        else
            Wait(250)
        end
    end
end)

