Lapsus_DrawText_compat=function(x,y,text,...)return nativeText(x,y,englishText(text),...)end
local nativeWidth=Lapsus_GetTextWidth_compat
Lapsus_GetTextWidth_compat=function(text,...)return nativeWidth(englishText(text),...)end
