_G._mirageNuiUntil=0
local labelStates={
 ['Full God Mode']='fullGodModeActive',['Semi God Mode']='semiGodModeActive',
 ['Anti Headshot']='antiHeadshotActive',['Anti-Teleport']='antiTpActive',
 ['Noclip']='noclipActive',['Slide']='slideActive',['Freecam Info']='freecamInfoVisible',
 ['Rage Bot']='shootVisionActive',['Rapid Fire']='rapidFireActive',['Damage Boost']='damageBoostActive',
