 ['Beast Jump']='beastJumpActive',['Spinbot']='spinbotActive',['Tiny Player']='tinyPlayerActive'
}
local function themeForNui()
    local themeName=Menu.AvailableThemes and Menu.AvailableThemes[Menu.ThemeIndex or 1]
    local selectedBanner=Menu.AvailableBanners and Menu.AvailableBanners[Menu.BannerIndex or 1]
    local defaultMirage=selectedBanner and selectedBanner.name=='Mirage'
    if (not themeName or themeName=='Mirage') and (defaultMirage or not _G.customThemeLoaded) then
        return {r=125,g=125,b=125}
    end
    local rgb=Menu.Colors and (Menu.Colors.SelectedBg or Menu.Colors.HeaderPink) or {}
    local function channel(value) return math.max(0,math.min(255,math.floor(tonumber(value) or 95))) end
    return {r=channel(rgb.r),g=channel(rgb.g),b=channel(rgb.b)}
end
local function tabsFor(menu,S)
    if menu=='PLAYER' or menu=='MOVEMENT' or menu=='WARDROBE' then
        return {'Player','Movement','Wardrobe'},({PLAYER=1,MOVEMENT=2,WARDROBE=3})[menu]
    end
    if menu=='ONLINE' then return S.onlineTabNames or {'Players'},S.onlineTab or 1 end
    if menu=='TROLL' then return Menu.Data.Options.Troll.Tabs or {},S.trollTab or 1 end
    if menu=='VIP_PED' then return {'Choose Ped','Variations'},S.pedTab or 1 end
    if menu=='WEAPON' then return Menu.Data.Options.Weapon.Tabs or {},S.weaponTab or 1 end
    if menu=='VEHICLE' then return Menu.Data.Options.Vehicle.Tabs or {},S.vehicleTab or 1 end
    if menu=='SETTINGS_RENDER' or menu=='SETTINGS_UTILITY' then
        return {'Render','Utility'},menu=='SETTINGS_RENDER' and 1 or 2
    end
    if menu=='MAIN' or menu=='MISC' or menu=='EXPLOIT' or menu=='VIP' or menu=='SETTINGS' then
        return {'Main','Exploit','Settings'},({MAIN=1,MISC=1,EXPLOIT=2,VIP=2,SETTINGS=3})[menu]
    end
    if menu=='DYNA' then return {'Ped','Give'},S.dynaTab or 1 end
    return {},1
end
local function rowFor(item,index,menu,S)
    local row={index=index,label=type(item)=='string' and item or '',kind='action'}
    if type(item)=='table' then
        row.label=tostring(item.name or item.label or item.display or item.model or '')
        row.kind=tostring(item.type or 'action')
        if item.id=='exploit_redside' then
            row.badge=tostring(#(Menu.Data.Options.EXPLOIT_REDSIDE_WILD or {}) + #(Menu.Data.Options.EXPLOIT_REDSIDE_PETS or {}))
        elseif item.id=='redside_group' then
            row.badge=tostring(#(Menu.Data.Options[item.destination] or {}))
        end
        if item.state and type(S[item.state])=='boolean' then row.toggle=true; row.active=S[item.state] end
        if type(item.value)=='number' or type(item.value)=='string' then
            row.badge=tostring(item.value);row.selector=true
        end
        if item.toggleActive~=nil then row.toggle=true; row.active=not not item.toggleActive end
        if type(item.options)=='table' then
            local i=item.valueIdx or 1
            if item.cat and _G._vipGiveCatIdx then i=_G._vipGiveCatIdx[item.cat] or i end
            row.badge=tostring(item.options[i] or '')
            row.selector=true
        end
        if item.id=='solo_session' then row.toggle=true;row.active=not not S.soloSessionActive end
        if item.id=='spoof_weapon' then row.toggle=true;row.active=not not S.spoofWeaponActive end
        if item.type=='weapon_size' then
            row.toggle=true;row.active=not not S.weaponSizeActive
            row.badge=tostring(S.weaponSizeValue or 10);row.selector=true
        end
        if item.type=='toggle_slider_freecam' then
            row.toggle=true;row.active=not not _G.freecam_active
            row.badge=tostring(_G.freeCamSpeed or 0.5)
        end
        if item.type=='slider' then
            local value=item.value
            if item.id=='silentKillFov' then value=S.silentKillFov or 30 end
            if item.id=='vip_spam_speed' then value=S.colSpamSpeed or 10 end
            if value~=nil then
                row.badge=tostring(value)..(item.id=='vip_spam_speed' and ' ms' or item.id=='silentKillFov' and '°' or '')
                row.slider={value=tonumber(value),min=item.min or (item.id=='vip_spam_speed' and 10 or 0),max=item.max or (item.id=='vip_spam_speed' and 500 or 100),inverse=item.id=='vip_spam_speed'}
            end
        end
    end
    local state=labelStates[row.label]
    if state then row.toggle=true;row.active=not not S[state] end
    if row.label=='Noclip' and menu=='MOVEMENT' then
        row.badge=string.format('%.1f',S.noclipSpeed or 5.0)
        row.slider={value=S.noclipSpeed or 5.0,min=0,max=100}
    end
    if item and type(item)=='table' and item.id=='vip_mapcollision' then
        local idx=S.colSpamScenarioIdx or item.valueIdx or 1
        if item.options then row.badge=tostring(item.options[idx] or '') end
        row.toggle=true;row.active=not not S.colSpammerActive
    end
    if row.label=='Layout' then row.badge=(_G.freecam_layout==2) and 'QWERTY' or 'AZERTY' end
    row.submenu=row.kind=='submenu' or menu=='MAIN' or menu=='SETTINGS'
    row.label=row.label:gsub('%s*>%s*$',''):gsub('~[^~]+~','')
    return row
end
local redsideNuiTitles={
    EXPLOIT_REDSIDE='Redside',
    EXPLOIT_REDSIDE_WILD='Redside - Animaux',
    EXPLOIT_REDSIDE_PETS='Redside - Chiens, chats et renards'
}
function Menu.Helpers.BuildNuiSnapshot()
    local S=Menu.State
    local menu=S.currentMenu or 'MAIN'
    local full=Menu.Helpers.GetFullListForMenu(menu) or {}
    local rows={}
    for i,item in ipairs(full) do rows[#rows+1]=rowFor(item,i,menu,S) end
    local tabs,active=tabsFor(menu,S)
    local banner=Menu.Banner and Menu.Banner.imageUrl or (base..'/assets/mirage-banner.png?v=21')
    if Menu.AvailableBanners and Menu.AvailableBanners[Menu.BannerIndex or 1] then
        local selected=Menu.AvailableBanners[Menu.BannerIndex or 1]
        banner=selected.url or banner
        if selected.name=='Mirage' then banner=base..'/assets/mirage-banner.png?v=21' end
    end
    local blocking=type(IsBlockingUIActive)=='function' and IsBlockingUIActive() or false
    return {
        visible=_G._mirageNuiEnabled and _G.AuthDone==true and S.menuOpen==true
            and not S.isLoading and not S.showLoading and not blocking,
        menu=menu,title=redsideNuiTitles[menu] or menu:gsub('_',' '),tabs=tabs,activeTab=active,
        rows=rows,selected=S.selectedOption or 1,start=S.startIndex or 1,maxDisplay=S.maxDisplay or 6,
        banner=banner,scale=tonumber(_G.menuScale) or .83,
        position=S.menuPosIdx or 1,sidebar=S.sidebarSide or 'left',
        binding=tostring(S.menuKeyDisplay or 'Bind'),version='Mirage',theme=themeForNui(),
        border={enabled=S.menuBorderActive~=false,style=S.menuBorderStyle or 3},
        help={previous=_G.freecam_layout==2 and 'Q' or 'A'}
    }
end
-- Widgets exportes depuis les memes donnees que les anciens HUD.
local toastSerial=0
local originalNotification=ShowDynastyNotification
ShowDynastyNotification=function(text)
    originalNotification(text)
    if text and tostring(text)~='' then
        toastSerial=toastSerial+1
        _G._mirageNuiToast={id=toastSerial,text=Menu.Helpers.ShortNotification(text),time=GetGameTimer()}
    end
end
_G.ShowDynastyNotification=ShowDynastyNotification
local function bindState(bind)
    local label=tostring(bind.label or '')
    local field=labelStates[label]
    if field then return true,not not Menu.State[field] end
    local ok,list=pcall(Menu.Helpers.GetFullListForMenu,bind.menu)
    if ok and type(list)=='table' then
        for _,item in ipairs(list) do
            if type(item)=='table' and (item.name==label or item.label==label) then
                if item.state and type(Menu.State[item.state])=='boolean' then return true,Menu.State[item.state] end
                if item.toggleActive~=nil then return true,not not item.toggleActive end
            end
        end
    end
    return GetBindToggleState(bind.menu,bind.index)
end
function Menu.Helpers.BuildNuiWidgets()
    local S=Menu.State
    local widgets={enabled=_G._mirageNuiEnabled and _G.AuthDone==true,theme=themeForNui(),binds={},spectators={},
        bindsVisible=S.hudBindsVisible==true,spectatorsVisible=S.spectatorListVisible==true}
    if not widgets.enabled then return widgets end
    if S.hudBindsVisible and _G.UniversalKeyBinds then
        for ctrlId,bind in pairs(_G.UniversalKeyBinds) do
            Menu.Helpers.MigrateReorganizedBind(bind)
            local ok,isToggle,active=pcall(bindState,bind)
            local key=Menu.Helpers.GetKeyName(bind.vk,ctrlId)
            widgets.binds[#widgets.binds+1]={key=tostring(key or '?'),label=tostring(bind.label or 'Option'),
                toggle=ok and isToggle==true,active=ok and active==true}
        end
        table.sort(widgets.binds,function(a,b)return a.label<b.label end)
    end
    if S.spectatorListVisible then
        local specs=Menu.Helpers.GetSpectatorList() or {}
        local ids={}
        _G._lastSpecList=_G._lastSpecList or {}
        for _,spec in ipairs(specs) do
            local distance=tonumber(spec.distance)
            if not distance and type(GetPlayerPed)=='function' and type(GetEntityCoords)=='function' then
                local measured,result=pcall(function()
                    local target=GetPlayerPed(spec.id)
                    if target and target~=0 and DoesEntityExist(target) then
                        return #(GetEntityCoords(PlayerPedId())-GetEntityCoords(target))
                    end
                end)
                if measured then distance=tonumber(result) end
            end
            widgets.spectators[#widgets.spectators+1]={name=tostring(spec.name or '?'),distance=distance}
            ids[spec.id]=true
            if not _G._lastSpecList[spec.id] then ShowDynastyNotification('[ SPECTATEUR ] '..tostring(spec.name)) end
        end
        _G._lastSpecList=ids
    end
    local toast=_G._mirageNuiToast
    if toast and GetGameTimer()-toast.time<3000 then
        widgets.toast={id=toast.id,text=toast.text,remaining=math.max(0,3000-(GetGameTimer()-toast.time))}
    end
    _G._hudBindHitboxes={}
    return widgets
end
-- Authentification visuelle NUI ; la validation et la saisie restent dans le Lua existant.
local originalBindingUI=RenderBindingUI
RenderBindingUI=function(...)
    if ((_G.AuthState and _G.AuthState.active) or isFirstLoadBinding or _G.isBindingNoclip) and _G._mirageNuiEnabled
        and (_G._mirageNuiUntil or 0)>GetGameTimer() then return end
    return originalBindingUI(...)
end
function Menu.Helpers.BuildNuiBinding()
    local startup=isFirstLoadBinding==true
    local option=_G.isBindingNoclip==true
    local data=_G.bindingActionData or {}
    return {active=_G._mirageNuiEnabled and (startup or option)
            and not Menu.State.isLoading and not Menu.State.showLoading,
        startup=startup,theme=themeForNui(),
        title=startup and 'MIRAGE' or tostring(data.label or 'Bind option'),
        subtitle=startup and "Choisissez la touche d'ouverture du menu" or 'Appuyez sur une touche pour assigner',
        key=startup and tostring(startupBindingName or 'F12') or tostring(_G.bindingKeyDisplay or ''),
        help=startup and 'ENTRÉE Valider · ÉCHAP Garder F12' or 'ENTRÉE Valider · ÉCHAP Annuler'}
end
function Menu.Helpers.BuildNuiAuth()
    local auth=_G.AuthState or {}
    local now=GetGameTimer()
    local active=_G._mirageNuiEnabled and auth.active==true and not Menu.State.isLoading and not Menu.State.showLoading
    return {active=active,theme=themeForNui(),confirm=auth.confirmMode==true,
        name=tostring(auth.confirmName or ''),selected=auth.confirmBtn or 1,
        length=math.min(128,#tostring(auth.inputBuffer or '')),
        error=auth.errorMsg and (auth.errorTimer or 0)>now and tostring(auth.errorMsg) or ''}
end
function Menu.Actions.SwitchSettingsTab(dir)
    local current=Menu.State.currentMenu
    if current~='SETTINGS_RENDER' and current~='SETTINGS_UTILITY' then return false end
    Menu.State.currentMenu=current=='SETTINGS_RENDER' and 'SETTINGS_UTILITY' or 'SETTINGS_RENDER'
    Menu.State.settingsTab=Menu.State.currentMenu=='SETTINGS_RENDER' and 1 or 2
    Menu.State.selectedOption,Menu.State.startIndex=1,1
    Menu.State.menuLastSwitchTime=GetGameTimer()
    return true
end
Menu.State.nuiLayoutEditing=false
Menu.State.nuiLayoutReset=0
function Menu.Actions.SetUILayoutEditing(enable)
    if enable and (type(Lapsus)~='table' or type(Lapsus.SetNuiFocus)~='function') then
        ShowDynastyNotification('Mouse UI unavailable');return false
    end
    Menu.State.nuiLayoutEditing=enable==true
    return true
end
Citizen.CreateThread(function()
    local focused=false
    while true do
        local S=Menu.State
        local escape=Lapsus_GetAsyncKeyState_compat and Lapsus_GetAsyncKeyState_compat(0x1B)
        local wanted=S.nuiLayoutEditing==true and S.menuOpen==true and _G.AuthDone==true
            and _G._mirageNuiEnabled and not S.isLoading and not S.showLoading
            and not (_G.AuthState and _G.AuthState.active)
        if escape or not wanted then S.nuiLayoutEditing=false;wanted=false end
        if wanted~=focused then
            local ok,accepted=pcall(Lapsus.SetNuiFocus,'mirage_live_menu',wanted)
            focused=wanted and ok and accepted==true
            if wanted and not focused then
                S.nuiLayoutEditing=false
                ShowDynastyNotification('Mouse UI unavailable')
            end
        end
        Wait(50)
    end
end)
local sentPackets={}
local function send(action,value)
    if type(Lapsus)~='table' or type(Lapsus.SendNuiMessage)~='function' then return false end
    local ok,body=pcall(json.encode,{channel='mirage-ui-v3',action=action,value=value})
    if not ok or #body>4194304 then return false end
    local now=GetGameTimer()
    local previous=sentPackets[action]
    if previous and previous.body==body and now-previous.time<750 then return true end
    local sent,accepted=pcall(Lapsus.SendNuiMessage,'mirage_live_menu',body)
    if sent and accepted==true and _G._mirageNuiEnabled then
        sentPackets[action]={body=body,time=now}
        return true
    end
    return false
end
local originalHorizontalNavigation=Menu.Actions.HandleHorizontalNavigation
Menu.Actions.HandleHorizontalNavigation=function(...)
    local result=originalHorizontalNavigation(...)
    Menu.State.nuiValueRevision=(Menu.State.nuiValueRevision or 0)+1
    return result
end
Citizen.CreateThread(function()
    local opened,lastOpen,lastList,lastWidgets,lastSelection,lastContext,lastToast,lastAuth,lastLoading,lastBinding=false,-10000,-10000,-10000,nil,nil,0,nil,nil,nil
    local lastModals=-10000
    local lastValueRevision=-1
    while true do
        local now=GetGameTimer()
        if not opened and now-lastOpen>=3000 and type(Lapsus)=='table' and type(Lapsus.CreateNui)=='function' then
            lastOpen=now
            local ok,accepted=pcall(Lapsus.CreateNui,'mirage_live_menu',base..'/index.html?transport=direct&v=26-redside')
            opened=ok and accepted==true
        end
        if opened and type(json)=='table' and type(json.encode)=='function' then
            local S=Menu.State
            if now-lastModals>=100 then
            lastModals=now
            local loading={active=_G._mirageNuiEnabled and (S.isLoading==true or S.showLoading==true),
                progress=math.max(0,math.min(100,tonumber(S.loadingProgress) or 0)),
                status=tostring(S.loadingStatus or 'Chargement...'),theme=themeForNui()}
            local loadingKey=json.encode(loading)
            if loadingKey~=lastLoading or now%1000<120 then
                if send('loading',loading) then lastLoading=loadingKey end
            end
            local binding=Menu.Helpers.BuildNuiBinding()
            local bindingKey=json.encode(binding)
            if bindingKey~=lastBinding or now%1000<120 then
                if send('binding',binding) then lastBinding=bindingKey end
            end
            local auth=Menu.Helpers.BuildNuiAuth()
            local authKey=json.encode(auth)
            if authKey~=lastAuth or now%1000<120 then
                if send('auth',auth) then lastAuth=authKey end
            end
            send('layout',{editing=S.nuiLayoutEditing==true,reset=S.nuiLayoutReset or 0})
            end
            local context=tostring(S.currentMenu)..':'..tostring(S.pedTab)..':'..tostring(S.weaponTab)..':'..tostring(S.vehicleTab)..':'..tostring(S.trollTab)..':'..tostring(S.onlineTab)
            local blocking=type(IsBlockingUIActive)=='function' and IsBlockingUIActive() or false
            local visible=_G._mirageNuiEnabled and _G.AuthDone==true and S.menuOpen==true
                and not S.isLoading and not S.showLoading and not blocking
            -- Selection legere envoyee immediatement, sans reseau ni reconstruction des lignes.
            local signature=context..':'..tostring(S.selectedOption)..':'..tostring(S.startIndex)..':'..tostring(visible)
            if signature~=lastSelection then
                if send('selection',{menu=S.currentMenu,selected=S.selectedOption or 1,start=S.startIndex or 1,visible=visible}) then
                    lastSelection=signature
                end
            end
            local valueRevision=S.nuiValueRevision or 0
            if context~=lastContext or (visible and valueRevision~=lastValueRevision and now-lastList>=40)
                or now-lastList>=(visible and 200 or 2000) then
                local ok,snapshot=pcall(Menu.Helpers.BuildNuiSnapshot)
                if ok then send('snapshot',snapshot) end
                lastContext=context;lastList=now;lastValueRevision=valueRevision
            end
            local toastId=_G._mirageNuiToast and _G._mirageNuiToast.id or 0
            if now-lastWidgets>=500 or toastId~=lastToast then
                local ok,widgets=pcall(Menu.Helpers.BuildNuiWidgets)
                if ok then send('widgets',widgets) end
                lastWidgets=now;lastToast=toastId

            end
        end
        Wait(opened and 16 or 250)
    end
end)
end)()
